\includegraphics[width=88mm]{math.pdf}
\vspace{-15pt}
\caption{Two mathematical interpretations of GEMV.}
\label{Fig:math}
\vspace{-5pt}
\end{figure}
\begin{figure*}[hbt]
\centering
\vspace{-20pt}
