\begin{restatable}{theorem}{BlackBoxReduction}
    \label{thm:BlackBoxReduction}
    Let $\mathcal{A}$ be an $\alpha$-approximation algorithm for $\ac{MinMaxDP}$, and let $\mathcal{R}(m)$ denote its runtime dependent on $m \coloneqq |A|$.
    There exists a $\max\{\alpha, (1+\epsilon)\}$-approximation for \ac{TMO} with runtime in $\mathcal{O}\left(m \cdot \mathcal{R}\left(m^2(2+\frac{1}{\epsilon})\right)\right)$.
