Note that $\phi(D)$ is equal to the maximal number of \encircle{$S$}-labeled vertices on a path from the root to a leaf in the contracted decomposition tree. Hence, the uniqueness of $\phi$ follows by the uniqueness of the contracted decomposition tree.

\begin{lemma}
    \label{lem:ContrComposTree}
    The contracted decomposition tree for any \ac{SePa} graph is unique.
\end{lemma}
\begin{proof}[Proof of \Cref{lem:ContrComposTree}]
    Let $D=(V,A)$ be a given \ac{SePa} graph. Note first that in a contracted decomposition tree, any path from the root to a leaf always alternates between \encircle{$S$} and \encircle{$P$} nodes.

    Assume for contradiction that there are two different contracted decomposition trees $T_c$ and $T_c'$ for $D$.
    Now, consider a vertex $v$ in $T_c$ with maximal distance to the root, such that the subtree with root $v$ in $T_c$ is not contained in $T_c'$. Since every leaf in both $T_c$ and $T_c'$ corresponds to an arc in $D$, $v$ must be an internal node.
    By definition, the children $w_1,\dots,w_\ell$ of $v$ are roots of subtrees in $T_c$ and $T_c'$ (\ie every subtree rooted in $w_i$ for $i \in [\ell]$ is the same in both trees by choice of $v$).
    Assume that the nodes $w_i$ for $i \in [\ell]$ do not have the same parent in $T_c'$. This is without loss of generality, since  if all $w_i$ for $i \in [\ell]$ have the same parent  $v'$ in $T_c'$, then $v'$ must have at least one more child, as otherwise we get a contradiction to the choice of $v$. In this case, we can swap the roles of $T_c$ and $T_c'$. 

    %(otherwise swap the roles of $T_c$ and $T_c'$ from hereon). 
    For $i \in [\ell]$, let $s_i,t_i \in V$ be the start and target nodes of the subgraphs corresponding to $w_i$.
    Further, let $A_i \coloneqq \{a \in A \mid a \text{ is contained in the subgraph corresponding to } w_i\}$.

    \begin{itemize}
        \item Assume that the label of $v$ is \encircle{$S$}.

        \Wlog the children $w_1,\dots, w_\ell$ of $v$ are ordered such that $t_i=s_{i+1}$ for $i \in [\ell-1]$.
        By construction with respect to $T_c$, for $i\in \{2,\dots\ell\}$ there is no arc in $A \setminus A_i$ leaving $s_i$ and for $i \in \{1,\dots, \ell-1\}$ no arc in $A \setminus A_i$ entering $t_i$ in the original graph $D=(V,A)$.

        Let $v_i'$ be the parent vertex of $w_i$ in $T_c'$.
        If there exists $j \in [\ell]$ such that vertex $v_j'$ is labeled with \encircle{$P$}, this is a contradiction:
        For $j \neq \ell$ there would be an arc in $A \setminus A_j$ that enters $t_j$. For $j=\ell$, there would be an arc in $A \setminus A_j$ leaving $s_\ell$.

        Hence, we can assume that $v_i'$ is labeled with \encircle{$S$} for $i \in [\ell]$.
        By definition of $v$, we know that there exists $j \in [\ell-1]$ such that $v_j' \neq v_{j+1}'$.
        Since $t_j =s_{j+1}$, and $w_j$, $w_{j+1}$ have different parents in $T_c'$, we have that $t_j$ must be the sink of the subgraph corresponding to $v_j'$ (and $s_{j+1}$ must be the source of the subgraph corresponding to $v_{j+1}'$).
        Since the contracted decomposition tree alternates between \encircle{$S$} and \encircle{$P$} compositions, the parent vertex of $v_{j}'$ (respectively $v_{j+1}'$) is \encircle{$P$}-labeled, and hence, there is an arc in $A \setminus A_j$ entering $t_j$ (and an arc in $A \setminus A_{j+1}$ leaving $s_{j+1}$).
        This is a contradiction.

        \item Assume that the label of $v$ is \encircle{$P$}.

        By construction with respect to $T_c$, $s_1=s_i$ and $t_1=t_i$ for $i \in [\ell]$.
        Let $v_i'$ be the parent vertex of $w_i$ in $T_c'$.
        If there exists an $i \in [\ell]$ such that vertex $v_i'$ is labeled with \encircle{$S$}, and since not all nodes $w_j$ have the same parent, this would be a contradiction since either $s_i$ or $t_i$ cannot be used for further compositions. But all subgraphs for the children $w_j$, $j \in [\ell]$ must be in parallel (and in particular, must have the same source and destination).
        Hence, we can assume that $v_i'$ is labeled with \encircle{$P$} for $i \in [\ell]$.

        By definition of $v$, we know that there exists a $j \in [\ell-1]$ such that $v_j' \neq v_{j+1}'$.
        Since we only consider \encircle{$S$}-\encircle{$P$}-alternating paths in the tree, the parent vertex of $v_{j}'$ (respectively $v_{j+1}'$) is \encircle{$S$}-labeled.
        Thus, either $s_j$ or $t_j$ cannot be used for further compositions, a contradiction since we still need to compose all the subgraphs for the children $w_j$, $j \in [\ell]$ in parallel. \qedhere
    \end{itemize}
\end{proof}


\section{Greedy algorithm for MinMaxDP – missing proofs}
\label{app:Greedy}
In this section, we give the missing proofs of \Cref{sec:Greedy}.

\subsection{Proof of \Cref{lem:H_k-combination}}
\label{app:lem:H_k-combination}
\HkCombination*

\begin{proof}
    Let $q_1 \geq \dots \geq q_{k_1}$ and $r_1 \geq \dots \geq r_{k_2}$ be the lengths of the paths in path profiles $\bQ$  and $\bR$, respectively. 
    In the following, we refer to these as  strict orders, \ie\ $q_i \prec q_j$ and $r_i \prec r_j$ if and only if $i<j$.

    Note that consistency of $\bP$ in $D'$ follows immediately from the consistency of $\bQ$ and $\bR$ in $D^{(1)}$ and $D^{(2)}$, respectively, since
    \begin{equation*}
        \cost(\bP, D') = \sum_{j=1}^{k_1} q_j + \sum_{j=1}^{k_2} r_j
        %= \cost(\bQ, D^{(1)})+\cost(\bR, D^{(2)})
        \overset{\eqref{eq:inv1}}{\leq} \cost(\bP^*, D^{(1)})+\cost(\bP^*, D^{(2)}) =
        \cost(\bP^*, D').
    \end{equation*}

    Now, we prove that the series composition $\bP = \bQ \serc \bR$ (thus, $k_1=k_2=:k'$) is balanced.
    Let $p_1 \geq \dots \geq p_{k'}$ be the lengths of the paths in profile $\bP$.
    We define $c \colon [k'] \to [k']$ to be the bijective function where $c(i)$ is the index such that $P_i$ is obtained by combining $Q_{c(i)}$ and $R_{k-c(i)+1}$.
    Without loss of generality, if $p_i=p_j$ with $i<j$, we assume that $c(i) < c(j)$. This way, we obtain once again a strict order on $\bP$.
    Using this ordering of the lengths of $\bP$ also gives us a strict order, \ie\ $p_i \prec p_j$ if and only if $i < j$.

    In order to show that $\bP$ is balanced in $D'$, we fix some $i \in [k'-1]$, and
     define
    \begin{equation*}
        S_1 \coloneqq \{1 \leq j \leq c(i+1)-1 \mid p_{c^{-1}(j)} \succ p_{i+1} \} \, \text{ and } \, S_2 \coloneqq \{c(i+1)+1 \leq j \leq k' \mid 
        p_{c^{-1}(j)} \succ p_{i+1} \}.
    \end{equation*}
    Note that $i=|S_1| + |S_2|$ by definition of the sets $S_1$ and $S_2$.
    Further, we define
    \begin{equation*}
        T_1 \coloneqq \{1 \leq j \leq c(i+1)-1 \mid p_{c^{-1}(j)} \prec p_{i+1}\}.
    \end{equation*}
    Then $[c(i+1)-1] = S_1 \dot\cup\ T_1$ holds by definition of $c$ and since $\prec$ is a strict ordering.
    Let $j_1 \leq \dots \leq j_{\ell}$ be the elements of $T_1$.
    Further, define $j_0 \coloneqq 0$ and $j_{\ell+1} \coloneqq c(i+1)$.
    Then $S_1 = \dot\bigcup_{h=0}^\ell I_h$ where $I_h \coloneqq [j_{h}+1,j_{h+1}-1]_{\mathbb{Z}}$ is the interval between $j_{h}$ and $j_{h+1}$ for $h \in \{0,\dots,\ell\}$.
    We obtain
    \begin{align}
    \label{eq:greedy_series}
    \begin{split}
        &\frac{1}{|I_h|} \sum_{j \in I_h} (q_j + r_{k'-j+1})
        \overset{\small (*)}{\leq} r_{k'-j_{h+1}+1} + \frac{1}{|I_h|} \sum_{j \in I_h} q_j
        \overset{\small (**)}{\leq} r_{k'-j_{h+1}+1} + \frac{1}{j_{h+1}-1} \sum_{j=1}^{j_{h+1}-1} q_j\\
        &\overset{\small \eqref{eq:inv2}}{\leq} r_{k'-j_{h+1}+1} + \makespan(\bP^*,D^{(1)}) + q_{j_{h+1}}
        \overset{\small (***)}{\leq} \makespan(\bP^*,D')  + p_{i+1}
    \end{split}
    \end{align}
    where $(*)$ holds since $r_{k'-j+1} \leq r_{k'-j_{h+1}+1}$ for $j \in I_h$.
    Equation $(**)$ holds since $q_1 \geq \dots \geq q_{j_h} \geq q_{j_h+1} \geq \dots \geq q_{j_{h+1}-1}$, so the average over all path lengths is larger than the average over the length of the $|J_h|$ shortest paths.
    The last equation $(***)$ holds since $ \makespan(\bP^*,D^{(1)}) \leq  \makespan(\bP^*,D')$ and since by definition $j_{h+1} \leq c(i+1)$ and $j_{h+1} \notin S_1$, so $ q_{j_{h+1}} + r_{k'-j_{h+1}+1} \leq p_{i+1}$.

    Since $S_1 = \dot\bigcup_{h=0}^\ell I_h$, it follows that
    \begin{equation}
        \label{eq:DP-corollary}
        \frac{1}{|S_1|} \sum_{j \in S_1} (q_j + r_{k'-j+1}) \leq \max_{h \in \{0,\dots,\ell\}} \frac{1}{|I_h|} \sum_{j \in I_h} (q_j + r_{k'-j+1}) \overset{\eqref{eq:greedy_series}}{\leq} \makespan(\bP^*,D') + p_{i+1}.
    \end{equation}

    By a similar argumentation (swapped roles for $q$ and $r$), we obtain
    \begin{equation}
        \label{eq:DP-corollary-b}
        \frac{1}{|S_2|} \sum_{j \in S_2} (q_j + r_{k'-j+1}) \leq  \makespan(\bP^*,D') + p_{i+1}.
    \end{equation}
    In summary, it follows that
    \begin{align*}
        \sum_{j=1}^i p_i 
        &= \sum_{j \in S_1} (q_j + r_{k'-j+1}) + \sum_{j \in S_2} (q_j + r_{k'-j+1})\\
        &\leq (|S_1| + |S_2|) \cdot (\makespan(\bP^*,D') + p_{i+1})
        = i \cdot ( \makespan(\bP^*,D') + p_{i+1})
    \end{align*}
    Thus, the greedy profile $\bP = \bQ \serc \bR$ is balanced in $D' = D^{(1)} \serc D^{(2)}.$
    \medskip

    Next, we consider the path profile  $\bP = \bQ \parc \bR$ obtained by a parallel composition of $\bQ$ and $\bR$ by the greedy algorithm. Let $p_1 \geq \dots \geq p_{k'}$ be the lengths of the paths in $\bP$ (thus, 
    $k'=k_1 + k_2$).
    To show that $\bP$ is balanced,  we fix some $i \in [k']$. Let $i_1$ and $i_2$ denote the numbers of paths from $P_1,\dots,P_i$ that traverse $D^{(1)}$ and $D^{(2)}$, respectively.
    If $i_1=k_1$, we get
    \begin{align*}
        \sum_{j=1}^{i_1} q_j &= \sum_{j=1}^{k_1} q_j = \cost(\bQ,D^{(1)}) \overset{\eqref{eq:inv1}}{\leq} \cost(\bP^*,D^{(1)}) \leq k_1 \cdot \makespan(\bP^*,D^{(1)})\\
        &\leq k_1 \cdot \makespan(\bP^*,D') \leq i_1 \left( \makespan(\bP^*,D') + p_{i+1} \right).
    \end{align*}
    If $i_1 < k_1$, we get
    \[
        \sum_{j=1}^{i_1} q_j \overset{\eqref{eq:inv2}}{\leq} i_1 \left( \makespan(\bP^*,D^{(1)}) + q_{i_1+1}\right) \leq i_1 \left( \makespan(\bP^*,D')  + p_{i+1} \right)
    \]
    where the last equality holds since $p_{i+1} = \max \{q_{i_1+1} , r_{i_2+1} \} \geq q_{i_1+1} $. Similarly, we obtain
    \[
        \sum_{j=1}^{i_2} r_j \leq i_2 \left( \makespan(\bP^*,D')  + p_{i+1} \right).
    \]
    Combining these equations, we conclude that
    \begin{align*}
        \sum_{j=1}^i p_i &= \sum_{j=1}^{i_1} q_j + \sum_{j=1}^{i_2} r_j
        \leq  i_1 \left( \makespan(\bP^*,D')  + p_{i+1} \right) + i_2 \left( \makespan(\bP^*,D') + p_{i+1} \right)\\
        &= i \left(\makespan(\bP^*,D') + p_{i+1} \right).
    \end{align*}
    Hence, $\bP = \bQ \parc \bR$ is balanced with $\bP^*$ in $D'=D^{(1)} \parc D^{(2)}$.
\end{proof}

\subsection{Proof of \Cref{lem:H_k-approx}}
\label{app:lem:H_k-approx}
\HkApprox*
\begin{proof}
    In this proof, we will use the following well known recursive formula for $H_i$:
    \begin{equation}
        \label{eq:H_i_recursion}
        \frac{1}{i} \left( \sum_{j=1}^{i-1} H_j \right) +1 = H_{i} \qquad \text{ for all } i \in \mathbb{Z}_{\geq 2}.
    \end{equation}
    Let $p_1 \geq \dots \geq p_k$ the lengths of the paths in $\bP$.
    Using the recursive formula \eqref{eq:H_i_recursion} and equation \eqref{eq:inv2} for $i \in [k-1]$, we start showing by induction that 
    \begin{equation}
        \label{eq:DP-Hk_corollary}
        p_1 \leq H_i \cdot \makespan(\bP^*,D) + p_{i+1} \qquad \text{ for all } i \in [k-1].
    \end{equation}
    For $i=1$ it follows directly from \eqref{eq:inv2}. 
    For the induction step, fix an $i \in [k-2]$ and assume that \eqref{eq:DP-Hk_corollary} holds for $i'\leq i$. We will now show that \eqref{eq:DP-Hk_corollary} also holds for $i+1$.
    \begin{align*}
        p_1 &\overset{\small (*)}{\leq} \frac{1}{i+1} \left(p_1 + \sum_{j=1}^i \left(H_j \cdot \makespan(\bP^*,D) + p_{j+1}\right)\right)\\
        &= \frac{1}{i+1} \cdot \makespan(\bP^*,D)  \left(\sum_{j=1}^i H_j \right) + \frac{1}{i+1} \left( \sum_{j=1}^{i+1} p_j \right)\\
        &\overset{\small (**)}{\leq} \frac{1}{i+1} \cdot \makespan(\bP^*,D) \left(\sum_{j=1}^i H_j \right) + \left( \makespan(\bP^*,D) + p_{i+2}\right)\\
        &\overset{\small \eqref{eq:H_i_recursion}}{=} H_{i+1} \cdot \makespan(\bP^*,D)  + p_{i+2}.
    \end{align*}
    Here, equation $(*)$ holds by averaging the equation $p_1 \leq p_1$ and equations \eqref{eq:DP-Hk_corollary} for $i'\leq i$ given by induction hypothesis. Equation $(**)$ holds by equation \eqref{eq:inv2} since $i+1\leq k-1$.

    Using equations \eqref{eq:DP-Hk_corollary} for $i \in [k-1]$, we obtain
    \begin{align*}
        \makespan(\bP,D)
        &= p_1 \overset{\eqref{eq:DP-Hk_corollary}}{\leq} \frac{1}{k} \cdot \left( p_1 + \sum_{i=1}^{k-1}(H_i \cdot \makespan(\bP^*,D) + p_{i+1}) \right)\\
        &= \frac{1}{k}  \cdot \makespan(\bP^*,D) \cdot \left( \sum_{i=1}^{k-1} H_i \right) + \frac{1}{k} \left( \sum_{i=1}^k p_i \right)\\
        &\overset{\small \eqref{eq:inv1}}{\leq} \frac{1}{k} \makespan(\bP^*,D) \cdot \left( \sum_{i=1}^{k-1} H_i \right) + \frac{1}{k} \cost(\bP^*,D)\\
        &\overset{\text{avg.}}{\leq} \frac{1}{k}  \cdot \makespan(\bP^*,D) \cdot \left( \sum_{i=1}^{k-1} H_i \right) + \makespan(\bP^*,D)\\
        &= \left( \frac{1}{k} \left(\sum_{i=1}^{k-1} H_i\right) +1 \right)
        \cdot \makespan(\bP^*,D)
        \overset{\small \eqref{eq:H_i_recursion}}{=} H_k \cdot \makespan(\bP^*,D).
        \qedhere
    \end{align*}
\end{proof}

\subsection{Proof of \Cref{lem:phi-combination}}
\label{app:lem:phi-combination}
\GreedyPhi*
\begin{proof}
    Let $p_1^{(j)} \geq \dots \geq p_{k_j}^{(j)}$ be the path lengths of path profile $\bP^{(j)}$ with $k_j$ paths for $j \in [i]$.

    Note that consistency of $\bP$ follows immediately from the consistency of $\bP^{(j)}$ for $j \in [i]$, since
    \begin{equation}
        \label{eq:inv1_proof}
        \cost(\bP,D') = \sum_{j=1}^i \tau\left(P^{(j)},D^{(j)}\right) \overset{\eqref{eq:inv1}}{\leq} \sum_{j=1}^i \cost\left(\bP^*,D^{(j)}\right) = \cost(\bP^*,D')
    \end{equation}
    We first consider the case where $D'$ is the root of an $S$-component, and show that  $D'$  is $\phi$-bounded.
    Note that $D'$ is the series composition of $D^{(1)}, \dots, D^{(i)}$, where each $D^{(j)}$ is a graph containing exactly one arc or is obtained by a parallel composition.
    Thus, $k=k_j$ for $j \in [i]$ and
    \begin{equation}
        \label{eq:phi_constr_cut}
        \phi(D') = \max_{j \in [i]} \left\{ \phi \left(D^{(j)} \right) \right\} +1.
    \end{equation}
    Let $p_1\geq \dots \geq p_k$ be the lengths of the paths in the greedy series composition of $\bP^{(1)}, \dots ,  \bP^{(i)}$ according to the fixed decomposition of $D'$. 
    Then, we have
    \begin{equation}
        \label{eq:phi_composition1}
        \begin{split}
        p_1 - p_k 
        &\overset{\small (*)}{\leq} \max_{j \in [i]} \left\{ p_1^{(j)} - p_k^{(j)} \right\}
        \overset{\small (**)}{\leq} \max_{j \in [i]} \left\{ \left(\phi(D^{(j)}) +1 \right) \cdot \makespan(\bP^*,D) \right\}\\
        &\overset{\eqref{eq:phi_constr_cut}}{\leq} \phi(D') \cdot \makespan(\bP^*,D),
        \end{split}
    \end{equation}
    where $(*)$ holds by the greedy composition rule, and $(**)$ holds since each $\bP^{(j)}$ is $\phi$-bounded in $D^{(j)}$.
    Further, we know that
    \begin{equation}
        \label{eq:phi_composition2}
        p_k \leq \frac{1}{k} \cost(\bP,D') \overset{\eqref{eq:inv1_proof}}{\leq} \frac{1}{k} \cost(\bP^*,D') \leq \makespan(\bP^*,D).
    \end{equation}
    We insert \eqref{eq:phi_composition2} into \eqref{eq:phi_composition1} and we get
    \begin{equation*}
        p_1 \leq \phi(D') \cdot \makespan(\bP^*,D) + p_k \leq (\phi(D')+1) \cdot \makespan(\bP^*,D). 
    \end{equation*}

    Next, we consider a $P$-component whose root corresponds to $D'$.
    Then $D'$ is obtained by  combining $D^{(1)}, \dots, D^{(i)}$ via  parallel compositions, where each $D^{(j)}$ either contains exactly one arc or is obtained by a series composition.
    Thus $k_1 + \dots + k_i=k$ and
    \begin{equation}
        \label{eq:phi_constr_cut_p}
        \phi(D') =\max_{j \in [i]} \left\{\phi(D^{(j)})\right\}
    \end{equation}
    Again, let $p_1 \geq \dots \geq p_k$ be the path lengths of the path profile $\bP$ obtained by greedily combining the path profiles $\bP^{(1)},\dots, \bP^{(i)}$ according to the fixed decomposition of $D'$.
    Here, $\bP$ is $\phi$-bounded, since $\bP^{(j)}$ is $\phi$-bounded in $D^{(j)}$ for $j \in [i]$:
    \begin{equation*}
        p_1 \leq \max_{j \in [i]} \left\{ p_1^{(j)} \right\}
        \leq  \max_{j \in [i]} \left\{ \left(\phi\left(D^{(j)}\right)+1\right) \cdot \makespan(\bP^*,D) \right\}
        \overset{\eqref{eq:phi_constr_cut_p}}{=} (\phi(D)+1) \cdot \makespan(\bP^*,D).
        \qedhere
    \end{equation*}
\end{proof}


\subsection{Proof of \Cref{DPHk}}
\label{app:lem:DPHk}

\DPHk*
\begin{proof}
    Let $\bP^*$ be the optimal path profile for $D$.

    Consider the path profiles of table entries along $\bP^*$, \ie\ the entries $(D',k',\theta')$ where $k'$ equals the number of paths of $\bP^*$ going through $D'$ and $\theta'$ equals their total length, \ie $\theta' = \cost(\bP^*,D')$.
    We show that these path profiles fulfill equations \eqref{eq:inv1} and \eqref{eq:inv2}. 
    For the single arcs this is trivially the case. For larger graphs, it follows iteratively (\wrt the series-parallel composition of $D$) by \Cref{lem:H_k-combination} and the fact that the left hand side of \eqref{eq:inv2} is minimized by our selection rule.

    Hence, in the last step, we pick a path profile $\bP$ whose objective value is at most as large as the objective value of path profile $\bP'$ in table entry $(D,k,\cost(\bP^*,D))$.
    Since $\bP'$ is consistent and balanced in $D$, it is a $H_k$-approximation by \Cref{lem:H_k-approx}. Thus,
    \begin{equation*}
        DP = \makespan(\bP,D) \leq \makespan(\bP',D)  \leq H_k \cdot \makespan(\bP^*,D)  = H_k \cdot \OPT. \qedhere
    \end{equation*}
\end{proof}

\subsection{Proof of \Cref{DPphi}}
\label{app:lem:DPphi}
\DPphi*
\begin{proof}
    Consider a graph $D' \sqsubseteq D$ that corresponds to a leaf in the decomposition tree of $D$ or to the root of an $S$- or $P$-component.
    Let $k'$ be the number of paths in $\bP^*$ that go through $D'$  and $\theta'=\cost(\bP^*,D')$ their total length in $D'$.
    First, we will show by induction that the path profile $\bP'$ in table entry $(D',k',\theta')$ with path length $p_1' \geq \dots \geq p_{k'}'$ is consistent and $\phi$-bounded.

    If $D'$ consists of only a single arc, the statement follows directly.

    Next we focus on an $S$- or $P$-component.
    Consistency follows directly, since we only consider path profiles for table entries along $\bP^*$, \ie\ path profiles with total length $\cost(\bP^*,D')$ and the correct number of paths.

    For now, assume that $D'$ corresponds to the root vertex of an $S$-component.
    Let $D^{(1)},\dots,D^{(i)} \sqsubseteq D$ be the subgraphs corresponding to children of the selected $S$-component.
    That means, $D'$ is obtained by series compositions of the subgraphs $D^{(1)},\dots,D^{(i)}$.
    Note that it might well be that the decomposition tree has multiple branches, \eg if $D' = ( D^{(1)} \serc D^{(2)}) \serc (D^{(3)} \serc D^{(4)})$.

    By construction, it holds that
    \begin{equation}
        \label{eq:phi_construction}
        \phi(D') = \max_{j \in [i]} \left\{ \phi \left(D^{(j)}\right) \right\} +1 \geq \phi\left(D^{(j)}\right).
    \end{equation}

    For $j \in [i]$, let $\bP^{(j)}$ be the path profile in table entry $\left(D^{(j)},k',\cost(\bP^*,D^{(j)})\right)$ with paths of length $p^{(j)}_1 \geq \dots \geq p_{k'}^{(j)}$.
    By our induction hypothesis $\bP^{(j)}$ is consistent and $\phi$-bounded in $D^{(j)}$.

    To show that the chosen solution for the table entry $(D',k',\theta')$ is $\phi$-bounded and fulfills equation~\eqref{eq:inv1}, we show the following claim:
    \begin{claim}
        \label{claim:p1-pk}
        Let $D_q$ be obtained by a series combination of $D^{(j)}$ with $j \in S_q \subseteq [i]$ and $D_r$ be obtained by a series combination of $D^{(j)}$ with $j \in S_r \subseteq [i]$ where $S_q \cap S_r = \emptyset$.
        Moreover, let $D_q \serc D_r = \tilde{D} \sqsubseteq D$.
        Then, the solution picked for $(\tilde{D}, k', \cost(\bP^*,\tilde{D}))$ fulfills
        \begin{equation}
            \label{eq:p1-pk}
            \tilde{p}_1 - \tilde{p}_{k'} \leq \max_{j \in S_q \cup S_r} \left\{p_1^{(j)}- p_{k'}^{(j)} \right\}
        \end{equation}
    \end{claim}
    \begin{claimproof}
        We prove this claim by induction.
        Let $q_1 \geq \dots \geq q_{k'}$ be the path length of the path profile $\bQ$ in table entry $(D_q,k',\cost(\bP^*,D_q))$ and let $r_1 \geq \dots \geq r_{k'}$ be the path length of the path profile $\bR$ in table entry $(D_r,k',\cost(\bP^*,D_r))$.
        We assume that \eqref{eq:p1-pk} holds for $\bQ$ and $\bR$, hence
        \begin{equation}
            \label{eq:p1-pk_IH}
            q_1 - q_{k'} \leq \max_{j \in S_q} \left\{ p_1^{(j)} - p_{k'}^{(j)} \right\} \qquad \text{ and } \qquad r_1 - r_{k'} \leq \max_{j \in S_r} \left\{ p_1^{(j)} - p_{k'}^{(j)} \right\}.
        \end{equation}
        For the path profile $\hat{\bP}$ obtained by the series combination of $\bQ$ and $\bR$, it holds that
        \begin{equation}
            \label{eq:p1-pk_IS}
            \hat{p}_1 - \hat{p}_{k'} \leq \max\left\{q_1 - q_{k'}, r_1 - r_{k'} \right\} \overset{\eqref{eq:p1-pk_IH}}{\leq} \max_{j \in S_q \cup S_r} \left\{ p_1^{(j)} - p_{k'}^{(j)} \right\}.
        \end{equation}
        Since $\hat{\bP}$ was a candidate for table entry $(D_r,k',\cost(\bP^*,\tilde{D}))$, and we pick the candidate $\tilde{\bP}$ minimizing the distance between the longest and the shortest path according to \eqref{eq:DP_phi_choice_s}, we get $\tilde{p}_1 - \tilde{p}_{k'} \leq \hat{p}_1 - \hat{p}_{k'}$.
        Together with \eqref{eq:p1-pk_IS} this proves the claim.
    \end{claimproof}

    By \Cref{claim:p1-pk}, we know that the path $\bP'$ in table entry $(D',k',\theta')$ fulfills
    \begin{equation}
        \label{eq:p1-k1:equation_series}
        p_1' - p_{k'}'
        \leq \max_{j \in [i]} \left\{ p_1^{(j)} - p_{k'}^{(j)}\right\}
        \leq \max_{j \in [i]} \left\{ \left(\phi \left(D^{(j)} \right) +1\right) \cdot \OPT \right\} \overset{\eqref{eq:phi_construction}}{\leq} \phi(D') \cdot \OPT.
    \end{equation}
    Thus, we obtain
    \begin{align*}
        p_1' &\overset{\eqref{eq:p1-k1:equation_series}}{\leq} \phi(D') \cdot \OPT + p_{k'}'
        \overset{\text{avg.}}{\leq} \phi(D') \cdot \OPT + \frac{1}{k'}\cost(\bP',D')
        \overset{\small (*)}{\leq} \phi(D') \cdot \OPT + \frac{1}{k'}\cost(\bP^*,D')\\
        &\overset{\text{avg.}}{\leq} \phi(D') \cdot \OPT + \cost(\bP^*,D')
        \leq \phi(D') \cdot \OPT + \OPT
        = (\phi(D')+1) \cdot \OPT.
    \end{align*}
    where $(*)$ holds since we used the solutions with $\cost(\bP^{(j)},D^{(j)})=\cost(\bP^*,D^{(j)})$ so $\cost(\bP',D') = \cost(\bP^*,D')$.
    \medskip

    Next, we focus on a $P$-component.
    Let $D^{(1)},\dots,D^{(i)} \sqsubseteq D$ be the subgraphs corresponding to children of the selected $P$-component.
    That means, $D'$ is obtained by parallel compositions of the subgraphs $D^{(1)},\dots,D^{(i)}$.
    For $j \in [i]$, let $\bP^{(j)}$ be the path profile in table entry $\left(D^{(j)},k_j,\cost(\bP^*,D^{(j)})\right)$ where $k_j$ is the number of paths of $\bP^*$ going through $D^{(j)}$ and let $p^{(j)}_1 \geq \dots \geq p_{k_j}^{(j)}$ be the paths lengths of $\bP^{(j)}$.

    Again, it might be the case that the component has multiple branches, \eg if $D' = ( D^{(1)} \parc D^{(2)}) \parc (D^{(3)} \parc D^{(4)})$.
    By construction, it holds that
    \begin{equation}
        \label{eq:phi_construction_parallel}
        \phi(D') = \max_{j \in [i]} \left\{ \phi \left(D^{(j)}\right) \right\} \geq \phi\left(D^{(j)}\right).
    \end{equation}
    Since we choose the candidate path profile that minimizes the longest path according to \eqref{eq:DP_phi_choice_p} and as selecting $k_j$ paths in $D^{(j)}$ yields one of the candidate profiles considered, we obtain
    \begin{equation}
        \label{eq:phi_p1_parallel}
        p_1' \leq \max_{j \in [i]} \left\{ p_1^{(j)}\right\}.
    \end{equation}
    Since $\bP^{(j)}$ is $\phi$-bounded, we get
    \begin{equation}
        p_1'
        \overset{\eqref{eq:phi_p1_parallel}}{\leq} \max_{j \in [i]} \left\{ p_1^{(j)}\right\}
        \leq \max_{j \in [i]} \left\{ \left( \phi\left(D^{(j)} \right) +1 \right) \cdot \OPT \right\}
        \overset{\eqref{eq:phi_construction_parallel}}{\leq} \left( \phi(D') +1 \right) \cdot \OPT.
    \end{equation}

    \medskip
    Hence, we proved by induction on the decomposition tree (since $D'$ corresponds to a root of a $S$- or $P$-component) that the path profile $\bP'$ in table entry $(D,k,\cost(\bP^*,D))$ is consistent and $\phi$-bounded.
    In the end of the dynamic program, the path profile $\bP'$ is a potential candidate. Since we select the path profile with smallest makespan, we get
    \begin{equation*}
        DP \leq p_1' \leq (\phi(D) +1) \cdot \OPT. \qedhere
    \end{equation*}
\end{proof}


\subsection{Running time – Proof of \Cref{lem:DPruntime} and \Cref{lem:DPepsruntime}}
\label{app:DP_runtime}
\DPruntime*
\begin{proof}
    First note that we have to fill $\mathcal{O}(m k |\Theta|)$ table entries.
    For a table entry, we have to consider $k \cdot |\Theta|$ candidates.
    Constructing a path profile for a candidate takes $\mathcal{O}(k\log(k))$ time (sorting the paths by length).
    Evaluating \eqref{eq:DP_choice} for a candidate takes $\mathcal{O}(k^2)$ time.
    So it takes $\mathcal{O}(k^3 |\Theta|)$ time to fill a table entry.
    Thus, the total runtime is bounded by $\mathcal{O}(mk^3|\Theta|^2)$.
\end{proof}

A simple bound on $\Theta$ would be $m \cdot \tau_{\max}$.
However, this can be an extremely large number.
Especially, since it is possible that an artificial arc from $s$ to $t$ is added with arbitrary high travel time.
Even if this arc is never used in an optimal solution, the DP needs to consider this possibility and thus has pseudo-polynomial runtime.

To circumvent this, we guess the longest arc used by an optimal solution (at most $m$ possibilities) and round the arc length accordingly.
\DPepsruntime*

\begin{proof}
    To show that such an algorithm exists, we will describe how to use a rounding (depending on $\epsilon$) such that first $|\Theta|$, the number of different possibilities of the total length, can be bounded by $m$ and $\frac{1}{\epsilon}$. And second, a solution to the rounding adds a factor of at most $(1+\epsilon)$ to the $H_k$-approximation ratio of the dynamic program.

    For the rounding, we aim to guess the longest arc that is used in an optimal solution. We do this by going through all arcs $a \in A$.
    For a given arc $\bar a \in A$ with length $\tau_{\bar a}$, let $D'$ be the graph $D$ where all arcs $a\in A$ with $\tau_{a} > \tau_{\bar a}$ are deleted.
    Let $F \coloneqq \frac{\epsilon \cdot \tau_{\bar a}}{m}$ and define $\tau'_a \coloneqq \left\lceil \frac{\tau_a}{F}\right\rceil$. Note that this means instead of iterating over all arcs, we basically just iterate over the different length that arcs can have.

    Let $\bP(\tau_{\bar a})$ be the path profile obtained by applying the DP to $D'$ with arc length $\tau'$.
    Finally, we pick the path profile $\bP$ with minimal objective among all computed solutions $\bP(\tau_{\bar a})$, \ie
    $\bP = \text{argmin} \{\makespan(\bP(\tau_{a})) \mid a \in A \} $.
    \medskip

    The computed path profile $\bP$ has an objective value that is at most as long as the one of $\bP(\tau_{\max}^*)$, where $\tau_{\max}^*$ is the length of the longest arc in the optimal path profile $\bP^*$.

    To simplify notation, we use $F$ for the rounding divisor for $\tau_{\max}^*$, $\tau'$ for the rounded transit times for $\tau_{\max}^*$ and $\makespan'$ to map a path profile to its solution value with respect to the rounded transit times for $\tau_{\max}^*$.
    Similarly, let $\bP' \coloneqq \bP(\tau_{\max}^*)$ be the solution computed by the dynamic program with respect to this rounding according to $\tau_{\max}^*$.
    Further let $\bar{\bP}^*$ be an optimal path profile in $D$ with respect to travel times $\tau'$.
    Then, the following equations hold by definition of $\makespan'$:
    \begin{equation}
        \label{eq:DP-rounding_lb}
        0 \leq F \cdot\sum_{a \in P_1'} \left( \left\lceil \frac{\tau_a}{F} \right\rceil - \frac{\tau_a}{F} \right) = F \cdot \makespan'(\bP') - \makespan(\bP')
    \end{equation}
    here $P_1'$ expresses the longest path of $\bP'$ and 
    \begin{equation}
        \label{eq:DP-rounding_ub}
        F \cdot \makespan'(\bP^*) - \makespan(\bP^*) = F \cdot\sum_{a \in P_1^*} \left( \left\lceil \frac{\tau_a}{F} \right\rceil - \frac{\tau_a}{F} \right) \leq F \cdot \sum_{a \in P_1^*} 1 \leq mF.
    \end{equation}
    Using these two equations, we can show that $\tau(\bP) \leq H_k (1+ \epsilon) \tau(\bP^*)$:
    \begin{align*}
        \makespan(\bP)
        &\overset{\small (*)}{\leq} \makespan(\bP')
        \overset{\eqref{eq:DP-rounding_lb}}{\leq} F \cdot \makespan'(\bP')
        \overset{\small (**)}{\leq} F \cdot H_k \cdot \makespan'(\bar{\bP}^*)
        \overset{\small (***)}\leq F \cdot H_k \cdot \makespan'(\bP^*)\\
        &\overset{\eqref{eq:DP-rounding_ub}}\leq F \cdot H_k \cdot \left( m + \frac{\makespan(\bP^*)}{F} \right)
        = H_k \cdot (\epsilon \cdot \tau_{\max}^* + \makespan(\bP^*))\\
        &\overset{\small (****)}{\leq} H_k \cdot (1+ \epsilon) \cdot\makespan(\bP^*)
    \end{align*}
    Here, $(*)$ holds as the algorithm chooses a path profile minimizing the makespan ampong all possible roundings, $(**)$ holds by \Cref{DPHk}, $(***)$ holds by definition of $\bar{\bP}^*$ and $(****)$ holds since we chose $\tau_{\max}^*$ as the longest arc in the optimal solution.
    \medskip

    Lastly, we show the that the running time is polynomial in $m$ and $\frac{1}{\epsilon}$.
    By the rounding, we get that $\Theta \leq m\left(m \cdot \frac{1}{\epsilon}+1\right)$.
    Thus, rounding and running the dynamic program takes $\mathcal{O}\left(m^5k^4 \left(\frac{1}{\epsilon}\right)^2\right)$.
    There are at most $m$ different rounded instances and choosing the solution with the minimal longest path takes at most $\mathcal{O}(m\log(m))$ in addition.
    Hence, the total running time is bounded by $\mathcal{O}\left( m^6k^4\left(\frac{1}{\epsilon}\right)^2\right)$.
\end{proof}
