\begin{proof}[Proof of Theorem~\ref{th:inferenceintervals}]
Let us first observe that focal sets of $m_{B|A}$ have the form of $\bigcup_{i=1}^n (a_i\times T^i)$ where $T^i\in 2^{E_B}$ for all $i=1,\dots,n$. It holds that
    \begin{equation*}
        m_{B|A}\left(\bigcup_{i=1}^n (a_i\times T^i)\right)=\prod_{i=1}^n m_{B_{a_i}}(T^i).
    \end{equation*}
    It follows that focal sets of $m_{A,B}$ have the form $\bigcup_{i:a_i\in V} (a_i\times T^i)$ for all $V\in 2^{E_A}$ and $T^i\in 2^{E_B}$. Recalling that $m_{A,B}=m_A\otimes \left(\bigotimes_i m_{B|a_i}\right)$ and applying Dempster's rule of combination, we obtain
    \begin{align*}
       & m_{A,B}\left(\bigcup_{i:a_i\in V} (a_i\times T^i)\right)=\\
       &=m_A(V)\sum_{h:a_h\notin V} \left(\sum_{T^h\in 2^{E_B}} m_{B|A}\left(\bigcup_{i=1}^n (a_i\times T^i)\right)\right)\\
       &=m_A(V)\sum_{h:a_h\notin V} \left(\sum_{T^h\in 2^{E_B}} \prod_{i=1}^n m_{B_{a_i}}(T^i) \right) \\
        &=m_A(V)\prod_{i:a_i\in V}m_{B_{a_i}}(T^i),
    \end{align*}
    where the last equality follows from the fact that $\sum_{T^h\in 2^{E_B}}m_{B_{a_h}}(T^h)=1$ which implies that indices $h:a_h\notin V$ disappear from the product.
   Expression (\ref{eq:lowboundB}) immediately follows from the definitions, and we get
    \begin{align*}
        \underline{p}^B_j&=Bel_{m_B}(\{b_j\})=m_B(\{b_j\})=\\
        &=\sum_{V\in 2^{E_A}}m_{A,B}(V\times \{b_j\})\\
        &=\sum_{V\in 2^{E_A}}  m_A(V)\prod_{i: a_i\in V} m_{B_{a_i}}(\{b_j\}) \\
        &= \sum\limits_{V\in 2^{E_A}}  m_A(V)\prod_{i: a_i\in V} \underline{p}^i_j .
    \end{align*}
The proof for (\ref{eq:upboundB}) is similar: the key is to prove that
\begin{equation*}
    Bel_{m_B}(E_B\smallsetminus\{b_j\})=\sum\limits_{V\in 2^{E_A}}  m_A(V)\prod_{i: a_i\in V} (1-\overline{p}^i_j) 
\end{equation*}
which follows from $Bel_{m_{B_{a_i}}}(E_B\smallsetminus\{b_j\})=1-\overline{p}^i_j$.
\end{proof}
\begin{proof}[Proof of Theorem~\ref{th:mobius}]
    The fact that $m_A^M(\{a_i\})=\underline{p}^A_i$ for all $i=1,\dots, n$ follows immediately from the condition of coherency \hyperref[condcoh2]{[Coh2]}.
    To prove that every subset with cardinality $2\le k \le n-2$ has zero mass we use strong induction on $k$. If $k=2$, then
    \begin{align*}
        m_A^M(\{a_i,a_j\})&=Bel_{m_A^M}(\{a_i,a_j\})-m_A^M(\{a_i\})-m_A^M(\{a_j\})\\
        &=\max \{\underline{p}^A_i+\underline{p}^A_j,1-\sum_{h\ne i,j}\overline{p}^A_h\}-\underline{p}^A_i-\underline{p}^A_j.
    \end{align*}
    Hence, it is enough to prove that $\underline{p}^A_i+\underline{p}^A_j\ge 1-\sum_{h\ne i,j}\overline{p}^A_h$,
    which is the same as showing that
    \begin{align}
        &\overline{S}_A-1-(\overline{p}^A_i-\underline{p}^A_i)-(\overline{p}^A_j-\underline{p}^A_j)\ge 0\nonumber\\
        &\Leftarrow (n-2)(1-\underline{S}_A)-(\overline{p}^A_i-\underline{p}^A_i)-(\overline{p}^A_j-\underline{p}^A_j)\ge 0 \label{salame}
    \end{align}
    where the implication follows from the fact that the probability interval is good thus $\Delta_A\ge 0$. To prove (\ref{salame}) we just note that $n\ge 4$ and
    \begin{equation} \label{condoch3_rewritten}
        \overline{p}^A_h-\underline{p}^A_h\le 1-\underline{S}_A\quad\text{for all $h=1,\dots,n$}
    \end{equation}
    which is just a rewriting of the condition of coherency \hyperref[condcoh3]{[Coh3]}. Therefore, due to the arbitrariness of $i$ and $j$, every set of cardinality $2$ has zero mass.

    Consider $V\in 2^{E_A}$ such that $2<|V|\le n-2$. From the definition of belief we have that
    \begin{align}
        m_A^M(V)&=Bel_{m_A^M}(V)-\sum_{W\subset V}m_A^M(W) \nonumber\\
        &=Bel_{m_A^M}(V)-\sum_{i:a_i\in V}m_A^M(\{a_i\})\label{salame2}\\
        &=\max\{\sum_{i:a_i\in V}\underline{p}_i^A,1-\sum_{i:a_i\notin V}\overline{p}_i^A\}-\sum_{i:a_i\in V}\underline{p}_i^A \nonumber
    \end{align}
where (\ref{salame2}) follows from the induction hypothesis. Therefore, as in the previous case, it suffices to prove that
\begin{equation*}
    \sum_{i:a_i\in V}\underline{p}_i^A\ge 1-\sum_{i:a_i\notin V}\overline{p}_i^A.
\end{equation*}
This inequality is implied by 
\begin{equation*}
    (n-2)(1-\underline{S}_A)-\sum_{i:a_i\in V}(\overline{p}^A_i-\underline{p}^A_i)\ge 0
\end{equation*}
due to the fact that $(\overline{p}^A,\underline{p}^A)$ is a good probability interval. This last inequality follows from (\ref{condoch3_rewritten}) and the fact that $|V|\le n-2$. Therefore, due to the arbitrariness of $V$, every set of cardinality $2< k \le n-2$ has mass $m_A^M$ equal to zero.

To complete the proof, it remains to show that the mass of sets with cardinality \( n-1 \) is equivalent to the standard good mass of these same sets. Using the definition of belief, we have
\begin{align}
    m_A^M(E_A\smallsetminus\{a_i\})&=Bel_{m_A^M}(E_A\smallsetminus\{a_i\})-\;\sum_{\mathclap{W\subset E_A\smallsetminus\{a_i\}}}m_A^M(W)\nonumber\\
    &=\max\{\sum_{h\ne i}\underline{p}^A_h,1-\overline{p}^A_i\}-\sum_{h\ne i}m_A^M(\{a_h\})\label{salame3}\\
    &=1-\overline{p}^A_i -\sum_{h\ne i}\underline{p}_h^A \label{salame4}
\end{align}
where (\ref{salame3}) follows from the fact that every other subset has zero mass, and (\ref{salame4}) follows from the condition of coherency \hyperref[condcoh3]{[Coh3]}.

The fact that $m_A^M(E_A)=\Delta_A$ follows from the fact that $\sum_{V\in 2^{E_A}}m_A^M(V)=1$.
\begin{align*}
    m_A^M(E_A)&=1-\sum_{i=1}^n m_A^M(\{a_i\})-\sum_{i=1}^n m_A^M(E_A\smallsetminus\{a_i\})\\
    &=\overline{S}_A+(n-2)\underline{S}_A-(n-1).
\end{align*}
\end{proof}

