To conclude this section, we give another ternary adaptation of $\CSP(C^*_{2k} \mid C_{2k})$. However, this time the non-redundancies are approaching linear. For odd $m \in \N$ define
\[
    \CYC_m := \{(x,y,z) \in (\Z/m\Z)^3 : x+y+z = 0 \wedge y-x \in \{0,1\}\}.
\]
Further define $\CYCs_{m} := \CYC_m \setminus \{(0,0,0)\}$.  See Figure~\ref{fig:CYC-m} for an illustration. We seek to prove the following
\begin{theorem}\label{thm:CYC-upper}
For all odd $m \ge 3$, we have that $\NRD(\CYCs_m, n) \le \Oh_m(n^{\frac{m}{m-1}}).$ 
\end{theorem}

\begin{remark}
This proof never uses the fact that $m$ is odd. We state it this way because the corresponding ``lower bound'' of \Cref{thm:CYC-Mal'tsev} only holds for odd $m$. In fact, for even $m \ge 2$, one can show that $\NRD(\CYCs_m) = \Oh_m(n)$ (e.g., $\CYCs_2$ is $2$-in-$3$-SAT).
\end{remark}

\begin{proof}
Similar to the proof of \Cref{thm:inf-ternary-exp}, we split the proof of our upper bound into two parts. First, we show that $\NRD(\CYCs_m\mid \CYC_m, n) = \Oh_m(n^{\frac{m}{m-1}})$. Second, we show that $\NRD(\CYC_m, n) = \Oh_m(n)$. These imply the upper bound on $\NRD(\CYCs_m, n)$ by \Cref{lem:NRD-chain}.

\paragraph{Step 1.} By \Cref{lemma:reduction:to:multipartite}, it suffices to show that a tripartite non-redundant instance $H := $ $(A_1, A_2,$ $A_3,$ $F \subseteq A_1 \times A_2 \times A_3)$ of $\CSP(\CYCs_m \mid \CYC_m)$ has at most $\Oh_m(n^{\frac{m}{m-1}})$ hyperedges.

First, notice that $H$ is a \emph{linear} hypergraph; that is, no two hyperedges overlap in exactly two vertices. Assume for sake of contradiction that $e = (x_1, x_2, x_3)$ and $f = (y_1, y_2, y_3)$ have two vertices in common. Since $H$ is non-redundant, there must be a map that sends $e$ to $(0,0,0)$ but $f$ to some element of $\CYCs_m$. However, $\CYCs_m$ lacks any elements with two or more zeros, a contradiction.

Since $H$ is a linear hypergraph, we may define $E := \{(x_1, x_2) : \exists x_3 \in A_3, (x_1, x_2, x_3) \in F\}$ and note that $|E| = |F|$. Thus, by \Cref{cor:C2k} and \Cref{rem:tC2k}, it suffices to prove that $G := (A_1, A_2, E)$ is a non-redundant instance of $\CSP(\widetilde{C}_{2m}^* \mid \widetilde{C}_{2m})$.

For any $e := (x_1, x_2, x_3) \in F$ let $f_e : A_1 \cup A_2 \cup A_3 \to \{0,1,\hdots, m-1\}$ be the homomorphism which maps $H$ to $\CYC_m$ but $e$ is the only hyperedge mapped to $(0,0,0)$. Note that $\widetilde{C}^*_{2m} = \{(z_1,z_2) : \exists z_3, (z_1,z_2,z_3) \in \CYC_m\}$. Therefore, $f_e$ restricted to $A_1 \cup A_2$ is a homomorphism from $G$ to $\widetilde{C}_{2m}$ which only maps $(x_1,x_2)$ to $(0,0)$. Thus, $G$ is a non-redundant instance of $\CSP(\widetilde{C}_{2m}^* \mid \widetilde{C}_{2m})$, as desired.

\paragraph{Step 2.} To finish, we show that $\NRD(\CYC_m, n) = \Oh_m(n)$. We do this by constructing an explicit Abelian embedding of $\CYC_m$. Let $D := \Z/m\Z$ and consider the group $G = (\Z/2\Z)^D$ which we identify with the set of subsets of $D$ equipped with the symmetric difference operator $\oplus$. Furthermore, we identify each element $i \in D$ with its singleton $\{i\} \in G$. 

Let $Q$ be the subgroup of $G^3$ generated by the elements of $\CYC_m$. By definition, $\CYC_m \subseteq Q \cap D^3$. We claim that $\CYC_m = Q \cap D^3$. Consider any triple $(a_1,a_2,a_3) \in D^3$ such that there exists a subset $S \subseteq \CYC_m$ such that 
\[
    (\{a_1\}, \{a_2\}, \{a_3\}) = \bigoplus_{(b_1,b_2,b_3) \in S} (\{b_1\}, \{b_2\}, \{b_3\}).
\]
A key observation is the following. For any $T \subseteq \widetilde{C}_{2m}$, consider the analogous expression $(B_1, B_2) := \bigoplus_{(b_1, b_2) \in T} (\{b_1\}, \{b_2\})$. If we interpret $T$ as a collection of paths in $\widetilde{C}_{2m}$, then $B_1$ and $B_2$ are precisely the sets of endpoints of the paths (restricted to the two halves of the bipartite graph). Thus, since $\CYC_m$ restricted to its first two coordinates is precisely $\widetilde{C}_{2m}$, the projection of $S$ to its first two coordinates must correspond precisely to a path between $a_1$ (on the left) and $a_2$ (on the right) in $\widetilde{C}_{2m}$. Since each tuple of $\CYC_m$ is uniquely determined by its first two coordinates, we have narrowed down $S$ to the following two possibilities:
\begin{align*}
S_0 &:= \{(a_1, a_1, -2a_1), (a_1-1, a_1, -2a_1+1), (a_1-1, a_1-1, -2a_1+2), \hdots, (a_2, a_2, -2a_2)\}\\
S_1 &:= \{(a_1, a_1+1, -2a_1-1), (a_1+1, a_1+1, -2a_1-2), \hdots, (a_2-1, a_2, -2a_2+1)\}
\end{align*}
One can verify that $\bigoplus_{(b_1,b_2,b_3) \in S_i} (\{b_1\}, \{b_2\}, \{b_3\})$ gives the same value for $i \in \{0,1\}$. Note that $S_0 \sqcup S_1$ is a partition of $\CYC_m$. Thus, at least one of $S_0$ or $S_1$ has cardinality at most $m$. Notice that the third coordinate of $S_0$ increases by $1$ for each successive tuple, and the third coordinate of $S_1$ decreases by $1$ for each successive tuple. Thus, for the set $S_i$ of size at most $m$, the expression $\bigoplus_{(b_1,b_2,b_3) \in S_i} (\{b_1\}, \{b_2\}, \{b_3\}).$ will sum $|S_i|$ distinct values in the third coordinate. The only way this can equal $\{a_3\}$ is for $|S_i| = 1$ and $S_i = \{(a_1, a_2, a_3)\}$. Thus, $(a_1,a_2,a_3) \in \CYC_m$, as desired. 

%

Thus, we have proven that $\CYC_m$ has an Abelian group embedding, so $\NRD(\CYC_m, n) \le \Oh_m(n)$.
%
\end{proof}

\begin{remark}
The argument used in Step 1 can be interpreted as a special case of Theorem~\ref{thm:fgppp-nrd} with the fgppp-definition of $(\CYCs_{m}\mid\CYC_m)(x_1,x_2,x_3) \equiv (\widetilde{C}^*_{2m}\mid \widetilde{C}_{2m})(x_1,x_2)$.
\end{remark}

%

\begin{remark}
One can check that $\CYCs_{3} = \{111,222,012,120,201\}$ which is equal to the $\BCK$ predicate first considered by \cite{bessiere2020Chain}. The best upper bound on $\NRD(\BCK, n)$ in the literature is $\Oh(n^{1.5}\log n)$ by \cite{brakensiek2024Redundancy}. Theorem~\ref{thm:CYC-upper} mildly improves this upper bound to $\Oh(n^{1.5})$. %
\end{remark}

Sadly, we do not know of a nontrivial lower bound for the non-redundancy $\CYCs_m$. However, we give evidence that a nontrivial lower bound should exist by proving that $\CYCs_m$ lacks a Mal'tsev embedding.

\begin{theorem}\label{thm:CYC-Mal'tsev}
For all odd $m \ge 3$, $\CYCs_m$ lacks a Mal'tsev embedding. 
\end{theorem}

The proof of Theorem~\ref{thm:CYC-Mal'tsev} is rather technical as it first requires developing new properties about the operators in an algebra with a Mal'tsev term. As such, we defer the proof of Theorem~\ref{thm:CYC-Mal'tsev} to Section~\ref{subsec:excl}.

\section{An Algebraic Theory of Fine-Grained Reductions for Promise Relations}\label{sec:theory}

In this section we develop a novel algebraic theory for studying conditional non-redundancy. It turns out that the fundamental algebraic object are {\em partial polymorphisms} between relation pairs $(S,T)$. This polymorphism notion merges and generalizes the following two notions.

\begin{enumerate}
    \item 
    Polymorphisms between relation pairs $(A,B)$ that have been fundamental in studying the approximation variant of CSP known as {\em promise CSP}~\cite{brakensiek2021Promise,barto2021Algebraica}.
    \item 
    Partial polymorphisms of relations that have been used to study fine-grained complexity questions~\cite{lagerkvist2021Coarse}, kernelization~\cite{lagerkvist2020Sparsification}, and non-redundancy~\cite{bessiere2020Chain,carbonnel2022Redundancy}.
\end{enumerate}

We begin in Section~\ref{subsec:galois} by proving that our partial polymorphism notion on the functional side yields sets of partial functions closed under the formation of {\em minors}. On the relational side we instead get {\em quantifier-free} primitive positive definitions, and we obtain a full Galois correspondence between these notions. Moving up one abstraction level we in Section~\ref{sec:patterns} describe {\em identities} satisfied by partial promise polymorphisms and the corresponding relational objects, {\em $c$-tupled functionally guarded primitive positive definitions}, in Section~\ref{sec:fgpp}. We explore connections to conditional non-redundancy in Section~\ref{sec:gadget_reductions} and prove that the partial polymorphisms from $S$ to $\widetilde{T} = D^r \setminus (T \setminus S)$ indeed correlate with $\NRD(S \mid T, n)$ for relations $S \subseteq T \subseteq D^r$. As such, they are sometimes said to be {\em conditional polymorphisms} of $(S,T)$.
Finally, in Section~\ref{sec:cube-power} we consider a class of identities that are particularly important for establishing lower bounds on non-redundancy.

%

%

    \subsection{A Galois Connection} \label{subsec:galois}
    We begin by developing a Galois connection between sets of partial functions closed under the formation of {\em minors} and sets of relations closed under a certain type of conjunctive formulas. Throughout, we assume that all domains $D_1$ and $D_2$ are finite, although many concepts generalize to e.g.\ {\em $\omega$-categorical} structures.
    A {\em relation pair} over finite domains $D_1$ and $D_2$ is a tuple $(S, T)$ where $S \subseteq D_1^r$ and $T \subseteq D_2^r$  for some $r \geq 0$ (note that $D_1^0 = D_2^0 = \emptyset$). If, in addition,  there exists a homomorphism $h \colon D_1 \to D_2$, i.e., $h(t) \in T$ for each $t \in S$ then $(S,T)$ is said to be a {\em promise relation}, and is sometimes written $(S,T, h)$. A {\em promise language} is a set of relation pairs where there exist $h \colon D_1 \to D_2$ such that $(S,T, h)$ is a promise relation for each relation pair $(S,T)$, and a {\em language} is simply a set of relation pairs. Note that all relation pairs in a language might not have the same arity. In the forthcoming applications we often assume that $D_1 \subseteq D_2$ in which case $h$ can always be defined as the identity function $h(x) = x$ over $D_1$. If the domain for a promise relation $(S,T)$ is not specified we always assume that $S \subseteq T$. We often write $(\cla, \clb)$ for a language and thus write $(S,T) \in (\cla, \clb)$ to denote a specific relation pair.

Let $D_1$ and $D_2$ be two finite sets. An $n$-ary {\em partial function} from $D_1$ to $D_2$ is a map $f \colon X \to D_2$ for $X \subseteq D_1^n$, and we write $\dom(f) = X$ for the set of values where $f$ is defined. We frequently express $x \notin \dom(f)$ by $f(x) = \bot$. A {\em subfunction} of $f$ is a partial function $g$ where $\dom(g) \subseteq \dom(f)$ and such that $g(\mathbf{x}) = f(\mathbf{x})$ for every $\mathbf{x} \in \dom(g)$.
%
%
%
We write $\pi^n_i$ for the $i$-ary {\em projection}, in approximation contexts often called {\em dictator} satisfying $\pi^n_i(\mathbf{x}) = \mathbf{x}_i$. The domain is usually taken from the context and not explicitly denoted. A {\em partial projection} (or {\em partial dictator}) is a subfunction of a projection. When $D_1 = D_2 = D$ then it is natural to combine functions in the following sense: 
for an $n$-ary partial function $f$ and $m$-ary partial functions $g_1, \ldots, g_n$ over the same universe $D$ we define composition of $f, g_1, \ldots, g_n$ as \[(f \circ (g_1, \ldots, g_n))(x_1, \ldots, x_m) = f(g_1(x_1, \ldots, x_m), \ldots, g_n(x_1, \ldots, x_m))\] for all sequences of arguments $x_1, \ldots, x_m \in A$ such that (1) each $(x_1, \ldots, x_m) \in \dom(g_i)$ and (2) $g_1(x_1, \ldots, x_m), \ldots, g_n(x_1, \ldots, x_m) \in \dom(f)$. Composition of total functions is then just a special case when all involved functions $f, g_1, \ldots, g_n$ are total, i.e., $\dom(f) = D^n$ and each $\dom(g_i) = D^m$. For a set of (total or partial) functions $F$ over $A$ we write $[F]$ for the smallest set of (total or partial) functions over $A$ which contains $F$, is closed under composition, and which contains all (total or partial) projections. Such sets are sometimes called (strong partial) {\em clones} and naturally correspond to the term algebra induced by a given algebra.

%

When working with partial functions from $D_1$ to $D_2$ it is generally not possible to compose functions, and the relevant algebraic closure condition is instead formation of {\em partial minors}.

\begin{definition}
A $n$-ary (variable-identification) {\em minor} $f_{/h}$ of an $m$-ary partial function $f \colon X \to D_2$, where $h \colon [m] \to [n]$, is a function of the form $f_{/h}(x_1, \ldots, x_n) = f(x_{h(1)}, \ldots, x_{h(m)})$.    
\end{definition}

We now define a {\em partial minor}, often just called a {\em minor}, $g$ of $f$ as a subfunction of $g'$ for a variable identification minor $g'$ of $f$ (observe that $g'$ is technically a subfunction of itself, so any variable identification minor is also a minor). 

\begin{definition}
A set of partial functions $F$ from $D_1$ to $D_2$ is said to be a {\em strong partial minion} if it is closed under minors, i.e., if $f \in F$ and $g$ is a minor of $f$ then $g \in F$. We write $\minor{F}$ for the smallest strong partial minion that contains $F$.
\end{definition}

Note that the subfunction condition in the definition of a partial minor clearly sets apart strong partial minions from minions of total functions and prevents the former to be defined under the unifying umbrella of {\em abstract minions}~\cite{brakensiek2020Powera}. %
%
However, we will see that many notions carry over to the partial setting and that strong partial minions can be described via relations.
%
Thus, we say that an $n$-ary partial function $f \colon \dom(f) \to D_2$ is a {\em partial polymorphism} of an $r$-ary relation pair $(S,T)$ if, for each sequence $x^{(1)}, \ldots, x^{(n)} \in S$, either

\begin{enumerate}
    \item 
    there exists $1 \leq i \leq r$ such that $(x^{(1)}_i, \ldots, x^{(n)}_i) \notin \dom(f)$, or
    \item 
    $(f(x^{(1)}_1, \ldots, x^{(n)}_1), \ldots, f(x^{(1)}_r, \ldots, x^{(n)}_r)) \in T$.
\end{enumerate}

Similarly, $f$ is a partial polymorphism of a language $(\cla, \clb)$ if it is a partial polymorphism of every $(S,T) \in (\cla, \clb)$, in which case we also say that $(\cla, \clb)$ is {\em invariant} under $f$.

%

\begin{definition}
For a language $(\cla, \clb)$ we let $\pPol(\cla, \clb)$ be the set of all partial polymorphisms from $\cla$ to $\clb$.
\end{definition}

If $(\cla, \clb) = \{(S,T)\}$ is singleton then we write $\pPol(S,T)$ rather than $\pPol(\{(S,T)\})$, and if $\cla = \clb$, simply $\pPol(\cla)$. Let us also remark that sets of the form $\pPol(\cla)$ are closed under functional composition as well as subfunctions.

%
%
%

\begin{definition}
    For a set of partial functions $F$ from $D_1$ to $D_2$ we let \[\inv(F) = \{(S,T) \mid r \geq 0, S \subseteq D_1^r, T \subseteq D_2^r, F \subseteq \pPol(S,T)\}.\]
\end{definition}

We observe that $\inv(F)$ is a promise language if $\minor{F}$ contains at least one unary, total function.

Let us now relate the $\inv(\cdot)$ and $\pPol(\cdot)$ operators together as follows. To simplify the definition we temporarily work in the setting of relational structures in a prescribed signature $\tau$ containing relation symbols and their associated arities.
A {\em quantifier-free primitive positive formula} (qfpp-formula) over a relational signature $\tau$ is a conjunctive formula $\varphi(x_1, \ldots, x_r)$ with free variables $x_1, \ldots, x_r$ where each atom is of the form $R_i(\mathbf{x}^i)$ (for some $(R_i, r_i) \in \tau$ and $r_i$ tuple of variables $\mathbf{x}^i$), an equality of the form $x = y$, for $x,y \in \{x_1, \ldots, x_r\}$, or $\mathsf{f}(x_i)$ for some $x_i \in \{x_1, \ldots, x_r\}$, where $\mathsf{f}$ is a special notation for the empty unary relation. Each combination of a qfpp-formula $\varphi(x_1, \ldots, x_n)$ and a $\tau$-structure $\cla$ induces a relation $\{(a_1, \ldots, a_r) \mid \varphi^{\cla}(a_1, \ldots, a_r)\}$, where equality $=$ is interpreted in the obvious way, and where $\sf{f}$ is interpreted as $\emptyset$. The sole reason for introducing $\sf{f}$ is that the relation pair $(\emptyset, \emptyset)$ is invariant under every partial polymorphism and thus should always be definable. In the literature one sometimes assumes the existence of a symbol $\sf{t}$ always interpreted as the full relation, but note that we can simulate a constraint $\sf{t}$ via an equality constraint $x = x$. 
%
%

We lift this notion to relation pairs as follows.
Let $(\cla, \clb)$ be a language over $D_1, D_2$ and $(\cla', \clb')$ a language over $D_1, D_2$. We say that $(\cla', \clb')$ is 

\begin{enumerate}
    \item {\em quantifier-free primitive positive definable} (qfpp-definable) in $(\cla, \clb)$ if, for each relational symbol $R$ (of arity $r$) of $(\cla', \clb')$, there is a qfpp-formula $\varphi_R$  such that
    \[
    R^{\cla'} = \{(a_1, \ldots, a_{r}) \in D_1^{r} \mid \varphi^{\cla}_R(a_1, \ldots, a_{r})\},
    \]  
    and, similarly, 
    \[
        R^{\clb'} = \{(a_1, \ldots, a_{r}) \in D_2^{r} \mid \varphi^{\clb}_R(a_1, \ldots, a_{r})\},  
    \]

    \item a {\em strict relaxation} of $(\cla, \clb)$ if $\cla, \cla', \clb, \clb'$ are similar relational structures and, for every relational symbol $R$,
    \[
    R^{\cla'} \subseteq R^{\cla} \quad \text{and} \quad R^{\clb} \subseteq R^{\clb'}.
    \]
\end{enumerate}

More generally $(\cla, \clb)$ is {\em quantifier-free primitive positive promise definable} (qfppp-definable) in $(\cla', \clb')$ if the former can be obtained by a sequence of qfpp-definitions and strict relaxations of the latter.
We write $\qfppp{\cla, \clb}$ for the smallest set of relation pairs containing $(\cla, \clb)$ and which is closed under qfppp-definitions, and similarly to the $\pPol(\cdot, \cdot)$  operator write $\qfppp{S,T}$ for a singleton language $(\cla, \clb) = \{(S,T)\}$. 

\begin{lemma} \label{lemma:is_a_minion}
    Let $(\cla, \clb)$ be a language. Then 
    $\pPol(\cla, \clb)$ is a strong partial minion ($\pPol(\cla, \clb) = \minor{\pPol(\cla, \clb)}$).
\end{lemma}

\begin{proof}
The inclusion $\pPol(\cla, \clb) \subseteq \minor{\pPol(\cla, \clb)}$ is trivial since every partial function is a minor of itself. For the other direction, let $g$ be an $n$-ary minor of an $m$-ary $f \in \pPol(\cla, \clb)$, i.e., $g$ is a subfunction of a variable-identification minor $f_{/h}$ of $f$ for some $h \colon [m] \to [n]$. For each $(S,T) \in (\cla, \clb)$ it follows that each application $f_{/h}(t^{(1)}, \ldots, t^{(m)})$ for $t^{(1)}, \ldots, t^{(m)} \in S$ is equivalent to $f$ applied as $f(t^{h(1)}, \ldots, t^{h(m)})$, which is either undefined or included in $T$. Hence, $f_{/h}$ preserves $(S,T)$. Similarly, it is easy to see that any subfunction $g$ of $f_{/h}$ also preserves any relation invariant under $f_{/h}$, and we conclude that $\pPol(\cla, \clb) = \minor{\pPol(\cla, \clb)}$.
 %
\end{proof}

Note that if $(\cla, \clb)$ over $D_1, D_2$ is a promise language, witnessed by a function $h \colon D_1 \to D_2$, then $h \in \pPol(\cla, \clb)$, but if $(\cla, \clb)$ is not a promise language then we are not guaranteed the existence of a total, unary function in $\pPol(\cla, \clb)$.

\begin{lemma} \label{lemma:is_qfpp_closed}
Let $D_1$ and $D_2$ be two finite sets. Then $\qfppp{\inv(F)} = \inv(F)$ for any set $F$ of partial functions from $D_1$ to $D_2$. 
\end{lemma}

\begin{proof}
    The inclusion $\inv(F) \subseteq \qfppp{\inv(F)}$ is trivial since any relation can qfpp-define itself. For the other direction, consider relation symbols $R$ of arity $r$ and $R'$ of arity $r'$, interpreted by $R^{\cla}, R'^{\cla}$ in $\cla$ over $D_1$ and $R^{\clb}, R'^{\clb}$ over $D_2$, and the following qfpp-definitions $\varphi$.
    \begin{enumerate}
    \item 
     $R(x_1, \ldots, x_r) \land \mathsf{f}(x_i)$  for some $x \in [r]$. In this case the statement is trivial.
    \item
      $R(x_1, \ldots, x_r) \land (x_i = x_j)$ for $i,j \in [r]$. Then $\varphi^{\cla} = \{(d_1, \ldots, d_r) \mid (d_1, \ldots, d_r) \in S, d_i = d_j\}$  and $\varphi^{\clb} = \{(d_1, \ldots, d_r) \mid (d_1, \ldots, d_r) \in R^{\clb}, d_i = d_j\}$. Consider an $n$-ary $f \in F$ and an application $f(t^{(1)}, \ldots, t^{(n)}) = t$ for $t^{(1)}, \ldots, t^{(n)} \in \varphi^{\cla}$ where every application $f(t^{(1)}_k, \ldots, t^{(n)}_k)$, $1 \leq k \leq r$, is defined. Observe that $t_i = t_j$, i.e., the $i$th element of $t$ equals the $j$th element of $t$, which implies that $t \in \varphi^{\clb}$ (since $t \in R^{\clb}$).
    \item
      $R(x_{h(1)}, \ldots, x_{h(r)})$ for $h \colon [r] \to [s]$ for some $s \geq 1$. We sketch the most important arguments. Note that one for each $(d_1, \ldots, d_s) \in \varphi^{\cla}$ (respectively, $\varphi^{\clb}$) can define a corresponding tuple $(d_{h(1)}, \ldots, d_{h(r)}) \in \varphi^{\cla}$ (respectively, $\varphi^{\clb}$). Thus, if $f(t^{(1)}, \ldots, t^{(n)}) = t$  for some $n$-ary $f \in F$ and $t^{(1)}, \ldots, t^{(n)} \in \varphi^{\cla}$ then one can define tuples which when applied to $f$ yields a tuple in $\varphi^{\clb}$.
    \item
      $R(x_{h(1)}, \ldots, x_{h(r)}) \land R'(x_{h'(1)}, \ldots, x_{h'(r')})$ for $h \colon [r] \to X$ and $h' \colon [r'] \to Y$. First, assume that $X \cap Y = \emptyset$, i.e., the two constraints have no overlapping variables. Then $\varphi^{\cla}$ (respectively, $\varphi^{\clb}$) is simply the Cartesian product of two relations that are invariant under $F$ from the preceding case, and the claim easily follows. Similarly, if $X = Y$ then the resulting relation is the intersection of two invariant constraints. The general case follows via similar arguments. 
    \end{enumerate}
This generalizes to arbitrary qfpp-definitions via a simple inductive argument.
Last, consider a strict relaxation $(S',T')$ of some $(S,T) \in \inv(F)$, i.e., $S' \subseteq S$ and $T' \supseteq T$. Assume there exists an $n$-ary $f \in F$ and tuples $t^{(1)}, \ldots, t^{(n)} \in S' \subseteq S$ such that $f(t^{(1)}, \ldots, t^{(n)}) = t \notin T'$. It follows that $f$ does not preserve $(S,T)$, either, since $t^{(1)}, \ldots, t^{(n)} \in S \supseteq S'$ and since $t \notin T \subseteq T'$.
    %
    %
    %
     %
    %
   %
   %
   %
   %
   %
\end{proof}

With similar arguments we obtain the following two characterizations.

\begin{lemma} \label{lemma:ppol_preserves_qfpp}
Let $(\cla, \clb)$ be a language. Then $\pPol(\qfppp{\cla, \clb}) = \pPol(\cla, \clb)$.
\end{lemma}

\begin{lemma} \label{lemma:minors_preserve_relations}
Let $F$ be a set of partial functions over $A,B$. Then $\inv(F) = \inv(\minor{F})$.
\end{lemma}

To complete our description we additionally need the following two lemmas.

\begin{lemma} \label{lemma:pippenger1} 
  Let $F$ be a strong partial minion over domains $D_1$, $D_2$. For any partial function $g \colon X \to D_2$ (for some $n \geq 1$ and $X \subseteq D_1^n$) where $g \notin F$ there 
  \begin{enumerate}
  \item 
        exists a relation pair $(S,T)$ such that $F \subseteq \pPol(S,T)$ and $g \notin \pPol(S,T)$, and
      \item 
      if $F$ contains a unary, total function $h$ then $(S,T)$ is a promise relation.
  \end{enumerate}
  %
\end{lemma}

\begin{proof}
  First, consider the relation $S = \{t^{(1)}, \ldots, t^{(n)}\}$ whose arguments (in, say, lexicographical order) enumerates the domain $X$ of $g$, i.e., for the $i$th tuple $t \in X$ we have that $(t^{(1)}_i, \ldots, t^{(n)}_i) = t$. Second, consider the relation $T$ formed by, for every $f \in F$ of arity $m$, and all tuples $t^{(i_1)}, \ldots, t^{(i_m)} \in S$, adding $f(t^{(i_1)}, \ldots, t^{(i_m)})$ whenever each application is defined. 
  %

  By definition, $g$ cannot preserve $(S,T)$ since it would then be equivalent to a partial function in $F$. Similarly, by construction, $(S,T)$ is invariant under every function in $F$. Note that if $F$ contains a unary, total function $h$, then by construction, $h$ is a homomorphism from $S$ to $T$, and $(S,T)$ is thus a promise relation.
\end{proof}  

\begin{lemma} \label{lemma:pippenger2}
    Let $(\cla, \clb)$ be a  language. Let $(S,T)$ be a  relation pair over $A,B$ such that $(S,T) \notin \qfppp{\cla, \clb}$. Then there exists $f \in \pPol(\cla, \clb)$ such that $f \notin \pPol(S, T)$.
\end{lemma}

\begin{proof}
This follows from Proposition 2.5 in Pippenger~\cite{pippenger2002} since the construction does not use existential quantification.
\end{proof}

We may now conclude that sets of the form $\inv(\pPol(\cla, \clb))$ are precisely the sets containing $(\cla, \clb)$ closed under qfppp-definitions, and, similarly, that all strong partial minions $\minor{F}$ can be described as the set of polymorphisms of the relations invariant under $F$ ($\pPol(\inv(F))$).

\begin{theorem}
    Let $(\cla, \clb)$ be a language over $D_1, D_2$. Then $\qfppp{\cla, \clb} = \inv(\pPol(\cla, \clb))$.
\end{theorem}

\begin{proof}
The first direction follows from Lemma~\ref{lemma:ppol_preserves_qfpp}. Second, let $(S,T) \in \inv(\pPol(\cla, \clb))$. If $(S,T) \notin \qfppp{\cla, \clb}$ then Lemma~\ref{lemma:pippenger2} implies that there is $f \in \pPol(\cla, \clb)$ such that $f \notin \pPol(S,T)$, contradicting that $(S,T)$ is invariant under every partial function in $\pPol(\cla, \clb)$.
\end{proof}

\begin{theorem}
Let $F$ be a set of partial functions from $D_1$ to $D_2$. Then $\minor{F} = \pPol(\inv(F))$.
\end{theorem}

\begin{proof}
First, let $f \in \minor{F}$. Then $f$ preserves every relation in $\inv(F)$ (by Lemma~\ref{lemma:minors_preserve_relations}). Second, let $f \in \pPol(\inv(F))$. If $f \notin \minor{F}$ then Lemma~\ref{lemma:pippenger1} implies that there is $(S,T)$ such that $\minor{F} \subseteq \pPol(S,T)$ but $f \notin \pPol(S,T)$, i.e., $(S,T) \in \inv(F)$, contradicting the assumption that $f \in \pPol(\inv(F))$.
\end{proof}

By combining everything together thus far we obtain a Galois connection between $\inv(\cdot)$ and $\pPol(\cdot, \cdot)$ which implies the following duality.

\begin{theorem} \label{thm:galois}
    Let  $(\cla, \clb)$ and  $(\cla', \clb')$ be languages over $D_1, D_2$. Then \[\pPol(\cla, \clb) \subseteq \pPol(\cla', \clb') \]
if and only if 
\[ (\cla', \clb') \subseteq \qfppp{\cla, \clb}.\]
\end{theorem}

\begin{proof}
      First, assume that $\pPol(\cla, \clb) \subseteq \pPol(\cla', \clb')$. Assume there exists $(S,T) \in (\cla', \clb')$ such that $(S,T) \notin \qfppp{\cla, \clb}$. By Lemma~\ref{lemma:pippenger2} there exists $f \in \pPol(\cla, \clb)$ such that $f \notin \pPol(S,T) \supseteq \pPol(\cla', \clb')$, contradicting the assumption that $\pPol(\cla, \clb) \subseteq \pPol(\cla', \clb')$.

        For the other direction, assume that $(\cla', \clb') \subseteq \qfppp{\cla, \clb}$. Assume there exists $f \in \pPol(\cla, \clb)$ such that $f \notin \pPol(\cla', \clb')$, and let $(S,T) \in (\cla', \clb')$  be a promise relation witnessing this, i.e., $f \notin \pPol(S,T))$. 
  By assumption, $(S,T) \in \qfppp{\cla, \clb}$, and 
  Lemma~\ref{lemma:ppol_preserves_qfpp} then implies that $\pPol(\cla, \clb) = \pPol(\qfppp{\cla, \clb}) \subseteq \pPol(S,T)$, contradicting the assumption that $f \in \pPol(\cla, \clb)$.
\end{proof}

Recall that for a promise relation $(S, T)$ over $D$ we write $\widetilde{T}$ for  $D^r \setminus (T \setminus S)$. We can now prove that the conditional non-redundancy of a relation is determined by the partial polymorphisms from $S$ to $\widetilde{T}$, i.e., we are interested in partial polymorphisms $f$ such that if $f(t_1, \ldots, t_n) = t$ is defined then $t \in S$ {\em if} $t \in T$. 

\begin{proposition}\label{prop:gadget-nrd}
Let $(S_1, T_1)$ and $(S_2, T_2)$ be promise relations over a domain $D$. If  $\pPol(S_2, \widetilde{T_2}) \subseteq \pPol(S_1, \widetilde{T_1})$ then $\NRD(S_1 \mid T_1, n) = \Oh(\NRD(S_2 \mid T_2, n))$.
\end{proposition}

\begin{proof}
We provide a proof sketch since this proposition is superseded by Theorem~\ref{thm:fgppp-nrd} in Section~\ref{sec:gadget_reductions}, and ignore handling relaxations and equality constraints. First, via Theorem~\ref{thm:galois} the condition that $\pPol(S_1, \widetilde{T_1}) \subseteq \pPol(S_2, \widetilde{T_2})$ implies that $(S_2, T_2)$ qfpp-defines $(S_1, T_1)$. 
Consider a conditional non-redundant instance $(X,Y)$ of $\CSP(S_1 \mid T_1)$ on $n$ variables. We replace every constraint of $S_1$ with the corresponding constraints of $S_2$, as prescribed by the witnessing qfpp-definition. For each constraint $y \in Y$, there then exists an assignment $\sigma_y : X \to D$ for which $\sigma_y(y') \in T_1$ for all $y' \in Y \setminus \{y\}$ but $\sigma_y(y) \in T_1 \setminus S_1$. 

In particular, $\sigma_y$ will $S_2$-satisfy every constraint which replaces each $y' \in Y \setminus \{y\}$. However, for the clauses replacing $y$, we have that
\[
    0 = (D^r \setminus (T_1 \setminus S_1))(\sigma_y(y)) = \bigwedge_{i=1}^t (D^r \setminus (T_2 \setminus S_2))(\sigma_y(y|_{S_i})).
\]
Thus, complementing both sides, we then have that
\[
    1 = (T_2 \setminus S_2)(\sigma_y(y)) = \bigvee_{i=1}^t (T_1 \setminus S_1)(\sigma_y(y|_{S_i}))
\]
and at least one of the constraints replacing $y$ will have $\sigma_y$ assign it to some value in $T_1 \setminus S_1$. Pick one such clause arbitrarily for each $y \in Y$. The $\sigma_y$'s witness that the resulting instance is non-redundant for $\CSP(S_1 \mid T_1)$.
\end{proof}

From now on, we primarily work in the signature-free setting and when specifying that an $r$-ary relation $R$ over $D$ is definable via a combination of a qfpp-formula $\varphi_R$ and a structure $\Gamma$ over $D$ as $R = \{(a_1, \ldots, a_r) \in D^r \mid \varphi^{\Gamma}_{R}(a_1, \ldots, a_r)\}$ we express this as
\[R(x_1, \ldots, x_r) \equiv \varphi^{\Gamma}_R(x_1, \ldots, x_r)\]
and do not make a sharp distinction between structures $\Gamma$ and sets of relations $\Gamma$.

\subsection{Polymorphism Patterns}
\label{sec:patterns}

Fully describing $\pPol(\cla, \clb)$ even for Boolean promise languages $(\cla, \clb)$ appears to be out of reach with current algebraic methods. Fortunately, we can abstract away specific operations and concentrate on {\em identities} satisfied by the operations instead, similar to
the universal algebraic approach for studying classical complexity of (P)CSPs where one typically looks only at {\em linear} identities $f(x_1, \ldots, x_n) \approx g(y_1, \ldots, y_m)$~\cite{barto2017Polymorphisms}. However, the identities relevant in our setting have an even more restricted form where the right-hand side consists of a single variable, and can concisely be defined as follows in the signature-free setting.  %

\begin{definition}
    An $n$-ary {\em polymorphism pattern} over a set of variables $V$ for $n \geq 1$ is a subset of $\{(t,x) \mid t = (x_1, \ldots, x_n) \in V^n, x \in V\}$.
\end{definition}

\begin{example} \label{ex:maltsev}
A {\em Mal'tsev} term $\phi$ can be defined by $P = \{((x,x,y), y), ((y,x,x), y)\}$ over $V = \{x,y\}$ and a {\em majority} term can be defined by $P' = \{((x,x,y), x), ((x,y,x), x), ((y,x,x), x)\}$.
%
%
\end{example}

\begin{definition}
    Let $D$ be a set and let $P$ be an $n$-ary polymorphism pattern. 
    We define $\interpretation{D}{P}$ as the set of $n$-ary partial functions $f$ such that:
    \begin{enumerate}
            \item 
            if $((x_1, \ldots, x_n), x) \in P$ where $x \in \{x_1, \ldots, x_n\}$, then for every $g \colon \{x_1, \ldots, x_n\} \to D$ we have  \[f(g(x_1), \ldots, g(x_n)) = g(x),\]
            \item 
        if $((x_1, \ldots, x_n), y) \in P$ where $y \notin \{x_1, \ldots, x_n\}$ then $(g(x_1), \ldots, g(x_n)) \in \dom(f)$ for every $g \colon \{x_1, \ldots, x_n\} \to D$, and
    \end{enumerate}
     which is undefined otherwise.
\end{definition}

Functions in $\interpretation{D}{P}$ are sometimes called {\em pattern polymorphisms}.

\begin{example} \label{ex:interpretation}
    If we revisit Example~\ref{ex:maltsev} then for the Mal'tsev term $P = \{((x,x,y), y), (y,x,x), y)\}$ we have $\interpretation{P}{\{0,1\}} = \{m\}$ for 
    \begin{enumerate}
        \item 
        $m(1,1,0) = m(0,1,1) = m(0,0,0) = 0$, and
        \item 
        $m(0,0,1) = m(1,0,0) = m(1,1,1) = 1$, 
    \end{enumerate}
    and which is undefined for $(0,1,0)$ and $(1,0,1)$. Note that this function is {\em idempotent} and {\em self-dual} in the sense that negating the input variables corresponds to negating the output. 
    %

    In contrast, for $P' = \{((x,x,y), x), ((x,y,x), x), ((y,x,x), x)\}$ we get $\interpretation{P'}{\{0,1\}} = \{m'\}$ where $m'$ is the totally defined majority function on the Boolean domain. However, for any $D$ with at least three elements  $\interpretation{P'}{D}$ will contain a properly partial function.
\end{example}

If $\interpretation{D}{P} = \emptyset$ then $P$ is {\em inconsistent} over $D$ and if $\interpretation{D}{P}$ contains all $n$-ary functions over $D$ then $P$ is said to be {\em trivial} over $A$. A pattern which is not inconsistent is simply said to be {\em consistent}.
We observe that for a consistent pattern $P$ we have $|\interpretation{D}{P}| = 1$ {\em unless} $P$ contains an identity $((x_1, \ldots, x_n), y)$ for $y \notin \{x_1, \ldots, x_n\}$, in which case this identity induces $|D|$ different partial functions $f_1, \ldots, f_{|A|}$ where $f_i(g(x_1), \ldots, g(x_n)) = i$ for every $g \colon \{x_1, \ldots, x_n\} \to D$. In other words the specific value for this identity is arbitrary, and can be uniquely defined as a {\em multifunction} $f$ such that $f(g(x_1), \ldots, g(x_n)) = D$. However, to avoid overloading the technical machinery more than needed, we stick with the viewpoint that $\interpretation{A}{P}$ is a set of functions.
We remark that patterns $P$ such that $|\interpretation{D}{P}|>1$ are typically too restrictive to be interesting in the general setting, but they are relevant in the multisorted setting discussed below. 
%

We proceed by relating $\interpretation{D}{P}$ to the property of {\em commuting} with all maps which, intuitively, shows that the domain of any function in $\interpretation{D}{P}$ is highly symmetric.

\begin{definition}
    Let $f$ be an $n$-ary partial function over $D$ and let $g \colon D \to D$ be a unary map. We say that $f$ {\em commutes} with $g$ if $f(g(x_1), \ldots, g(x_n)) = g(f(x_1, \ldots, x_n))$ for all $(x_1, \ldots, x_n) \in \dom(f)$. 
    %
    %
\end{definition}

\begin{example}
    Recall that the partial Boolean Mal'tsev operation $m$ was idempotent and self-dual. One alternative way to define this notion is that $m$ commutes with the two Boolean constant maps and with Boolean negation $g(x) = 1 - x$.
\end{example}

%
We lift this notion to pairs of functions (possibly defined over different domains) as follows.

\begin{definition}
    Let $f$ and $f'$ be $n$-ary partial functions over $D_1$ and $D_2$, respectively. We say that $f,f'$ {\em commute} with $g \colon D_1 \to D_2$ if 
    \[f'(g(x_1), \ldots, g(x_n)) = g(f(x_1, \ldots, x_n))\] and is defined for all $(x_1, \ldots, x_n) \in \dom(f)$.
\end{definition}

\begin{proposition} \label{prop:commutes}
    Let $P$ be an $n$-ary polymorphism pattern and let $D_1$ and $D_2$ be finite sets. For every $p \in \interpretation{D_1}{P}$ there exists $p' \in \interpretation{D_2}{P}$ such that $p,p'$ commutes with every unary $g \colon D_1 \to D_2$.
\end{proposition}

\begin{proof}
Let $p \in \interpretation{D_1}{P}$. We observe that if $((x_1, \ldots, x_n), x) \in P$ where $x \in \{x_1, \ldots, x_n\}$ then, for every $p' \in \interpretation{D_2}{P}$, we must have that $p'(g(b_1), \ldots, g(b_n)) = g(p(b_1, \ldots, b_n))$ for every $g \colon D_1 \to D_2$ and $b_1, \ldots, b_n$ such that there is $h \colon \{x_1, \ldots, x_n\} \to D_1$, where $b_i = h(x_i)$. 

On the other hand, assume that $((x_1, \ldots, x_n), y) \in P$ for $y \notin \{x_1, \ldots, x_n\}$. Let $b_1, \ldots, b_n \in D_1$ such that there is $h \colon \{x_1, \ldots, x_n\} \to D_1$ where $h(x_i) = b_i$ for every $1 \leq i \leq n$, i.e., $b_1, \ldots, b_n$ matches the pattern, as witnessed by the function $h$. There then exists $p' \in \interpretation{D_2}{P}$ such that $g(p(b_1, \ldots, b_n)) = p'(g(b_1), \ldots, g(b_n))$ for every $g \colon D_1 \to D_2$.
\end{proof}
%


We will often work in the following setting: consider finite, disjoint sets $D_1, \ldots, D_k$ for some $k \geq 1$, and a relation $R \subseteq (D_1 \cup \ldots \cup D_k)^r$ with an associated signature $s \colon [k] \to [r]$ which for each argument returns the corresponding sort, i.e., if $h(i) = j$ then $t_i \in D_j$ for each $t \in R$.
%
Note that we for each $D$ and $r \geq 1$ can construct $r$ disjoint copies $D_1, \ldots, D_r$ of $R$ and thus simply speak about $r$-ary multisorted relations over $D$. To ease the notation we thus sometimes simply say that $R$ is an $r$-ary multisorted relation over $D$, rather than over disjoint copies $D_1, \ldots, D_r$.  It is then convenient not only to let the pattern act independently on each domain, but to allow different patterns for each domain type, which is in line with multisorted algebras in the CSP literature~\cite{bulatov2003}.


\begin{definition}
    A \emph{multisorted pattern} is a tuple $(P_1,\ldots,P_r)$ where $P_i$ is an $n$-ary polymorphism pattern for each $i \in [r]$. We say that  $P$ preserves an $m$-ary multisorted promise relation $(S,T)$ over $D_1 \cup \ldots \cup D_r$ with signature $s \colon [m] \to [r]$ if
    \[(p_{s(1)}(x^{(1)}_1, \ldots, x^{(n)}_1), \ldots, p_{s(m)}(x^{(1)}_m, \ldots, x^{(n)}_m)) \in T\] for all $p_{s(1)} \in \interpretation{D_{s(1)}}{P_{s(1)}}, \ldots, p_{s(m)} \in \interpretation{D_{s(m)}}{P_{s(m)}}$ and $x^{(1)}, \ldots, x^{(n)} \in S$ where each $(x^{(1)}_i, \ldots, x^{(n)}_i) \in \dom(p_{s(i)})$.
\end{definition}

This naturally allows us to speak about the set of patterns preserving a given promise relation.

\begin{definition}
    For a (multisorted) promise relation $(S,T)$ over $D$ ($D_1 \cup \ldots \cup D_r$) we let \[\pattern(S,T) = \{P \mid P \text{ is an } n \text{-ary  pattern}, n \geq 1, (S,T) \in \inv(\{P\})\}\] and 
    \[\mpattern(S,T) = \{(P_1, \ldots, P_r) \mid (P_1, \ldots, P_r) \text{ is a multisorted pattern}, (S,T) \in \inv(\{P\})\}.\]
\end{definition}

We are now interested in properties of $\pattern(\cdot)$ (and $\mpattern(\cdot)$) when viewed as algebraic objects themselves. With the aim of showing that these sets form minor like objects we define the following closure operator for (multisorted) patterns.

\begin{definition}
    Let $P = (P_1, \ldots, P_r)$ be a multisorted pattern where each $P_i$ has arity $n$. A {\em variable identification minor} of $P$ is a multisorted pattern $P_{/h} = (P_{1/h}, \ldots, P_{r/h})$ where $P_{i/h} = \{(x_{1}, \ldots, x_{m}), x)) \mid (x_{h(1)}, \ldots, x_{h(n)}), x) \in P_i\} $ for some $h \colon [n] \to [m]$ and $m \geq 1$. 
\end{definition}

Similarly to minors of partial functions we then say that $P'$ is a {\em minor} of a multisorted pattern $P$ if it is a subset of a variable identification minor of $P$.

\begin{definition}
    For a set of multisorted patterns $Q$ we let $[Q]_{\min} = \{P' \mid P' \text{ is a minor of } P \in Q\}$.
\end{definition}

Simultaneously, it then also makes sense to describe the relations invariant under a set of multisorted patterns.

\begin{definition}
    For a set of (multisorted) polymorphism patterns $Q$ and $D$ we write $\inv_D(Q)$ for the set of all (multisorted) $(S,T)$ over $D$ preserved by each $P \in Q$, and $\inv(Q) = \bigcup_{i \geq 1, |D| = i} \inv_D(Q)$ for the set of all (multisorted) relations, over some finite domain, preserved by $Q$.
\end{definition}

%

We can relate these operators together as follows.

\begin{proposition} \label{prop:minors_preserve}
    For any set $Q$ of (multisorted) polymorphism patterns $\inv(Q) = \inv([Q]_{\min})$.
\end{proposition}

\begin{proof}
    Since $Q \subseteq [Q]_{\min}$ it trivially follows that $\inv([Q]_{\min}) \subseteq \inv(Q)$. For the other direction, pick $(S,T) \in \inv(Q)$ over some $D = D_1 \times \ldots \times D_r$. Let $P' \in [Q]_{\min}$ be a multisorted polymorphism pattern. First, assume that $P'$ is a variable identification minor of some $P \in Q$. Then $P'$ must preserve $(S,T)$, too, since each function in $\interpretation{D}{P'}$ is a variable identification minor of a function in $\interpretation{D}{P}$, and we may simply apply Proposition~\ref{lemma:minors_preserve_relations}. Similarly, if $P'' \subseteq P'$, then $P''$ preserves $(S,T)$ since every partial function in $\interpretation{D}{P''}$ is a subfunction of a partial function in $\interpretation{D}{P}$.
\end{proof}

Similarly, we obtain the following proposition via an abstraction of Lemma~\ref{lemma:is_a_minion} on the pattern level.

\begin{proposition}
$\mpattern(S,T) = [\mpattern(S,T)]_{\min}$ for any multisorted promise relation $(S,T)$.
\end{proposition}



