Next, we prove a converse result which shows that we can $c$-fgppp-define $(S_1, T_1)$ if it is invariant under $P$ whenever $(S_2, T_2)$ is invariant under $P^c$. For simplicity we present it for individual relations but the generalization to promise constraint languages is effortless.

\begin{lemma} \label{lemma:can_fgppp_define}
Let $(S_1, T_1)$, $(S_2, T_2)$ be promise relations over $D_1$, $D_2$. If $P \in \pattern{(S_1, T_1)}$  whenever $P^c \in \pattern(S_2, T_2)$ for consistent $P^c$, then $(S_2, T_2)$ $c$-fgppp-defines $(S_1, T_1)$.
\end{lemma}

\begin{proof}
  Assume that $P \in \pattern(S_1, T_1)$ whenever $P^c \in \pattern(S_2, T_2)$, for a consistent pattern $P^c$.
  We begin by introducing some notation.

    \begin{enumerate}
        \item 
        Let $|S_1| = m$ and let $t_1, \ldots, t_m \in S_1$ be an enumeration of the tuples in $S_1$.
        \item 
        Let $r_1 \geq 1$ be the arity of $S_1$ and $r_2 \geq 1$ the arity of $S_2$. For each $1 \leq i \leq r_1$ we let $c^i = (t^{(1)}_{i}, \ldots, t^{(m)}_{i})$ be the $i$th column of $S_1$ under the enumeration $t_1, \ldots, t_m$.
    \end{enumerate}

Consider the $r_1$-ary relations $S'_1$ and $T'_1$ defined via $c$-fgpp-formulas $\varphi^{S_2}(x_1, \ldots, x_{r_1})$ and $\varphi^{T_2}(x_1, \ldots, x_{r_1})$ over variables $x_1, \ldots, x_{r_1}$ where we for every sequence $s^{(1)}, \ldots, s^{(m)} \in S_2$, with columns \[d^1 = (s^{(1)}_{1}, \ldots, s^{(m)}_{1}), \ldots, d^{r_2} = (s^{(1)}_{r_2}, \ldots, s^{(m)}_{r_2})\]
add

\begin{enumerate}
    \item 
    $S_2(g_1(x_{h(1, 1)}, \ldots, x_{h(1,c)}), \ldots, g_{r_2}(x_{h(r_2, 1)}, \ldots, x_{h(r_2, c)}))$ to $\varphi^{S_2}$, and 
    \item 
    $T_2(g_1(x_{h(1, 1)}, \ldots, x_{h(1,c)}), \ldots, g_{r_2}(x_{h(r_2, 1)}, \ldots, x_{h(r_2, c)}))$ to $\varphi^{T_2}$, 
\end{enumerate}
    if there exist $g_1, \ldots, g_{r_2} \colon D^c_1 \to D_2$ and $h \colon [r_2] \times [c] \to [r_1]$ such that $g_1(c^{h(1,1)}, \ldots, c^{h(1,c)}) = d^1, \ldots, g_{r_2}(c^{h(r_2, 1)}, \ldots, c^{h(r_2, c)}) = d^{r_2}$. We then view $c^1, \ldots, c^{r_1}$ as an incomplete pattern $P'$ by viewing $D_1$ as a set of variables $V$ and each $c^i$ as a tuple of variables. Say that a pattern $P$ over $V$ is an {\em instantiation}  of $P'$ if $((x_1, \ldots, x_{m}), y) \in P$ for some $y \in V$ if and only if $(x_1, \ldots, x_m) \in P'$. Then the following statements are true.
    \begin{enumerate}
        \item 
        $t \in S'_1$ if there is an instantiation $P$ of $P'$ such that  $P^c \in \pattern(S_2, S_2)$ such that $t$ (viewed as an $m$-ary function) is a subfunction of a partial function in $\interpretation{D_1}{P}$, and %
        \item 
        $t \in T'_1$ if there is an instantiation $P$ of $P'$ where $P^c \in \pattern(S_2, T_2)$ such that $t$ (viewed as an $m$-ary function) is a subfunction of a partial function in $\interpretation{D_1}{P}$.
      \end{enumerate}
%
    Hence, if there exists $f \in T'_1$ where $f \notin T_1$ then there exists $m$-ary $P^c \in \pattern(S_2, T_2)$ such that $f$ is a subfunction of a partial function in $\interpretation{D_1}{P}$ but where $f \notin \pPol(S_1, T_1)$.

    We conclude that $T'_2 = T_1, S_1 \subseteq S'_1$, and that $(S_1, T_1)$ is fgppp-definable via a strict relaxation of $(S'_1, T'_1)$.
\end{proof}

For $c = 1$ we obtain the following precise characterization which  generalizes Carbonnel~\cite{carbonnel2022Redundancy} in the promise setting. 
%

\begin{theorem}
\label{thm:fgppp-pattern}
Let $(S_1, T_1)$ be a promise relation over $D_1$ and $(S_2, T_2)$ a promise relation over $D_2$. Then $\pattern(S_2, T_2) \subseteq \pattern(S_1, T_1)$ if and only if $(S_2, T_2)$ fgppp-defines $(S_1, T_1)$.
\end{theorem}

For $c \geq 1$ we for a promise relation $(S,T)$ let \[\pattern^c(S,T) = \{P^c \in \pattern(S,T) \mid P \text{ is a consistent pattern}\}.\] As a dual operation we for a set $Q$ of patterns of the form $P^c$ write $Q^{\frac{1}{c}}$ for $\{P \mid P^c \in Q\}$. Hence, $\pattern^{\frac{c}{c}}(S,T)$ is the set of patterns $P$ where $P^c$ is consistent and preserves $(S,T)$. We obtain the following.

\begin{theorem}
\label{thm:fgppp-pattern_c}
Let $(S_1, T_1)$ be a promise relation over $D_1$ and $(S_2, T_2)$ a promise relation over $D_2$, and let $c \geq 1$. Then $\pattern^{\frac{c}{c}}(S_2, T_2) \subseteq \pattern(S_1, T_1)$ if and only if $(S_2, T_2)$ fgppp-defines $(S_1, T_1)$.
\end{theorem}

