    \subsection{Gadget Reductions for Conditional Non-redundancy}
    \label{sec:gadget_reductions}
        %
%
 %

%
We continue by relating fgppp-definitions, and thus also patterns, to conditional non-redundancy. Our goal is to prove the following (compare with Proposition 2 in Carbonnel~\cite{carbonnel2022Redundancy}) statement.

\begin{theorem}\label{thm:fgppp-nrd}
Let $(S_1, T_1)$ and $(S_2, T_2)$ be promise relations over $D_1$, respectively, $D_2$. If $(S_2, \widetilde{T}_2)$ $c$-fgppp-defines $(S_1, \widetilde{T}_1)$ for some $c \geq 1$ then $\NRD(S_1 \mid T_1, n) = O_{D_1,D_2,r_1,r_2}(n + \NRD(S_2 \mid T_2, n^c))$.
\end{theorem}

As an immediate corollary of Theorem~\ref{thm:fgppp-pattern}, we have the following algebraic test for bounding non-redundancy

\begin{corollary}
If $\pattern(S_2, \widetilde{T}_2) \subseteq \pattern(S_1, \widetilde{T}_1)$ then $\NRD(S_1 \mid T_1, n) = O_{D,r_1,r_2}(n + \NRD(S_2 \mid T_2, n))$.
\end{corollary}

Our overall proof strategy is similar to that of Carbonnel~\cite{carbonnel2022Redundancy} but more involved due to the richer machinery.  We write our proof in a modular fashion by proving Theorem~\ref{thm:fgppp-nrd} for each of the ``atomic'' operations involved in an fgppp-definition. In certain cases the resulting bound is thus sharper than the general bound in Theorem~\ref{thm:fgppp-nrd}. We start with strict relaxations.

\begin{proposition}\label{prop:strict-relaxation-nrd}
Assume $D := D_1 = D_2$ and $r := r_1 = r_2$. If $S_1 \subseteq S_2$ and $\widetilde{T}_2 \subseteq \widetilde{T}_1$, then $\NRD(S_1 \mid T_1, n) \le \NRD(S_2 \mid T_2, n)$.
\end{proposition}
\begin{proof}
Consider any conditionally non-redundant instance $(X, Y \subseteq X^r)$ of $\CSP(S_1 \mid T_1)$ with witnessing assignments $\psi_y : X \to D$ for all $y \in Y$. If $\widetilde{T}_2 \subseteq \widetilde{T}_1$, then $T_1 \setminus S_1 \subseteq T_2 \setminus S_2$. Since we also have $S_1 \subseteq S_2$, the assignments $\{\psi_y : y \in Y\}$ also witness that $(X,Y)$ is a conditionally non-redundant instance of $\CSP(S_2 \mid T_2)$.
\end{proof}

Second, we handle equality constraints.

\begin{proposition}\label{prop:equality-nrd}
Assume $D := D_1 = D_2$ and $r := r_1 = r_2$. Assume that there exists distinct $i,j \in [r]$ such that
\begin{align}
    S_1(x_1, \hdots, x_r) &= S_2(x_1, \hdots, x_r) \wedge x_i = x_j,\nonumber\\
    \widetilde{T}_1(x_1, \hdots, x_r) &= \widetilde{T}_2(x_1, \hdots, x_r) \wedge x_i = x_j.\label{eq:wtQeq}
\end{align}
Then, $\NRD(S_1 \mid T_1, n) \le \NRD(S_2 \mid T_2, n) + n-1$.
\end{proposition}
\begin{proof}
Let $(X, Y)$ be a conditionally non-redundant instance of $\CSP(S_1 \mid T_1)$, and let $\{\psi_y : X \to D \mid y \in Y\}$ be the witnessing assignments. Let $Y_{\EQ} \subseteq Y$ be the set of clauses $y \in Y$ for which $\psi_y(y_i) \neq \psi_y(y_j)$. It is clear that the graph $\{(y_i, y_j) \in X^2 \mid y \in Y_{\EQ}\}$ is a acyclic, so $|Y_{\EQ}| \le |X|-1$.

By negating both sides of (\ref{eq:wtQeq}), we have that
\[
    (T_1 \setminus S_1)(x_1, \hdots, x_r) = (T_2 \setminus S_2)(x_1, \hdots, x_r) \vee x_i \neq x_j.
\]
For each $y \in Y$, we have that $\psi_y(y) \in T_1 \setminus S_1$. Further, by definition of $Y_{\EQ}$, for each $y \in Y \setminus Y_{\EQ}$, we have that $\psi_y(y_i) = \psi_y(y_j)$, so $\psi_y(y) \in T_2 \setminus S_2$. Therefore, $(X, Y \setminus Y_{\EQ})$ is a conditionally non-redundant instance of $\CSP(S_2 \mid T_2)$.
\end{proof}

Third, we handle the conjunction of two predicates, which immediately extends to an arbitrary number of predicates.

\begin{proposition}\label{prop:conjunction-nrd}
Assume $D := D_1 = D_2$. Let $f,g: [r_2] \to [r_1]$ be functions such that
\begin{align}
    S_1(x_1, \hdots, x_{r_1}) &= S_2(x_{g(1)}, \hdots, x_{g(r_2)}) \wedge S_2(x_{f(1)}, \hdots, x_{f(r_2)}),\nonumber\\
    \widetilde{T}_1(x_1, \hdots, x_{r_1}) &= \widetilde{T}_2(x_{g(1)}, \hdots, x_{g(r_2)}) \wedge \widetilde{T}_2(x_{f(1)}, \hdots, x_{f(r_2)}).\label{eq:wtQconj}
\end{align}
Then, $\NRD(S_1 \mid T_1, n) \le \NRD(S_2 \mid T_2, n)$.
\end{proposition}
\begin{proof}
Let $(X, Y \subseteq X^{r_1})$ be a conditionally non-redundant instance of $\CSP(S_1 \mid T_1)$, and let $\{\psi_y : X \to D \mid y \in Y\}$ be the witnessing assignments. For each $y \in Y$, let $y_f, y_g \in X^{r_2}$ be
\begin{align*}
    y_f &:= (y_{g(1)}, \hdots, y_{g(r_2)}),\\
    y_g &:= (y_{f(1)}, \hdots, y_{f(r_2)}).
\end{align*}
For each $y, y' \in Y$, we have that $\psi_y(y') \in S_1$ if and only if $\psi_y(y'_f) \in S_2$ and $\psi_y(y'_g) \in S_2$. Furthermore, by negating both sides of (\ref{eq:wtQconj}), we can deduce that
\begin{align*}
(T_1 \setminus S_1)(x_1, \hdots, x_{r_1}) &= (T_2 \setminus S_2)(x_{g(1)}, \hdots, x_{g(r_2)}) \vee (T_2 \setminus S_1)(x_{f(1)}, \hdots, x_{f(r_2)}).
\end{align*}
In particular, since $\psi_y(y) \in T_1 \setminus S_1$, we have that $\psi_y(y_f) \in T_2 \setminus S_2$ or $\psi_y(y_g) \in T_2 \setminus S_2$. Let $y_{\rep} \in \{y_f, y_g\}$ be an arbitrary representative for which $\psi_y(y_{\rep}) \in T_2 \setminus S_2$. Then define $Y_{\rep} := \{y_{\rep} : y \in Y\} \subseteq X^{r_2}$. From our discussion, we have that $\{\psi_y : y \in Y\}$ witness that $(X, Y_{\rep})$ is a conditionally non-redundant instance of $\CSP(S_2 \mid T_2)$. In particular, $|Y_{\rep}| = |Y|$ as each $\psi_y$ fails to $S_2$-satisfy a unique clause $y_{\rep}$ of $(X, Y_{\rep})$.
\end{proof}

As an immediate corollary of our progress so far, we have that conditional non-redundancy behaves well with respect to qfppp-reductions. However, we now conclude by showing that functional guarding also behaves well with respect to conditional non-redundancy.

%

\begin{proposition}\label{prop:functional-guarding-nrd}
For $c \geq 1$ let $h \colon [r_2] \times [c] \to [r_1]$ and $g_1, \hdots, g_{r_2} : D^c_1 \to D_2$ be functions such that
\begin{align}
    S_1(x_1, \hdots, x_{r_1}) &= S_2(g_1(x_{h(1,1)}, \ldots, x_{h(1,c)}), \hdots, g_{r_2}(x_{h(r_2, 1)}, \ldots, x_{h(r_2, c)})) \label{eq:123}\\
    \widetilde{T}_1(x_1, \hdots, x_{r_1}) &= \widetilde{T}_2(g_1(x_{h(1,1)}, \ldots, x_{h(1,c)}), \hdots, g_{r_2}(x_{h(r_2, 1)}, \ldots, x_{h(r_2, c)})).\label{eq:234}
\end{align}
Then, $\NRD(S_1 \mid T_1, n) \le O_{r_2}(\NRD(S_2 \mid T_2, n^c))$.
\end{proposition}

\begin{proof}
Let $(X, Y \subseteq X^{r_1})$ be a conditionally non-redundant instance of $\CSP(S_1 \mid T_1)$ with witnessing assignments $\{\psi_y : X \to D_2 \mid y \in Y\}$. Let $X_{+} := X^c \times [r_2]$ and for each $y \in Y$, let 
\[
y_{+} := ((y_{h(1,1)}, \ldots, y_{h(1,c)}, 1), \hdots, (y_{h(r_2, 1)}, \ldots, y_{h(r_2, c)}, r_2)) \in X_{+}^{r_2}.
\]
Let $Y_{+} := \{y_{+} \mid y \in Y\}$ and for each $y_{+} \in Y_{+}$ let $\psi_{y_{+}} : X_{+} \to D_1$ be such that for all $(x, i) \in X_{+}$, we have that $\psi_{y_{+}}(x, i) = g_i(\psi_y(x))$, where $\psi_y$ is applied componentwise to $x$ and therefore yields a $c$-ary tuple matching the arity of $g_i$. From (\ref{eq:123}) and (\ref{eq:234}), we can see that $\{\psi_{y_{+}} \mid y_{+} \in Y_{+}\}$ witness that $(X_{+}, Y_{+})$ is a conditionally non-redundant instance of $\CSP(S_2 \mid T_2)$ and thus $|Y_{+}| = |Y|$. Since $|X_{+}| = r_2 |X|^c$ we therefore have $\NRD(S_1 \mid T_1, n) \le \NRD(S_2 \mid T_2, n^c \cdot r_2)$, and since $\NRD(S_2 \mid T_2, n^c \cdot r_2) \in O_{r_2}(\NRD(S_2 \mid T_2, n^c))$ (\Cref{lem:NRD-scale}) 
%
the desired bound follows.
%
%
\end{proof}
Note that this bound, in contrast to Carbonnel~\cite{carbonnel2022Redundancy} who obtain a dependency on $|D|^{|D|}$, does {\em not} depend on the size of the domains.
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%

Last, we conclude the proof of Theorem~\ref{thm:fgppp-nrd}.

%
\begin{proof}[Proof of Theorem~\ref{thm:fgppp-nrd}]
If $(S_2, T_2)$ fgppp-defines $(S_1, T_1)$, then this definition can be constructed using at most $O_{D_1,D_2,r_1,r_2}(1)$ iterations of the operations in Proposition~\ref{prop:strict-relaxation-nrd}, Proposition~\ref{prop:equality-nrd}, Proposition~\ref{prop:conjunction-nrd}, and Proposition~\ref{prop:functional-guarding-nrd}. Furthermore, the arity of any intermediate predicate pair is at most $O_{D_1,D_2,r_1,r_2}(1)$, so the constant factor bound of Proposition~\ref{prop:functional-guarding-nrd} still applies. Last, as a special case, consider the case when $(S_1, T_1)$ is fgppp-definable with qfppp-definition over $(S_2, T_2)$ which involves one or more $\mathsf{f} = \emptyset$ constraints. Then, $S_1 = T_1 = \emptyset$ and the claim trivially follows.
%
\end{proof}



\subsection{The Cube-Power Polymorphism Patterns} \label{sec:cube-power}


We now review a particularly important class of polymorphism patterns, corresponding to the powers of the \emph{cube} identities mentioned in Example~\ref{example:3cube}, studied by Berman et al.~\cite{berman2009Varieties}. The $k$-cube pattern polymorphisms were referred to as \emph{$k$-universal} partial polymorphisms in previous work~\cite{lagerkvist2021Coarse,carbonnel2022Redundancy}.


\begin{definition} \label{def:kcube}
    Let $k \geq 2$. The \emph{$k$-cube} polymorphism pattern $U_k$ is the pattern with arity $2^k-1$ on variable set $V=\{x,y\}$, with patterns $P_i=(X_i,y)$ for $i \in [k]$ where
    for each $j \in [2^k-1]$, position $j$ of $X_i$ equals $x$ if the $i$th bit of the binary expansion of $j$ is 1, and $y$ otherwise.
\end{definition}

Since $|I_D(U_k)|=1$ for every domain $D$, we let $u_k$ refer to the unique member of $I_D(U_k)$, where the domain $D$ will frequently be understood from context. The significance of $U_k$ is that every relation $R \subseteq D^r$ for some domain $D$ and arity $r$ can fgpp-define the $k$-ary $\mathsf{OR}$ relation if and only if $u_k \notin \pPol(R)$; see~\cite{lagerkvist2021Coarse,carbonnel2022Redundancy}. This immediately gives the following. 

\begin{lemma} \label{lm:cube-power-lb}
    Let $R \subseteq D^r$ be a relation over some domain $D$, and assume $u_k^c \notin \pPol(R)$ for some $k > c \geq 1$. Then $\NRD(R,n)=\Omega(n^{k/c})$.
\end{lemma}

\begin{example}  
Consider the following relation from \cite{brakensiek2024Redundancy}.
Define $R=\text{3LIN}_{\Z/3\Z}=\{(x,y,z) \in \{0,1,2\}^3 \mid x+y+z+0 \pmod 3\}$
and $R^*=\text{3LIN}^*_{\Z/3\Z}= R \setminus \{(0,0,0)\}$.
It was shown in \cite{brakensiek2024Redundancy} that $\NRD(R^*,n)=\Omega(n^{1.5})$ and 
$\NRD(R^*,n)=\Oh(n^{1.6}\log n)$. The lower bound now follows from Lemma~\ref{lm:cube-power-lb} as $u_3^2((0,1,2), (1,0,2), (1,1,1), (1,2,0), (1,0,2), (2,2,2), (2,0,1))=(0,0,0)$.
\end{example}

Lemma~\ref{lm:cube-power-lb} is a powerful approach towards lower bounds on non-redundancy; e.g., beyond this example, it also covers all lower bounds of Section~\ref{sec:frac}. However, it is also not a ``universal'' method of showing tight lower bounds on the non-redundancy, as shown at the end of this section.


In our study of relations with near-linear NRD, we will be particularly interested in the power patterns $U_k^{k-1}$, since these are the weakest patterns that exclude near-linear NRD. Let us make some quick observations about these patterns.
%
%
The first is a direct observation that follows from the definition (we include the case $U_2^1=U_2$ for uniformity).

\begin{proposition} \label{prop:ukc-description}
  Let $k \in \N$, $k \geq 2$. The polymorphism pattern $U_k^{k-1}$ 
  has arity $2^k-1$, and its patterns are described as follows:
  For every $i \in [k]$, there is a pattern $P_i=(X_i,y_i)$
  where $X_i[p]=X_i[q]$ for $p, q \in [2^k-1]$ if and only if
  $p \oplus q = e_i$ when $p$ and $q$ are viewed as bitstrings
  and $e_i$ is the $i$th unit vector, and where
  $y_i$ is the unique variable that occurs only once in $X_i$.  
\end{proposition}

We continue with the following observations. 

\begin{lemma} \label{lm:ukc-basics}
  The following hold.
  \begin{enumerate}
  \item For any $k \geq 2$, $U_k^{k-1}$ is symmetric in the following
    sense: Let $P_1, \ldots, P_k$ be the patterns of $U_k^{k-1}$
    as in ~\Cref{prop:ukc-description}.
    For every permutation $\pi$ on $[k]$
    there is a permutation $\sigma$ on $[2^k-1]$ such that
    for every $i \in [k]$, the values of pattern $P_i$ read in order
    $\sigma$ match the values of pattern $P_{\pi(i)}$ read in the
    original order. 
  \item Over any domain $D$, $u_p^{p-1}$ implies $u_q^c$ 
    for every $p \geq q \geq 2$ and every $c < q$.
  \item Let $R \subset D^r$ be a relation for some domain $D$ and
    arity $r$. Then $R$ is preserved by $u_k^{c}$ for every $k \geq 2$ and $c<k$
    if and only if $R$ is preserved by $u_r^{r-1}$.
  \end{enumerate}
\end{lemma}
\begin{proof}
  For the first, if we view the arguments of $U_k^{k-1}$ as
  corresponding to non-zero bitstrings $b \in \{0,1\}^k$, 
  then applying $\pi$ directly to the bitstring yields the desired
  permutation $\sigma$.
    For the second, first let $R \subseteq D^r$ be an $r$-ary relation
  preserved by $u_p^{p-1}$ for some $p \geq 2$, 
  and let $t_1, \ldots, t_m \in R$ be such that
  $u_q^{q-1}(t_1,\ldots,t_m)=t$ is defined, $q < p$.
  Select $t' \in R$ arbitrarily. Then
  $u_p^{p-1}(t_1,\ldots,t_m,t',\ldots,t')=t$ is defined,
  by the description in ~\Cref{prop:ukc-description}.
  Thus $u_p^{p-1}$ implies $u_q^{q-1}$.
  To complete the property, we note that for any $k$,
  and any $a \leq b<k$, $u_k^b$ implies $u_k^a$:
  in line with ~\Cref{prop:ukc-description},
  the patterns of $u_k^c$ for any $c$ correspond to sets $S \subset [k]$
  containing $c$ indexes from $[k]$, and such a pattern has the same
  variable in two positions $i$, $j$ if and only if 
  $i$ and $j$ match on all bits present in $S$.
  Thus, for every pattern $P_S$ of $u_k^a$,
  indexing $a$ bits $S \subset [k]$, let $S' \subset [k]$ be any
  subset of $S$ with $b$ bits. Then the pattern
  $P_{S'}$ is strictly less restrictive than $P_S$,
  so any tuple that matches a pattern of $u_k^a$
  also matches a pattern of $u_k^b$. Similarly, the output
  of pattern $P_{S'}$ matches an argument that also
  matches the output of $P_S$. 

  For the last point, we note by the second property that 
  $R$ is preserved by all $u_k^c$, $k \geq 2$, $c<k$
  if and only if $R$ is preserved by $u_k^{k-1}$ for all $k \geq 2$.
  Thus, assume that $R$ is violated by $u_k^{k-1}$
  for some $k \geq 2$. If $k<r$, then $R$ is violated by $u_r^{r-1}$
  by the second property. Otherwise, assume $k>r$,
  and let $t_1, \ldots, t_m \in R$ be such that
  $u_k^{k-1}(t_1,\ldots,t_m)=t$ is defined where $t \notin R$.
  By the first property, we may assume that this application
  of $u_k^{k-1}$ only uses patterns $P_i$ corresponding to the $r$
  least significant bits according to ~\Cref{prop:ukc-description}.
  But then, all ``repeats'' in the pattern have distance at most $2^{r-1}$
  and $u_r^{r-1}(t_1,\ldots,t_{2^r-1})=t$ is defined, showing
  $u_r^{r-1} \notin \pPol(R)$.
\end{proof}

The last property allows us to verify with a finite computation that a relation cannot be shown to have superlinear NRD using $c$-fgppp-definitions of $\OR$ (i.e., via Lemma~\ref{lm:cube-power-lb}).
See Section~\ref{subsec:excl} for more

Unfortunately, the second property of Lemma~\ref{lm:ukc-basics} does
not generalize: in general, if $p/q \leq k/c$, it does not
necessarily follow that $u_p^q$ implies $u_k^c$. 
Let $P_1=(X_1,y_1), \ldots, P_6=(X_6,y_6)$ enumerate the patterns of $U_4^2$,
and let $V$ be the set of variables of $U_4^2$.
Define a relation $R \subseteq V^6$ by $R=\{t_1,\ldots,t_{15}\}$
where $t_i=(X_1[i], \ldots, X_6[i])$. 
Then by design $R$ is not preserved by $u_4^2$, but
one can verify that $R$ is preserved by $u_2^1=u_2$.

Finally, we note that the final property of Lemma~\ref{lm:ukc-basics}
represents a weakness in the method, in that the cube-power patterns $U_p^q$
cannot be used to prove a lower bound of $\Omega(n^{1+\varepsilon})$
for the non-redundancy of an $r$-ary relation $R$ for any $0 < \varepsilon < 1/(r-1)$,
despite the results of Section~\ref{sec:nrd-bin} showing that infinitely many such bounds exist, even for $r \leq 3$ (at least conditionally, in Section~\ref{subsec:binary-class}, and conjecturally, in Section~\ref{subsec:approach-linear}). %
We show a complementary upper bound, showing that $U_p^q$ cannot show a lower bound $\Omega(n^{r-\varepsilon})$ for the non-redundancy of $R$ for any $0 < \varepsilon < 1$ unless $\NRD(R,n)=\Theta(n^r)$.

\begin{lemma} \label{lm:upq-near-r}
  Let $R \subseteq D^r$ for $r \geq 2$ be a relation such that $U_r \in \pattern(R)$.
  Then $U_p^q \in \pattern(R)$ for every $p/q > r-1$. 
\end{lemma}
\begin{proof}
  Assume $u_p^q \notin \pPol(R)$ for some $p/q > r-1$. Then $R$
  $q$-fgpp-defines $\OR_p$, and this definition can be assumed to
  consist of a single constraint, i.e.,
  \[
    \OR_p(x_1,\ldots,x_p) \equiv R(g_1(X_1), \ldots, g_r(X_r))
  \]
  for some maps $g_i \colon \{0,1\}^q \to D$ and some scopes
  $X_i \subseteq X$ of $q$ variables each, where $X=\{x_1,\ldots,x_p\}$. 
  First assume that there is a scope $X_i$, say $X_r$, such that every
  variable in $X_r$ also occurs in $X_j$ for some $j<r$. Then
  $|\bigcup_{i=1}^{r-1} X_i|=|X|=p \leq (r-1)q$.
  Otherwise, let $x_{i_j}$, $j \in [r]$ be variables such that
  $x_{i_j}$ occurs only in $X_j$ for $j \in [r]$. Consider the set of
  assignments to $X$ where $x_t=0$ for every $t \in [r] \setminus \{i_1,\ldots,i_r\}$.
  Each map $g_i$, $i \in [r]$, takes two distinct values under these assignments,
  and this defines a subset $F=\prod_{i=1}^r \{a_i,b_i\} \subseteq D^r$
  such that $|F \setminus R|=1$. Thus we have a witness that
  $R$ violates $u_r$. 
\end{proof}



\section{Connections to Hypergraph Tur{\'a}n} \label{sec:hypergraph-turan}

%
%
Given a set of patterns $Q$ we are now interested in studying the conditional non-redundancy of families of promise relations invariant under $Q$. We study this systematically in Section~\ref{subsec:turan} and exemplify our main result in Section~\ref{subsec:turan_examples}
%
%
    \subsection{Patterns and Hypergraphs}
\label{subsec:turan}
   Before we can relate conditional non-redundancy with pattern polymorphisms we need to extend the algebraic vocabulary so that it is applicable to CSP instances and not only to relations. First, given $R \subseteq S \subseteq D^r$ and an instance $(X,Y)$ of $\CSP(R \mid S)$ recall that we (by Lemma~\ref{lemma:reduction:to:multipartite}) without loss of generality may assume that it is $r$-partite and that each $i \in [r]$ is associated with exactly one sort $X_i$.
   %
   Given a multisorted pattern $P = (P_1, \ldots, P_r)$ of arity $n$ each $P_i$ then induces a set of partial functions $\interpretation{X_i}{P_i}$, and given $p_i \in \interpretation{X_i}{P_i}$ for every $1 \leq i \leq r$ we can then apply $p_1, \ldots, p_r$ to $y^1, \ldots, y^n$ as $(p_1, \ldots, p_r)(y^1, \ldots, y^n)$ which for each $1 \leq i \leq r$ yields $p_i(y^1_i, \ldots, y^n_i)$.

%
%
 \begin{lemma} \label{lem:cpol-redundancy}
  Let $R \subseteq S \subseteq D_1 \times \ldots \times D_r$ be multisorted relations with $r$ sorts $D_1 \cup \ldots \cup D_r = D$ and let $P=(P_1,\ldots, P_r)$ be 
  an $n$-ary multisorted pattern such that $(R,\widetilde{S}) \in \inv(P)$. 
  Let $(X,Y)$ be an $r$-partite instance of $\CSP(R \mid S)$ and let 
  $y^{(1)},\ldots, y^{(n)}, y \in Y$ such that $(p_1, \ldots, p_r)(y^{(1)},\ldots,y^{(n)})=y$ is defined
  and $y \notin \{y^{(1)},\ldots,y^{(n)}\}$ for some $p_1 \in \interpretation{X_1}{P_1}, \ldots, p_r \in \interpretation{X_r}{P_r}$. Then $y$ is conditionally redundant in $(X,Y)$. 
\end{lemma}

\begin{proof}
  Assume that there is an assignment $\sigma \colon X \to D$ such that $\sigma(y) \in S \setminus R$
  and $\sigma(y') \in R$ for every $y' \in Y - \{y\}$. 
  It follows that there exists $q_1 \in \interpretation{D_1}{P_1}, \ldots, q_r \in \interpretation{D_r}{P_r}$
    such that
  $\sigma(y) = (q_1, \ldots, q_r)(\sigma(y^{(1)}), \ldots, \sigma(y^{(n)}))$:
  for every position $i \in [r]$, we have $y_i = p_i(y^{(1)}_i,\ldots,y^{(n)}_i)$,
  hence there exists a pair $((x_1,\ldots,x_n),x_{j_i}) \in P_i$, so that
  $y_i=y^{{(j_i)}}_i$ and:
  \begin{enumerate}
      \item 
      if $x_{j_i} \in \{x_1, \ldots, x_n\}$ then $q_i(\sigma(y^{(1)})_i,\ldots,\sigma(y^{(n)})_i)=\sigma(y^{(j_i)})_i$ for every possible $q_i \in \interpretation{D_i}{P_i}$, and 
      \item 
      if $x_{j_i} \notin \{x_1, \ldots, x_n\}$ then $\interpretation{D_i}{P_i}$ for every $d \in |D_i|$ contains a partial function $q^d$ such that $q^d(\sigma(x_1), \ldots, \sigma(x_n)) = d$, and we choose $d = \sigma(y_i)$.
  \end{enumerate}
  But now $\sigma(y^{(1)}), \ldots, \sigma(y^{(n)}) \in R$ and $\sigma(y) \in S$,
  which implies $\sigma(y) \in R$, contrary to our assumption. 
\end{proof}   

Lemma~\ref{lem:cpol-redundancy} requires a fair amount of notation to state but as the following example shows is actually a reasonable and straightforward property on conditionally non-redundant constraints.

\begin{example}
We recall the relations $R=\text{3LIN}_{\Z/3\Z}=\{(x,y,z) \in \{0,1,2\}^3 \mid x+y+z \equiv 0 \pmod 3\}$
and $R^*=\text{3LIN}^*_{\Z/3\Z}= R \setminus \{(0,0,0)\}$ from Brakensiek \& Guruswami~\cite{brakensiek2024Redundancy}, introduced in Section~\ref{sec:cube-power}. 
Consider the multisorted polymorphism pattern $P = (P_1, P_2, P_3)$ where (1) $P_1 = P_2 = \{((x), x)\}$ is the pattern satisfied only by the unary projection and (2) $P_3 = \{((x), y)\}$ is an unrestricted pattern, i.e., one satisfied by any unary function. 
We claim that $(R^*, \widetilde{R}) \in \inv(P)$. 
To see this, note first that $\interpretation{\{0,1,2\}}{P_1} = \interpretation{\{0,1,2\}}{P_2} = \{\pi^1_1\}$, while $\interpretation{\{0,1,2\}}{P_3} = \{0,1,2\}^{\{0,1,2\}}$. 
Thus, the preservation condition boils to the following: for any tuple $t \in R^*$ we must have that $(t_1, t_2, d) \in \widetilde{R}$ for any $d \in \{0,1,2\}$, i.e., that $(t_1, t_2, d)$ is not included in $R \setminus R^* = \{(0,0,0)\}$. 
This is clearly true since if at least only entry in $t$ is non-zero and the sum is 0, $t_1$ and $t_2$ cannot both be 0, and the claim follows.

Now, consider an instance $(\{x,y,z,v\}, \{(x,y,z), (x,y,v)\})$ of $\CSP(R^* \mid R)$. We introduce disjoint copies $X_1, X_2, X_3$ of $X$ and then use functions
\begin{enumerate}
\item
$\pi^1_1 \in \interpretation{X_1}{P_1}$,
\item
$\pi^1_1 \in \interpretation{X_2}{P_2}$,
\item
$f \in \interpretation{X_3}{P_3}$ where $f(d) = v$ for every $d \in X_3$.
\end{enumerate}
It then follows that $(p_1, p_2, p_3)((x,y,z)) = (x,y,v) \in Y$ and that $(x,y,v)$ is conditionally redundant in $\CSP(R^* \mid R)$.
\end{example}

To connect to the hypergraph structure, we need the following assumptions.
Let $P=(P_1,\ldots,P_r)$ be an $n$-ary multisorted polymorphism pattern.
Say that $P$ is \emph{unit} if $|P_i|=1$ for every $i \in [r]$, i.e., each $P_i$ consists of a single pattern $((x_{i,1},\ldots,x_{i,n}),y_i)$. For a set of patterns $Q$ with $r$ sorts we let $\inv^{r}(Q) \subseteq \inv(Q)$ be the set of promise relations of arity $r$ (with exactly $r$ sorts).

\begin{proposition} \label{prop:unit_pattern_suffices}
  Let $P = (P_1, \ldots, P_r)$ be an $n$-ary multisorted polymorphism pattern. Then there exists a set of unit patterns $U \subseteq \minor{P}$ such that $\inv^r(U) = \inv^r(P)$.
\end{proposition}

\begin{proof}
  First, observe that $U = \{(U_1, \ldots, U_r) \mid 1 \leq i \leq r, U_i \subseteq P_i, |U_i| = 1\} \subseteq \minor{P}$ since we allow subsets in the minor definition. Due to Propositition~\ref{prop:minors_preserve} this implies that $\inv(P) \subseteq \inv(U)$ and hence also that $\inv^r(P) \subseteq \inv^r(U)$. For the other direction, assume there exists $(S,T) \in \inv^r(U)$ where $(S,T) \notin \inv^r_D(P)$ for any finite set $D = D_1 \cup \ldots \cup D_r$, and let $p_1 \in \interpretation{D_1}{P_1}, \ldots, p_r \in \interpretation{D_r}{P_r}$ witness this, i.e., $(p_1, \ldots p_r)(s^{(1)}, \ldots, s^{(n)}) = t \notin T$ for $s^{(1)}, \ldots, s^{(n)} \in S$. Each such application of a $p_i$ is witnessed by a unit pattern, and it follows that there exist subfunctions $u_1 \in \interpretation{D_1}{U_1}, \ldots, u_r \in \interpretation{D_r}{U_r}$ of $p_1, \ldots, p_r$ such that $(u_1, \ldots u_r)(s^{(1)}, \ldots, s^{(n)}) = t \notin T$, contradicting the original assumption.
\end{proof}

Let $P=(P_1,\ldots,P_r)$ be a unit multisorted pattern
with patterns $P_i=\{((x_{i,1},\ldots,x_{i,n}),y_i)\}$ (where the 
$x_{i,j}$ are not necessarily distinct). 
Say that $P$ is a \emph{partial projection} if there is $j \in [n]$ such that for every
$i \in [r]$, $y_i=x_{i,j}$, and \emph{non-trivial} otherwise. 

We define a hypergraph $\cH(P)$ from $P$ as follows.
For $i \in [r]$, let $X_i$ be the variable set that $P_i$ is defined
over, and assume (syntactically) that $X_i \cap X_j = \emptyset$
for $i \neq j$. Then $\cH(P)$ is the hypergraph on 
vertex set $X=X_1 \cup \ldots \cup X_r$ and with $n+1$
hyperedges given by $Y=\{(x_{1,j},\ldots,x_{r,j}) \mid j \in [n]\} \cup \{(y_1,\ldots,y_r)\}$.
Refer to $(y_1,\ldots,y_r)$ as the \emph{output edge} of $\cH(P)$.

We can now observe the following. 

\begin{lemma} \label{lem:unit-pattern-hypergraph}
  Let $R \subseteq S \subseteq D^r$ be a pair of multisorted relations and let
  $P$ be a unit multisorted pattern that is not a partial projection, such that $P \in \mpattern(R, \widetilde{S})$. 
  Let $(X,Y)$ be a conditionally non-redundant instance of $\CSP(R \mid S)$.
  Then $(X,Y)$ is $\cH(P)$-free (when interpreted as a hypergraph).
\end{lemma}

\begin{proof}
    Let $\{y^{(1)},\ldots,y^{(n)},y\} \subseteq Y$ form a hypergraph isomorphic to $\cH(P)$
    such that each $y^{(i)}$ maps to the $i$th edge of $\cH(P)$ in the order of construction 
    and where $y$ maps to the output edge. Then, by construction, $(p_1, \ldots, p_r)(y^{(1)},\ldots, y^{(n)})$ is defined for all $p_1 \in \interpretation{X_1}{P_1}, \ldots, p_r \in \interpretation{X_r}{P_r}$, and it is clear that there exists such functions which yield $y$. Since $P$ is not a partial projection it follows that $y \notin \{y^{(1)},\ldots,y^{(n)}\}$ and that 
    $(X,Y)$ is conditionally redundant by Lemma~\ref{lem:cpol-redundancy}.    
\end{proof}

Recall by Proposition~\ref{prop:unit_pattern_suffices} that for $r$-ary relations a general multisorted pattern
$P=(P_1,\ldots,P_r)$ is equivalent to the collection of unit patterns
produced by selecting one pair from $P_i$ for every $i \in [r]$. Hence, working with only unit patterns is not restrictive, and
Lemma~\ref{lem:unit-pattern-hypergraph} then implies that every multisorted
polymorphism pattern implies a finite collection of excluded multipartite hypergraphs.


To show the result in the other direction, consider the following. 
Let an instance $(X,Y)$ of $\CSP(R \mid S)$ be \emph{minimal redundant}
if $(X,Y)$ is conditionally redundant but for every $y \in Y$,
$(X,Y-\{y\})$ is a conditionally non-redundant instance of $\CSP(R \mid S)$. 
Note that this is a well-behaved notion since conditionally
non-redundant instances $(X,Y)$ are closed under taking subsets of $Y$. We now show the following.

\begin{lemma}\label{lem:H-to-P}
  Let $(X,Y)$ be a minimal redundant instance of $\CSP(R \mid S)$
  for some $R \subseteq S \subseteq D^r$.
  Let $y \in Y$ be such that there is no assignment $\psi$
  that satisfies every $y' \in Y-\{y\}$ (i.e., $\psi(y') \in R$) but has $\psi(y) \in S \setminus R$. 
  Then there is a unit multisorted polymorphism pattern $P$ and a
  permutation $y_1, \ldots, y_m$ of $Y-\{y\}$ such that $P \in \mpattern(R,\widetilde{S})$ and $p_1 \in \interpretation{X_1}{P_1}, \ldots, p_r \in \interpretation{X_r}{P_r}$ such that
  $(p_1, \ldots, p_r)(y_1,\ldots,y_m)=y$ and $\cH(P)=(X,Y)$.
  \end{lemma}

\begin{proof}
  Let $Y=\{y_1,\ldots,y_m,y\}$ and let $y$ be such that there is no
  assignment $\psi$ such that $\psi(y') \in R$ for every $y' \in Y-\{y\}$
  and $\psi(y) \in S \setminus R$. This exists, as otherwise $(X,Y)$
  is conditionally non-redundant. Define a multisorted pattern
  $P=(P_1,\ldots,P_r)$ on variable set $X$ such that for $i \in [r]$
  we have $P_i=\{((y_1(i), \ldots, y_m(i)),y(i)\}$. Observe that $P$ is a unit and non-trivial.  Next, we show that $P \in \mpattern(R,\widetilde{S})$.

  Assume for the sake of contradiction that $P \not\in \mpattern(R,\widetilde{S})$. Then, there exist tuples $t_1, \ldots, t_m \in R$ and $p_1 \in \interpretation{X_1}{P_1}, \ldots, p_r \in \interpretation{X_r}{P_r}$
  such that $t = (p_1, \ldots, p_r)(t_1,\ldots,t_m)$ is defined and $t \in S \setminus R$.
  Define $\psi \colon X \to D$ by letting $\psi(y_i(j))=t_i(j)$ for
  every $i \in [m]$, $j \in [r]$, and likewise $\psi(y(j))=t(j)$.
  Note that this is consistently defined by construction of $P$.
  Then $\psi(y_i) \in R$ for every $i \in [m]$, and $\psi(y) \in S \setminus R$, 
  which is contrary to our assumptions. Thus $P \in \mpattern(R,\widetilde{S})$.
  The remaining statements hold by construction. 
\end{proof}
To finish our characterization we first define the following tensor product  which allows us to combine two promise relations $(S_1, T_1)$  and $(S_2, T_2)$ into a promise relation of the same arity but over a larger domain. First, given $R$ and $S$ we let
\[R \otimes S := (\{((a_1,b_1),\hdots, (a_r,b_r)) : a \in R, b \in S\}, ),\]
and then
\[(S_1, T_1) \otimes (S_2, T_2) := (S_1 \otimes S_2, T_1 \otimes T_2).\]

\begin{proposition}
    Let $(S_1, T_1)$ and $(S_2, T_2)$ be two $r$-ary multisorted relations with $r$ sorts. Then $(S_1, T_1) \otimes (S_2, T_2)$ is fgppp-equivalent to $\{(S_1, T_1), (S_2, T_2)\}$.
\end{proposition}

\begin{proof}
  Assume that $S_1 \subseteq T_1 \subseteq D_1 \times \ldots \times D_r$ and that $S_2 \subseteq T_2 \subseteq E_1 \times \ldots \times E_r$. For $1 \leq i \leq r$ let $g^i_1 \colon D_i \times E_i \to D_i$ be the first projection and $g^i_2 \colon D_i \times E_i \to E_i$ the second projection. Then, 
    \[
    (S_1 \otimes S_2)(x_1, \hdots, x_r) \equiv S_1(g^1_1(x_1), \hdots, g^r_1(x_r)) \wedge S_2(g^1_2(x_1), \hdots, g^r_2(x_r)),
  \]
  and
      \[
    (T_1 \otimes T_2)(x_1, \hdots, x_r) \equiv T_1(g^1_1(x_1), \hdots, g^r_1(x_r)) \wedge T_2(g^1_2(x_1), \hdots, g^r_2(x_r)).
  \]
    Thus, $\{(S_1, T_1), (S_2, T_2)\}$ fgppp-defines $(S_1, T_1) \otimes (S_2, T_2)$. For the other direction, fix $s \in S_2 \subseteq T_2$, and for $i \in [r]$, let $h_i : D_i \to D_i \times E_i$ be the map $h_i(x) = (x, s_i)$. Then,
    \[
    S_1(x_1, \hdots, x_r) \equiv (S_1 \otimes S_2)(h_1(x_1), \hdots, h_r(x_r)),
  \]
  and
      \[
    T_1(x_1, \hdots, x_r) \equiv (T_1 \otimes T_2)(h_1(x_1), \hdots, h_r(x_r)).
  \]
    By an analogous formula, $(S_1, T_1) \otimes (S_2, T_2)$ fgppp-defines $(S_2, T_2)$ as well.
\end{proof}

Via Corollary~\ref{cor:pattern_galois} we obtain the following general description.

\begin{corollary} \label{cor:tensor-pol} 
Let $(S_1, T_1)$ and $(S_2, T_2)$ be two multisorted promise relations with $r$ sorts. Then 
\begin{enumerate}
 \item $(S_1, T_1) \otimes (S_2, T_2)$ is fgppp-equivalent to $\{(S_1, T_1), (S_2, T_2)\}$, and
 \item $\mpattern(\{(S_1, T_1), (S_2, T_2)\}) = \mpattern((S_1, T_1) \otimes (S_2, T_2))$.
 \end{enumerate}
\end{corollary}

Given a set of multisorted patterns $Q$ (all with exactly $r$ sorts), we define $\inv^{= r}(Q)$ to be the set of multisorted pairs $(R,\widetilde{S})$ of arity $r$ over any domain with exactly $r$ sorts, one for each argument, such that $(R,\widetilde{S}) \in \inv(Q)$. We then define \[\NRD(\inv^{(= r)}(Q), n) := \max_{(R,S) \in \inv^{= r}(Q)}\NRD(R \mid S, n).\] We now prove  that $\NRD(\inv^{= r}(Q, n)$ is precisely captured by a hypergraph Tur{\'a}n problem, generalizing observations of \cite{bessiere2020Chain,carbonnel2022Redundancy}. 

%

\begin{theorem}\label{lem:inv-turan}
  Let $Q$ be a finite set of multisorted polymorphism patterns with exactly $r$ sorts. Then there is a finite set $\cH(Q)$ of $r$-partite hypergraphs with the following property: %
  for all $n \in N$,
  \begin{align}
    \NRD(\inv^{= r}(Q), n) = \ex_r(n, \cH(Q)),\label{eq:nrd-turan}
  \end{align}
  where $\ex_r(n, \cH)$ is the size of the largest $r$-partite $r$-uniform hypergraph on $n$ vertices excluding $\cH$.
%
%
%
%
%
\end{theorem}

%

%


\begin{proof}
Let $[Q]_{\surj}$ be the closure of $Q$ with respect to \emph{surjective} minors: in other words, if $P \in Q$ of arity $m$, then $P'$ of arity $n$ is in $[Q]_{\surj}$ if there exists a surjective function $h \colon [m] \to [n]$ (so $n \le m$) such that for $i \in [r]$ and every $((x_1,\hdots, x_n), x) \in P'_i$ we have that $((x_{h(1)}, \hdots, x_{h(m)}), x) \in P_i$.

Recall that if $P$ is a unit pattern polymorphism, then there is a corresponding hypergraph $\cH(P)$. Slightly overloading the notation we then define
\[
    \cH(Q) := \{\cH(P) : P \in [Q]_{\surj}, P\text{ unit}\}.
\]

We prove (\ref{eq:nrd-turan}) as a pair of inequalities. Since $\inv^{= r}(Q) = \inv^{= r}([Q]_{\surj})$ (this is a special case of Proposition~\ref{prop:minors_preserve}), we have that the $\le$ direction of (\ref{eq:nrd-turan}) is an immediate consequence of Lemma~\ref{lem:unit-pattern-hypergraph}. 
%

Let $(X,Y)$ be the largest $r$-partite hypergraph on $n$ vertices which is $\cH(Q)$-free. For every $Y' \subseteq Y$ and $y' \in Y'$, let $P(Y',y')$ be the $r$-sorted unit pattern polymorphism of arity $\ar(P(Y',Y')= |Y'|-1$ which maps $Y' \setminus \{y'\}$ to $y'$.
%

%
The key observation is that $P(Y', y') \not\in [Q]_{\min}$. %
If not, there exists $P' \in Q$ and $P'' \subseteq P'$ unit such that $P(Y', y') = (P'')_{/h}$ for some \emph{non}-surjective $h \colon [\ar(P'')] \to [\ar(P(Y',y'))]$. Note then there must exist $Y'' \subseteq Y'$ and a surjective map $h' \colon [\ar(P'')] \to [\ar(P(Y'',y')]$ such that $h$ and $h'$ are equivalent in the sense that $P(Y'', y') = (P'')_{/h'}$
%
In that case, $P(Y'', y') \in [Q]_{\min}$, which contradicts the fact that $(X,Y)$ and thus $(X,Y'')$ is $\cH(Q)$-free.

%

Thus, $P(Y', y') \not\in [Q]_{\min}$, so $\inv^{= r}(Q) \supsetneq \inv^{= r}(Q \cup \{P(Y',y')\})$. Thus, it is possible to find $(R(Y',y'), S(Y',y')) \in \inv^{= r}(Q)$ such that $P(Y',y') \not\in \mpattern(R(Y',y'), S(Y',y'))$. Now define
\[
    (R, S) := \bigotimes_{Y' \subseteq Y, y' \in Y'} (R(Y',y'), S(Y',y')).
\]
%
By Corollary~\ref{cor:tensor-pol}, we know that $Q \subseteq \mpattern(R, S)$, but $P(Y',y') \not\in \mpattern(R, S)$ for all $Y'$ and $y'$. To finish, it suffices to prove that $(X,Y)$ is a conditionally non-redundant instance of $\CSP(R \mid S)$.
If not, there exists a minimally redundant subinstance $(X,Y')$. By Lemma~\ref{lem:H-to-P}, we then have that $P(Y', y') \in \mpattern(R,\widetilde{S}),$ a contradiction. Thus, $(X,Y)$ is non-redundant.
\end{proof}

