\section{Omitted Details from Section~\ref{sec:frac}}\label{app:frac}

\subsection{Connections to Kernelization}\label{app:ker}

Recall that that for $p \ge q$, we define $\SATDP_{p,q}$ to be $\{\ORDP_{p,q}, \CUT\}$ where $\ORDP_{p,q}$ is defined in \Cref{def:Rpq} and $\CUT = \{(0,1), (1,0)\}$. We now work toward showing that the kernelization exponent of $\CSP(\SATDP_{p,q})$ is $p/q$. 

\begin{lemma} \label{lem:lowerbound:transform}
For each fixed~$p,q \in \mathbb{N}$ with~$p \geq q$, there is a polynomial-time reduction that transforms any $n$-variable instance~$\phi$ of CNF-$p$-SAT into an equivalent instance~$(V,C)$ of $\csp(\SATDP_{p,q})$ with~$|V| = 2n + (2n)^q$ variables.
\end{lemma}
\begin{proof}
Consider an instance~$\phi$ of~CNF-$p$-SAT. It consists of a set of clauses~$A_1, \ldots, A_m$ over Boolean variables~$x_1, \ldots, x_n$, with each clause~$A_i$ being a disjunction of literals. Each literal is either a variable~$x_i$ or its negation~$\neg x_i$. 

We construct an equivalent instance of~$\csp(\SATDP_{p,q})$ in the following way. Let~$X := \{x_i, \overline{x}_i \mid i \in [n]\}$ and~$\widetilde{X} := \{\tilde{x}_\mathbf{x} \mid \mathbf{x} \in X^q\}$. So~$X$ contains one element for each possible literal of~$\phi$, while~$\widetilde{X}$ contains one element for each $q$-tuple~$\mathbf{x}$ of literals. We use~$V = X \cup \widetilde{X}$ as the set of variables for the CSP under construction. We will refer to the variables in~$X$ as the \emph{Boolean} variables and to those in~$\widetilde{X}$ as the \emph{padding} variables. Observe that~$|V| = 2n + (2n)^q$, as claimed. In the remainder, it will be convenient to let~$\mathsf{var}(\ell) \in X$ denote the variable in~$X$ corresponding to a literal~$\ell$. So if~$\ell = x_i$ is a positive literal, we have~$\mathsf{var}(\ell) = x_i$, while for negative literals~$\neg x_i$ we have~$\mathsf{var}(\ell) = \overline{x}_i$.

To ensure that the variables~$x_i$ and~$\overline{x}_i$ act as each others negations, we add the constraint~$\CUT(x_i, \overline{x}_i)$ to~$C$ for each~$i \in [n]$.

We transform clauses of~$\phi$ into constraints using the relation~$\ORDP_{p,q}$, as follows. For each clause~$A_j = \ell_1 \vee \ldots \vee \ell_p$, where each~$\ell_k$ is a literal of the form~$x_i$ or~$\neg x_i$, we add a corresponding constraint~$\ORDP_{p,q}(\mathbf{v}_j)$ to~$C$, where~$\mathbf{v}_j$ is a tuple of~$p + p^q$ elements of~$V$. The $i$th value of~$\mathbf{v}_j$, denoted~$\mathbf{v}_j[i]$, is defined as follows:
\begin{itemize}
    \item if~$i \in [p]$, then~$\mathbf{v}_j[i] = \mathsf{var}(\ell_i)$.
    \item if~$i > p$, then~$\mathbf{v}_j[i] = \tilde{x}_{\mathbf{x}}$, where~$\mathbf{x} \in X^q$ is the $q$-tuple of Boolean variables defined as follows. Let~$I := (i_1, \ldots, i_q) = \idx_{p,q}(i-p)$ be the tuple of~$q$ indices in the range~$[p]$ that is labeled~$i-p$ by the chosen bijection~$\idx_{p,q}$. Then we define:
    \begin{equation}
        \mathbf{x} = (\mathsf{var}(\ell_{i_1}), \ldots, \mathsf{var}(\ell_{i_q})).
    \end{equation}
\end{itemize}
So the tuple of variables to which the constraint associated to clause~$A_j$ is applied is computed as follows: the first~$p$ variables are Boolean variables corresponding to the literals occurring in~$A_j$; the remaining variables are padding variables. The padding variable~$\tilde{x}_{\mathbf{x}}$ used at position~$p + i$ is the one that was created for the $q$-tuple of literals that appear in clause~$A_j$ at the positions encoded by~$\idx_{p,q}(i)$.

This concludes the description of the~$\csp(\SATDP_{p,q})$-instance~$(V,C)$, which can easily be done in polynomial time for fixed~$p$ and~$q$. It remains to argue that the Boolean formula~$\phi$ is satisfiable if and only if~$(C,V)$ is satisfiable. We first argue the converse. If~$\sigma \colon V \to D_{p,q}$ is an assignment that satisfies all constraints of~$C$, then its restriction to the original variables~$\{x_1, \ldots, x_n\}$ satisfies all clauses of~$\phi$. To see this, consider an arbitrary clause~$A_j$ of~$\phi$. Since~$\sigma$ satisfies all constraints of~$C$, in particular it satisfies the constraint~$\ORDP_{p,q}(\mathbf{v}_j)$ that was inserted into~$C$ on account of clause~$A_j$. By construction, the first~$p$ variables of~$\mathbf{v}_j$ correspond to the literals in~$A_j$. By definition of~$A_j$, the constraint~$\ORDP_{p,q}(\mathbf{v}_j)$ can only be satisfied if the values of the first~$p$ variables of~$\mathbf{v}_j$ are Boolean, and at least one of them is~$1$. Hence there is a literal~$\ell_i$ in clause~$A_j$ such that the corresponding variable (either~$x_i$ or~$\overline{x}_i$) in~$X$ has value~$1$ under~$\sigma$. If~$\ell_i$ is positive, this directly shows that the restriction of~$\sigma$ to~$\{x_1, \ldots, x_n\}$ satisfies clause~$A_j$. If~$\ell_i$ is a negative literal of the form~$\neg x_k$, then we know~$\sigma(\overline{x}_k) = 1$. Since~$\sigma$ also satisfies the constraint~$(\CUT, (x_k, \overline{x}_k))$ that was inserted into~$C$, we find~$\sigma(x_k) = 0$. This again guarantees that the restriction of~$\sigma$ to~$\{x_1, \ldots, x_n\}$ satisfies~$A_j$. As this argument applies for an arbitrary clause~$C_j$, the entire formula~$\phi$ is indeed satisfied by the stated assignment.

%

To conclude the proof, we establish correctness in the converse direction: if~$\phi$ has a satisfying assignment~$f \colon \{x_1, \ldots, x_n\} \to \{0,1\}$, then~$(C,V)$ has a satisfying assignment~$\sigma \colon V \to D_{i,j}$. The assignment~$\sigma$ is derived from~$f$ as follows.
\begin{itemize}
    \item For each positive Boolean variable~$x_i \in V \cap X$ we set~$\sigma(x_i) = f(x_i)$.
    \item For each negative Boolean variable~$\overline{x}_i \in V \cap X$ we set~$\sigma(\overline{x}_i) = 1 - f(x_i)$.
    \item For each padding variable~$\tilde{x}_\mathbf{x}$ where~$\mathbf{x} = (x_{i_1}, \ldots, x_{i_q}) \in X^q$, the value~$\sigma(\tilde{x}_\mathbf{x})$ is the bitstring~$(f(x_{i_1}) \ldots f(x_{i_q}))$.
\end{itemize}
Hence the value of a padding variable~$\tilde{x}_{\mathbf{x}}$ that was created on account of a tuple of~$q$ Boolean variables is simply the bitstring obtained by concatenating the $f$-values of these Boolean values. From these definitions, it is straightforward to verify that~$\sigma$ satisfies~$(V,C)$. Since each clause of~$\phi$ is satisfied by~$f$, in each constraint of the form~$\ORDP_{p,q}(\mathbf{v}_j)$ created for a clause~$A_j$, one of the first~$p$ Boolean variables will be set to~$1$ since~$f$ satisfies a literal of~$A_j$. Since the values of the padding variables appearing in the rest of the constraint are defined precisely as the bitstrings of the values whose positions they control, the remaining conditions of \Cref{def:Rpq} are also satisfied. This concludes the proof of \Cref{lem:lowerbound:transform}.
\end{proof}

By combining the reduction from in the previous lemma with known kernelization lower bounds for CNF-$p$-SAT due to Dell and van Melkebeek~\cite{dell2014Satisfiability}, we obtain kernelization lower bounds for~$\CSP(\SATDP_{p,q})$. We introduce some terminology that allows us to draw this connection. In the following, a \emph{parameterized problem}~$Q$ is a subset of $\Sigma^* \times \mathbb{N}_{+}$, where $\Sigma$ is a finite alphabet. When applying tools of parameterized complexity to our study of CSPs, we use the number of variables~$n$ in the CSP as the parameter~$k$ of the parameterized problem.

\begin{definition} \label{def:gen:kernel}
Let $Q, Q' \subseteq \Sigma^*\times\mathbb{N}_{+}$ be parameterized problems and let $h \colon \mathbb{N}_{+}\rightarrow\mathbb{N}_{+}$  be a computable function. A \emph{generalized kernelization for $Q$ into $Q'$ of size $h(k)$} is an algorithm that, on input $(x,k) \in \Sigma^*\times\mathbb{N}_{+}$, takes time polynomial in $|x|+k$ and outputs an instance $(x',k')$ such that:
\begin{enumerate}
\item $|x'|$ and $k'$ are bounded by $h(k)$, and
\item $(x',k')\in Q'$ if and only if $(x,k) \in Q$.
\end{enumerate}
The algorithm is a \emph{polynomial generalized kernelization} if $h(k)$ is a polynomial.
\end{definition}

The adjective \emph{generalized} corresponds to the fact that the algorithm is allowed to map instances from the source problem~$Q$ into equivalent instances of a different (but fixed) decision problem~$Q'$. Using this terminology, the lower bound by Dell and van Melkebeek can be stated as follows.

\begin{theorem}[\cite{dell2014Satisfiability}] \label{cnf:dell:lowerbound}
    For each integer~$p \geq 3$ and~$\varepsilon > 0$, the CNF-$p$-SAT problem parameterized by the number of variables~$n$ does not admit a generalized kernelization of size~$\Oh(n^{p-\varepsilon})$ unless \containment.
\end{theorem}

In this theorem, and in \Cref{def:gen:kernel}, the size of the instances is measured in terms of the number of symbols over alphabet~$\Sigma$, i.e., in terms of the number of bits needed to encode the instance. Our definition of the size of a kernelization for $\CSP(\Gamma)$ in the introduction was measuring the number of \emph{constraints} in the reduced instance. Notice that in our setting of CSPs over finite constraint languages consisting of finite relations, the difference between these two types of measurements is small: an instance that is encoded in~$f(n)$ bits has at most~$f(n)$ constraints, while an instance of~$f(n)$ constraints can be encoded in~$\Oh_\Gamma (f(n) \log n)$ bits by encoding, for each constraint, which relation~$R \in \Gamma$ it uses ($\Oh_\Gamma(1)$ bits) and to which variables the constraint is applied ($\Oh_R(1)$ variables, each encoded in~$\Oh(\log n)$ bits). Since our notion of kernelization exponent is oblivious to~$\log n$ factors, when considering the kernelization exponent of nonuniform CSPs it does not matter whether we measure kernelization size in bits or constraints. With this knowledge, we present the lower bound in the following lemma.

\begin{lemma} \label{lem:kernel:lowerbound}
Assuming \ncontainment, for each fixed~$p,q \in \mathbb{N}$ with~$p \geq q$ and~$p \geq 3$, the kernelization exponent of~$\csp(\SATDP_{p,q})$ is at least~$\frac{p}{q}$.
\end{lemma}
\begin{proof}
Assume for a contradiction that the kernelization exponent of~$\csp(\SATDP_{p,q})$ is less than~$\frac{p}{q}$. It follows that there exists a positive real~$\eps$ such that~$\csp(\SATDP_{p,q})$ has a kernelization that reduces to equisatisfiable instances with~$\Oh(n^{\frac{p}{q}-\eps})$ constraints.

By \Cref{cnf:dell:lowerbound}, to contradict the assumption \ncontainment it suffices to leverage \Cref{lem:lowerbound:transform} together with the assumed kernelization for $\csp(\SATDP_{p,q})$ into a generalized kernelization for CNF-$p$-SAT of bitsize~$\Oh(n^{p-\delta})$ for some~$\delta > 0$. This can be done as follows.

Given an $n$-variable instance~$\phi$ of CNF-$p$-SAT, the generalized kernelization transforms it into an equivalent instance~$(V,C)$ of~$\csp(\SATDP_{p,q})$ on~$|V| = 2n+(2n)^q$ variables by invoking \Cref{lem:lowerbound:transform}. It then applies the assumed kernelization to~$(V,C)$, resulting in an equivalent instance~$(V',C')$ on at most~$\Oh(|V|^{\frac{p}{q} - \eps}) \leq \Oh(n^q)^{\frac{p}{q} - \eps} \leq \Oh(n^{p - q \eps})$ constraints. Since variables not occurring in any constraint can be removed without changing the answer to the instance, while the arity of the constraints is~$\Oh(1)$ for fixed~$p$ and~$q$, we may assume without loss of generality that~$|V'| \leq \Oh(|C'|) \leq \Oh(n^{p - q \eps})$. Hence the identity of a single variable can be encoded in~$\log_2 \Oh(n^{p - q \eps}) \leq \Oh(\log_2 n)$ bits; here we use the fact that~$\log_2(n^{p - q\eps}) = (p - q\eps) \cdot \log_2 (n)$ while~$p \in \Oh(1)$. As the arity of each constraint is constant, each constraint of the instance~$(V',C')$ can be encoded in~$\Oh(\log n)$ bits by listing the binary representations of the indices of all the variables occurring in the constraint. Hence instance~$(V',C')$ can be encoded in~$\Oh(n^{p - q\eps} \log n)$ bits and is equivalent to the CNF-$p$-SAT instance~$\phi$. Since both transformation steps can be carried out in polynomial time, this results in a generalized kernelization for CNF-$p$-SAT of bitsize~$\Oh(n^{p - q\eps} \log n)$. Since~$\log n \in \Oh(n^\beta)$ for each~$\beta > 0$, this shows that CNF-$p$-SAT has a generalized kernelization of bitsize~$\Oh(n^{p - q\eps + \frac{q \eps}{2}})$, so of size~$\Oh(n^{p - \delta})$ for~$\delta = \frac{q \eps}{2} > 0$. But this implies \containment via the results of Dell and van Melkebeek~\cite{dell2014Satisfiability}.
\end{proof}

Note that while the statement of \Cref{lem:kernel:lowerbound} requires~$p \geq 3$, for any rational number~$\frac{p}{q} \geq 1$ we can write it as a ratio~$\frac{3p}{3q}$ of numbers that are at least three. We now prove the corresponding upper bounds. The manner in which we use the Kruskal-Katona theorem to bound the size of the instance after preprocessing is very similar to the proof of \Cref{lem:or-dp:upper}, but additional effort is needed to make the proof algorithmic and avoid the assumption of having multipartite instances.

\begin{lemma} \label{lem:kernel:upperbound}
For each fixed~$p,q \in \mathbb{N}$ with~$p \geq q$, there is a polynomial-time kernelization algorithm that transforms any $n$-variable instance~$(V,C)$ of $\csp(\SATDP_{p,q})$ into an equivalent instance~$(V',C')$ with~$|C'| \leq \Oh_{p,q}(n^{\frac{p}{q}})$. Hence the kernelization exponent of~$\CSP(\SATDP_{p,q})$ is at most~$\frac{p}{q}$.
\end{lemma}
\begin{proof}
Given an instance~$(V,C)$ of~$\csp(\SATDP_{p,q})$ on~$n := |V|$ variables, the kernelization consists of two phases aimed at reducing the number of constraints over~$\CUT$ and over~$\ORDP_{p,q}$, respectively. For the first phase, it is easy to reduce the number of constraints over~$\CUT$ to~$\Oh(n)$. Consider the graph~$G$ on vertex set~$V$ which has an edge for each constraint over~$\CUT$. If this graph is not bipartite, then since each edge corresponds to a~$\CUT$ constraint that requires the variables represented by its endpoints to have distinct Boolean values, the instance is unsatisfiable. It then suffices to output a constant-size unsatisfiable instance as the result of the kernelization. If~$G$ is bipartite, then we compute a spanning forest~$F$ of~$G$, which contains a spanning tree of each connected component. Remove all~$\CUT$ constraints that do not correspond to an edge in~$F$. We argue that this does not change the satisfiability of the instance, as follows. For each removed constraint~$\CUT(x, x')$, there is a path~$P$ between~$x$ and~$x'$ in the spanning forest~$F$. The path~$P$ has an odd number of edges, as otherwise it would make an odd cycle together with the edge~$\{x,x'\}$ which would violate the assumption that~$G$ is bipartite. As each edge on~$P$ corresponds to ~$\CUT$ constraint that we preserve in the instance, any satisfying assignment to the remaining constraints must alternate the assigned Boolean true/false value for each variable on path~$P$. As the number of edges on~$P$ is odd, to satisfy all cut constraints from~$P$ the value assigned to~$x$ must differ to that of~$x'$. Hence any omitted constraint~$\CUT(x,x')$ must be satisfied by any assignment that satisfies the remaining clauses. Since a spanning forest for a graph on~$|V|$ vertices has less than~$|V|$ edges and can be computed efficiently, the first phase of the kernelization can be executed in polynomial time and reduces the number of~$\CUT$ constraints to~$\Oh(n)$.

For the second phase of the algorithm, which is the most difficult, the goal is to reduce the number of~$\ORDP_{p,q}$ constraints. As an opening step for phase two, we partition the variables of the instance into types: \emph{Boolean} variables (that occur in a constraint over~$\CUT$, or that occur in one of the first~$p$ positions of a constraint over~$\ORDP_{p,q}$) and \emph{padding} variables (that occur in a constraint over~$\ORDP_{p,q}$ at a position after~$p$). If these two sets are not disjoint, then the choice of~$\ORDP_{p,q}$ ensures that even the subinstance consisting of two clauses that have this conflicting use of the variable, is unsatisfiable. Hence we may output such a subinstance as the result of the kernelization and terminate. In the remainder, we may assume the variables are partitioned into Boolean and padding variables.

To reduce the number of constraints of type~$\ORDP_{p,q}$ we apply two simple reduction rules based on the semantics of the~$\ORDP_{p,q}$ predicate, exploiting the fact that the values of padding variables in such constraints uniquely determine the values of the Boolean variables on the positions they govern. We exhaustively apply the following two reduction rules.
\begin{enumerate}
    \item Suppose there are indices~$i, i' \in [p^q]$ for which the instance contains two (not necessarily distinct) constraints
    \begin{align*}
    y =& \ORDP_{p,q}(x_1, \ldots, x_p, \tilde{x}_1, \ldots, \tilde{x}_{p^q}),\\
    y' =& \ORDP_{p,q}(x'_1, \ldots, x'_p, \tilde{x}'_1, \ldots, \tilde{x}'_{p^q}),
    \end{align*}
    such that~$\tilde{x}_i = \tilde{x}'_{i'}$ but for the associated tuples~$(t_1, \ldots, t_q) = \idx_{p,q}(i)$ and~$(t'_1, \ldots, t'_q) = \idx_{p,q}(i')$ we have~$(x_{t_1}, \ldots, x_{t_j}) \neq (x'_{t'_1}, \ldots, x'_{t'_j})$. In other words, there are two constraints that use the same padding variable~$\tilde{x}_i = \tilde{x}'_{i'}$, but the tuples of Boolean variables they control differ. Let~$j \in [q]$ such that~$x_{t_j} \neq x'_{t'_j}$. We now simplify the instance as follows: replace all occurrences of variable~$x'_{t'_j}$ in the CSP by~$x_{t_j}$ and remove variable~$x'_{t'_j}$. It is clear that any satisfying assignment of the reduced instance yields a satisfying assignment to the original, by simply assigning the eliminated variable~$x'_{t'_j}$ the same value as~$x_{t_j}$. Due to the semantics of~$\ORDP_{p,q}$ (Property~\ref{constraint:dp} in \Cref{def:Rpq}) the other direction holds as well: any satisfying assignment to the original instance must assign~$x_{t_j}$ and~$x'_{t'_j}$ the same value, since the value of both variables must match the $j$-th bit in the bitstring assigned as the value for~$\tilde{x}_i = \tilde{x}'_{i'}$. Hence this replacement preserves the satisfiability of the instance while strictly reducing the number of variables.
%
    %
%
    %
    %
    Intuitively, this reduction rule ensures that each $q$-tuple of Boolean variables that occurs in some constraint has a \emph{unique} padding variable associated to it, which we will exploit in the analysis below.
    \item Suppose there is an index~$i \in [p^q]$ for which the instance contains two constraints 
    \begin{align*}
    y =& \ORDP_{p,q}(x_1, \ldots, x_p, \tilde{x}_1, \ldots, \tilde{x}_{p^q}),\\
    y' =& \ORDP_{p,q}(x'_1, \ldots, x'_p, \tilde{x}'_1, \ldots, \tilde{x}'_{p^q}),
    \end{align*}
    in which the padding variables~$\tilde{x}_i, \tilde{x}'_i$ used on the $i$-th padding position are distinct, but in which the tuples of Boolean variables appearing at positions~$(t_1, \ldots, t_q) := \idx_{p,q}(i)$ are identical, so that~$\tilde{x}_i \neq \tilde{x}'_i$ while~$(x_{t_1}, \ldots, x_{t_q}) = (x'_{t_1}, \ldots, x'_{t_q})$. Then we do the following: replace all occurrences of padding variable~$\tilde{x}'_i$ by padding variable~$\tilde{x}_i$ and then remove~$\tilde{x}'$ from the instance. Due to the semantics of~$\ORDP_{p,q}$ (Property~\ref{constraint:dp} in \Cref{def:Rpq}), any satisfying assignment to the original instance must give~$\tilde{x}_i$ and~$\tilde{x}'_i$ the same value since the value of both variables is the bitstring of values assigned to the~$q$ Boolean variables~$(x_{t_1}, \ldots, x_{t_q}) = (x'_{t_1}, \ldots, x'_{t_q})$. Hence this replacement preserves the satisfiability of the instance. 

    Exhaustive application of this reduction rule ensures that for each $p$-tuple of Boolean variables, there is at most one constraint over~$\ORDP_{p,q}$ in which that exact $p$-tuple appears on the first~$p$ positions.
\end{enumerate}
The instance~$(V',C')$ that is obtained from exhaustively applying these reduction rules is returned as the output of the kernelization algorithm. Since all preprocessing steps preserve the satisfiability of the instance, it is equisatisfiable to~$(V,C)$. As the reduction rules can easily be implemented to run in polynomial time, it remains to argue that the number of constraints~$|C'|$ in the reduced instance is bounded by~$\Oh_{p,q}(n^{\frac{p}{q}})$. Since the number of constraints over~$\CUT$ has been reduced to~$\Oh(n)$ by the first phase, it suffices to bound the constraints~$C^* \subseteq C'$ over~$\ORDP_{p,q}$. Note that~$|V'| \leq |V| = n$ since we never introduce new variables. Now we set up an application of the Kruskal-Katona theorem to bound the number of constraints~$|C^*|$ in terms of the number of variables~$|V'|$. 

The set family~$\mathcal{A}$ to which we apply the Kruskal-Katona theorem is defined over the universe~$V' \times [p]$. For each constraint~$y = \ORDP_{p,q}(x_1, \ldots, x_p, \tilde{x}_1, \ldots, \tilde{x}_{p^q})$ in~$C^*$, we add a set~$A_y = \{ (x_1, 1), (x_2, 2), \ldots, (x_p, p)\}$ to~$\mathcal{A}$. Since all pairs in the set have different second coordinates, the resulting set family~$\mathcal{A}$ is $p$-uniform. Let~$\mathcal{B}$ be the $q$-shadow of~$\mathcal{A}$, i.e., it contains each size-$q$ subset~$B \subseteq V' \times [p]$ for which~$B$ is contained in some set~$A_y$ of~$\mathcal{A}$. Next, we relate~$|\mathcal{A}|$ to~$|C^*|$ and~$|\mathcal{B}|$ to~$|V'|$.

Observe first that~$|C^*| = |\mathcal{A}|$. This follows from the fact that each constraint~$y \in C^*$ contributes a set~$A_y$ to~$\mathcal{A}$, while no two distinct constraints can contribute the same set: that would mean there are two distinct constraints over~$\ORDP_{p,q}$ in which the \emph{same} $p$-tuple of variables appears on the first~$p$ positions, which triggers the second reduction rule.

Next, we will argue that~$|\mathcal{B}| \leq |V'| \cdot p^q$ by relating sets in the $q$-shadow to padding variables. To establish this we provide an injection~$f \colon \mathcal{B} \to V' \times [p^q]$, where the Cartesian product with~$[p^q]$ plays the role of the reduction to a multipartite instance in \Cref{lem:or-dp:upper}. The injection~$f$ is defined as follows. Consider a $q$-set~$B = \{(x_{t_1}, t_1), \ldots, (x_{t_q}, t_q)\} \in \mathcal{B}$ and label its elements such that~$t_1 < \ldots < t_q$. Let~$S_y \in \mathcal{A}$ be a set that contains~$B$ and consider the constraint~$y = \ORDP_{p,q}(x'_1, \ldots, x'_p, \tilde{x}'_1, \ldots, \tilde{x}'_{p^q}) \in C^*$ for which~$S_y$ was added to~$\mathcal{A}$. Since~$B$ is a subset of~$S_y$, while the pairs over~$V' \times [p]$ encode the positions at which Boolean variables appear in constraints of~$C^*$, we have~$x_{t_j} = x'_{t_j}$ for each~$j \in [q]$: for each pair~$(x,j) \in B$ consisting of a Boolean variable~$x$ and a position~$j \in [p]$, the $j$-th Boolean variable in constraint~$y$ is~$x$. Let~$i := \idx_{p,q}^{-1}(t_1, \ldots, t_q) \in [p^q]$ be the index of the $q$-tuple of positions represented by~$B$. Then we define~$f(B) := (\tilde{x}_{i}, i)$, that is, we map set~$B$ to the pair consisting of~$i$ and the padding variable that occurs in constraint~$y$ at the position~$i$ that controls the $q$-tuple of variables in~$B$.

Next, we argue that~$f$ is indeed an injection. Suppose for a contradiction that two distinct sets~$B,B' \in \mathcal{B}$ map to the same pair~$(\tilde{x}, i)$; let these be $B = \{(x_{t_1}, t_1), \ldots, (x_{t_q}, t_q)\}$ and~$B' = \{(x'_{t'_1}, t'_1), \ldots, (x'_{t'_q}, t'_q)\}$ labeled with~$t_1 < \ldots < t_q$ and~$t'_1 < \ldots < t'_q$. Since~$f(B) = f(B') = (\tilde{x}, i)$, they agree on their second coordinate which implies that~$i = \idx_{p,q}(t_1, \ldots, t_q) = \idx_{p,q}(t'_1, \ldots, t'_q)$. Hence the $q$-sets~$B, B'$ are obtained from $p$-sets~$A_y, A_{y'}$ by selecting the Boolean variables from the \emph{same} positions~$(t_1, \ldots, t_q) = (t'_1, \ldots, t'_q)$ of the respective constraints~$y, y'$. Since the sets~$B, B'$ are distinct while their projection onto the second element of the pairs yields the same set~$\{t_1, \ldots, t_q\} = \{t'_1, \ldots, t'_q\}$ of indices, there is an index~$j \in [q]$ for which~$(x_{t_j}, t_j) \neq (x'_{t'_j}, t'_j)$ with~$t_j = t'_j$. Consequently,~$x_{t_j} \neq x'_{t'_j}$ are \emph{distinct} Boolean variables in clauses~$y, y'$, that appear on a position~$t_j$ controlled by a padding variable with index~$i$, and the two constraints~$y,y'$ use the \emph{same} padding variable~$\tilde{x}$ at position~$i$. But this contradicts the assumption that the first reduction rule is exhaustively applied. We conclude that~$f$ is indeed an injection.
%

We now use these bounds to finish the proof. As in the proof of \Cref{lem:or-dp:upper}, let~$c_{p,q} \geq 1$ be any constant such that~$\binom{m}{p} \leq c_{p,q} \cdot \binom{m}{q}^{\frac{p}{q}}$. Since~$f$ is an injection from~$\mathcal{B}$ to~$V' \times [p^q]$ we infer~$|\mathcal{B}| \leq |V'| \cdot p^q$. Let~$m \geq p$ be the largest integer such that~$|\mathcal{A}| \geq \binom{m}{p}$, so that~$|\mathcal{A}| < \binom{m+1}{p} \leq 2p \binom{m}{p}$. By the Kruskal-Katona theorem (\Cref{kruskal-katona}) we have~$|V'| \cdot p^q \geq |\mathcal{B}| \geq \binom{m}{q}$. Hence we can now derive:
\begin{align*}
    |C^*| = |\mathcal{A}| \leq 2p \cdot \binom{m}{p} \leq 2p \cdot c_{p,q} \cdot \binom{m}{q}^{\frac{p}{q}} \leq 2p \cdot c_{p,q} \cdot (|V'| \cdot p^q)^{\frac{p}{q}} \leq \Oh_{p,q}(n^{\frac{p}{q}}).
\end{align*}
As this directly bounds the kernelization exponent of~$\CSP(\SATDP_{p,q})$, it concludes the proof of \cref{lem:kernel:upperbound}.
\end{proof}

By combining the upper- and lower bounds, we now derive the main result of this section.

\begin{theorem}
    Let~$p \geq q \in \N$ such that~$p \geq 3$. Assuming \ncontainment, the kernelization exponent of~$\CSP(\SATDP_{p,q})$ is~$\frac{p}{q}$. Hence every rational number of value at least one is the kernelization exponent of some CSP.
\end{theorem}
\begin{proof}
    For~$p \geq q \in \N$ with~$p \geq 3$, \Cref{lem:kernel:lowerbound} shows that under the assumption~\ncontainment the kernelization exponent of~$\CSP(\SATDP_{p,q})$ must be at least~$\frac{p}{q}$, while~\Cref{lem:kernel:upperbound} gives a matching upper bound. Hence the kernelization exponent is~$\frac{p}{q}$. As every fraction~$\frac{p'}{q'} \geq 1$ of integers can be written as~$\frac{3p'}{3q'}$ satisfying this premise, every rational at least one is the kernelization exponent of some CSP.
\end{proof}

\subsection{A Construction of Lower Arity}\label{app:frac-alt}

In this portion of the appendix, we prove Theorem~\ref{thm:frac-nrd-alt}. To help with understanding the main proof technique, we first prove a special case.

%

\subsubsection{Warm-up Predicate}\label{app:warmup}

As a warmup, we consider $p=3$, $q=2$ and $\cF = \{\{1,2\},\{2,3\},\{3,1\}\}$. It is clear that $\cF$ is $2/3$-regular. In that case, we have that the domain $D := E_{3,2}$ is $\{00,01,10,11\}$ and the relation $\DP_{\cF}$ being
\begin{align*}
    \DP_{\cF} := \{&(00,00,00),(00,01,10),(01,10,00),(01,11,10),\\
    &(10,00,01),(10,01,11),(11,10,01),(11,11,11)\}.
\end{align*}
With $\ORDP_{\cF}$ being the same relation except we omit $(00,00,00)$.

\begin{remark}
An fgpp-equivalent formulation of $\ORDP_{\cF}$ is $D := \{0,1,2,3\}$ and \[R := \{012, 120, 201, 321, 213, 132, 333\}.\]
\end{remark}

Using an argument similar to that of \Cref{lem:nrd:or-dp-star:linear}, we can prove that $\NRD(\DP_{\cF}, n) = \Oh(n)$. As such, it suffices understand the asymptotics of $\NRD(\ORDP_{\cF} \mid \DP_{\cF}, n)$. We begin with a lower bound.

\begin{lemma}\label{lem:lb}
$\NRD(\ORDP_{\cF} \mid \DP_{\cF}, n) \ge \Omega(n^{1.5})$.
\end{lemma}

\begin{proof}
Assume that $n = 3t^2$. Let $X := [3] \times [t]^2$. Define $Y \subseteq X^3$ as follows
\[
    Y := \{e_{a,b,c} := ((1,a,b),(2,b,c),(3,c,a)) \in X^3 : a,b,c \in [t]\}.
\]
Obviously, $|Y| = t^3$, so it suffices to prove that $(X,Y)$ is conditionally non-redundant. Fix $(a,b,c) \in [t]^3$ and define $\sigma_{a,b,c} : X \to D$ as follows
\begin{align*}
    \sigma_{a,b,c}(1,a',b') := \begin{cases}
    00 & a=a' \wedge b=b'\\
    01 & a=a' \wedge b\neq b'\\
    10 & a\neq a' \wedge b=b'\\
    11 & a\neq a' \wedge b\neq b'.
    \end{cases}\\
    \sigma_{a,b,c}(2,b',c') := \begin{cases}
    00 & b=b' \wedge c=c'\\
    01 & b=b' \wedge c\neq c'\\
    10 & b\neq b' \wedge c=c'\\
    11 & b\neq b' \wedge c\neq c'.
    \end{cases}\\
    \sigma_{a,b,c}(3,c',a') := \begin{cases}
    00 & c=c' \wedge a=a'\\
    01 & c=c' \wedge a\neq a'\\
    10 & c\neq c' \wedge a=a'\\
    11 & c\neq c' \wedge a\neq a'.
    \end{cases}
\end{align*}
One can check that for every $(a',b',c') \in [t]^3$ we have that $\sigma_{a,b,c}(e_{a',b',c'}) \in \DP_{\cF}$ and $\sigma_{a,b,c}(e_{a',b',c'}) = (00,00,00)$ if and only if $(a,b,c) = (a',b',c')$.
\end{proof}

Now we prove an essentially matching upper bound.

\begin{lemma}\label{lem:ub}
$\NRD(\ORDP_{\cF} \mid \DP_{\cF}, n) = \Oh(n^{1.5})$.
\end{lemma}

\begin{proof}
Let $(X, Y)$ be a conditionally non-redundant instance. By \Cref{lemma:reduction:to:multipartite}, we may assume that the instance is tripartite. That is, $X := X_1 \sqcup X_2 \sqcup X_3$ with $Y \subseteq X_1 \times X_2 \times X_3$. For each $y \in Y$, let $\sigma_y : X \to D$ be an assignment such that $\sigma_y(y) = (00,00,00)$ and $\sigma_y(y') \in \ORDP_{\cF}$ for all $y' \in Y \setminus \{y\}$. Since no $t \in \ORDP_{\cF}$ has two coordinates equal to $00$, we must have that $Y$ is linear (i.e., any two clauses have at most one variable in common).

For distinct $i,j \in [3]$, let $Y_{ij} := \{(y_i, y_j) : y \in Y\} \subseteq X_i \times X_j.$  Since $Y$ is linear, we have that each $Y_{ij}$ has the same cardinality as $Y$. We say that $x, x' \in X_i$ are $j$-equivalent, denoted by $x \sim_j x'$ if $x$ and $x'$ are in the same connected component of $Y_{ij}$. A crucial observation is as follows.
\begin{claim}\label{claim:merge}
Let $x, x' \in X_i$ be such that $x \sim_{i+1} x'$ and $x \sim_{i+2} x'$, then for every $\DP_{\cF}$-satisfying assignment $\sigma : X \to D$ for $Y$, we have that $\sigma(x) = \sigma(x')$.
\end{claim}
\begin{proof}
Note that for any $i \in [3]$, we have that $\DP_{\cF}|_{i,i+1} = \{(00,00),(00,01),(10,00),(10,01)\} \cup$ $\{(01,10),(01,11),(11,10),(11,11)\}$, where indices are taken modulo $3$.
%
Thus, if $x, x' \in X_i$ satisfy $x \sim_{i+1} x'$, then $(\sigma(x), \sigma(x')) \in \{00,10\}^2 \cup \{01,11\}^2$ for any $\DP_{\cF}$-satisfying assignment $\sigma$.

Likewise, since $\DP_{\cF}|_{i,i+2} := \{(00,00),(00,10),(01,00),(01,10)\} \cup$ $ \{(10,01),(10,11), (11,01),$ $(11,11)\}$, so any $x, x' \in X_i$ satisfying $x \sim_{i+2} x'$ must have $(\sigma(x), \sigma(x')) \in \{00,01\}^2 \cup \{10,11\}^2$. Therefore, if $x \sim_{i+1} x'$ and $x \sim_{i+2} x'$, then
\[
    (\sigma(x), \sigma(x')) \in (\{00,10\}^2 \cup \{01,11\}^2) \cap (\{00,01\}^2 \cup \{10,11\}^2) = \{(00,00),(01,01),(10,10),(11,11)\},
\]
as desired.
\end{proof}

As such, if for some $i \in [3]$ and distinct $x, x' \in X_i$, we have that $x \sim_{i+1} x'$ and $x \sim_{i+2} x'$, then we can replace $X$ with $X \setminus \{x'\}$ and replace every $y \in Y$ with $y_i = x'$ with a corresponding $y'$ with $y'_i = x$ while preserving non-redundancy. Thus, assume without loss of generality that for every distinct $x, x' \in X_i$, we have that either $x \not\sim_{i+1} x'$ or $x \not\sim_{i+2} x'$.

For each distinct $i,j \in [3]$, let $\ell_{ij}$ be the number of connected components of $Y_{ij}$. Let $\alpha_{ij} : X_i \sqcup X_j \to [\ell_{ij}]$ be an indicator map of these connected components. By our WLOG assumption, we have that each $x \in X_i$ is uniquely determined by $(\alpha_{i,i+1}(x), \alpha_{i,i+2}(x))$. In particular, this means that each edge $y \in Y$ is uniquely determined by
\[
(\alpha_{1,2}(y_1) = \alpha_{1,2}(y_2), \alpha_{1,3}(y_1) = \alpha_{1,3}(y_3), \alpha_{2,3}(y_2) = \alpha_{2,3}(y_3)).
\]

In other words, we can identify $Y$ with $\widetilde{Y} \subseteq [\ell_{12}] \times [\ell_{13}] \times [\ell_{23}]$ and each $X_i$ with $\widetilde{X}_i \subseteq [\ell_{i,i+1}] \times [\ell_{i,i+2}]$ corresponding to the projection of $\widetilde{Y}$ onto $[\ell_{i,i+1}] \times [\ell_{i,i+2}]$. By Shearer's inequality\footnote{This precise version of Shearer's inequality appeared as Problem 5 at the 1992 International Mathematical Olympiad~\cite{djukic2006imo}.} \cite{chung1986intersection}, we then have that
\[
    |Y| = |\widetilde{Y}| \le \sqrt{|\widetilde{X}_1| \cdot |\widetilde{X}_2| \cdot |\widetilde{X}_3|} = \sqrt{|X_1|\cdot |X_2|\cdot |X_3|} \le n^{1.5}. \qedhere
\]
\end{proof}

\begin{remark}
This proof in fact shows that the construction in Lemma~\ref{lem:lb} is the optimal-sized tripartite instance for infinitely many choice of $n$.
\end{remark}

As an immediate corollary of Lemma~\ref{lem:lb} and Lemma~\ref{lem:ub}.

\begin{theorem}
$\NRD(\ORDP_{\cF}, n) = \Theta(n^{1.5})$.
\end{theorem}

