\title{\texorpdfstring{Symport/Antiport P Systems with\\ Membrane Separation Characterize $\PsharpP$}{Symport/Antiport P Systems with Membrane Separation Characterize P\textasciicircum(\#P)}}

\author[1]{Vivien Ducros}
