	\section{The Connected-RIS Design}
	%	
	Now, we assume that $\theta_{\rm BS}$, $\phi_{\rm BS}$ and $\theta_{\rm UE}$ are fixed, and change the position of the UE w.r.t. the azimuth angle $\phi_{\rm UE}$.\footnote{In urban environments, the main challenge for the RIS deployments is ensuring coverage in the horizontal plane (azimuth) due to obstacles, e.g., buildings. Usually, the elevation angle has a small impact on the signal propagation, as the height of buildings and the RIS panel placement typically result in a fixed elevation angle, particularly for ground-level UEs.} For each UE position, defined by the steering direction $\phi_{\rm UE}$, we generate the phase-shift matrix $\mathbf{\Psi}$, where the entries are determined using the following equation \cite{EBasar2019}:
	\begin{align}
		\psi_{n,m}=&\exp\left(-j(\angle h_{{\rm BS}, n,m}+\angle h_{n,m, {\rm UE}})\right), \nonumber\\&\qquad \quad\forall n\in\{1,\cdots, N_{\rm z}\}~\&~\forall m\in\{1,\cdots, N_{\rm y}\}.
		\label{phase-shift}
	\end{align}
	The objective is to cover the region defined by the azimuth angle $\phi_{\rm UE}$ spanning from $-80^{\circ}$ to $80^{\circ}$, and generate the phase-shift matrix for each steering direction $\phi_{\rm UE}$. To achieve this, we follow the procedure described in Algorithm 1. The process is repeated for each of the three deployment cases described in section III-B.

	\begin{algorithm}[h!]
		\caption{RIS Phase-Shift Design and Beam Steering}
		\begin{algorithmic}[1]
			\REQUIRE Number of RIS elements $N$, BS angles $(\phi_{\rm BS}, \theta_{\rm BS})$, UE angle $\theta_{\rm UE}$, distances $d_{\rm BS,RIS}$ and $d_{\rm RIS,UE}$

			\STATE Initialize the steering angle: $\phi_{\rm UE} = -80^\circ$
			\STATE Generate channel dataset using equations~(\ref{Chan1}) and (\ref{Chan2})
			\STATE Compute initial phase-shift matrix $\mathbf{\Psi}_1$ using~(\ref{phase-shift}) at $\phi_{\rm UE}$
			\STATE Evaluate RIS gain $G_{\rm RIS}(\phi)$ for all $\phi \in [-80^\circ\!:\!1^\circ\!:\!80^\circ]$
			\STATE Find angle $\phi_{\min}$ such that $G_{\rm RIS}(\phi_{\min}) = G_{\rm RIS,min}$

			\STATE Set iteration index $q = 1$
			\WHILE{$\phi_q \leq 80^\circ$}
			\STATE Generate channel dataset using~(\ref{Chan1}) and (\ref{Chan2})
			\STATE Compute phase-shift matrix $\mathbf{\Psi}_q$ using~(\ref{phase-shift}) at $\phi_q$
			\STATE Evaluate RIS gain $G_{\rm RIS}(\phi)$ for all $\phi \in [-80^\circ\!:\!1^\circ\!:\!80^\circ]$
			\STATE Identify $\phi_q$ where $G_{\rm RIS}(\phi_q) = G_{\rm RIS,min}$
			\STATE Compute phase difference: $\Delta \phi = \phi_q - \phi_{q-1}$
			\STATE Update steering angle: $\phi_{q+1} = \phi_q + \frac{\Delta \phi}{2}$
			\STATE Compute next phase-shift matrix $\mathbf{\Psi}_{q+1}$
			\STATE Increment index: $q \gets q + 1$
			\ENDWHILE
			\ENSURE $Q=q-1$, Phase-shift matrices $\{\mathbf{\Psi}_q\}_{q=1}^{Q}$
		\end{algorithmic}
	\end{algorithm}


