		\centering
		\hspace*{-0.2in}
		\centering
		\includegraphics[height=3.2in, width=4in]{newfig83times83anglecheck.pdf}
		\caption{RIS gain versus azimuth angle $\phi$ for a steering direction $\phi_{\rm UE}=-80^{\circ}$ in {\it Deployment Case 1}, i.e., RIS near the BS. Here, $\Delta G^{\rm dB}=6$ dB.}
		\label{fig:prob1_6_21}
