\section{Preliminaries}\label{apx:prelim}
For $n\in \N$ we denote $\{0,1,\dots,n-1\}$ by $[n]$ and sometimes by $\Z_n$.
For $n \in \N$ we denote by $\phi(n)$ the Euler's totient function, i.e, it counts the positive integers in $[n]$ that are relatively prime to $n$.
The multiplicative group $\Z_n^*$ consists of the set of natural numbers that are smaller than $n$ and relatively prime to it, and the operation is multiplication mod $n$.
We denote by $\log$ the logarithm with base two.
We denote by $x \,||\, y$ the concatenation of the vectors $x$, $y$, and by $\mathsf{len}(s)$ the length of the sequence $s$.
For a sequence $s = (\ldots, s_i, \ldots)$ we denote by $s[i : j]$ the sub-sequence $(s_i, \ldots, s_{j-1})$.
For a set $S$ we denote by $\gets S$ the process of choosing a uniformly random element of $S$.
For an algorithm $A$ we also write $\gets A$ to denote the (potentially random) element returned by $A$.
Let $\lambda$ be the security parameter, we denote by $\text{negl}(\lambda)$ any function that is in $O(1/p(\lambda))$ for every polynomial $p(\cdot)$. As is standard in Cryptography research, we think of $\lambda$ as the ``key size'', and of running times that are super-polynomial in $\lambda$ as ``infeasible''.  
\begin{comment}
\paragraph{Pseudorandom function (PRF).} Let $\mathcal{F} = \{F_k : \{0,1\}^{\ell_1(\lambda)} \to \{0,1\}^{\ell_2(\lambda)} \mid k \in \{0,1\}^\lambda\}$ be a family of functions. $\mathcal{F}$ is a PRF if $F_k$ is efficiently computable and for all probabilistic polynomial-time distinguishers $D$,
\[
\left| \Pr_{k \leftarrow \{0,1\}^\lambda} \left[ D^{F_k(\cdot)}(1^\lambda) = 1 \right] - \Pr_{f} \left[ D^{f(\cdot)}(1^\lambda) = 1 \right] \right| \le \text{negl}(\lambda)
\]
where $f$ denotes a random function from $\{0,1\}^{\ell_1(\lambda)}$ to $\{0,1\}^{\ell_2(\lambda)}$.
\end{comment}

\subsection{Language Models}

Some notions in this subsection are adapted from \cite{CGZ}.

\begin{definition}\label{def:model} A language model $M$ over token set $\mathcal{T}$ is a deterministic algorithm that takes as input a prompt $\mathsf{prompt}$ and tokens previously output by the model $z = (z_1, \ldots, z_{i-1})$, and outputs a probability distribution $p_i = M(\mathsf{prompt}, z)$ over $\mathcal{T}$.
\end{definition}

\begin{definition} A language model's response to $\mathsf{prompt}$ is a random variable $M(\mathsf{prompt}) \in \mathcal{T}^*$ defined algorithmically as follows. We begin with an empty list of tokens $z = ()$. As long as the last token in $z$ is not $\mathsf{done}$, we draw a token $z_i$ from the distribution $M(\mathsf{prompt}, z)$ and append it to $z$.
\end{definition}

\subsection{Entropy and Empirical Entropy}

For a distribution $D$ over a finite set $X$, the Shannon entropy is
\[
H(D) = \mathbb{E}_{z \sim D}[-\log D(z)].
\]
The empirical entropy of $z$ in $D$ is $-\log D(z)$.

\begin{definition}
For a language model $M$, a prompt $\mathsf{prompt}$, and a response $z \in \mathcal{T}^*$, the empirical entropy of $M$ responding with $z$ to $\mathsf{prompt}$ is:
\[
H_e(M, \mathsf{prompt}, z) := -\log \Prob[M(\mathsf{prompt}) = z].
\]
\end{definition}

Note that
\[
H(M(\mathsf{prompt})) = \mathbb{E}_z[H_e(M,\mathsf{prompt},z)].
\]

