\section{Impossibility of Prompt-Detection Filters}\label{apx:promptdetection}

\subsection{Moderately-strong filters}\label{apx:timelock}

We first state a formal version of Theorem~\ref{thm:detection-impossible-timelock}.
Next, we will present the construction and prove its correctness in the remaining part of this section.

\begin{theorem}[Impossibility of prompt-detection filters]
\label{thm:detection-impossible-timelock-formal}
There exists $\e \in (0,1)$, such that for all security parameters $\secp \in \N$, every time parameter $\poly(\secp) \leq t \leq 2^{O(\secp)}$, every set of harmful prompts $S_H \subseteq \{0,1\}^{l_m}$, where $l_m = \Theta(\log(\secp)), \Omega(\log(\secp)) = \log(|S_H|) \leq l_m - \Omega(\log(\secp))$, for every language model $M$ running in time $O(t)$ per token, for every %sequence of prompt generators $G = \{G_\secp\}_{\secp \in \N}$ satisfying $H(G_\secp) \geq \poly(\secp, \log(t))$ 
prompt generator $G$ satisfying $H(G) \geq \poly(\secp)$ and running in time $\poly(\secp)$ per token the following conditions hold.

There exists an adversarial prompt generator $G'$ with a running time $\poly(\secp)$ per token and a language model $M'$ with a running time $\poly(\secp) \cdot O(t)$ per token such that the following conditions hold.
\begin{enumerate}
    \item{\textbf{($G'$ incites harmful behavior in $M'$)}.} For every malicious prompt $m \in S_H$, the following two distributions are close:
    \[
    \left\{M'(z) \ \middle| \ z \gets G'(m) \right\}, \left\{M(m) \right\}.
    \]
    In words, for every harmful prompt from $S_H$ the outputs of $M'$ and $M$ follow almost the same distribution, in particular, a similar harmful behavior is induced for $M$ and $M'$.
    \item{\textbf{($M'$ and $M$ behave identically on $G$ almost always)}.} With probability $1 - \secp^{-\Omega(1)}$ over $z \gets G$ the distributions $M'(z)$ and $M(z)$ are equal.
    \item{\textbf{($G$ and $G'$ are indistinguishable for filters running in $o(t^\eps)$)}.} Under the assumption that RSW is secure, for every prompt filter running in time $o(t^\eps)$, for every $m \in S_H$ the advantage in distinguishing outputs of $G$ and $G'(m)$ is $\secp^{-\Omega(1)}$.
    In words, no filter running in time $o(t^\eps)$ can reject\footnote{If it doesn't also reject the innocent prompts.} the adversarial prompts from $G'$.
\end{enumerate}

\end{theorem}

\subsubsection{Construction}

In this subsection, we give a more detailed version of the construction provided in Section~\ref{sec:overview}.
Our construction is given in Algorithms~\ref{alg:harminciteformal} and~\ref{alg:maliciousllmformal}, which are formal versions of Algorithms~\ref{alg:harmincite} and~\ref{alg:maliciousllm}.

\begin{algorithm}
\caption{\(\mathsf{HarmIncite}(G,m,t,\secp)\) \Comment{$G$: an innocent prompt generator; $m$: a harmful prompt; $t$: time parameter; $\secp$: security parameter}}\label{alg:harminciteformal}
\begin{algorithmic}[1]
\State Sample two primes \(p,q\) in $[1,w]$ \Comment{$w = 2^{O(\secp)}$}
\State Set $n \gets p \cdot q$
\State Compute $e \gets 2^t \pmod{(p-1)(q-1)}$ \Comment{$\phi(n) = (p-1)(q-1)$}
\State Sample $r \gets \Z_n$ %\Comment{See Remark~\ref{rem:differentsampling} and Fact~\ref{fact:residues}} 
\If{$r \in \Z_n^*$} \Comment{See Remark~\ref{rem:differentsampling}}
    \State Compute $(g,i) \gets \mathsf{ind}(r)$ \Comment{See Definition~\ref{def:bijection}}
    \State Compute $g' \gets g^e \pmod{n}$
    \State Set $s \gets \mathsf{ind}^{-1}(g', i)$
\Else
    \State Set $s \gets r$
\EndIf
%\State \(((N, r), s) \gets \mathsf{Gen}(t,1^\secp)\)
\State Sample a pairwise independent hash function \(h\) 
\State Sample $v \gets \{0,1\}^{O(\secp)}$
\State $c \gets Q(s,v) \oplus m$ \Comment{$Q$ is the hard-core function}
\State \(R \gets h \ \| \ h(n) \ \| \ r \ \| \ v \ \| \ c\) \Comment{Concatenate components}
\State \Return \(z \gets \mathsf{Samp}(G, R)\) \Comment{Sample output so that randomness is recoverable}
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{\(\mathsf{MaliciousLLM}(M, z, G, t, \secp, S_H)\) \Comment{\(M\): an LLM; \(z\): input; \(G\): weak innocent prompt generator; $t$: time parameter; $\secp$: security parameter; $S_H$: set oh harmful prompts}}\label{alg:maliciousllmformal}
\begin{algorithmic}[1]
\State \(R \gets \mathsf{RecoverRand}(G, z)\)
\State Parse \(R\) as \(h \ \| \ u \ \| \ r \ \| \ v \ \| \ c\)
\ForAll{\(\hat{n} \in h^{-1}(u)\)}
    %\State \(\hat{s} \gets r\)
    \If{$r \in \Z_n^*$} \Comment{See Remark~\ref{rem:differentsampling}}
    \State Compute $(g,j) \gets \mathsf{ind}(r)$ \Comment{See Definition~\ref{def:bijection}}
    \State Compute $\hat{g} \gets g^e \pmod{\hat{n}}$
    \State Set $\hat{s} \gets \mathsf{ind}^{-1}(\hat{g}, j)$
    \Else
        \State Set $\hat{s} \gets r$
    \EndIf
    \For{\(i \in [t]\)}
        \State \(\hat{s} \gets \hat{s}^2 \text{ mod } \hat{n}\)
    \EndFor
    \State \(m \gets \hat{s} \oplus c\) \Comment{$m$ is the malicious prompt extracted from ciphertext $c$}
    \If{\(m \in S_H\)}
        \State \Return \(M(m)\) \label{line:returnharmful}
    \EndIf
\EndFor
\State \Return \(M(z)\) \label{line:returnnormal}
\end{algorithmic}
\end{algorithm}

Next, we provide a few simple facts from number theory that are needed to address the differences between the formal and informal versions of the algorithms.

\begin{definition}
Let $n \in N$.
We call $x \in \Z_n^*$ a quadratic residue modulo $n$ if there exists $r$ such that $x = r^2 \bmod n$.
\end{definition}

The following is a standard fact from number theory. See \cite{odedfoundations} for details.

\begin{fact}\label{fact:residues}
Let $n \in \N$ be a product of two different odd primes, i.e., $n = pq$.
The set of quadratic residues modulo $n$ is a subgroup, denoted by $G_n$, of $\Z_n^*$ of size $|\Z_n^*|/4$.
Moreover, the mapping $x \mapsto x^2$ is a 2-to-1 mapping from $\Z_n^*$ to $G_n$.
\end{fact}

\begin{definition}\label{def:bijection}
For $n \in \N$ we define a bijection $\mathsf{ind} : \Z_n^* \rightarrow G_n \times \{0,1\}^2$ as $\mathsf{ind}(x) := (g,i)$, where $g \in G_n$ is such that $x^2 = g^2$ and $i$ denotes which (in the increasing order) of the $4$ elements $r \in \Z_n^*$ satisfying $r^2 = x^2$, $x$ is.   
\end{definition}

\begin{remark}\label{rem:differentsampling}
Note that in Algorithm~\ref{alg:harminciteformal} (in contrast to Algorithm~\ref{alg:harmincite}), to compute the puzzle $s$, an intermediate bijection $\mathsf{ind}$ (Definition~\ref{def:bijection}) is used.
The reason is the following.
The mapping $x \mapsto x^2$ is a $4$-to-$1$ function in $\Z_n^*$.
To ensure that the mapping between $r \in \Z_n$ and a puzzle $s$ is $1$-to-$1$, we use the function $\mathsf{ind}$ to \say{remember} which of the $4$ possible $r$'s was used.
\end{remark}

Next, we give a formal definition of $\mathsf{Enc}$ used in Algorithm~\ref{alg:harmincite}.

\paragraph{Hardcore functions.}
We will apply the technique of hardcore bits (\cite{GoldreichL89}) and its extension to hardcore functions. 
Recall that a hardcore bit is a function $B$ that outputs a single bit $B(x)$ which is hard to predict given $f(x)$. 
A hardcore function $Q$ for a one-way function $f$ is a function which outputs possibly more than one bit such that, given $f(x)$, and the description of $Q$, it is hard to distinguish $Q(x)$ from a random string even when $f(x)$ is known.  
Goldreich and Levin introduced the first hardcore predicates and functions for general one-way functions (OWFs), showing that a random linear function is hardcore and the linear function defined by a random Toeplitz matrix is a hardcore function.

The first step of $G'$ is to sample $p,q$ at random from a set $[1,k]$ (see Algorithm~\ref{alg:harminciteformal}), where $k = 2^{O(\secp)}$.
Next, we let $h$ be a pairwise independent hash function that $h$ hashes $n$ to a range of size $\Theta(\e^2 \cdot ((k/\log(k))^2)$.
The $\e$ is set to $\secp^{-\gamma}$ for some $\gamma > 0$ to be fixed in the proof (Section~\ref{sec:mainformalproof}).
%Let $f^{-1}(n,r) = r^{-2^t} \bmod n$, i.e., it's an inverse of $f$ wrt. the $r$ parameter.
For a message $m \in \{0,1\}^{l_m}$ (as in the statement of Theorem~\ref{thm:detection-impossible-timelock-formal}) and using the notation from Algorithm~\ref{alg:harminciteformal} we define $R$ to be
\begin{equation}\label{eq:hidemessage}
R \gets h \ \| \ h(n) \ \| \ r \ \| \ v \ \| \ Q(s,v) \oplus m,
\end{equation}
where $v \gets \{0,1\}^{O(\secp)}$ and $Q(s,v)$ is a hardcore function with $l_m = \Theta(\log(\secp))$ output bits.

\begin{note}
In Section~\ref{sec:overview} we simplified the above construction and claimed $R = (x,\mathsf{Enc}(g(x),m))$.
Informally speaking, in the formal version we set 
\[
x = h \ \| \ h(n) \ \| \ r, \ \mathsf{Enc}(g(x),m) = v \ \| \ Q(s,v) \oplus m,
\]
where $v \gets \{0,1\}^{O(\secp)}$.
\end{note}

Next, we give some remarks about Algorithm~\ref{alg:maliciousllmformal}.
As we mentioned in the overview it is possible to efficiently enumerate through all the preimages of $h(n)$ under $h$.
Note that according to \eqref{eq:hidemessage} when $M'$ parses $R$ it does it as follows:
\[
R = h \ \| \ u \ \| \ r \ \| \ v \ \| \ c.
\]
For instance, an additional part $v$, which was not present in the simplified version of Algorithm~\ref{alg:rec} appears here.

Next, the model $M'$ squares the starting point $t$ times and tries to decrypt $c$ with the current candidate for $n$, i.e., $\hat{n}$.
By decrypt we mean it evaluates $\mathsf{Dec}(\hat{s},v,c)$ defined as 
\[
\hat{m} \gets c \oplus Q(\hat{s},v).
\]
The check $\hat{m} \neq \bot$ becomes instead $m \in S_H$. 
That is we assume $M'$ knows the set of harmful prompts $S_H$ and checks if the decryption belongs to that set and if yes it executes $M$ on it (which will lead to a harmful output).
If, none of the the decryptions \say{succeed} then it returns $M(z)$.

%\greg{In the formal algorithm I assumed M' knows t}

\begin{remark}\label{rem:exttoTLP}
We proved Theorem~\ref{thm:detection-impossible-timelock-formal} using the RWS construction of time-lock puzzles.
However, there are generic constructions of time-lock puzzles.
The first one \citep{shafitimelocks} was based on obfuscation and randomized encodings.
A culmination of a series of follow-up works \citep{giulioTLP, bitanskyTLP, giulioTLPfinal} managed to construct time-lock puzzles based on a version of the Learning With Errors \citep{regevLWE} (LWE) assumption. 
One advantage of basing TLPs on LWE is that the other constructions are broken by quantum algorithms, while LWE is a candidate for post-quantum secure cryptography.

It would be interesting to extend Theorem~\ref{thm:detection-impossible-timelock-formal}, so that it can be based on any time-lock puzzle.
The one crucial property that we use is the pseudorandomness of the puzzle, and this seems like the key issue in generalizing the result. 
Recall that we had to be careful in designing Algorithm~\ref{alg:harminciteformal} so that the distribution of $s$ is uniform.
It seems that the main property we need is that the distribution on hard instances is uniform over a set $S$ whose approximate size is known to us.
We leave the question of whether the generalization is possible for future work.
\end{remark}

