\section{Defining Alignment}

We further formulate a simulation-based definition of alignment, drawing inspiration from the literature on cryptography.  Let $T$ be a set of specifications of tasks which we do not want the LLM to perform for us. For example $T$ could be producing instuctions on how to construct a bomb\footnote{see https://openai.com/index/introducing-the-model-spec/}. We say that an LLM $L$ is \textit{safe with respect } to $T$ if for all polynomial-time users $U$, there exists a polynomial-time algorithm (aka simulator) $U'$ (that is strictly weaker than L), where if $U$ can use $L$ to achieve task $T$ with probability at least $\varepsilon$ (i.e. $\Pr[ U^L violates T] > \varepsilon$), then the simulator $U'$ could have achieved the task $T$ on its own (without access to the LLM $L$) with probability at least roughly $\varepsilon$. I.e., the LLM was not instrumental in achieving the task. This definition is inspired by the definition of zero-knowledge in cryptography.
\end{comment}

\section{Mitigation and Connections to Watermarking}

\subsection{Watermarks}

First, we define watermarking schemes, for which we adopt definitions from \cite{CGZ}.
The only difference is that we require a watermark to still be detected even if the output of the watermarking scheme was changed by a transformation from a class $E$.

\begin{definition}[Class of Transformations]
A \emph{class of transformations} $E$ is an equivalence relation over $\mathcal{T}^*$.
We interpret it as follows.
For $z \in \mathcal{T}^*$ it can be transformed into any element in the equivalence class of $z$.
We denote by $E(z)$ the equivalence class of $z$.
\end{definition}

\begin{definition}[Watermarking scheme]
A watermarking scheme for a model $M$ over $\mathcal{T}$ is a tuple of algorithms $\mathcal{W} = (\mathsf{Setup}, \mathsf{Wat}, \mathsf{Detect})$ where:
\begin{itemize}
  \item $\mathsf{Setup}(1^\lambda) \to \mathsf{sk}$ outputs a secret key, with respect to a security parameter $\lambda$.
  \item $\mathsf{Wat}_\mathsf{sk}(\mathsf{prompt})$ is a randomized algorithm that takes as input a prompt $\mathsf{prompt}$ and generates a response in $\mathcal{T}^*$.
  \item $\mathsf{Detect}_{\mathsf{sk}}(z) \to \{\mathsf{true}, \mathsf{false}\}$ is an algorithm that takes as input a sequence $z \in \mathcal{T}^\star$ and outputs true or false.
\end{itemize}
\end{definition}

\begin{definition}[Soundness]
A watermarking scheme $\mathcal{W}$ is \emph{sound} if for every security parameter $\lambda$ and token sequence $x \in \mathcal{T}^\star$ of length $|z| \le \mathsf{poly}(\lambda)$,
\[
\Pr_{\mathsf{sk} \leftarrow \mathsf{Setup}(1^\lambda)}[\mathsf{Detect}_{\mathsf{sk}}(z) = \mathsf{true}] \le \mathsf{negl}(\lambda).
\]
\end{definition}

\begin{definition}[$b(L)$-Completeness]
An algorithm $\mathcal{W}$ is a $b(L)$-\emph{complete} watermarking scheme robust against a class of transformations $E$ if for every security parameter $\lambda$ and prompt $\mathsf{prompt}$ of length $|\mathsf{prompt}| \le \mathsf{poly}(\lambda)$,
\begin{align*}
\Pr_{\mathsf{sk} \leftarrow \mathsf{Setup}(1^\lambda),\, z \leftarrow \mathsf{Wat}_{\mathsf{sk}}(\mathsf{prompt})}&[\exists_{z' \in E(z)} \ \mathsf{Detect}_{\mathsf{sk}}(z') = \mathsf{false} \text{ and } \\
&H_e(M, \mathsf{prompt},z) \ge b(|z|)] \le \mathsf{negl}(\lambda).
\end{align*}
\end{definition}

\begin{definition}[Undetectability]
A watermarking scheme $\mathcal{W} = (\mathsf{Setup}, \mathsf{Wat}, \mathsf{Detect})$ is \emph{undetectable} if for every security parameter $\lambda$ and all polynomial-time distinguishers $D$,
\[
\left| 
\Pr[D^{M, M}(1^\lambda) = 1]
-
\Pr_{\mathsf{sk} \leftarrow \mathsf{Setup}(1^\lambda)}[D^{M, \mathsf{Wat}_{\mathsf{sk}}}(1^\lambda) = 1]
\right| \le \mathsf{negl}(\lambda),
\]
where the notation $D^{O_1, O_2}$ means that $D$ is allowed to adaptively query both $O_1$ and $O_2$ with arbitrary prompts.
\end{definition}

\subsection{Our result}

\begin{definition}[Prompt-mitigation Filter]
A \emph{prompt-mitigation filter} for a class $E$ is an algorithm that takes as input $z \in \mathcal{T}^*$ and replies with en element of $E(z) \cup \{\bot\}$, which we interpret as it either produced an element in the equivalence class of $z$ or rejects.    
\end{definition}

The following is a formal version of Theorem~\ref{thm:mitigation-impossible}.

\begin{theorem}[Impossibility of prompt-mitigation filters]
\label{thm:watermarking-mitigation-impossible-formal}
If there exists a watermarking scheme robust against a class of transformations $E$ then
for all security parameters $\secp \in \N$, for every language model $M$, for every %sequence of prompt generators $G = \{G_\secp\}_{\secp \in \N}$ satisfying $H(G_\secp) \geq \poly(\secp, \log(t))$ 
prompt generator $G$ satisfying $H(G) \geq \poly(\secp)$ and running in time $\poly(\secp)$ per token the following conditions hold.

There exists a language model $M'$ with a running time $\poly(\secp) + O(T_M)$ per token, where $T_M$ is the running time of $M$ per token, and an adversarial prompt generator $G'$ with a running time $\poly(\secp)$ per token such that if $G'$ and $M'$ share a secret key then the following conditions hold.
\begin{enumerate}
    \item{\textbf{($G'$ incites harmful behavior in $M'$ even in the presence of prompt-mitigation filters)}.} 
    For every prompt-mitigation filter $F$ running in polynomial-time with all but negligible in $\secp$ probability over $z \gets G'$ it holds that 
    \[
    F(z) = \bot \text{ or } M'(z) \text{ is harmful}.
    \]
    \item{\textbf{($M'$ and $M$ behave identically on $G$ almost always)}.} With all but negligible in $\secp$ probability over $z \gets G$ the distributions $M'(z)$ and $M(z)$ are equal.
    \item{\textbf{($G$ and $G'$ are indistinguishable for filters running in polynomial-time)}.} 
    For every algorithm running in polynomial-time the advantage in distinguishing outputs of $G$ and $G'$ is negligible in $\secp$.
\end{enumerate}
\end{theorem}

\begin{note}
Observe that conditions 1 and 3 from Theorem~\ref{thm:watermarking-mitigation-impossible-formal} imply that if a polynomial-time prompt-mitigation filter $F$ does not reject outputs of $G$ then the outputs of $G$ even when passed through the mitigation of $F$ will still incite harmful behavior in $M'$.   
\end{note}

\subsection{Construction}

Let $\mathcal{W} = (\mathsf{Setup}, \mathsf{Wat}, \mathsf{Detect})$ be a watermarking scheme robust against a class of transformations $E$.
Let $G$ be a prompt generator satisfying $H(G) \geq \poly(\secp)$.
Firstly, we let $G'$ and $M$ share a $\mathsf{sk}$ generated by $\mathsf{Setup}(1^\secp)$.
We define $G' := \mathsf{Wat}_\mathsf{sk}()$.\footnote{We run $\mathsf{Wat}$ on an empty prompt.}
Note that $\mathsf{Wat}$ implicitly depends on $G$.
For a language model $M$ we define $M'$ that on input $z$ works as follows:
\begin{enumerate}
    \item If $\mathsf{Detect}_\mathsf{sk}(z) = \mathsf{true}$ then return a harmful output.
    \item Return $M(z)$ otherwise.
\end{enumerate}

\subsection{Proof}

The proof requires a careful comparison of requirements of Theorem~\ref{thm:watermarking-mitigation-impossible-formal} and properties of watermarking schemes robust against classes of transformations.
The result follows from the following.
\begin{itemize}
    \item Condition 1 follows from completeness of $\mathcal{W}$.
    \item Condition 2 follows from soundness of $\mathcal{W}$.
    \item Condition 3 follows from undetectability of $\mathcal{W}$.
\end{itemize}

