\section{Background}
We introduce the necessary terms and concepts from Morse theory for PL functions and Cerf theory for smooth functions~\cite{edelsbrunner2010computational, dey2022computational}. We refer the reader to classic texts and surveys on smooth Morse theory~\cite{milnor1963morse} and Cerf theory~\cite{gay2012connected,hatcher1973pseudoisotopies} for a detailed exposition.


\subsection{PL functions on combinatorial manifolds}
A simplicial complex \(K\) is called a \emph{triangulation} of a manifold \(\Mspace\) if the underlying space of \(K\) is homeomorphic to \(\Mspace\). A PL function on \(\Mspace\) is defined by assigning real values to vertices of \(K\) and extending the map linearly in the interior of each simplex. A triangulated manifold of dimension $d$ is called a \emph{combinatorial manifold} if the link of each vertex is homeomorphic to a sphere of dimension $d-1$. 

Throughout this paper, we work in the category of combinatorial manifolds and analyze topological properties of one‑parameter families of PL functions on them. First, we recall some basic notions associated with a PL function $f:\Mspace \to \Real$~\cite{edelsbrunner2010computational}. 
The \emph{star} of a vertex \(u \in K\) is defined as \(\St(u)=\{\sigma\in K : u\in\sigma\}\). 
The \emph{link} of a vertex \(u\) is defined as \(\Lk(u)=\{\tau\in K : \exists\,\sigma\in\St(u),\,\tau\subset\sigma,\,u\notin\tau\}\). 
The \emph{lower link} of a vertex \(u\) is a subset of the link and is defined as \(\Lk^-(u)=\{\tau\in\Lk(u) : \forall\,v\in\tau,\,f(v)\le f(u)\}\).\\

The PL function $f$ is called \emph{generic PL} if $f(u) \neq f(v)$ for two distinct vertices $u, v$ of $K$. Vertices of $K$ may be classified as regular or critical with respect to a generic PL function $f$ based on the homology of the lower link. They are also referred to as ``homologically regular'' or ``H-regular'' and ``homologically critical'' or ``H-critical''~\cite[Definition 3.3]{Grun-Kuhn-PLMorse}.
%
\begin{definition}[Regular point]\label{defn:regularpt}
A vertex \(v\) is called a \emph{regular point} of \(f\) if for every \(i \in [0,d]\), $\widetilde H_{i-1}\bigl(\Lk^-(v);\Real\bigr)\;=\;0$.
\end{definition}
%
%
\begin{definition}[Critical point]\label{defn:criticalpt}
A vertex \(v\)  is \emph{critical} for \(f\) if the homological index
\( \beta(v) =  (\beta_0(v),\beta_1(v),\dots,\beta_d(v)), \) where \(\beta_i(v) \;=\;\dim_{\Real}\widetilde H_{i-1}\bigl(\Lk^-(v);\Real\bigr) \), is not identically zero. 
\end{definition}
%
%
In the above, we adopt the convention that the reduced homology group $\widetilde H_{-1}(\Xspace;\Real)= 0$ if $\Xspace\neq\emptyset$, and $\widetilde H_{-1}(\Xspace;\Real)= \Real$ if $\Xspace=\emptyset$.
A critical point \(v\) is called \emph{non‑degenerate} if exactly one entry $\beta_i(v)$ of its index $\beta(v)$ equals 1 and all others are 0. In this case, $v$ is called a critical point of index $i$. If exactly one entry $\beta_i$ is non-zero then the critical point of index $i$ is said to have multiplicity  $\beta_i$. 
%
\begin{definition}[PL Morse function]\label{defn:plMorse}
A generic PL function, whose critical points are all non-degenerate, is called a \emph{PL Morse} function.  
\end{definition}



\subsection{Cerf theory for smooth functions}\label{sec:Cerfgraphic}
A generic one-parameter family of smooth functions $f_t: \Mspace \rightarrow \Real$, where $t$ ranges over an interval $I$, is Morse at all but finitely many time instances. At a degenerate time instance $t_0$ two critical points of $f_t$ may have identical values. As time $t$ increases and crosses $t_0$, the corresponding pair of critical values may cross each other. Alternatively, we observe a birth/death transition of critical points. 
The function $f_t$ can be expressed as follows in terms of local coordinates \revision{$x = (x_1,\ldots,x_d)$} of $\Mspace$ within the neighborhood of a degenerate birth/death critical point~\cite{cerf1970stratification}.
%
%
{
\setlength{\abovedisplayskip}{0pt}
\setlength{\belowdisplayskip}{0pt}
\begin{equation}
    \revision{f_t(x) = x_{k+1}^3 \pm tx_{k+1}} - \sum_{i=1}^k x_i^2 + \sum_{i=k+2}^d x_i^2.
\end{equation}
}
%
The cubic term in $x_{k+1}$ unfolds the degenerate quadratic so that at $t=0$ a canceling pair of index-$k$ and index-$(k+1)$ critical points is created or annihilated, as determined by the $\pm$ sign before $x_{k+1}$.
Suppose that each \(f_t\) takes values in a compact interval \(J \subset \Real\) for $t \in I$. Cerf studied the stratification of the space of smooth functions on \(\Mspace\times I\)~\cite{cerf1970stratification}.  
%
\begin{definition}[Cerf graphic]\label{defn:smoothcerfgraphic}
    The \emph{Cerf graphic} of a smooth family of functions \(\{f_t\}\) is the subset
\[
  \Cerfgraphic \;=\; \bigl\{(t,c)\in I\times J \mid c\text{ is a critical value of }f_t\bigr\}
  \;\subset\; I\times J.
\]
\end{definition}
%
%\revision{[Removed] Cerf also introduced a finite list of local modifications—called \emph{Cerf moves}—that relate the Cerf graphic of a generic one‑parameter family to that of another. Further details on smooth Cerf moves (and their PL analogs) are presented in supplementary material.
%}



