The Betti number $\beta_{i}^{t}(v)$ of the lower link of a vertex $v$ changes after a crossing. We characterize this change as follows.

\begin{theorem}\label{thm:betti-update}
Let $\left\{f_t\right\}$ be a generic one-parameter PL family. If two vertices $v$ and $u$ cross between time instances $t_1$ and $t_2$ in the vertex diagram of $\left\{f_t\right\}$ and there is no other crossing within the time range $[t_1,t_2]$, then the Betti numbers of the lower link of $v$ and $u$ satisfy the following relationship:
{
\setlength{\abovedisplayskip}{0pt}
\setlength{\belowdisplayskip}{0pt}
   \[  \sum_{i=0}^{d} {(-1)}^{i} (\beta_{i}^{t_2}(v) - \beta_{i}^{t_1}(v)) \;=\; - \sum_{i=0}^{d} {(-1)}^{i} (\beta_{i}^{t_2}(u) - \beta_{i}^{t_1}(u)) \]
}
\end{theorem}

\begin{proof}
Let \(\Lk_{t_1}^-(v)\) and \(\Lk_{t_1}^-(u)\) be the lower links of vertices \(v\) and \(u\) at time \(t_1\), and $I_{uv}$ denote their intersection, $I_{uv} \;=\;\Lk_{t_1}^-(v)\,\cap\,\Lk_{t_1}^-(u).$ Without loss of generality, assume that $f_{t_1}(v) > f_{t_1}(u)$. If vertices $v$ and $u$ are connected by an edge of $K$, then at a time instance $t_2$ after the crossing, their lower links may be expressed as follows:
%
{\setlength{\abovedisplayskip}{1pt}
\setlength{\belowdisplayskip}{0pt}
\begin{align*}
  \Lk_{t_2}^-(u)
    &= \Lk_{t_1}^-(u)\;\cup\;\bigl(v\star I_{uv}\bigr),\\
  \Lk_{t_2}^-(v)
    &= \Lk_{t_1}^-(v)\;\setminus\;\bigl(u\star I_{uv}\bigr).
\end{align*}
}
%
Applying the Mayer–Vietoris sequence to the decomposition
\(\Lk_{t_2}^-(u)=\Lk_{t_1}^-(u)\,\cup\,(v\star I_{uv})\)
yields the long exact sequence
%
{
\setlength{\abovedisplayskip}{0.5pt}
\setlength{\belowdisplayskip}{0.5pt}
\[
\begin{aligned}
  \cdots\;&\to\;\tilde H_n(I_{uv})
  \;\to\;\tilde H_n\bigl(\Lk_{t_1}^-(u)\bigr)\oplus\tilde H_n(v\star I_{uv})\\
  &\to\;\tilde H_n\bigl(\Lk_{t_2}^-(u)\bigr)
  \;\to\;\tilde H_{n-1}(I_{uv})
  \;\to\;\cdots
\end{aligned}
\]
}
%
Similarly, we obtain a long exact sequence for \(\Lk_{t_2}^-(v)=\Lk_{t_1}^-(v)\setminus(u\star I_{uv})\).
Since \(v\star I_{uv}\) and \(u\star I_{uv}\) are contractible, their reduced homology groups vanish, and the above exact sequences simplify to
%
{
\setlength{\abovedisplayskip}{0pt}
\setlength{\belowdisplayskip}{0pt}
\[
  \cdots
  \to \tilde H_n(I_{uv})
  \to \tilde H_n\bigl(\Lk_{t_1}^-(u)\bigr)
  \to \tilde H_n\bigl(\Lk_{t_2}^-(u)\bigr)
  \to \tilde H_{n-1}(I_{uv})
  \to \cdots,
\]
}
\[
  \cdots
  \to \tilde H_n(I_{uv})
  \to \tilde H_n\bigl(\Lk_{t_2}^-(v)\bigr)
  \to \tilde H_n\bigl(\Lk_{t_1}^-(v)\bigr)
  \to \tilde H_{n-1}(I_{uv})
  \to \cdots.
\]
%
%
Let \(r_i\) denote the rank of \(\tilde H_{i-1}(I_{uv})\).  Counting alternating sums of ranks in both exact sequences, we obtain, 
%the following expressions
{
\setlength{\abovedisplayskip}{0pt}
\setlength{\belowdisplayskip}{0.5pt}
\begin{align*}
  \sum_{i=0}^{d}(-1)^i r_i
  \;+\;
  \sum_{i=0}^{d}(-1)^{\,i+1}\beta_i^{t_1}(v)
  \;+\;
  \sum_{i=0}^{d}(-1)^i\beta_i^{t_2}(v)
  \;&=\;0,\\
  \sum_{i=0}^{d}(-1)^i r_i
  \;+\;
  \sum_{i=0}^{d}(-1)^{\,i+1}\beta_i^{t_1}(u)
  \;+\;
  \sum_{i=0}^{d}(-1)^i\beta_i^{t_2}(u)
  \;&=\;0.
\end{align*}
}
Equating the two expressions, removing the common term involving $r_i$, and combining the remaining two terms, we obtain the desired relationship.
\end{proof}
