\section{Proof of Proposition~\ref{prop:metric}}
\label{appendix:proof}

\begin{proof}
Let $x, y, z$ be arbitrary nodes in the node set $V_{R_f}$ of a Reeb graph $R_f$. We aim to demonstrate that the Symmetric Reeb Radius, $d_{R_f}(x,y) = \frac{1}{2}(\rho_f(x,y) + \rho_f(y,x))$, where $\rho_f$ is the Reeb Radius (Definition~\ref{def:reeb_radius}), satisfies the properties of a metric.

\begin{enumerate}
    \item \textbf{Non-negativity:}
    The Reeb radius $\rho_f(x, y)$ is defined as an infimum of suprema of absolute differences of function values, specifically $\sup_{t \in [0, 1]} |\bar{f}(x) - \bar{f}(\gamma(t))|$ for paths $\gamma$. Since absolute values are inherently non-negative, their supremum over any path is also non-negative. Consequently, the infimum of these non-negative values, $\rho_f(x, y)$, must satisfy $\rho_f(x, y) \geq 0$. Therefore, $d_{R_f}(x, y) = \frac{1}{2}(\rho_f(x, y) + \rho_f(y, x))$ must also be non-negative.
    % Minor polish: Added "specifically ... for paths gamma" for a bit more context. Changed "i.e." to "specifically".

    \item \textbf{Identity of Indiscernibles:}
    If $x = y$, then the path $\gamma$ from $x$ to $x$ can be the trivial path consisting only of the node $x$. For this path, $\bar{f}(\gamma(t)) = \bar{f}(x)$ for all $t$, so $\sup_{t \in [0, 1]} |\bar{f}(x) - \bar{f}(\gamma(t))| = 0$. Thus, $\rho_f(x, x) = 0$. This implies $d_{R_f}(x, x) = \frac{1}{2}(\rho_f(x, x) + \rho_f(x, x)) = 0$.

    Conversely, assume $d_{R_f}(x, y) = 0$. Given that $\rho_f(x,y)$ and $\rho_f(y,x)$ are non-negative, this equality implies that both $\rho_f(x, y) = 0$ and $\rho_f(y, x) = 0$.
    The condition:

    $\rho_f(x, y) = \inf_{\gamma: x \to y} \sup_{t \in [0,1]} |\bar{f}(x) - \bar{f}(\gamma(t))| = 0$ means that for any $\delta > 0$, there exists a path $\gamma$ from $x$ to $y$ such that $\sup_{t \in [0,1]} |\bar{f}(x) - \bar{f}(\gamma(t))| < \delta$. This implies that all points $\gamma(t)$ on such a path must have function values $\bar{f}(\gamma(t))$ arbitrarily close to $\bar{f}(x)$.
    In a generic Reeb graph (derived from a simple Morse function, where critical points have distinct function values and map to distinct nodes, or are well-defined branch points), if $x \neq y$, any path connecting them must involve traversing arcs where $\bar{f}$ is monotonic or passing through other critical points. If $x \neq y$, then for any path $\gamma$ between them, there must be some point(s) $\gamma(t_0)$ on the path such that $\bar{f}(\gamma(t_0)) \neq \bar{f}(x)$, unless the entire segment from $x$ to $y$ consists of points with the same function value as $x$. In a Reeb graph, such a segment would be contracted to a single node unless $x$ and $y$ are the same node.
    Therefore, if $\rho_f(x,y) = 0$, it necessitates that $x=y$.
    Thus, $d_{R_f}(x, y) = 0 \iff x = y$.
    % Minor polish: Clarified the implication of infimum being zero. Emphasized properties of generic Reeb graphs.

    \item \textbf{Symmetry:}
    This property follows directly and trivially from the definition of $d_{R_f}$:
    \[
    d_{R_f}(x, y) = \frac{1}{2} \left( \rho_f(x, y) + \rho_f(y, x) \right) = \frac{1}{2} \left( \rho_f(y, x) + \rho_f(x, y) \right) = d_{R_f}(y, x).
    \]
    Hence, $d_{R_f}$ is symmetric.
    % Minor polish: Added "and trivially".

    \item \textbf{Triangle Inequality:} We need to show that $d_{R_f}(x, z) \leq d_{R_f}(x, y) + d_{R_f}(y, z)$.
    The critical preliminary step is to establish the triangle inequality for the (potentially asymmetric) Reeb radius $\rho_f$ itself:
    \begin{equation} \label{eq:rho_f_triangle_inequality_app} % Added _app to avoid clash if similar label exists
    \rho_f(x, z) \leq \rho_f(x, y) + \rho_f(y, z).
    \end{equation}
    To prove Equation~\eqref{eq:rho_f_triangle_inequality_app}, let $x, y, z$ be arbitrary nodes in $V_{R_f}$. For any $\epsilon > 0$, by the definition of $\rho_f$ as an infimum, there exist paths $\gamma_{xy}$ (from $x$ to $y$) and $\gamma_{yz}$ (from $y$ to $z$) in $R_f$ such that:
    \begin{align}
        \sup_{s \in \gamma_{xy}} |\bar{f}(x) - \bar{f}(s)| &< \rho_f(x, y) + \frac{\epsilon}{2}, \label{eq:epsilon_path_xy_app} \\
        \sup_{s \in \gamma_{yz}} |\bar{f}(y) - \bar{f}(s)| &< \rho_f(y, z) + \frac{\epsilon}{2}. \label{eq:epsilon_path_yz_app}
    \end{align}
    Consider the concatenated path $\gamma_{xz} = \gamma_{xy} \oplus \gamma_{yz}$, which connects $x$ to $z$ via $y$. For any point $s$ on this path $\gamma_{xz}$:

    Case 1: If $s \in \gamma_{xy}$.
    Then, from Inequality~\eqref{eq:epsilon_path_xy_app}, we have $|\bar{f}(x) - \bar{f}(s)| < \rho_f(x, y) + \frac{\epsilon}{2}$. Since $\rho_f(y, z) \ge 0$ and $\epsilon/2 < \epsilon$, this implies $|\bar{f}(x) - \bar{f}(s)| < \rho_f(x, y) + \rho_f(y, z) + \epsilon$.

    Case 2: If $s \in \gamma_{yz}$.
    Using the triangle inequality for real numbers, we have $|\bar{f}(x) - \bar{f}(s)| \leq |\bar{f}(x) - \bar{f}(y)| + |\bar{f}(y) - \bar{f}(s)|$.
    From Inequality~\eqref{eq:epsilon_path_yz_app}, we know $|\bar{f}(y) - \bar{f}(s)| < \rho_f(y, z) + \frac{\epsilon}{2}$.
    The term $|\bar{f}(x) - \bar{f}(y)|$ represents the absolute difference in function values at the specific node $y$, which is the endpoint of $\gamma_{xy}$. As such, $|\bar{f}(x) - \bar{f}(y)| \leq \sup_{q \in \gamma_{xy}} |\bar{f}(x) - \bar{f}(q)|$. From Inequality~\eqref{eq:epsilon_path_xy_app}, this means $|\bar{f}(x) - \bar{f}(y)| < \rho_f(x, y) + \frac{\epsilon}{2}$.
    Substituting these into the inequality for $|\bar{f}(x) - \bar{f}(s)|$:
    \[ |\bar{f}(x) - \bar{f}(s)| < \left(\rho_f(x, y) + \frac{\epsilon}{2}\right) + \left(\rho_f(y, z) + \frac{\epsilon}{2}\right) = \rho_f(x, y) + \rho_f(y, z) + \epsilon. \]
    Since in both cases (for any $s \in \gamma_{xz}$) we have $|\bar{f}(x) - \bar{f}(s)| < \rho_f(x, y) + \rho_f(y, z) + \epsilon$, it follows that:
    \[ \sup_{s \in \gamma_{xz}} |\bar{f}(x) - \bar{f}(s)| \leq \rho_f(x, y) + \rho_f(y, z) + \epsilon. \]
    Given that $\rho_f(x, z)$ is the infimum of such suprema over all paths from $x$ to $z$, and $\gamma_{xz}$ is one such path:
    \[ \rho_f(x, z) \leq \sup_{s \in \gamma_{xz}} |\bar{f}(x) - \bar{f}(s)|. \]
    Thus, we have $\rho_f(x, z) \leq \rho_f(x, y) + \rho_f(y, z) + \epsilon$.
    Since this inequality holds for any arbitrary $\epsilon > 0$, we conclude that Equation~\eqref{eq:rho_f_triangle_inequality_app} is true:
    \[ \rho_f(x, z) \leq \rho_f(x, y) + \rho_f(y, z). \]
    By a symmetric argument (or by swapping the roles of start/end points), we also have:
    \[ \rho_f(z, x) \leq \rho_f(z, y) + \rho_f(y, x). \]
    Now, using these results for the Symmetric Reeb Radius $d_{R_f}$:
    \begin{align*}
        d_{R_f}(x, z) &= \frac{1}{2} \left( \rho_f(x, z) + \rho_f(z, x) \right) \\
        &\leq \frac{1}{2} \left( (\rho_f(x, y) + \rho_f(y, z)) + (\rho_f(z, y) + \rho_f(y, x)) \right) \\
        &= \frac{1}{2} \left( \rho_f(x, y) + \rho_f(y, x) \right) + \frac{1}{2} \left( \rho_f(y, z) + \rho_f(z, y) \right) \\
        &= d_{R_f}(x, y) + d_{R_f}(y, z).
    \end{align*}
    Therefore, $d_{R_f}$ satisfies the triangle inequality.
    % Polish: Changed "p" back to "s" for points on path for internal consistency within this item. Clarified the bounding of |f(x)-f(y)|. Made the sup over s <= sum + epsilon explicit.
\end{enumerate}
Since $d_{R_f}$ satisfies non-negativity, identity of indiscernibles (particularly for generic Reeb graphs, as elaborated in point 2), symmetry, and the triangle inequality, it is a valid metric on the set of nodes $V_{R_f}$.
\end{proof}




\section{Detailed Stability Proofs}

\label{app:detailed_stability_proofs}

\subsection{Proof of Theorem~\ref{thm:stability_drf_gh} (Stability of Symmetric Reeb Radius Metric w.r.t. Field GH Distance)}
\label{app:proof_thm_stability_drf_gh_content}

\begin{proof}
Let $\delta = d_{\mathrm{GH}}((X, f), (Y, g))$ denote the Gromov-Hausdorff distance between the M-Metric Fields $(X,f)$ and $(Y,g)$, as defined in Definition~\ref{def:stability_GH_M_metric}. According to this definition (see also Definition 11 in Curry et al.~\cite{curry2024stability}), $\delta$ is the infimum of all non-negative values $r \geq 0$ for which an $(r, r)$-correspondence exists between $(X, f)$ and $(Y, g)$.
By the properties of an infimum, for any chosen $\delta' > \delta$, $\delta'$ cannot be a lower bound for the set of such $r$. Therefore, there must exist some $r^*$ such that $\delta \leq r^* \leq \delta'$, for which an $(r^*, r^*)$-correspondence $\EuScript{R} \subset X \times Y$ exists.

This correspondence $\EuScript{R}$ satisfies the conditions for an $(r,r)$-correspondence (Definition~\ref{def:stability_GH_M_metric}; see also Definition 10 in Curry et al.~\cite{curry2024stability}) with $r = r^*$:
\begin{itemize}
    \item The projections of $\EuScript{R}$ onto $X$ and $Y$ are surjective.
    \item For all pairs $(x, y), (x', y') \in \EuScript{R}$:
    \[ |d_X(x, x') - d_Y(y, y')| \leq 2r^* \quad \text{and} \quad |f(x) - g(y)| \leq r^*. \]
\end{itemize}
Since $r^* \leq \delta'$, these conditions immediately imply:
\[ |d_X(x, x') - d_Y(y, y')| \leq 2\delta' \quad \text{and} \quad |f(x) - g(y)| \leq \delta'. \]
Thus, the existing $(r^*, r^*)$-correspondence $\EuScript{R}$ also serves as a $(\delta', \delta')$-correspondence between $(X,f)$ and $(Y,g)$.

\textbf{Step 1: Define Correspondence between Reeb Graphs and Bound Functional Variation Difference.}
We define a correspondence $\EuScript{S} = \{ ([x], [y]) \mid (x, y) \in \EuScript{R} \} \subset R_f \times R_g$ between the nodes of the Reeb graphs $R_f$ (Definition~\ref{def:reeb_graph}) and $R_g$.
Now, consider any two pairs of points $(x, y) \in \EuScript{R}$ and $(x', y') \in \EuScript{R}$. The proof of Theorem 15 in Curry et al.~\cite{curry2024stability} details a construction involving approximate corresponding paths. This construction leverages the properties of the $(\delta', \delta')$-correspondence $\EuScript{R}$ (which bounds both metric distortion on the underlying spaces $X, Y$ and the difference between function values $f(x)$ and $g(y)$) along with the $(L, \epsilon)$-connectivity property of the scalar fields (Definition~\ref{def:stability_L_epsilon_connectivity}). This technique yields the following crucial intermediate bound on the difference between the functional variations $\rho_f(x, x')$ (along paths in $X$) and $\rho_g(y, y')$ (along paths in $Y$):
\begin{equation} \label{eq:app_rho_bound}
|\rho_f(x, x') - \rho_g(y, y')| \leq 2L\delta' + 2\delta' + 2\epsilon = 2(L+1)\delta' + 2\epsilon.
\end{equation}
This inequality is symmetric; it holds for the difference between $\rho_f(x, x')$ and $\rho_g(y, y')$, and equally for the difference between $\rho_f(x', x)$ and $\rho_g(y', y)$.

\textbf{Step 2: Bound the Symmetric Reeb Radius Difference on Reeb Graphs.}
Let $([x], [y]) \in \EuScript{S}$ and $([x'], [y']) \in \EuScript{S}$ be pairs in the Reeb graph node correspondence, derived from $(x, y) \in \EuScript{R}$ and $(x', y') \in \EuScript{R}$. We now aim to bound the distortion of this correspondence $\EuScript{S}$ with respect to the Symmetric Reeb Radius metrics $d_{R_f}$ and $d_{R_g}$ (Definition~\ref{def:symmetric_reeb_radius}). The Symmetric Reeb Radius $d_{R_f}([x], [x'])$ is defined based on the Reeb radii $\rho_f([x], [x'])$ and $\rho_f([x'], [x])$, which are computed using paths within the Reeb graph $R_f$. The argument in Curry et al.~\cite{curry2024stability} effectively relates these Reeb graph path-based radii back to the functional variations $\rho_f(x,x')$ computed in the underlying space $X$. Assuming this connection allows us to apply Equation~\eqref{eq:app_rho_bound} appropriately:
\begin{align*}
|d_{R_f}([x], [x']) - d_{R_g}([y], [y'])| &= \left| \frac{1}{2}\left(\rho_f([x], [x']) + \rho_f([x'], [x])\right) - \frac{1}{2}\left(\rho_g([y], [y']) + \rho_g([y'], [y])\right) \right| \\
% Assuming \rho_f([x],[x']) from Reeb graph paths can be related to \rho_f(x,x') from paths in X
% such that the bound from Eq. (A.1) applies to these Reeb graph radii differences.
&= \frac{1}{2} \left| (\rho_f(x, x') - \rho_g(y, y')) + (\rho_f(x', x) - \rho_g(y', y)) \right| \\
&\leq \frac{1}{2} \left( |\rho_f(x, x') - \rho_g(y, y')| + |\rho_f(x', x) - \rho_g(y', y)| \right) \quad (\text{by triangle inequality for } |\cdot|) \\
&\leq \frac{1}{2} \left( (2(L+1)\delta' + 2\epsilon) + (2(L+1)\delta' + 2\epsilon) \right) \quad (\text{using Eq.~\eqref{eq:app_rho_bound} twice}) \\
&= 2(L+1)\delta' + 2\epsilon.
\end{align*}


\textbf{Step 3: Conclude with Gromov-Hausdorff Bound for Reeb Graphs.}
The distortion of the correspondence $\EuScript{S}$ between the metric spaces $(R_f, d_{R_f})$ and $(R_g, d_{R_g})$ is thus bounded by $2(L+1)\delta' + 2\epsilon$. By a standard result that relates the Gromov-Hausdorff distance to the minimum distortion of a correspondence (e.g., \cite[Theorem 7.3.25]{burago2001course}), we have:
\[ d_{\mathrm{GH}}((R_f, d_{R_f}), (R_g, d_{R_g})) \leq \frac{1}{2} \times \mathrm{distortion}(\EuScript{S}). \]
Therefore,
\[ d_{\mathrm{GH}}((R_f, d_{R_f}), (R_g, d_{R_g})) \leq \frac{1}{2} (2(L+1)\delta' + 2\epsilon) = (L+1)\delta' + \epsilon. \]
This inequality holds for any $\delta' > \delta = d_{\mathrm{GH}}((X, f), (Y, g))$. By taking the infimum as $\delta' \to \delta^+$, we arrive at the desired result:
\[ d_{\mathrm{GH}}((R_f, d_{R_f}), (R_g, d_{R_g})) \leq (L+1)d_{\mathrm{GH}}((X, f), (Y, g)) + \epsilon, \]
which completes the proof of Theorem~\ref{thm:stability_drf_gh}.
\end{proof}



\subsection{Proof of Theorem~\ref{thm:stability_drf_L_infinity} (Stability of Symmetric Reeb Radius Metric w.r.t. \texorpdfstring{$L_\infty$}{L-infinity} Norm)}
\label{app:proof_thm_stability_drf_L_infinity_content}
\begin{proof}
We begin by recalling the result from Theorem~\ref{thm:stability_drf_gh}. When specialized to the case where both scalar fields, $f$ and $g$, are defined on the same underlying metric space $(X,d_X)$ (i.e., we set $Y=X$ and $d_Y=d_X$), Theorem~\ref{thm:stability_drf_gh} states:
\begin{equation} \label{eq:app_thm1_result_from_prev_thm} % Changed label slightly for clarity
d_{\mathrm{GH}}((R_f, d_{R_f}), (R_g, d_{R_g})) \leq (L+1) d_{\mathrm{GH}}((X, f), (X, g)) + \epsilon.
\end{equation}
Our objective is to establish an upper bound for the term $d_{\mathrm{GH}}((X, f), (X, g))$ using the supremum norm difference between the fields, defined as $\|f - g\|_\infty = \sup_{x \in X} |f(x) - g(x)|$.

From Definition~\ref{def:stability_GH_M_metric} (and also Definition 11 in Curry et al.~\cite{curry2024stability}), the Gromov-Hausdorff distance $d_{\mathrm{GH}}((X, f), (X, g))$ between these two M-Metric Fields (defined on the same underlying space $X$) is the infimum of all $r \geq 0$ for which an $(r, r)$-correspondence $\EuScript{R} \subset X \times X$ exists. Such a correspondence must satisfy two conditions for all pairs $(x_1, y_1), (x_2, y_2) \in \EuScript{R}$:
\begin{itemize}
    \item Metric distortion bound: $|d_X(x_1, x_2) - d_X(y_1, y_2)| \leq 2r$.
    \item Function proximity bound: $|f(x_1) - g(y_1)| \leq r$.
\end{itemize}

Consider the identity correspondence $\EuScript{R}_{\text{id}} = \{ (x, x) \mid x \in X \}$. Since both fields $f$ and $g$ share the domain $X$, this is a valid correspondence. We verify if $\EuScript{R}_{\text{id}}$ can serve as an $(r,r)$-correspondence for a suitable $r$:
\begin{itemize}
    \item \textbf{Metric Distortion:} For any two pairs $(x,x)$ and $(x',x')$ in $\EuScript{R}_{\text{id}}$, the condition becomes $|d_X(x, x') - d_X(x, x')| \leq 2r$. This simplifies to $0 \leq 2r$, which is satisfied for any non-negative $r$.
    \item \textbf{Function Proximity:} For any pair $(x,x)$ in $\EuScript{R}_{\text{id}}$, the condition is $|f(x) - g(x)| \leq r$. To ensure this holds for all $x \in X$, $r$ must be chosen such that $r \geq \sup_{x \in X} |f(x) - g(x)|$. The smallest such $r$ is precisely $\|f - g\|_\infty$.
\end{itemize}
Thus, the identity correspondence $\EuScript{R}_{\text{id}}$ constitutes an $(r,r)$-correspondence when we set $r = \|f - g\|_\infty$.

Since $d_{\mathrm{GH}}((X, f), (X, g))$ is the infimum over all $r \geq 0$ for which an $(r,r)$-correspondence exists, and we have found such a correspondence for $r = \|f - g\|_\infty$, it must be that:
\[
d_{\mathrm{GH}}((X, f), (X, g)) \leq \|f - g\|_\infty.
\]
Substituting this inequality back into Equation~\eqref{eq:app_thm1_result_from_prev_thm}, we directly obtain:
\begin{align*}
d_{\mathrm{GH}}((R_f, d_{R_f}), (R_g, d_{R_g})) &\leq (L+1) d_{\mathrm{GH}}((X, f), (X, g)) + \epsilon \\
&\leq (L+1) \|f - g\|_\infty + \epsilon,
\end{align*}
which is the statement of Theorem~\ref{thm:stability_drf_L_infinity}, thereby completing the proof.
\end{proof}


\subsection{Proof of Theorem~\ref{thm:stability_measure} (Stability of PI-Based Probability Measure)}
\label{app:proof_thm_stability_measure_content}

\begin{proof}
The objective of this proof is to establish that the Total Variation distance between the PI-based probability measures of two Reeb graphs, $d_{TV}(\nu_{R_f}, \nu_{R_g})$, is bounded by $M \|f - g\|_\infty$ for some constant $M$. This argument is structured in three main steps. We assume that $f$ and $g$ are continuous scalar fields on a compact topological space $X$, and $\nu_{R_f}, \nu_{R_g}$ are the PI-based probability measures as defined in Definition~\ref{def:pi_based_measure_method}. We also presuppose suitable regularity conditions (e.g., that $f$ and $g$ are Morse-Smale functions) to ensure that their persistence diagrams are finite and their Reeb graph structures are stable under small perturbations, particularly if an explicit vertex matching correspondence $\gamma$ is invoked.

\textbf{Step 1: Stability of Extended Persistence Diagrams.}
Let $D(f)$ and $D(g)$ denote the extended persistence diagrams (as described in Section~\ref{sec:extended_persistence}) derived from the scalar fields $f$ and $g$, respectively. A cornerstone result in persistent homology is the stability of these diagrams with respect to the bottleneck distance, $d_B$. Specifically, the bottleneck distance between $D(f)$ and $D(g)$ is bounded by the $L_\infty$ norm of the difference between the generating functions $f$ and $g$ \cite[Stability Theorem]{cohen2009extending}:
\begin{equation} \label{eq:app_bottleneck_stability}
d_B(D(f), D(g)) \leq \|f - g\|_\infty.
\end{equation}

\textbf{Step 2: Stability of Persistence Images (PIs).}
Let $I_f$ and $I_g$ be the Persistence Images (PIs), constructed as detailed in Section~\ref{sec:persistence_images_bg}, corresponding to the diagrams $D(f)$ and $D(g)$. Adams et al.~\cite[Theorem 10]{adams2017persistence} demonstrated that PIs are stable with respect to the 1-Wasserstein distance, $W_1(D(f),D(g))$, between the input persistence diagrams. This stability result states that the $L^1$-norm difference between the PIs $I_f$ and $I_g$ is bounded:
\[ \|I_f - I_g\|_1 \leq C_W \cdot W_1(D(f), D(g)). \]
The constant $C_W = (\sqrt{5}\|\nabla w\|_\infty + \sqrt{\frac{10}{\pi}}\frac{\|w\|_\infty}{\sigma})$ depends on properties of the weighting function $w$ used in the PI construction (specifically, an upper bound on the norm of its gradient, $\|\nabla w\|_\infty$, and its supremum norm, $\|w\|_\infty$) and the bandwidth $\sigma$ of the Gaussian kernel $\phi$.

The 1-Wasserstein distance $W_1(D(f),D(g))$ can, in turn, be bounded by the $L_\infty$ norm difference $\|f-g\|_\infty$. For instance, if $X$ is a finite CW-complex with $N_{\text{cells}}$ cells (or under suitable discretization assumptions for a general continuous $X$), the $W_1$ distance can be bounded by a multiple of $\|f-g\|_\infty$, e.g., $W_1(D(f),D(g)) \leq N_{\text{cells}} \cdot \|f-g\|_\infty$ (drawing from results like \cite[Theorem 4.8]{skraba2020wasserstein}, which relate $W_1$ to $L_1$-type differences between functions, subsequently bounded by $L_\infty$ differences). Combining these, we establish that the PIs are stable with respect to $\|f-g\|_\infty$:
\begin{equation} \label{eq:app_pi_stability}
\|I_f - I_g\|_1 \leq C_W \cdot N_{\text{cells}} \cdot \|f - g\|_\infty = K_{PI} \|f - g\|_\infty,
\end{equation}
where $K_{PI} = C_W \cdot N_{\text{cells}}$ is a consolidated constant.

\textbf{Step 3: Stability of the Normalized Probability Measure $\nu_{R_f}$.}
We assume that for sufficiently small $\|f-g\|_\infty$, the structural stability of the Reeb graphs ensures a meaningful correspondence (e.g., a bijection $\gamma: V'_{R_f} \to V'_{R_g}$) between the respective sets of significant vertices $V'_{R_f} \subset V_{R_f}$ and $V'_{R_g} \subset V_{R_g}$ (both of size, say, $V_N$) that form the basis of the PI-derived probability measure. For a node $v \in V'_{R_f}$ associated with a persistence point $(b_v, p_v)$, its unnormalized contribution to the measure $\nu_{R_f}$ is given by $\text{contrib}_f(v) = \sum_{k=1}^N I_f[k] \cdot \phi_{(b_v, p_v)}(c_k)$ (from Definition~\ref{def:pi_based_measure_method}).

We aim to bound the difference $|\text{contrib}_f(v) - \text{contrib}_g(\gamma(v))|$. This difference can be decomposed:
\begin{align*}
|\text{contrib}_f(v) - \text{contrib}_g(\gamma(v))| 
&\leq \left| \sum_{k=1}^N (I_f[k] - I_g[k]) \phi_{(b_v, p_v)}(c_k) \right| \\
&\quad + \left| \sum_{k=1}^N I_g[k] \left(\phi_{(b_v, p_v)}(c_k) - \phi_{(b_{\gamma(v)}, p_{\gamma(v)})}(c_k)\right) \right|.
\end{align*}
The first term is bounded by $\|\phi_{(\cdot, \cdot)}(\cdot)\|_\infty \|I_f - I_g\|_1 \leq \|\phi\|_\infty K_{PI} \|f-g\|_\infty$, where $\|\phi\|_\infty$ is the supremum norm of the Gaussian kernel.
For the second term, assuming the Gaussian kernel $\phi_{(b,p)}(c)$ is Lipschitz continuous with constant $L_\phi$ with respect to its center $(b,p)$, and noting that the Euclidean distance between persistence point coordinates, $\|(b_v, p_v) - (b_{\gamma(v)}, p_{\gamma(v)})\|_2$, can be bounded by $\sqrt{2} \cdot d_B(D(f),D(g))$ (a worst-case scenario for coordinate shifts given a bottleneck distance), this second term is bounded by $\|I_g\|_1 \cdot L_\phi \cdot \sqrt{2} \cdot d_B(D(f),D(g))$. Letting $M_{I_1}$ be an upper bound for $\|I_g\|_1$ (assuming PIs have bounded $L^1$ norm), we get:
\begin{align*}
|\text{contrib}_f(v) - \text{contrib}_g(\gamma(v))| 
&\leq \|\phi\|_\infty K_{PI} \|f-g\|_\infty + M_{I_1} L_\phi \sqrt{2} \|f-g\|_\infty \quad (\text{using Eq.~\eqref{eq:app_bottleneck_stability}}) \\
&= C' \|f-g\|_\infty,
\end{align*}
where $C' = (K_{PI} \|\phi\|_\infty + M_{I_1} L_\phi \sqrt{2})$ is a new constant.

Next, we consider the normalization factors $Z_f = \sum_{u \in V'_{R_f}} \text{contrib}_f(u)$ and $Z_g = \sum_{u \in V'_{R_g}} \text{contrib}_g(u)$. The difference is bounded by:
\[ |Z_f - Z_g| \leq \sum_{v \in V'_{R_f}} |\text{contrib}_f(v) - \text{contrib}_g(\gamma(v))| \leq V_N C' \|f-g\|_\infty. \]
Assuming $Z_f, Z_g \geq m_{Z} > 0$ (i.e., the total contribution is bounded below by a positive constant) and individual contributions $\text{contrib}_g(\gamma(v))$ are bounded above by $M_{\text{contrib}}$, we analyze the difference in the normalized probabilities $\nu_{R_f}(v) = \text{contrib}_f(v)/Z_f$ and $\nu_{R_g}(\gamma(v)) = \text{contrib}_g(\gamma(v))/Z_g$:
\begin{align*}
|\nu_{R_f}(v) - \nu_{R_g}(\gamma(v))| &= \left| \frac{\text{contrib}_f(v)}{Z_f} - \frac{\text{contrib}_g(\gamma(v))}{Z_g} \right| \\
&= \left| \frac{\text{contrib}_f(v)Z_g - \text{contrib}_g(\gamma(v))Z_f}{Z_f Z_g} \right| \\
% Standard manipulation: add and subtract contrib_g(\gamma(v))Z_g in numerator
&\leq \frac{|\text{contrib}_f(v) - \text{contrib}_g(\gamma(v))| \cdot |Z_g| + |\text{contrib}_g(\gamma(v))| \cdot |Z_g - Z_f|}{|Z_f Z_g|} \\
&\leq \frac{|\text{contrib}_f(v) - \text{contrib}_g(\gamma(v))|}{|Z_f|} + \frac{|\text{contrib}_g(\gamma(v))| \cdot |Z_g - Z_f|}{|Z_f Z_g|} \\
&\leq \frac{C' \|f-g\|_\infty}{m_Z} + \frac{M_{\text{contrib}} \cdot V_N C' \|f-g\|_\infty}{m_Z^2} = C'' \|f-g\|_\infty,
\end{align*}
where $C'' = \frac{C'}{m_Z} + \frac{M_{\text{contrib}} V_N C'}{m_Z^2}$.

Finally, the Total Variation distance (Definition~\ref{def:stability_tv_distance}) is $d_{TV}(\nu_{R_f}, \nu_{R_g}) = \frac{1}{2} \sum_{v \in V'_{R_f}} |\nu_{R_f}(v) - \nu_{R_g}(\gamma(v))|$ (assuming the bijection $\gamma$ correctly pairs corresponding nodes for the summation).
Thus, $d_{TV}(\nu_{R_f}, \nu_{R_g}) \leq \frac{1}{2} V_N C'' \|f-g\|_\infty$.
Setting $M = \frac{V_N C''}{2}$, we obtain the desired result: $d_{TV}(\nu_{R_f}, \nu_{R_g}) \leq M \|f - g\|_\infty$. The constant $M$ depends on various factors including PI construction parameters (kernel properties, weighting function characteristics, pixel resolution), the complexity of the underlying space $X$ (e.g., $N_{\text{cells}}$), and assumed bounds on contributions and normalization factors ($m_Z, M_{\text{contrib}}$). This completes the proof.
\end{proof}

\subsection{Proof of Theorem~\ref{thm:main_rgw_stability} (Stability of \texorpdfstring{$RGW_p$}{RGWp} Distance)}
\label{app:proof_thm_main_rgw_stability_content}

\begin{proof}
The goal of this proof is to demonstrate that the Reeb Gromov-Wasserstein distance, $RGW_p(R_f^*, R_g^*)$ (as defined in Definition~\ref{def:rgw_p_method}), between two decorated Reeb graphs $R_f^*=(R_f, d_{R_f}, \nu_{R_f})$ and $R_g^*=(R_g, d_{R_g}, \nu_{R_g})$ is controlled by the $L_\infty$ norm difference $||f-g||_\infty$ between their generating scalar fields and the parameter $\epsilon$ from the $(L,\epsilon)$-connectivity assumption.

Our strategy leverages the Gromov-Prokhorov distance $d_{\EuScript{GP}}$ (Definition~\ref{def:stability_gp_distance}) and a pivotal inequality established by Mémoli~\cite[Claim 10.6]{memoli2011gromov}, which relates $RGW_p$ to $d_{\EuScript{GP}}$:
\begin{equation} \label{eq:app_memoli_ineq_final_proof} % Renamed label
RGW_p(R_f^*, R_g^*) \leq (d_{\EuScript{GP}}(R_f^*, R_g^*))^{1/p} (D_{max}^p + 1)^{1/p}.
\end{equation}
Here, $D_{max} = \max(\text{diam}(R_f, d_{R_f}), \text{diam}(R_g, d_{R_g}))$ is the assumed uniform upper bound on the diameters of the Reeb graphs (viewed as metric spaces). The decorated Reeb graphs $R_f^*$ and $R_g^*$ are valid metric measure spaces, as per \cite[Def. 5.1]{memoli2011gromov}.

The core task is to establish an upper bound for $d_{\EuScript{GP}}(R_f^*, R_g^*)$. This is achieved through the following steps:

\begin{enumerate}
    \item \textbf{Step 1: Bounding Metric Component Closeness ($\delta_{GH}$)}
    From Theorem~\ref{thm:stability_drf_L_infinity}, we have established that the Gromov-Hausdorff distance between the metric structures of the Reeb graphs, $(R_f, d_{R_f})$ and $(R_g, d_{R_g})$, is bounded by:
    \[ d_{\mathrm{GH}}((R_f, d_{R_f}), (R_g, d_{R_g})) \leq (L+1) \|f - g\|_\infty + \epsilon. \]
    We denote this upper bound as $\delta_{GH} := (L+1) \|f - g\|_\infty + \epsilon$.
    (The implication stated in your draft, "This bound $\delta_{GH}$ implies the existence of a metric $d \in \EuScript{D}(d_{R_f}, d_{R_g})$... such that for any $(x,y) \in R_{corr}$, $d(x,y) \leq \delta_{GH}$ \cite[Lemma 10.1]{memoli2011gromov}," is a property related to how $d_{GH}$ can be realized, which underpins the connection to $d_{\EuScript{GP}}$, although for the $\max(\delta_{GH}, \eta_{TV})$ bound, we mainly need the values of $\delta_{GH}$ and $\eta_{TV}$.)

    \item \textbf{Step 2: Bounding Measure Component Closeness ($\eta_{TV}$)}
    From Theorem~\ref{thm:stability_measure}, the Total Variation distance between the probability measures $\nu_{R_f}$ and $\nu_{R_g}$ on the Reeb graph nodes is bounded by:
    \[ d_{TV}(\nu_{R_f}, \nu_{R_g}) \leq M \|f - g\|_\infty. \]
    We denote this upper bound as $\eta_{TV} := M \|f - g\|_\infty$.
    (The statement in your draft about the optimal coupling theorem and mass on "misaligned" pairs is a correct consequence of $d_{TV}$ and relevant for constructing the coupling in $d_{\EuScript{GP}}$, but again, the value $\eta_{TV}$ is what's primarily used in the typical $\max$ bound for $d_{\EuScript{GP}}$.)

    \item \textbf{Step 3: Bounding the Gromov-Prokhorov Distance ($d_{\EuScript{GP}}$)}
    The Gromov-Prokhorov distance $d_{\EuScript{GP}}(R_f^*, R_g^*)$ between the two metric measure spaces is controlled by both the geometric dissimilarity (related to $\delta_{GH}$) and the measure discrepancy (related to $\eta_{TV}$). Standard results in the theory of metric measure spaces (e.g., arguments found in Mémoli~\cite{memoli2011gromov}) provide a bound of the form:
    \begin{equation} \label{eq:app_dgp_bound_final_proof} % Renamed label
    d_{\EuScript{GP}}(R_f^*, R_g^*) \leq \max(\delta_{GH}, \eta_{TV}).
    \end{equation}
    Substituting our expressions for $\delta_{GH}$ and $\eta_{TV}$:
    \[ d_{\EuScript{GP}}(R_f^*, R_g^*) \leq \max\left((L+1)\|f-g\|_\infty + \epsilon, \; M\|f-g\|_\infty\right). \]
    To simplify this maximum, let $K_0 = \max(L+1, M)$. Using the inequality $\max(A+B, C) \leq \max(A,C) + B$ (which holds for non-negative $A, B, C$), we can set $A=(L+1)\|f-g\|_\infty$ (if $L+1 \ge M$) or $A=M\|f-g\|_\infty$ (if $M > L+1$), $B=\epsilon$ (only if $L+1 \ge M$), and $C$ as the other term. A cleaner way is:
    \[ \max\left((L+1)\|f-g\|_\infty + \epsilon, \; M\|f-g\|_\infty\right) \leq \max((L+1)\|f-g\|_\infty, \; M\|f-g\|_\infty) + \epsilon \]
    (This inequality holds because if the first term in the outer $\max$ is larger, the $\epsilon$ is simply added. If the second term is larger, then $M\|f-g\|_\infty \ge (L+1)\|f-g\|_\infty + \epsilon$, which implies $M\|f-g\|_\infty$ is also $\ge \max((L+1)\|f-g\|_\infty, M\|f-g\|_\infty) + \epsilon$ only if $\epsilon$ is negative or zero, which is not the general case. A safer bound for $\max(X+\epsilon, Y)$ is $\max(X,Y)+\epsilon$.)
    So, $\max((L+1)\|f-g\|_\infty + \epsilon, M\|f-g\|_\infty) \leq \max((L+1)\|f-g\|_\infty, M\|f-g\|_\infty) + \epsilon = K_0 \|f-g\|_\infty + \epsilon$.
    Therefore, we have:
    \[ d_{\EuScript{GP}}(R_f^*, R_g^*) \leq K_0 \|f-g\|_\infty + \epsilon. \]

    \item \textbf{Step 4: Deriving the Final Bound on $RGW_p$}
    We now substitute this bound for $d_{\EuScript{GP}}(R_f^*, R_g^*)$ into Mémoli's inequality (Equation~\eqref{eq:app_memoli_ineq_final_proof}):
    \[ RGW_p(R_f^*, R_g^*) \leq \left(K_0 \|f-g\|_\infty + \epsilon\right)^{1/p} (D_{max}^p+1)^{1/p}. \]
    Using the standard inequality $(a+b)^{k} \leq a^{k} + b^{k}$ for $a,b \ge 0$ and $0 < k \le 1$ (here $k=1/p$ with $p \ge 1$):
    \begin{align*}
    RGW_p(R_f^*, R_g^*) &\leq \left( (K_0 \|f-g\|_\infty)^{1/p} + \epsilon^{1/p} \right) (D_{max}^p+1)^{1/p} \\
    &= K_0^{1/p} (D_{max}^p+1)^{1/p} (\|f-g\|_\infty)^{1/p} + (D_{max}^p+1)^{1/p} \epsilon^{1/p}.
    \end{align*}
    By defining the constants $C_1 = K_0^{1/p} (D_{max}^p+1)^{1/p}$ and $C_2 = (D_{max}^p+1)^{1/p}$, we arrive at the main stability result:
    \[ RGW_p(R_f^*, R_g^*) \leq C_1 \cdot (\|f - g\|_\infty)^{1/p} + C_2 \cdot \epsilon^{1/p}. \]
    For the specific case where $p=1$, these constants become $C_1' = K_0 (D_{max}+1)$ and $C_2' = (D_{max}+1)$, yielding:
    \[ RGW_1(R_f^*, R_g^*) \leq C_1' \cdot \|f - g\|_\infty + C_2' \cdot \epsilon. \]
\end{enumerate}
This sequence of bounds demonstrates that small perturbations in the input scalar field (as controlled by $||f-g||_\infty$) and a small value for $\epsilon$ (related to the $(L,\epsilon)$-connectivity assumption) ensure a correspondingly small change in the $RGW_p$ distance, thereby establishing the desired stability property. This completes the proof of Theorem~\ref{thm:main_rgw_stability}.
\end{proof}






