\begin{lemma}\label{lem:reduction:AIP}
    For a 3-CNF formula $\phi$, 
    $\phi$ has a satisfying assignment if and only if 
    $\mathcal D_\phi$ has an induced $s$-$t$ hyperpath not contained in $\mathcal P_\phi$.
\end{lemma}
\begin{proof}
