\begin{lemma}
    For a 3-CNF formula $\phi$,
    $\phi$ has a satisfying assignment if and only if
    $\mathcal D_\phi$ has a minimal $s$-$t$ separator not contained in $\mathcal X(\phi)$.
\end{lemma}
\begin{proof}
    Suppose that $\phi$ has a satisfying assignment $\alpha$.
    We define a set of vertices using $\alpha$.
    Let $x_i$ be a variable in $\phi$.
    The set of vertices $X$ contains a vertex $x_i$ if $\alpha(x_i) = 1$,
    otherwise $X$ contains $\bar x_i$.
    From the construction of $\mathcal D_\phi$,
    each $y_i$ is connected to $s$ in $\mathcal D_\phi[X]$.
    Moreover, since $\alpha$ is a satisfying assignment,
    $c$ is not connected to $s$ in $\mathcal D_\phi[X]$.
    Therefore, $X$ is an $s$-$t$ separator and 
    a minimal $s$-$t$ separator that is contained in $X$ is not contained in $\mathcal X(\phi)$.

    Suppose that $\mathcal D_\phi$ has a minimal $s$-$t$ separator $X \not\in \mathcal X(\phi)$.
    From the construction of $\mathcal X(\phi)$ and $X \not\in \mathcal X(\phi)$,
    for each $1 \le i \le \size{V(\phi)}$, $x_i \notin X$ or $\bar x_i \notin X$.
    We define an assignment $\alpha_X$ as follows.
    If $x_i \in X$, $\alpha_X(x_i) = 1$, otherwise $\alpha_X(x_i) = 0$.
    From the construction of $\mathcal D_\phi$, 
    each clause is satisfied. 
    Otherwise, $\mathcal D_\phi[V(\mathcal D_\phi) \setminus X]$ has an $s$-$t$ hyperpath and it contradicts that $X$ is an $s$-$t$ separator.
    Therefore, $\alpha_X$ is a satisfying assignment of $\phi$.
    % \qed    
\end{proof}

We improve our reduction to the cardinality of each tail to two by making a small modification, 
In our reduction, the maximum cardinality of each tail is $n + 1$ since $\mathcal D_\phi$ has a hyperarc $A = (\set{y_1, \ldots, y_{n}, c}, \set{t})$.
In addition, $\mathcal D$ has $m$ hyperarcs whose tail has the cardinality three.
To simplify the following discussion, we assume that $n + m + 1$ is a power of two.
If $n+m+1$ is not a power of two, we add one dummy variable $z$ and dummy clauses $(z \lor z \lor z)$ to make $n+m+1$ a power of two.

For each clause $C_j = \ell^j_1 \lor \ell^j_2 \lor \ell^j_3$, we add one vertex $c_j$ and 
replace a hyperarc $(\set{\bar \ell^j_1, \bar \ell^j_2, \bar \ell^j_3}, \set{c})$ with two hyperarcs 
$(\set{\bar \ell^j_1, \bar \ell^j_2}, \set{c_j})$ and
$(\set{c_j, \bar \ell^j_3}, \set{c})$.
We replace a hyperarc $(\set{c, y_1, \ldots, y_n}, \set{t})$ with $A = (\set{c, c_1, \ldots, c_m, y_1, \ldots, y_n}, \set{t})$.
As a result of this modification, all hyperarcs except one have tails with cardinality at most two.
This modification adds only $\set{c_j}$ for each $1 \le j \le m$ as new minimal $s$-$t$ separators since $\set{c_j}$ is a minimal $s$-$t$ separator.
Applying the similar technique as in the previous section, 
we add vertices $d_2, \ldots, d_{n + m}$, and
replace a hyperarc $A = (\set{y_1, \ldots, y_n, c_1, \ldots, c_m, c}, \set{t})$ with
a set of hyperarcs $\inset{(\set{w_{2i}, w_{2i+1}}, \set{w_{i}})}{1 \le i \le n+m}$, 
where $w_1 = t$, $w_i = d_i$ if $i$ is at least $2$ and at most $n + m$,
$w_{n + m + 1} = c$, $w_i = c_{i - n - m - 1}$ if $i$ is at least $n + m + 2$ and at most $n + 2m + 1$, otherwise, $w_i = y_{i - n - 2m - 1}$.
% \reviewer{I guess you also include c into each new hyperedge giving you three tails.}.
Applying this modification, we obtain new $\order{n + m}$ minimal $s$-$t$ separators.
Therefore, by adding such small minimal separators to $\mathcal X(\phi)$,
the set of minimal separators that is not contained in $\mathcal X(\phi)$ does not change.
% \reviewer{In you reduction for another minimal s-t separator, you create an arc
%    $(\{\bar{l}_1^j, \bar{l}_2^j, \bar{l}_3^j \}, c)$
%  for each clause. I believe you should take the clause directly and not its complement. Indeed, if a valid assignment takes all the literal of a clause, its complement will leave s and t B-connected once you remove the set of vertices corresponding to the assignment
%  from the hypergraph.}

% If $k+1$ is not a power of two\reviewer{section 3.2 if k+1 is not a power of 2 I think you can simplify this by adding dummy clauses which are trivially fulfilled}, we add $2^\ell - k - 1$ vertices $z_{k + 2}, \ldots, z_{2^\ell}$ and a hyperarc $(\set{s}, z_{i})$ for each $k+2 \le j \le 2^\ell$ and replace $(\set{y_1, \ldots, y_k, c}, \set{t})$ into $(\set{y_1, \ldots, y_k, c, z_{k+2}, \ldots, z_{2^\ell}}, \set{t})$, where $2^\ell$ is the minimum integer larger than $k+1$.
% Applying this modification, we also obtain new $\order{k}$ minimal $s$-$t$ separators since $\set{z_i}$ is a minimal $s$-$t$ separator. 
% Therefore, by applying the previous modification again, 
% the following theorem and corollary hold.
% \reviewer{I think since $|H(A)|=1$ in theorems 1 and 2 using the name B-Hypergraphs here is helpful for consistency reasons}

\begin{theorem}
    \textsc{Another Minimal $s$-$t$ Separator} on a $B$-hypergraph $\mathcal D = (V, \mathcal A)$ is \NP-complete even if $\size{\mathcal X} \le \size{V}$ and $\size{T(A)} \le 2$ for any $A \in \mathcal A$.
    Therefore, there are no output-polynomial time algorithms for enumerating all minimal $s$-$t$ separators in a $B$-hypergraph unless $\P = \NP$ even if $\size{T(A)} \le 2$ holds for any $A \in \mathcal A$.    
\end{theorem}

\subsection{\texorpdfstring{$s$-$t$}{s-t} hyperpath Enumeration}\label{subsec:bpath:bf}
% We give a reduction from \textsc{Minimal Transversal Enumeration} to \textsc{$s$-$t$ hyperpath Enumeration} for $BF$-hypergraphs.
Let $\mathcal H = (V, \mathcal E)$ be a hypergraph.
We construct a directed hypergraph $\mathcal D_{\mathcal H} = (V_{\mathcal H}, \mathcal A_\mathcal H)$ as follows.
The set of vertices $V_{\mathcal H}$ consists of $\mathcal E \cup \set{s, t}$.
For each $v \in V$, we add a hyperarc $(\set{s}, \mathcal E_v)$, 
where $\mathcal E_v$ is the set of hyperedges in $\mathcal E$ that contain $v$.
Note that $\mathcal E_v$ is the set of hyperedges in $\mathcal H$, but
it is the set of vertices in $\mathcal D_{\mathcal H}$.
Thus, $(\set{s}, \mathcal E_v)$ is a pair of distinct sets of vertices in $V_{\mathcal H}$.
% \reviewer{p.8:It is a bit unclear what $(\{s\},E_v)$ means. I guess, you treat $E_v$ as the concatenation of all vertices involved in the hyperedges containing v either as a head or tail.}, 
Additionally, we add hyperarc $(\mathcal E, \set{t})$.
% \reviewer{p.8: a hyperarc (E,{t}) -> hyperarc (E,{t})}.
Since each hyperarc $A \in \mathcal A_\mathcal H$ satisfies either $\size{T(A)} = 1$ or $\size{H(A)} = 1$,
$\mathcal D_\mathcal H$ is a $BF$-hypergraph.

\begin{lemma}\label{lem:bij:bf}
    Let $\mathcal H$ be a hypergraph and $\mathcal D_{\mathcal H}$ be a $BF$-hypergraph.
    There is a bijection between 
    the set of minimal transversals in $\mathcal H$ and the set of $s$-$t$ hyperpaths in $\mathcal D_\mathcal H$.    
\end{lemma}
\begin{proof}
 %    \reviewer{ The proof of Lemma 3 feels a bit clumsy. I don't understand why there is a separate paragraph
 % for the "Suppose that there is ..." since you are still proving that f(T) is a hyperpath.
 % The same goes for the surjective part of $f$. You also claim that "we show f is a bijection"
 % without specifying the codomain you are considering. In fact, I suspect the proof might be
 % easier to read if reorganized as follows:

 %   * for each T, f(T) is a s-t hyperpath
 %   * each s-t hyperpath equals f(T) for some minTR T
 %   * $T_1 \neq T_2$ entails $f(T_1) \neq f(T_2)$}
 %     \reviewer{In fact, I suspect the reduction of Section 3.3 would be slightly simpler by considering
 % the dual problem of finding all minimal covers of a hypergraph : given a hypergraph, find
 % all minimal subsets of edges the union of which is the whole set of vertices. Then, you would
 % just have to use vertices of the hypergraph (+ s, t) as the vertices of the directed hypergraph,
 % and not sets of vertices.}
 Let $\mathcal H$ be a hypergraph and $\mathcal D_{\mathcal H}$ be a $BF$-hypergraph obtained by the above procedure.
    We define a function $f: \mathrm{Tr}(\mathcal H) \to 2^{\mathcal A_{\mathcal H}}$ such that $f(T) = \inset{(\set{s}, \mathcal E_v)}{v \in T} \cup \set{(\mathcal E, \set{t})}$, where $T$ is a minimal transversal of $\mathcal H$.

    We show that for a minimal transversal $T$, $f(T)$ is an $s$-$t$ hyperpath.
    % \reviewer{In the part of the proof where it is shown that f(T) is an s-t hyperpath, it should be mentioned at the beginning why another s-t hyperpath $P_st$ would contradict the statement that f(T) is a hyperpath equivalent to T.}
    To this end, we show that $t$ is $B$-connected from $s$ in $\mathcal D_\mathcal H[f(T)]$.
    Since $T$ is a transversal, any vertex in $V(\mathcal D_{\mathcal H}) \setminus \set{s, t}$ is connected to $s$.
    From the definition of $f(T)$, $f(T)$ contains a hyperarc $(\mathcal E, \set{t})$.
    Since any vertex in $V(\mathcal D_{\mathcal H}) \setminus \set{s, t}$ is connected to $s$ and $f(T)$ contains $(\mathcal E, \set{t})$, $t$ is connected to $s$.
    We next show the minimality of $f(T)$ by contradiction.
    Suppose that there is an $s$-$t$ hyperpath $P_{st}$ contained in $f(T)$.
    If $(\mathcal E, \set{t}) \not\in P_{st}$, $P_{st}$ is not $s$-$t$ hyperpath.
    Thus, a hyperarc $A \in f(T) \setminus P_{st}$ satisfies $T(A) = \set{s}$ and $H(A) = \mathcal E_v$ for some $v \in V(\mathcal H)$.
    However, since $T$ is a minimal transversal, 
    there is a hyperedge $E \in \mathcal E_v$ such that $T \cap E = \set{v}$.
    In this case, $E$ is not connected to $s$.
    Therefore, $f(T)$ is an $s$-$t$ hyperpath.

    We next show that $f$ is a bijection between $\mathrm{Tr}(\mathcal H)$ and the set of all $s$-$t$ hyperpaths in $\mathcal D_\mathcal H$.
    We first show that $f$ is injective.
    Let $T_1$ and $T_2$ be two distinct minimal transversals.
    Since $T_1$ and $T_2$ are distinct, there are vertices 
    $v_1 \in T_1 \setminus T_2$ and
    $v_2 \in T_2 \setminus T_1$.
    Therefore,
    $f(T_1) \setminus f(T_2)$ contains a hyperarc $(\set{s}, \mathcal E_{v_1})$ and
    $f(T_2) \setminus f(T_1)$ contains a hyperarc $(\set{s}, \mathcal E_{v_2})$, and
    $f$ is injective.

    We next show that $f$ is surjective.
    Let $P_{st}$ be an $s$-$t$ hyperpath in $\mathcal D_{\mathcal H}$.
    From the construction of $\mathcal D_{\mathcal H}$,
    each hyperarc $A$ satisfying $T(A) = \set{s}$ corresponds to a vertex in $\mathcal H$.
    Thus, we consider a set of vertices $T$ corresponds to $P_{st} \setminus \set{(\mathcal E, \set{t})}$.
    Since $P_{st}$ is an $s$-$t$ hyperpath, each vertex $v \in T$ has a hyperedge $E$ such that $T \cap E = \set{v}$.
    Therefore, $T$ is a minimal transversal and $f$ is a bijection.
    % \qed    
\end{proof}

\begin{thmrep}
    If there is an output-polynomial time algorithm for \textsc{$s$-$t$ hyperpath Enumeration} on a $BF$-hypergraph $\mathcal D$, 
    there is an output-polynomial time algorithm for \textsc{Minimal Transversal Enumeration}.
\end{thmrep}
\begin{proof}
    Suppose that there is an output-polynomial time algorithm for \textsc{$s$-$t$ hyperpath Enumeration} on a $BF$-hypergraph.
    For a hypergraph $\mathcal H = (V, \mathcal E)$, we construct $\mathcal D_{\mathcal H}$ in
    $\order{||\mathcal H||}$ time, where $||\mathcal H||$ is the sum of the number of vertices and the cardinality of hyperedges.
    Since we have an output-polynomial time algorithm for enumerating all $s$-$t$ hyperpaths in $\mathcal D_{\mathcal H}$,
    we obtain the set of all $s$-$t$ hyperpaths in $\mathcal D_{\mathcal H}$.
    From \Cref{lem:bij:bf}, there is a bijection between the set of minimal transversals in $\mathcal H$ and the set of all $s$-$t$ hyperpaths in $\mathcal D_{\mathcal H}$.
    Moreover, we can restore $\mathrm{Tr}(\mathcal H)$ in $\order{||\mathcal H|| \cdot \mathrm{Tr}(\mathcal H)}$ time.
    Therefore, we obtain an output-polynomial time algorithm for \textsc{Minimal Transversal Enumeration}.
\end{proof}


\section{\texorpdfstring{Polynomial-delay Enumeration of $s$-$t$ hyperpaths for $B$-hypergraphs}{Polynomial-delay Enumeration of s-t hyperpaths for B-hypergraphs}}
We give a positive result of the $s$-$t$ hyperpath enumeration for a $B$-hypergraph.
In this section, a directed hypergraph may have parallel hyperarcs, that is, there may be hyperarcs with the same pair of tail set and head.
The proposed algorithm solves a slightly more general problem than the $s$-$t$ hyperpath enumeration.
We first extend the concept of an $s$-$t$ hyperpath.

Let $S$ be a set of vertices.
We define \emph{$B$-connection from $S$} as follows:
(i)  a vertex $s \in S$ is $B$-connected from $S$ and
(ii) if there is a hyperarc $A$ such that all the vertices in $T(A)$ are $B$-connected from $S$, then $H(A)$ is $B$-connected from $S$.
For a set of vertices $S$ and $T$,
an inclusion-wise minimal set of hyperarcs $P_{ST}$ is an \emph{$S$-$T$ hyperpath} if 
all vertices
% \todo{probably all is more specifiic} 
in $T$ is $B$-connected from $S$.
It should be noted that a $S$-$T$ hyperpath is also a generalization of 
a minimal directed Steiner tree~\cite{10.1145/3517804.3524148}.
Hereafter, we give a polynomial-delay enumeration algorithm for enumerating all $S$-$T$ hyperpaths.
We first introduce a characterization for an $S$-$T$ hyperpath in a $B$-hypergraph.

% We give several observations about $B$-connectivity that are useful in providing the proof of correctness of our algorithm.

\begin{lemma}\label{obs:hpath}
    A set of hyperarcs $P_{ST}$ is an $S$-$T$ hyperpath if and only if the followings hold:
    \begin{enumerate}
        \item There is a sequence of hyperarcs $(A_1, \ldots, A_{\size{P_{ST}}})$ such that for each $A_i$, $T(A_i) \subseteq S \cup \bigcup_{1 \le j \le i-1} H(A_j)$,
        % \item for each $t \in T$, there is a hyperarc $A_j$ satisfying $\set{t} = H(A_j)$,
        \item $|\{A\in P_{ST} \mid \set{v} = H(A)\}| = 0$ if $v \in S$, 
        otherwise $|\{A\in P_{ST} \mid \set{v} = H(A)\}| = 1$\label{item:minimal_BsT_to_much_in}, and
        \item  $|\{A\in P_{ST} \mid v \in T(A)\}| \ge 1$ if $v \in V(\mathcal D[P_{ST}]) \setminus (T \cup S)$.\label{item:minimal:hyperarcs}
        % \item for any proper subhypergraph of $P_{ST}$, $T$ has a vertex $t$ such that it is not $B$-connected from $S$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    Suppose that $P_{ST}$ satisfies the three conditions and $(A_1, \ldots, A_{\size{P_{ST}}})$ is an ordering of $P_{ST}$.
    From the condition~1 and 2, 
    all vertices in $\mathcal D[P_{ST}]$ is $B$-connected from $S$.
    % any $t \in T$ is $B$-connected from $S$ in $P_{ST}$.
    % Moreover, from the condition (ii), $t$ is $B$-connected from $S$.
    We show that the minimality of $P_{ST}$ by contradiction.
    Suppose that $P'_{ST} \subset P_{ST}$ is an $S$-$T$ hyperpath.
    Let $A$ be the largest hyperarc in $P'_{ST} \setminus P_{ST} $ with respect to the order of $P_{ST}$.
    If the head of $A$ is contained in $T$, 
    $t$ is not $B$-connected from $S$ since $P'_{ST}$ has no hyperarcs with $t$ as its head.
    Thus, the head of $A$ is not in $T$.
    If the head of $A$ is contained in $S$, it contradicts the condition~2.
    % \todo{I think it should be condition 2.}
    Thus, it is contained in $V \setminus (S \cup T)$.
    From the condition~3, $P_{ST}$ contains a hyperarc $A'$ that contains the head of $A$ as its tail.
    From the condition~1, $A'$ is larger than $A$ with respect to the order $(A_1, \ldots, A_{\size{P_{ST}}})$.
    If $A'$ is contained in $P'_{ST}$, it contradicts the minimality of $P'_{ST}$ since removing $A'$ from $P'_{ST}$ does not change $B$-connectivity for other vertices.
    If $A'$ is not contained in $P'_{ST}$,
    it contradicts the condition of $A$ since $A'$ is larger than $A$ with respect to the order of $P_{ST}$, and
    $P_{ST}$ is an $S$-$T$ hyperpath.



    Suppose that $P_{ST}$ is an $S$-$T$ hyperpath.
    % The conditions~2 and 3 are not related to the existence of such a hyperarcs ordering.
    Since $P_{ST}$ is an $S$-$T$ hyperpath, 
    the conditions~2 and 3 are satisfied, otherwise, it contradicts the minimality of $P_{ST}$.
    Therefore, we  show that $P_{ST}$ has an order satisfying the condition~1.
    We order $P_{ST}$ as follows.    
    Let $\mathcal A_1$ be the set of hyperarcs such that $T(A) \subseteq S$.
    We recursively define $\mathcal A_j$ as $\inset{A \in P_{ST} \setminus \mathcal A_{i-1}}{T(A) \subseteq S \cup \bigcup_{B \in \mathcal A_{i-1}}H(B)}$.
    Notice that the set of vertices $S \cup \bigcup_{B \in \mathcal A_{i}}H(B)$ is $B$-connected from $S$ in a directed subhypergraph induced by $\bigcup_{1 \le j \le i} \mathcal A_j$.
    % \todo{I think the we should say "induced by"}
    If an hyperarc $A \in P_{ST}$ is not contained any $\mathcal A_i$, it contradicts the minimality of $P_{ST}$.
    Moreover, for distinct $k_1$ and $k_2$, 
    $\mathcal A_{k_1}$ and $\mathcal A_{k_2}$ are disjoint.
    Therefore, $\set{\mathcal A_1, \ldots, \mathcal A_\ell}$ gives a partition of $P_{ST}$, where $\ell$ is the maximum integer satisfying $\mathcal A_\ell \neq \emptyset$.
    % \todo{I think it should be a $\mathcal A_\ell$}
    We consider an order of $P_{ST}$ as $(\mathcal A_1, \ldots, \mathcal A_\ell)$.
    We obtain a desired order of the set of hyperarcs in $P_{ST}$ 
    by ordering the hyperarcs within each $\mathcal A_i$ in an arbitrary order.
\end{proof}    

Our goal is to enumerate all sets of hyperarcs that satisfy the conditions in \Cref{obs:hpath} by a backtracking approach.
To this end, we recursively partition the problem into two subproblems.
This approach is inspired by Read and Tarjan's $s$-$t$ path enumeration algorithm~\cite{ReadTarjan}.
We describe an overview of our algorithm.

% First, we find an $S$-$T$ hyperpath $P_{ST}$.
% It is easy to find $P_{ST}$ and an ordering satisfying the condition in \Cref{obs:hpath} in polynomial time. 
% since $B$-connectivity can be computed in polynomial time. 
% If we have an $S$-$T$ hyperpath $P_{ST}$, we also can obtain a sequence representation $(A_1, \ldots, A_{k})$ of $P_{ST}$ in polynomial time using the following algorithm.
% We remove a hyperarc $A$ such that $H(A) \in T$ and update $T$ to $(T \cup T(A)) \setminus S$.
In our enumeration algorithm, 
we find an $S$-$T$ hyperpath $P_{ST}$ with an ordering $(A_1, \ldots, A_k = (T_k, h_k))$ in \Cref{obs:hpath}, 
divide enumeration problems into the enumeration of an $S$-$T$ hyperpath that contains $A_{k}$ and does not contain $A_{k}$.
The $S$-$T$ hyperpaths outputted by these two enumeration problems are clearly non-duplicate, 
and their union is equal to the set of $S$-$T$ hyperpaths of the original problem.
One subproblem, enumeration of $S$-$T$ hyperpaths that do not contain $A_{k}$ equals enumeration of $S$-$T$ hyperpaths in $D[\mathcal A \setminus \set{A_{k}}]$. 
The key observation is that the enumeration of $S$-$T$ hyperpaths can also be achieved by modifying $\mathcal D$ and $T$.
We give the details of our algorithm in \Cref{alg:proposed}.


\begin{algorithm}[t]
    \SetAlgoLined
    \SetKwProg{Procedure}{Procedure}{}{}
    \SetKwFunction{EnumHyperpaths}{EnumHyperpaths}
    \DontPrintSemicolon
    \Procedure{\EnumHyperpaths{$\mathcal D = (V, \mathcal A), S, T, P$}}{
        \lIf{$T = \emptyset$}{Output $P$ and \Return}
        \lIf{$\mathcal D$ has no $S$-$T$ hyperpaths}{\Return}
        Let $(A_1, \ldots, A_k = (T_k, h_k))$ be an $S$-$T$ hyperpath.\;
        \EnumHyperpaths{$\mathcal D[\mathcal A \setminus \set{A_k}], S, T, P$}\;
        $\mathcal A', T' \gets \emptyset, (T \cup T_k) \setminus (S \cup \set{h_k})$\tcp*{Note that $\mathcal A'$ is a multiset.}\label{alg:rec:0}
        \ForEach{$B \in \mathcal A \setminus \inset{A'' \in \mathcal A}{H(A'') = h_k}$}{
            \lIf{$h_k \in T(B)$}{
                Add $((T(B) \setminus \set{h_k}) \cup T_k, H(B))$ to $\mathcal A'$\label{alg:diff}.
            }\lElse{
                Add $B$ to $\mathcal A'$.
            }
            }

        \EnumHyperpaths{$(V \setminus \set{h_k}, \mathcal A'), S, T', P \cup \set{A_k}$}\label{alg:rec:1}\;        
    }
    \caption{A polynomial-delay and polynomial-space algorithm for enumerating all $S$-$T$ hyperpaths.}
    \label{alg:proposed}
\end{algorithm}

% \reviewer{p.11: The pseudocode and its discussion in the text use different notation (e.g. $A_k$ vs $A_T$).(see algorithm)}
% \reviewer{Algorithm 1: Step 4 is effectively treated as a black box in the main text. It would be great to move the 5 lines for the delay from the appendix into the main text.}
% \reviewer{the choice of the arc $h_T$ in line 4 of algorithm 1 seems to be quite important, that is, that $H(A_T)\in T$. In my opinion, a short discussion might be helpful to argue that this property is necessary.}

Hereafter, we formally define a division of the problem.
Let $\mathcal D = (V, \mathcal A)$ be a directed hypergraph and $P_{ST}$ be an $S$-$T$ hyperpath and $(A_1, \ldots, A_k = (T_k, h_k))$ be an order of $P_{ST}$ satisfying the conditions in \Cref{obs:hpath}.
We define $\mathcal P_{ST}(\mathcal D)$ as the set of $S$-$T$ hyperpaths in $\mathcal D$.
Furthermore, we introduce $\mathcal P^0_{ST}(\mathcal D, P_{ST}, A_k)$ and $\mathcal P^1_{ST}(\mathcal D, P_{ST}, A_k)$ as the set of $S$-$T$ hyperpaths that do not contain $A_k$ and contain $A_k$, respectively.
% \todo{I think it would be better, if we put $A_k$ in to the notation}.
Obviously, the set of all $S$-$T$ hyperpaths on $\mathcal D[\mathcal A \setminus \set{A_k}]$ corresponds to $\mathcal P^0_{ST}(\mathcal D, P_{ST}, A_k)$.
The remainder part is how to obtain $\mathcal P^1_{ST}(\mathcal D, P_{ST}, A_k)$ by modifying $\mathcal D$, $S$, and $T$.

Since any $S$-$T$ hyperpath in $\mathcal P^1_{ST}(\mathcal D, P_{ST}, A_k)$ contains $A_k$, 
there are no $S$-$T$ hyperpaths that contain a hyperarc whose head is $h_k$ without $A_k$ from \Cref{obs:hpath}.
Thus, removing all hyperarcs that contain $h_k$ as its head from $\mathcal D$ does not change the set of $S$-$T$ hyperpaths containing $A_k$.
% In what follows, we denote the set of hyperarcs $\inset{A \in \mathcal A}{H(A) = u}$ as $\delta^+(u)$.
Moreover, $u \in T_k$ is $B$-connected from $S$ in any $S$-$T$ hyperpath in $\mathcal P^1_{ST}(\mathcal D, P_{ST}, A_k)$ from \Cref{obs:hpath}.
% Otherwise, it contradicts the minimality of a $S$-$T$ hyperpath.
Thus, for any $Q \in \mathcal P^1_{ST}(\mathcal D, P_{ST}, A_k)$ and $B \in Q$ such that $T(B)$ contains $h_k$,
any vertex in $(T(B) \setminus \set{h_k}) \cup T_k$ is $B$-connected from $S$ in $\mathcal D[Q]$.
Motivated by these observations, we consider the following modification of hyperarcs in $\mathcal A \setminus \inset{A'' \in \mathcal A}{H(A) = h_k}$.
For a hyperarc $B \in \mathcal A \setminus \inset{A'' \in \mathcal A}{H(A'') = h_k}$,
we define a function $f$ as follows.
If $B$ does not contain $h_k$ as its tail, $f(B) = B$, otherwise, 
$f(B) = ((T(B) \setminus \set{h_k}) \cup T_k, H(B))$.
Based on $f$, we define the multiset of hyperarcs as $\mathcal B = \inset{f(B)}{B \in \mathcal A \setminus \inset{A'' \in \mathcal A}{H(A'') = h_k}}$.
Note that $f$ is a bijection between $\mathcal A \setminus \inset{A'' \in \mathcal A}{H(A'') = h_k}$ and $\mathcal B$.
We show that there is a bijection between the set of all $S$-$T'$ hyperpaths on $\mathcal D'$ and $\mathcal P^1_{ST}(\mathcal D, P_{ST}, A_k)$, 
where $\mathcal D' = (V \setminus \set{h_k}, \mathcal B)$ and $T' = (T \cup T(A_k)) \setminus (S \cup \set{H(A_k)})$.

\begin{lemma}\label{lem:bij_Y_A}
    % Let $A$ be a hyperarc satisfying $H(A) \in T$, $T'$ be the set of vertices $(T \cup T(A)) \setminus (S \cup \set{H(A)})$,
    % and $\mathcal P'$ be the set of $S$-$T'$ hyperpaths in $\mathcal D' = (V \setminus \set{H(A)}, \mathcal A')$, where $\mathcal A'$ is the multiset of hyperarcs defined as the following function $f$. For each $A' \in \mathcal A \setminus \set{A}$,
    % \begin{equation*}
    %     f(A') = 
    %     \begin{cases}
    %         (\emptyset, \emptyset) & \text{ if } H(A) = H(A') \\
    %         ((T(A') \cup T(A)) \setminus \set{H(A)}, H(A')) & \text{ if } H(A) \in T(A') \\
    %         A' & \text{ Otherwise.}
    %     \end{cases}
    % \end{equation*}
    There is a bijection between $\mathcal P_{ST'}(\mathcal D')$ and $\mathcal P^1_{ST}(\mathcal D, P_{ST}, A_k)$, 
    where $\mathcal D' = (V \setminus \set{h_k}, \mathcal B)$ and $T' = (T \cup T(A_k)) \setminus (S \cup \set{H(A_k)})$.
\end{lemma}
\begin{proof}   
    % From the construction of $\mathcal A'$, there is a one-to-one correspondence between $\mathcal A \setminus \delta^+(H(A_k))$ and $\mathcal A'$.
    For each $Q \in \mathcal P^1_{ST}(\mathcal D, P_{ST}, A_k)$, 
    we define the set of hyperarcs $g(Q) = \bigcup_{B \in Q\setminus\set{A_k}}f(B)$.
    We show that $g$ is a bijection between $\mathcal P^1_{ST}(\mathcal D, P_{ST}, A_k)$ and $\mathcal P_{ST'}(\mathcal D')$.
    We first show that $g$ is injective.
    Let $Q_1$ and $Q_2$ be distinct $S$-$T$ hyperpaths in $\mathcal P^1_{ST}(\mathcal D, P_{ST}, A_k)$.
    Thus, 
    both $Q_1 \setminus Q_2$ and
    $Q_2 \setminus Q_1$ are non-empty.
    It implies that $g(Q_1)$ and $g(Q_2)$ are distinct.

    We next show that $g$ is surjective.
    Let $Q'$ be an $S$-$T'$ hyperpath in $\mathcal P_{ST'}(\mathcal D')$.
    Since $Q'$ is an $S$-$T'$ hyperpath, any vertex in $T'$ is $B$-connected from $S$.
    Thus, $h_k$ is $B$-connected from $S$ in $\mathcal D[Q' \cup \set{A_k}]$ since $T_k \subseteq S \cup T'$.
    Moreover, any vertex in $\mathcal D[\set{A_k} \cup \bigcup_{B' \in Q'}f^{-1}(B')]$ is $B$-connected from $S$
    since any vertex in $T_k$ is $B$-connected from $S$ in $\mathcal D[\set{A_k} \cup \bigcup_{B' \in Q'}f^{-1}(B')]$.
    Finally, if $\set{A_k} \cup \bigcup_{B' \in Q'}f^{-1}(B')$ is not an $S$-$T$ hyperpath, then it contradicts the minimality of $Q'$.
    Therefore, $\set{A_k} \cup \bigcup_{B' \in Q'}f^{-1}(B')$ is an $S$-$T$ hyperpath in $\mathcal P^1_{ST}(\mathcal D, P_{ST}, A_k)$, and
    $g$ is surjective.
    % \qed
\end{proof}

