Our proposed reduction is presented on Fig.~\ref{fig::reduction}.

\begin{figure}[t!]
\begin{reduction}
Let $\tuple{S,A}$ be an ECI where $S = \{s_1,\dots,s_n\}$ and $A = \{A_1,\dots,A_k\}$.
Let $m = \sum_{i \in \{1,\dots,k\}}\ |A_i|$ be the number of elements in the subsets of $A$.
We define the PPI $\tuple{P,E,\tau}$ with $P = \tuple{\Omega, F, \pi}$ as follows:
\begin{itemize}
  \item $\Omega = W \cup X \cup Y \cup Z$ where
  \begin{itemize}
    \item $W = \{ W_0 \}$ is a singleton,
    \item $X = \{ X_0 \}$ is a singleton,
    \item $Y = \{ Y_{i,\ell} \mid i \in \{1,\dots,k\}, \ell \in \{1,\dots,n\} \textnormal{ such that } s_\ell \in A_i \}$ contains $m$ variables, and
    \item $Z = \{ Z_\ell \mid \ell \in \{1,\dots,n\} \}$ contains $n$ variables,
  \end{itemize}
  \item $F = \{F_1,\dots,F_k\}$ where $\forall i \in \{1,\dots,k\}$
  \begin{displaymath}
    F_i = \Omega \setminus \{Y_{i,\ell} \mid s_\ell \in A_i\} \setminus \{Z_{\ell} \mid s_\ell \in A_i\},
  \end{displaymath}
  \item $\pi$ satisfies 
  \begin{displaymath}    
  \pi = \left\{
    \begin{array}{ll}
    \pi(W_0) = \pi(X_0) = x, &\\
    \pi(Y_{i,\ell}) = y & i \in \{1,\dots,k\}, \ell \in \{1,\dots,n\} \textnormal{ such that } s_\ell \in A_i \\
    \pi(Z_\ell) = z & \ell \in \{1,\dots,n\},
    \end{array}
  \right.
\end{displaymath}
where
\begin{itemize}
  \item $x = \frac{1}{3}$,
  \item $y = \frac{1-2x}{m(1+2n)}$,
  \item $z = 2my %\frac{1-2x-my}{k}
  $, and
\end{itemize}
\item $E = W \cup Y$, and
\item $\tau = \frac{x + (m-n)y}{2x + (m-n)y}$.
\end{itemize}

Given a set $R \subseteq F$ of facts, we define the set $H_R \subseteq A$ of subsets by
\begin{displaymath}
  H_R = \{ A_i \mid \exists r \in R.\ \exists \ell \in \{1,\dots,n\}.\ s_\ell \in A_i \land Y_{i,\ell} \not\in r \}
\end{displaymath}
\end{reduction}
\caption{Reduction from \textsc{Exact Cover} to \textsc{Persuasion}.}
\label{fig::reduction}
\end{figure}

