\subsection{Properties of the reduction}

\begin{lemma}
  $\pi$ is a probability function over $\Omega$.
\end{lemma}

\begin{proof}
  We need to verify two properties: that the probability for each element in $\Omega$ is between $0$ and $1$,
  and that the probabilities add up to $1$.
  Remember that there are $m$ $Y$-variables and $n$ $Z$-variables. 

  \begin{enumerate}
    \item 
  Probabilities of $W_0$ and $X_0$ equal $1/3$ and are thus in $[0,1]$.
  Probability of a $Y$-variable is $(1-2x) / (m(1+2n)) = (1/3) / (m(1+2n))$;
  thus it is within $[0,1]$.
  Probability of a $Z$-variable is $z = 2my = 2m(1-2x)/(m(1+2n)) = 2(1-2x)/(1+2n) = (2/3)/(1+2n)$;
  thus it is within $[0,1]$.

  \item 
  The sum of probabilities is
  \begin{displaymath}
  \begin{split}
    \sum_{\omega \in \Omega} \pi(\omega)
    & = x+x+my+nz \\
    & = x+x + my + 2nmy \\
    & = x+x + (1+2n)my \\
    & = x+x + (1+2n)m\frac{1-2x}{m(1+2n)} \\
    & = x+x + (1-2x) \\ & = 1.
  \end{split}
  \end{displaymath}
  \end{enumerate}
\end{proof}

\begin{lemma}\label{lemma::0zvar}
  Any $R$ such that $\bigcap R$ contains one of more $Z$-variable satisfies $\prob{E}{R} < \tau$. 
\end{lemma}

\begin{proof}
  Let us assume that $\bigcap R$ contains at least one $Z$-variable.
  Let $m'$ and $n'$ be the number of $Y$-variables and $Z$-variables that appear
  in $\bigcap R$.
  Notice: $m' \in \{0,\dots,m\}$ and $n' \in \{1,\dots,n\}$.

  \begin{displaymath}
    \begin{split}
      \prob{E}{R} - \tau 
      & = \frac{x+m'y}{2x+m'y+n'z} - \tau\\
      & < \frac{x+my}{2x+z} - \tau \\
      & = \frac{x+my}{2x+z} - \frac{x + (m-n)y}{2x + (m-n)y}\\
      & \le \frac{x+my}{2x+z} - \frac{x}{2x}\\
      & = \frac{2x(x+my) - x(2x+z)}{2x(2x+z)}\\
      & = \frac{1}{2(2x+z)} (2(x+my) - (2x+z))\\
      & = \frac{1}{2(2x+z)} (2x+2my - 2x-z)\\
      & = \frac{1}{2(2x+z)} (2my -z)\\
      & = 0.
    \end{split}
  \end{displaymath}
  Thus, $\prob{E}{R}$ is strictly less than $\tau$.
\end{proof}

\begin{coro}\label{coro:yvars<}
  Any $R$ such that $\bigcap R$ contains strictly fewer than $(m-n)$ $Y$-variables satisfies $\prob{E}{R} < \tau$. 
\end{coro}

\begin{proof}
  Let $m'$ and $n'$ be the number of $Y$-variables and $Z$-variables that appear
  in $\bigcap R$.
  Assume $\prob{E}{R} = \tau$.
  From Lemma~\ref{lemma::0zvar}, we know $n'=0$.
  Thus, 
  \begin{displaymath}
    \begin{split}
      0 
      & = \prob{E}{R} - \tau \\
      & = \frac{x+m'y}{2x+m'y+n'z} - \tau \\
      & = \frac{x+m'y}{2x+m'y} - \tau\\
      & = \frac{x+m'y}{2x+m'y} - \frac{x + (m-n)y}{2x + (m-n)y},
    \end{split}
  \end{displaymath}
  Thus, $m' = m-n$.
\end{proof}

\begin{coro}\label{coro:yvars>}
  Any $R$ that satisfies $\prob{E}{R} \ge \tau$
  contains exactly $(m-n)$ $Y$-variables.
\end{coro}

\begin{proof}
  Assume $R$ is a solution to the PPI.
  From Lemma~\ref{lemma::0zvar}, we know that $\bigcap R$ contains no $Z$-variables,
  i.e., for each $\ell \in \{1,\dots,n\}$. there is $i \in \{1,\dots,k\}$,
  such that hold both $Z_i \not\in F_\ell$ and $F_\ell \in R$.
  But, by definition of the reduction,
  we also have $Y_{i,\ell} \not\in F_i$ and $Y_{i,\ell} \not\in \bigcap R$.
  In other words, for each $\ell \in \{1,\dots,n\}$,
  there is a different $Y$-variable not in $\bigcap R$,
  i.e., the number of $Y$-variables in $\bigcap R$ is at most $(m-n)$.
\end{proof}

%PREVIOUS LEMMA / COROLLARIES NEED TO PROVE:
%$\forall i. \exists! \ell.\ Y_{i,\ell} \in \Omega \setminus \bigcap R$

\begin{coro}\label{coro::exactcover}
  If $R$ is a solution to the PPI, then $H_R$ is a solution to the ECI.
\end{coro}

% WE ARE ASSUMING THAT NO $A_i$ IS EMPTY.

\begin{proof}
  Assume $R$ is a solution to the PPI.

  Firstly, let $\ell \in \{1,\dots,n\}$ be a universe index;
  from Lemma~\ref{lemma::0zvar}, we know that $\bigcap R$ does not contain $Z_\ell$. 
  Thus, looking at the subsets of $F$ that exclude $Z_\ell$,
  $R$ must contain a set $F_i$ ($i \in \{1,\dots,k\}$)
  such that $s_\ell \in A_i$.
  This $F_i$ also excludes $Y_{i,\ell}$.
  Thus, by definition of $H_R$, this $A_i$ belongs to $H_R$.
  Therefore, $\bigcup H_R$ includes $s_\ell$, and all elements in $S$.

  Secondly, 
  we just mentioned that for each index $\ell$, there is at least one variable $Y_{i,\ell}$ not in $\bigcap R$.
  Assume, by contradiction, that $H_R$ contains two different sets $A_i$ and $A_j$ that are not disjoint, 
  i.e., such that some universe index $\ell$ belongs to $A_i \cap A_j$.
  Then, both $Y_{i,\ell}$ and $Y_{j,\ell}$ are excluded by $\bigcap R$.
  However, this implies that $\bigcap R$ excludes at least $n+1$ $Y$-variables.
  This contradicts Corollary~\ref{coro:yvars>} which states 
  that $\bigcap R$ contains exactly $(m-n)$ $Y$-variables.
  Therefore all sets in $H_R$ are disjoint.

  In conclusion, $H_R$ is an exact cover of $S$.
\end{proof}

\begin{theo}
  \textsc{persuasion} is \textsc{np-hard}.
\end{theo}

\begin{proof}
  This is a consequence of Corollary~\ref{coro::exactcover}
  which showed that our reduction from \textsc{exact cover} to \textsc{persuasion} is correct.
\end{proof}

