		\section{Proof of Theorem 2.3}

		This proof is not original and is based on \cite{JKS08}, \cite{R15}, and  \cite{W07}. Additionally, we will make our constants explicit. Restating the theorem, we have: \\[0.5em]

		\hypertarget{A1}{}
		 \begin{customthm}{2.3}[Reduction of Indexing to Gap Hamming Distance with SR, Modified Version of {\cite[Lemma~5.3]{ACK15}}]
				Let $x$ be a random bitstring of length $\gamma = \frac{1}{\epsilon^{2}}$ and let $i$ be a random index in $\lbrack \gamma \rbrack.$ Choose $C\gamma$ public random bitstrings $r^{1}, \dotsc, r^{C \gamma}$ each of length $\gamma,$ where $C$ is a constant. Create $C\gamma$ length bitstrings $a, b$ as follows: 
				\begin{itemize}
				\item For each $j \in \lbrack C\gamma \rbrack,$ $a_{j} = \text{majority} \lbrace r_{k}^{j} \; | \; \text{indices } k \text{ for which } x_{k} = 1 \rbrace $
				\item For each $j \in \lbrack C\gamma \rbrack, b_{j} = r_{i}^{j}$ 
				\end{itemize}
				There is a procedure which with probability $\frac{1}{2} + \delta$ for some (fixed) constant $\delta \in (0, \frac{1}{2} \rbrack$ can determine the value of $x_{i}$ from any $d \sqrt{ C \gamma}-$additive approximation to $\Delta (a, b),$ provided $d \geq 0$ is a sufficiently small constant. 
		\end{customthm}

		\textit{Proof.} We will set $C = 9 \cdot \frac{1}{c^{2}}$ where $0 < c < \sqrt{\frac{2}{\pi}}.$ This will allow us to solve the indexing problem with probability $ \geq 1 - e^{-2} > \frac{5}{6}$ given a $d\sqrt{ \Delta (a, b)}$ additive approximation with $0 \leq d < \frac{1}{2}.$ The justification for these constants will be shown through the proof. Note that this analysis on the constants is probably not optimal but suffices for our results. \\[0.5em]

		Assume $r \sim \mu$ where $\mu$ is the uniform distribution on $\gamma$ length bitstrings. Define 
		$$a_{0} = \text{majority} \lbrace r_{k} \; | \; \text{indices } k \text{ for which } x_{k} = 1 \rbrace$$  

		where $a_{0} \in \lbrace 0, 1 \rbrace.$ Then we claim

		$$\text{Pr} \lbrack a_{0} \neq r_{i} \rbrack =  \begin{cases}
		 \geq \frac{1}{2} & \text{ if } x_{i} = 0 \\
		  \leq \frac{1}{2} - \frac{c}{\sqrt{\gamma}} &  \text{ if } x_{i} = 1
		\end{cases}$$

		To prove this, first let $\gamma$ be odd. Consider
		$$ S =  \lbrace r_{k} \; | \; \text{indices } k \text{ for which } x_{k} = 1, k \neq i \rbrace $$ 
		which corresponds to the set of bits in $r$ whose corresponding bits (at the same position) in $x$ are 1, excluding at position $i.$ Now we have two cases depending on the value of $x_{i}:$

		\begin{itemize}
		\item Case 1: $x_{i} = 0.$ If this is the case, then $a_{0}$ must just reduce to maj$(S).$ But maj$(S)$ is independent of $r_{i},$ so we have
			\begin{align*}
				Pr \lbrack a_{0} \neq r_{i} | x_{i} = 0 \rbrack &= Pr \lbrack \text{maj}(S) \neq r_{i} | x_{i} = 0 \rbrack \\
				& \geq \frac{1}{2}
			\end{align*}
		\item Case 2: $x_{i} = 1.$ We use the following lemma from \cite{W07} which states:
		\begin{lemma}[{\cite[Lemma~61]{W07}}]
		Let $m$ be a sufficiently large odd integer. There is a constant $0 < c < \sqrt{\frac{2}{\pi}}$ such that for i.i.d. Bernoulli(1/2) random variables $B_{1}, \dotsc, B_{m},$ for any $i, 1 \leq i \leq m,$
		$$ Pr \lbrack MAJ(B_{1}, \dotsc, B_{m}) = 1 \mid B_{i} = 1 \rbrack > \frac{1}{2} + \frac{c}{\sqrt{m}},$$
		where $MAJ(B_{1}, \dotsc, B_{m}) = 1$ iff the majority of the $B_{i}$ are 1. 
		\end{lemma}
		So applying this here we have, 
		\begin{align*}
		Pr \lbrack a_{0} = 1 \mid r_{i} = 1, x_{i} = 1 \rbrack > \frac{1}{2} + \frac{c}{\sqrt{
	\gamma}}
		\end{align*}
		which implies 
		$$Pr \lbrack a_{0} = 0 \mid r_{i} = 1, x_{i} = 1 \rbrack  < \frac{1}{2} - \frac{c}{\sqrt{\gamma}}$$
		and using symmetry and noting $r_{i}$ is 0 or 1 with probability $1/2$, we can conclude
		$$Pr \lbrack a_{0} \neq r_{i} | x_{i} = 1 \rbrack  < \frac{1}{2} - \frac{c}{\sqrt{\gamma}}$$
		\end{itemize}


		\begin{fact}[Hoeffding's Inequality]

		Let $X_{1}, X_{2}, \dotsc, X_{N}$ be $N$ i.i.d. 0-1 random variables and $X = \sum_{k=1}^{N} X_{k}.$ Then for $\nu \geq 0,$
		$$\text{Pr} \lbrack X - \mathbb{E} \lbrack X \rbrack > \nu \rbrack \leq e^{-2 \nu^{2}/N} 	 \text{ and }  	\text{Pr} \lbrack X - \mathbb{E} \lbrack X \rbrack < -\nu \rbrack \leq e^{-2 \nu^{2}/N} $$

		\end{fact}

		We choose $X_{k}$ to correspond to the indicator:

		$$ X_{k} =  \begin{cases}
				 1 & a_{k} \neq b_{k} \\
				  0 & a_{k} = b_{k}
				\end{cases}$$

		Now consider $X = \sum_{k=1}^{N} X_{k}.$ Note that this exactly encodes the random variable corresponding to $\Delta(a, b),$ where the choice of $b$ is dependent on a fixed $i \in \lbrack \gamma \rbrack.$ We can apply the Hoeffding bound by setting $N = 9 \cdot \gamma/c^{2}$ and $\nu = \sqrt{N}.$ This will break down into two cases:

		\begin{itemize}
		\item Suppose $x_{i} = 0.$ Then we have $\mathbb{E}\lbrack \Delta(a, b)  \rbrack = \mathbb{E} \lbrack X \rbrack \geq \frac{N}{2}$ and
		\begin{align*}
		Pr \lbrack \Delta(a, b)  < \frac{N}{2} - \sqrt{N} \rbrack &=  Pr \lbrack X - \frac{N}{2} < -\sqrt{N}\rbrack \\
		&\leq Pr \lbrack X - \mathbb{E} \lbrack X \rbrack < -\nu \rbrack \\
		&\leq e^{-2}
		\end{align*}
		\item Suppose $x_{i} = 1.$ Then we have $\mathbb{E} \lbrack \Delta(a, b) \rbrack = \mathbb{E} \lbrack X \rbrack \leq \frac{N}{2} - c \frac{N}{\sqrt{\gamma}}$ and

		\begin{align*}
		\frac{N}{2} - c\frac{N}{\sqrt{\gamma}} + \sqrt{N} &= \frac{N}{2} - c \cdot  9 \cdot \frac{\sqrt{ \gamma}}{c^{2}} + 3 \cdot \frac{\sqrt{\gamma}}{c} \\
		&= 	\frac{N}{2} - 6 \cdot \frac{\sqrt{\gamma}}{c^{2}} \\
		&= \frac{N}{2} - 2 \sqrt{N}
		\end{align*}

		which implies

		\begin{align*}
		Pr \lbrack \Delta(a, b)  > \frac{N}{2} - c\frac{N}{\sqrt{\gamma}} + \sqrt{N}  \rbrack &= Pr \lbrack X - (\frac{N}{2} - c\frac{N}{\sqrt{\gamma}}) > \sqrt{N}  \rbrack \\
		&\leq Pr \lbrack X - \mathbb{E} \lbrack X \rbrack > \nu \rbrack  \\
		&\leq e^{-2}
		\end{align*}
		\end{itemize} 


		Finally we can conclude that for any $i \in \lbrack \gamma \rbrack$ (which paramaterizes our choice of $b$), 


		 $$\begin{cases} 
		  Pr \lbrack \Delta(a, b) \geq \frac{N}{2} -\sqrt{N}  \rbrack \geq 1-e^{-2} > \frac{5}{6} & \text{if }x_{i} = 0 \\ 
		Pr \lbrack \Delta(a, b) \leq \frac{N}{2} - 2\sqrt{N}  \rbrack \geq 1-e^{-2} > \frac{5}{6} & \text{if } x_{i} = 1
		 \end{cases}$$

		 So knowing an estimate $E = \Delta(a, b) \pm d \sqrt{N}$ for $0 \leq d < \frac{1}{2}$ will allow us to discern the two cases with high probability since the gap between the two cases is $\sqrt{N}$.  \\[0.5em]

		 So all we need to do is test if our estimate E is greater than or less than $\frac{N}{2} - \frac{3}{2} \sqrt{N}$ and output $x_{i} = 0$ in the first case and $x_{i} = 1$ in the second case. This allows us to solve the indexing problem with probability greater than $1 - e^{-2} > \frac{5}{6}.$

