\subfloat[\label{fig:prob_changes_ours}]{\includegraphics[width=0.48\textwidth]{figs/log_prob_dynamics_sft.pdf}}\hfill
\caption{Visualization of Probability Mass Redistribution: (a) Average log-probability changes of \( \mathcal{D}_w \), \( \mathcal{D}_l \), and \( y^* \) over training steps under standard DPO; (b) Comparison of log-probability changes under SPO.}
\label{fig:thm2}
