\section{Proofs} \label{app:A}

\subsection{Proof of Theorem \ref{thm:prob_change}}\label{app:A.1}

First, the DPO loss function is defined as
\begin{equation}
\mathcal{L}_{\mathrm{DPO}}(\pi_\theta; \pi_{\mathrm{ref}}) = - \mathbb{E}_{(x, y_w, y_l) \sim \mathcal{D}} \left[ \log \sigma \left( \beta \log \frac{\pi_\theta(y_w|x)}{\pi_{\mathrm{ref}}(y_w|x)} - \beta \log \frac{\pi_\theta(y_l|x)}{\pi_{\mathrm{ref}}(y_l|x)} \right) \right].
\end{equation}
For a single preference triple \((x, y_w, y_l)\), the loss contribution is
\begin{equation}
\mathcal{L} = - \log \sigma(z),
\end{equation}
where \(z = \beta \left( \log \frac{\pi_\theta(y_w|x)}{\pi_{\mathrm{ref}}(y_w|x)} - \log \frac{\pi_\theta(y_l|x)}{\pi_{\mathrm{ref}}(y_l|x)} \right)\).

During gradient descent, the model parameters are updated as
\begin{equation}
\theta \leftarrow \theta - \eta \nabla_{\boldsymbol{\theta}} \mathcal{L},
\end{equation}
where \(\eta\) is the learning rate, and \(\nabla_{\boldsymbol{\theta}} \mathcal{L}_{\mathrm{DPO}}\) is the gradient of the DPO loss with respect to \(\theta\). Our goal is to compute the probability changes
\begin{equation}
\begin{aligned}
\Delta \pi_\theta(y_w|x) &= \pi_{\theta + \Delta \theta}(y_w|x) - \pi_\theta(y_w|x), \\
\Delta \pi_\theta(y_l|x) &= \pi_{\theta + \Delta \theta}(y_l|x) - \pi_\theta(y_l|x).
\end{aligned}
\end{equation}

Using a Taylor expansion at the current parameter point \(\theta\), we have
\begin{equation}
\begin{aligned}
\pi_{\theta + \Delta \theta}(y|x) &= \pi_\theta(y|x) + \nabla_{\boldsymbol{\theta}} \pi_\theta(y|x) \cdot \Delta \theta + \mathcal{O}(\|\Delta \theta\|^2) \\
&= \pi_\theta(y|x) + \nabla_{\boldsymbol{\theta}} \pi_\theta(y|x) \cdot \Delta \theta + \mathcal{O}(\eta ^2\|\nabla_{\boldsymbol{\theta}} \mathcal{L}\|^2). 
\end{aligned}
\end{equation}

Since the learning rate \(\eta\) is small, and gradient is usually bounded \citep{jentzen2020overallerroranalysistraining} and we also use gradient clipping \citep{zhao2022penalizing} in practical algorithms. Thus, we can ignore the second-order terms \(\mathcal{O}(\eta^2 \|\nabla_{\boldsymbol{\theta}} \mathcal{L}\|^2)\), which are typically on the order of \(10^{-10}\) (e.g., \(\eta = 10^{-5}\), \(\|\nabla_{\boldsymbol{\theta}} \mathcal{L}\| \approx 1\)) compared to the first-order term's order of \(10^{-5}\). Therefore, we have

\begin{equation}
\pi_{\theta + \Delta \theta}(y|x) \approx \pi_\theta(y|x) + \nabla_{\boldsymbol{\theta}} \pi_\theta(y|x) \cdot \Delta \theta.
\end{equation}
Thus, we can obtain
\begin{equation} \label{eq:delta_pi}
\Delta \pi_\theta(y|x) = \pi_{\theta + \Delta \theta}(y|x) - \pi_\theta(y|x) = \nabla_{\boldsymbol{\theta}} \pi_\theta(y|x) \cdot \Delta \theta.
\end{equation}
Since \(\nabla_{\boldsymbol{\theta}} \pi_\theta(y|x) = \pi_\theta(y|x) \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y|x)\), we get
\begin{equation}
\Delta \pi_\theta(y|x) = \pi_\theta(y|x) \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y|x) \cdot \Delta \theta.
\end{equation}
Next, we compute the gradient of the loss. For a single sample, the DPO loss is \(\mathcal{L} = - \log \sigma(z)\), and its gradient is
\begin{equation}
\nabla_{\boldsymbol{\theta}} \mathcal{L} = - \frac{1}{\sigma(z)} \cdot \sigma'(z) \cdot \nabla_{\boldsymbol{\theta}} z.
\end{equation}
The derivative of the sigmoid function is
\begin{equation}
\sigma'(z) = \sigma(z) (1 - \sigma(z)).
\end{equation}
Thus, we have
\begin{equation} \label{eq:loss_gradient}
\begin{aligned}
\nabla_{\boldsymbol{\theta}} \mathcal{L} &= - \frac{\sigma(z) (1 - \sigma(z))}{\sigma(z)} \cdot \nabla_{\boldsymbol{\theta}} z \\
&= - (1 - \sigma(z)) \cdot \nabla_{\boldsymbol{\theta}} z.
\end{aligned}
\end{equation}
Since \(z = \beta \left( \log \pi_\theta(y_w|x) - \log \pi_\theta(y_l|x) - \log \pi_{\mathrm{ref}}(y_w|x) + \log \pi_{\mathrm{ref}}(y_l|x) \right)\) and \(\pi_{\mathrm{ref}}\) is a fixed reference model, its log-probabilities do not depend on \(\theta\), so we have
\begin{equation}
\nabla_{\boldsymbol{\theta}} z = \beta \left( \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right).
\end{equation}
Substituting into the loss gradient in Eq. (\ref{eq:loss_gradient}), we obtain
\begin{equation}
\begin{aligned}
\nabla_{\boldsymbol{\theta}} \mathcal{L} &= - (1 - \sigma(z)) \cdot \beta \left( \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right) \\
&= - \beta (1 - \sigma(z)) \left( \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right).
\end{aligned}
\end{equation}

So the parameter update is
\begin{equation} \label{eq:delta_theta}
\begin{aligned}
\Delta \theta &= - \eta \nabla_{\boldsymbol{\theta}} \mathcal{L}_{\mathrm{DPO}} \\
&= \eta \mathbb{E}_{(x, y_w, y_l) \sim \mathcal{D}} \left[ \beta (1 - \sigma(z)) \left( \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right) \right].
\end{aligned}
\end{equation}
According to Eq. (\ref{eq:delta_pi}), for the preferred sample \(y_w\), the probability change is
\begin{equation}\label{eq:delta_pi_w}
\Delta \pi_\theta(y_w|x) \approx \pi_\theta(y_w|x) \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \Delta \theta.
\end{equation}
Combining with Eq. (\ref{eq:delta_theta}) and (\ref{eq:delta_pi_w}), we have
\begin{equation}
\begin{aligned}
\Delta \pi_\theta(y_w|x) &= \pi_\theta(y_w|x) \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \eta  \beta (1 - \sigma(z)) \left( \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right)\\
& = \eta \beta (1 - \sigma(z)) \pi_\theta(y_w|x) \left( \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\|^2 - \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right)
.
\end{aligned}
\end{equation}

For the dispreferred sample \(y_l\), the probability change is
\begin{equation}
\Delta \pi_\theta(y_l|x) \approx \pi_\theta(y_l|x) \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \cdot \Delta \theta.
\end{equation}

Following a similar logic, we can obtain
\begin{equation}
\begin{aligned}
\Delta \pi_\theta(y_l|x) &\approx \eta \beta (1 - \sigma(z)) \pi_\theta(y_l|x) \left( \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\|^2 \right).
\end{aligned}
\end{equation}
Since we are analyzing a single stochastic gradient step, we express the changes for the current sample
\begin{equation}
\begin{aligned}
\Delta \pi_\theta(y_w|x) &= \eta \beta (1 - \sigma(z)) \pi_\theta(y_w|x) \left( \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\|^2 - \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right), \\
\Delta \pi_\theta(y_l|x) &= \eta \beta (1 - \sigma(z)) \pi_\theta(y_l|x) \left( \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\|^2 \right).
\end{aligned}
\end{equation}
This completes the proof of Theorem \ref{thm:prob_change}.


\subsection{Proof of Corollary \ref{corollary:bound_on_probability_change}}\label{app:A.2}

According to Theorem \ref{thm:prob_change}, the probability change for the preferred sample \(y_w\) is given by
\begin{equation}
\begin{aligned}
\Delta \pi_\theta(y_w|x) = \eta \beta (1 - \sigma(z)) \pi_\theta(y_w|x) \left( \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\|^2 - \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right),
\end{aligned}
\end{equation}
where \(z = \beta \left( \log \frac{\pi_\theta(y_w|x)}{\pi_{\mathrm{ref}}(y_w|x)} - \log \frac{\pi_\theta(y_l|x)}{\pi_{\mathrm{ref}}(y_l|x)} \right)\).

By the Cauchy-Schwarz inequality, we have
\begin{equation}
\begin{aligned}
\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \leq \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\| \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\|.
\end{aligned}
\end{equation}
Thus:
\begin{equation}
\begin{aligned}
&\|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\|^2 - \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \\
&\geq \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\|^2 - \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\| \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\| \\
&= \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\| \left( \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\| - \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\| \right).
\end{aligned}
\end{equation}
Substituting this into the expression for \(\Delta \pi_\theta(y_w|x)\), we obtain
\begin{equation}
\begin{aligned}
\Delta \pi_\theta(y_w|x) &\geq \eta \beta (1 - \sigma(z)) \pi_\theta(y_w|x) \cdot \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\| \left( \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\| - \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\| \right).
\end{aligned}
\end{equation}
Similarly, for the dispreferred sample \(y_l\), Theorem \ref{thm:prob_change} gives
\begin{equation}
\begin{aligned}
\Delta \pi_\theta(y_l|x) = \eta \beta (1 - \sigma(z)) \pi_\theta(y_l|x) \left( \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\|^2 \right).
\end{aligned}
\end{equation}
Applying the Cauchy-Schwarz inequality again, we have
\begin{equation}
\begin{aligned}
\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \leq \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\| \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\|.
\end{aligned}
\end{equation}
Thus, we get
\begin{equation}
\begin{aligned}
&\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\|^2 \\
&\leq \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\| \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\| - \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\|^2 \\
&= \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\| \left( \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\| - \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\| \right).
\end{aligned}
\end{equation}
Substituting this into the expression for \(\Delta \pi_\theta(y_l|x)\), we obtain
\begin{equation}
\begin{aligned}
\Delta \pi_\theta(y_l|x) &\leq \eta \beta (1 - \sigma(z)) \pi_\theta(y_l|x) \cdot \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\| \left( \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\| - \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\| \right).
\end{aligned}
\end{equation}
This completes the proof of Corollary \ref{corollary:bound_on_probability_change}.


\subsection{Proof of Corollary \ref{corollary:relative_change}}\label{app:A.3}

According to Theorem \ref{thm:prob_change}, the probability changes for the preferred and dispreferred samples are given by
\begin{equation}
\begin{aligned}
\Delta \pi_\theta(y_w|x) &= \eta \beta (1 - \sigma(z)) \pi_\theta(y_w|x) \left( \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\|^2 - \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right), \\
\Delta \pi_\theta(y_l|x) &= \eta \beta (1 - \sigma(z)) \pi_\theta(y_l|x) \left( \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\|^2 \right),
\end{aligned}
\end{equation}
where \(z = \beta \left( \log \frac{\pi_\theta(y_w|x)}{\pi_{\mathrm{ref}}(y_w|x)} - \log \frac{\pi_\theta(y_l|x)}{\pi_{\mathrm{ref}}(y_l|x)} \right)\).

To derive the relative probability change, we first obtain
\begin{equation}
\begin{aligned}
&\Delta \pi_\theta(y_w|x) - \Delta \pi_\theta(y_l|x) \\
&= \eta \beta (1 - \sigma(z)) \Big[ \pi_\theta(y_w|x) \left( \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\|^2 - \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right) \\
&\quad - \pi_\theta(y_l|x) \left( \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\|^2 \right) \Big] \\
&= \eta \beta (1 - \sigma(z)) \Big[ \pi_\theta(y_w|x) \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\|^2 - \pi_\theta(y_w|x) \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \\
&\quad - \pi_\theta(y_l|x) \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) + \pi_\theta(y_l|x) \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\|^2 \Big].
\end{aligned}
\end{equation}
Next, we simplify the cross terms
\begin{equation}
\begin{aligned} \label{eq:simplified_cross_terms}
&\pi_\theta(y_w|x) \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) + \pi_\theta(y_l|x) \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \\
&= \left( \pi_\theta(y_w|x) + \pi_\theta(y_l|x) \right) \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x).
\end{aligned}
\end{equation}
By the AM-GM inequality, we have
\begin{equation}
\begin{aligned}\label{eq:am-gm}
\pi_\theta(y_w|x) + \pi_\theta(y_l|x) \geq 2 \sqrt{\pi_\theta(y_w|x) \pi_\theta(y_l|x)}.
\end{aligned}
\end{equation}
Thus, we get
\begin{equation}
\begin{aligned}
&\left( \pi_\theta(y_w|x) + \pi_\theta(y_l|x) \right) \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \\
&\geq 2 \sqrt{\pi_\theta(y_w|x) \pi_\theta(y_l|x)} \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x).
\end{aligned}
\end{equation}
Combining with Eq. (\ref{eq:simplified_cross_terms}) and (\ref{eq:am-gm}), we get
\begin{equation}
\begin{aligned}
&\Delta \pi_\theta(y_w|x) - \Delta \pi_\theta(y_l|x) \\
&\geq \eta \beta (1 - \sigma(z)) \Big[ \pi_\theta(y_w|x) \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\|^2 + \pi_\theta(y_l|x) \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\|^2 \\
&\quad - 2 \sqrt{\pi_\theta(y_w|x) \pi_\theta(y_l|x)} \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \Big].
\end{aligned}
\end{equation}
Notice that the expression inside the brackets can be rewritten as a squared norm
\begin{equation}
\begin{aligned}
&\pi_\theta(y_w|x) \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\|^2 - 2 \sqrt{\pi_\theta(y_w|x) \pi_\theta(y_l|x)} \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)  \\
&+ \pi_\theta(y_l|x) \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\|^2\\
&= \left\| \sqrt{\pi_\theta(y_w|x)} \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \sqrt{\pi_\theta(y_l|x)} \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right\|^2.
\end{aligned}
\end{equation}
Thus, we have
\begin{equation}
\begin{aligned}
\Delta \geq \eta \beta (1 - \sigma(z)) \left\| \sqrt{\pi_\theta(y_w|x)} \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \sqrt{\pi_\theta(y_l|x)} \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right\|^2,
\end{aligned}
\end{equation}
% Since \((1 - \sigma(z)) \geq 0\) and the squared norm is non-negative, the relative probability change is non-negative. For the expectation over the dataset, we write:
% \begin{equation}
% \begin{aligned}
% \Delta \pi_\theta(y_w|x) - \Delta \pi_\theta(y_l|x) \geq \eta \beta \mathbb{E}_{(x, y_w, y_l) \sim \mathcal{D}} \left[ (1 - \sigma(z)) \left\| \sqrt{\pi_\theta(y_w|x)} \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \sqrt{\pi_\theta(y_l|x)} \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right\|^2 \right].
% \end{aligned}
% \end{equation}
where \(\Delta \pi_\theta(y_w|x) - \Delta \pi_\theta(y_l|x)\). This completes the proof of Corollary \ref{corollary:relative_change}.


\subsection{Proof of Theorem \ref{thm:mass_shift}}\label{app:A.4}

Consider the output space \( \mathcal{Y} \) for input \( x \), with \( y_w \), \( y_l \), and \( y^* \) as the preferred, dispreferred, and next-highest probability outputs, respectively. The probability distribution satisfies
\begin{equation}
\pi_\theta(y_w|x) + \pi_\theta(y_l|x) + \pi_\theta(y^*|x) + \sum_{y \in \mathcal{Y} \setminus \{y_w, y_l, y^*\}} \pi_\theta(y|x) = 1.
\end{equation}
We analyze two cases: (1) preferred sample probability decreases; (2) dispreferred sample probability decreases.

\subsubsection{Case 1: Preferred Sample Probability Decreases}
Suppose \( \Delta \pi_\theta(y_w|x) < 0 \). By Theorem \ref{thm:prob_change}, the probability change is
\begin{equation}
\begin{aligned}
\Delta \pi_\theta(y_w|x) = \eta \beta (1 - \sigma(z)) \pi_\theta(y_w|x) \left( \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\|^2 - \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right),
\end{aligned}
\end{equation}
where \( z = \beta \left( \log \frac{\pi_\theta(y_w|x)}{\pi_{\mathrm{ref}}(y_w|x)} - \log \frac{\pi_\theta(y_l|x)}{\pi_{\mathrm{ref}}(y_l|x)} \right) \). For \( \Delta \pi_\theta(y_w|x) < 0 \), we require
\begin{equation}
\|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\|^2 < \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x).
\end{equation}
By Corollary \ref{corollary:bound_on_probability_change}, the dispreferred sample’s probability change satisfies
\begin{equation}
\begin{aligned}
\Delta \pi_\theta(y_l|x) \leq \eta \beta (1 - \sigma(z)) \pi_\theta(y_l|x) \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\| \left( \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\| - \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\| \right).
\end{aligned}
\end{equation}
If \( \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\| < \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\| \), then \( \Delta \pi_\theta(y_l|x) < 0 \). Even if this condition does not hold, Corollary \ref{corollary:relative_change} ensures
\begin{equation}
\Delta \pi_\theta(y_w|x) - \Delta \pi_\theta(y_l|x) \geq 0,
\end{equation}
implying \( \Delta \pi_\theta(y_l|x) \leq \Delta \pi_\theta(y_w|x) < 0 \), so \( \Delta \pi_\theta(y_l|x) \leq 0 \). By probability conservation, 
\begin{equation} \label{eq:prob_conservation}
\Delta \pi_\theta(y_w|x) + \Delta \pi_\theta(y_l|x) + \Delta \pi_\theta(y^*|x) + \sum_{y \in \mathcal{Y} \setminus \{y_w, y_l, y^*\}} \Delta \pi_\theta(y|x) = 0.
\end{equation}
Since \( \Delta \pi_\theta(y_w|x) < 0 \) and \( \Delta \pi_\theta(y_l|x) \leq 0 \), we have
\begin{equation}
\Delta \pi_\theta(y^*|x) + \sum_{y \in \mathcal{Y} \setminus \{y_w, y_l, y^*\}} \Delta \pi_\theta(y|x) = -(\Delta \pi_\theta(y_w|x) + \Delta \pi_\theta(y_l|x)) > 0.
\end{equation}
For any output \( y \in \mathcal{Y} \), Theorem \ref{thm:prob_change} gives
\begin{equation}
\begin{aligned}
\Delta \pi_\theta(y|x) =& \pi_\theta(y|x) \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y|x) \cdot \eta \beta (1 - \sigma(z)) \left( \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right) \\
=& \eta \beta (1 - \sigma(z)) \pi_\theta(y|x) \left( \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \right.\\
&\left. -\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right).
\end{aligned}
\end{equation}
For the remaining outputs, we have
\begin{equation}
\begin{aligned}
&\Delta \left[ \sum_{y \in \mathcal{Y} \setminus \{y_w, y_l, y^*\}} \pi_\theta(y|x) \right] = \eta \beta (1 - \sigma(z)) \cdot\\
&\sum_{y \in \mathcal{Y} \setminus \{y_w, y_l, y^*\}} \pi_\theta(y|x) \left( \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right).
\end{aligned}
\end{equation}
We assume \( \pi_\theta(y|x) \approx 0 \) for \(y \in \mathcal{Y} \setminus \{y_w, y_l, y^*\}\) and low gradient similarity with \( y_w \) and \( y_l \), and this is a reasonable assumption since \( y_w \) and \( y_l \) are the most probable outputs and we also use gradient clipping in practice algorithms. Thus, the changes for all other outputs are negligible. So we have
\begin{equation}
\Delta \pi_\theta(y^*|x) \approx -(\Delta \pi_\theta(y_w|x) + \Delta \pi_\theta(y_l|x)) > 0.
\end{equation}
Hence, probability mass primarily flows to \( y^* \).

\subsubsection{Case 2: Dispreferred Sample Probability Decreases}
Suppose \( \Delta \pi_\theta(y_l|x) < 0 \). By Theorem \ref{thm:prob_change}
\begin{equation}
\begin{aligned}
\Delta \pi_\theta(y_l|x) = \eta \beta (1 - \sigma(z)) \pi_\theta(y_l|x) \left( \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) - \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\|^2 \right).
\end{aligned}
\end{equation}
For \( \Delta \pi_\theta(y_l|x) < 0 \), we require
\begin{equation}
\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) < \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\|^2.
\end{equation}
From Eq.~\eqref{eq:prob_conservation}, we have
\begin{equation}
\Delta \pi_\theta(y_w|x) + \Delta \pi_\theta(y^*|x) + \sum_{y \in \mathcal{Y} \setminus \{y_w, y_l, y^*\}} \Delta \pi_\theta(y|x) = -\Delta \pi_\theta(y_l|x) > 0.
\end{equation}
Assuming \( \sum_{y \in \mathcal{Y} \setminus \{y_w, y_l, y^*\}} \Delta \pi_\theta(y|x) \approx 0 \), we get:
\begin{equation}
\Delta \pi_\theta(y_w|x) + \Delta \pi_\theta(y^*|x) \approx -\Delta \pi_\theta(y_l|x) > 0.
\end{equation}
The probability changes for \( y_w \) and \( y^* \) are:
\begin{equation}
\begin{aligned}
\Delta \pi_\theta(y_w|x) &= \eta \beta (1 - \sigma(z)) \pi_\theta(y_w|x) \left( \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\|^2 - \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right), \\
\Delta \pi_\theta(y^*|x) &= \eta \beta (1 - \sigma(z)) \pi_\theta(y^*|x) \left( \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y^*|x)\|^2 - \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y^*|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x) \right).
\end{aligned}
\end{equation}
The flow of probability mass depends on the initial probabilities \( \pi_\theta(y_w|x) \), \( \pi_\theta(y^*|x) \), and gradient similarities. If \( \pi_\theta(y_w|x) > \pi_\theta(y^*|x) \) and:
\begin{equation}
\|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\|^2 > \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x),
\end{equation}
then \( \Delta \pi_\theta(y_w|x) > 0 \), and probability mass primarily flows to \( y_w \). Otherwise, if \( \pi_\theta(y^*|x) > \pi_\theta(y_w|x) \) or the gradient similarity favors \( y^* \), then \( \Delta \pi_\theta(y^*|x) > 0 \).

This completes the proof of Theorem \ref{thm:mass_shift}.


\subsection{Derivation of Closed-Form Gradient}\label{app:A.5}

We derive the gradients of the optimization objective in Eq.~\eqref{eq:penalized_opt}, defined as
\begin{equation} \label{eq:objective}
\mathcal{L}(\boldsymbol{\theta}, \boldsymbol{\phi}) = \mathcal{L}_{\mathrm{dpo}}(\boldsymbol{\theta}, \boldsymbol{\phi}) + \lambda \left( \mathcal{L}_{\mathrm{sft}}(\boldsymbol{\theta}, \boldsymbol{\phi}) - \mathcal{L}_{\mathrm{sft}}^{*}(\boldsymbol{\theta}) \right) + \gamma \mathcal{L}_{\text{reg}}(\boldsymbol{\theta}, \boldsymbol{\phi}),
\end{equation}
where \(\mathcal{L}_{\mathrm{dpo}}(\boldsymbol{\theta}, \boldsymbol{\phi})\) is the DPO loss, \(\mathcal{L}_{\mathrm{sft}}(\boldsymbol{\theta}, \boldsymbol{\phi})\) is the SFT loss, \(\mathcal{L}_{\mathrm{sft}}^{*}(\boldsymbol{\theta}) = \min_{\boldsymbol{\phi}^{\prime} \in \Phi} \mathcal{L}_{\mathrm{sft}}(\boldsymbol{\theta}, \boldsymbol{\phi}^{\prime})\) is the optimal SFT loss for fixed \(\boldsymbol{\theta}\),  \(\mathcal{L}_{\text{reg}}=\max\left(0, 
                \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_l|x)\| 
                - \|\nabla_{\boldsymbol{\theta}} \log \pi_\theta(y_w|x)\|
            \right)\) is a regularization term according to Corollary ~\ref{corollary:bound_on_probability_change}, and \(\lambda > 0, \gamma > 0\) is a penalty coefficient.

For a single sample \((x, y_w, y_l) \in \mathcal{D}_{\mathrm{tr}}\), where \(y_w\) is the preferred response and \(y_l\) is the dispreferred response, and \((x, y_w) \in \mathcal{D}_{\mathrm{sft}}\), we next derive the closed-form gradients \(\nabla_{\boldsymbol{\theta}} \mathcal{L}\) and \(\nabla_{\boldsymbol{\phi}} \mathcal{L}\).

\subsubsection{Gradient with Respect to \(\boldsymbol{\theta}\)}
For the objective $\mathcal{L}(\boldsymbol{\theta}, \boldsymbol{\phi})$, the gradient is
\begin{equation} \label{eq:grad_theta}
\nabla_{\boldsymbol{\theta}} \mathcal{L} = \nabla_{\boldsymbol{\theta}} \mathcal{L}_{\mathrm{dpo}}(\boldsymbol{\theta}, \boldsymbol{\phi}) + \lambda \left( \nabla_{\boldsymbol{\theta}} \mathcal{L}_{\mathrm{sft}}(\boldsymbol{\theta}, \boldsymbol{\phi}) - \nabla_{\boldsymbol{\theta}} \mathcal{L}_{\mathrm{sft}}^{*}(\boldsymbol{\theta}) \right) + \gamma \nabla_{\boldsymbol{\theta}}\mathcal{L}_{\text{reg}}(\boldsymbol{\theta}, \boldsymbol{\phi}).
\end{equation}

\textbf{DPO Loss Gradient.}The DPO loss for a single sample is
\begin{equation}
\mathcal{L}_{\mathrm{dpo}}^{(x, y_w, y_l)}(\boldsymbol{\theta}, \boldsymbol{\phi}) = -\log \sigma(z),
\end{equation}
where \(z = \beta \left( \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x) - \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_l|x) - \log \pi_{\mathrm{ref}}(y_w|x) + \log \pi_{\mathrm{ref}}(y_l|x) \right)\). The gradient of \(\mathcal{L}_{\mathrm{dpo}}^{(x, y_w, y_l)}\) is
\begin{equation}
\nabla_{\boldsymbol{\theta}} \mathcal{L}_{\mathrm{dpo}}^{(x, y_w, y_l)} = -\frac{1}{\sigma(z)} \sigma'(z) \nabla_{\boldsymbol{\theta}} z.
\end{equation}
Since \(\sigma'(z) = \sigma(z)(1 - \sigma(z))\), we have
\begin{equation}
\nabla_{\boldsymbol{\theta}} \mathcal{L}_{\mathrm{dpo}}^{(x, y_w, y_l)} = -(1 - \sigma(z)) \nabla_{\boldsymbol{\theta}} z.
\end{equation}
Since \(
\nabla_{\boldsymbol{\theta}} z = \beta \left( \nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x) - \nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_l|x) \right)\) and \(\pi_{\mathrm{ref}}\) is independent of \(\boldsymbol{\theta}\). So we have
\begin{equation} \label{eq:dpo_grad_theta}
\nabla_{\boldsymbol{\theta}} \mathcal{L}_{\mathrm{dpo}}^{(x, y_w, y_l)} = -\beta (1 - \sigma(z)) \left( \nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x) - \nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_l|x) \right).
\end{equation}

\textbf{SFT Loss Gradient.} The SFT loss for a single sample is
\begin{equation}
\mathcal{L}_{\mathrm{sft}}^{(x, y_w)}(\boldsymbol{\theta}, \boldsymbol{\phi}) = -\log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x).
\end{equation}
The gradient is
\begin{equation} \label{eq:sft_grad_theta}
\nabla_{\boldsymbol{\theta}} \mathcal{L}_{\mathrm{sft}}^{(x, y_w)} = -\nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x).
\end{equation}

\textbf{Optimal SFT Loss Gradient.} The optimal SFT loss is
\begin{equation}
\mathcal{L}_{\mathrm{sft}}^{*}(\boldsymbol{\theta}) = \mathcal{L}_{\mathrm{sft}}(\boldsymbol{\theta}, \boldsymbol{\phi}^{*}(\boldsymbol{\theta})),
\end{equation}
where \(\boldsymbol{\phi}^{*}(\boldsymbol{\theta}) = \arg\min_{\boldsymbol{\phi}^{\prime} \in \Phi} \mathcal{L}_{\mathrm{sft}}(\boldsymbol{\theta}, \boldsymbol{\phi}^{\prime})\). This gradient is dependent on the optimal of the low level optimization problem, 
According to ~\citep{nouiehed2019solving} Lemma A.5, the optimal SFT loss gradient be evaluated directly at any optimal solution of the lower-level optimization problem under some mild assumption. Based on this, we have
\begin{equation}
\nabla_{\boldsymbol{\theta}} \mathcal{L}_{\mathrm{sft}}^{*}(\boldsymbol{\theta}) = \nabla_{\boldsymbol{\theta}} \mathcal{L}_{\mathrm{sft}}(\boldsymbol{\theta}, \boldsymbol{\phi}^{*}(\boldsymbol{\theta})) = -\nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}^{*}(\boldsymbol{\theta})}(y_w|x)\approx-\nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}^{(K)}(\boldsymbol{\theta})}(y_w|x), 
\end{equation}

where $K$ is the approximate solution of the lower-level optimization problem obtained after K-step gradient descent.

Combining these into Eq.~\eqref{eq:grad_theta}:
\begin{equation}
\begin{aligned}
\nabla_{\boldsymbol{\theta}} \mathcal{L} &= -\beta (1 - \sigma(z)) \left( \nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x) - \nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_l|x) \right) \\
&\quad - \lambda \left( \nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x) - \nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}^{*}(\boldsymbol{\theta})}(y_w|x) \right).
\end{aligned}
\end{equation}

\textbf{Regularization Loss Gradient.} The regularization term for a single sample is:
\begin{equation}
\mathcal{L}_{\text{reg}}^{(x, y_w, y_l)}(\boldsymbol{\theta}, \boldsymbol{\phi}) = \max\left(0, \|\nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_l|x)\| - \|\nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x)\|\right).
\end{equation}
Define \(\delta = \|\nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_l|x)\| - \|\nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x)\|\). The term \(\max(0, \delta)\) is non-differentiable at \(\delta = 0\), but we can use the subgradient. The subgradient of \(\mathcal{L}_{\text{reg}}^{(x, y_w, y_l)}\) with respect to \(\boldsymbol{\theta}\) is:
\begin{equation}
\nabla_{\boldsymbol{\theta}} \mathcal{L}_{\text{reg}}^{(x, y_w, y_l)} =
\begin{cases}
\nabla_{\boldsymbol{\theta}} \left( \|\nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_l|x)\| - \|\nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x)\| \right) & \text{if } \delta > 0, \\
0 & \text{if } \delta \leq 0.
\end{cases}
\end{equation}
For \(\delta > 0\), we compute:
\begin{equation}
\begin{aligned}
\nabla_{\boldsymbol{\theta}} \|\nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y|x)\| &= \nabla_{\boldsymbol{\theta}} \left( \left( \nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y|x) \right)^{1/2} \right) \\
&= \frac{1}{2 \|\nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y|x)\|} \nabla_{\boldsymbol{\theta}} \left( \nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y|x) \cdot \nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y|x) \right) \\
&= \frac{1}{\|\nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y|x)\|} \left( \nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y|x) \cdot \nabla_{\boldsymbol{\theta}}^2 \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y|x) \right).
\end{aligned}
\end{equation}
The term \(\nabla_{\boldsymbol{\theta}}^2 \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y|x)\) is the Hessian of \(\log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y|x)\), which is complex to compute directly. Thus, we have
\begin{equation}
\resizebox{0.99\textwidth}{!}{$
\begin{aligned} \label{eq:reg_grad_theta}
\nabla_{\boldsymbol{\theta}} \mathcal{L}_{\text{reg}}^{(x, y_w, y_l)} \approx
\begin{cases}
\frac{\nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_l|x) \cdot \nabla_{\boldsymbol{\theta}}^2 \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_l|x)}{\|\nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_l|x)\|} - \frac{\nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x) \cdot \nabla_{\boldsymbol{\theta}}^2 \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x)}{\|\nabla_{\boldsymbol{\theta}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x)\|} & \text{if } \delta > 0, \\
0 & \text{if } \delta \leq 0.
\end{cases}
\end{aligned}
$}
\end{equation}

\subsubsection{Gradient with Respect to \(\boldsymbol{\phi}\)}
The gradient is
\begin{equation} \label{eq:grad_phi}
\nabla_{\boldsymbol{\phi}} \mathcal{L} = \nabla_{\boldsymbol{\phi}} \mathcal{L}_{\mathrm{dpo}}(\boldsymbol{\theta}, \boldsymbol{\phi}) + \lambda \nabla_{\boldsymbol{\phi}} \mathcal{L}_{\mathrm{sft}}(\boldsymbol{\theta}, \boldsymbol{\phi}) + \gamma \nabla_{\boldsymbol{\theta}}\mathcal{L}_{\text{reg}}(\boldsymbol{\theta}, \boldsymbol{\phi}),
\end{equation}
since \(\mathcal{L}_{\mathrm{sft}}^{*}(\boldsymbol{\theta})\) is independent of \(\boldsymbol{\phi}\), so \(\nabla_{\boldsymbol{\phi}} \mathcal{L}_{\mathrm{sft}}^{*}(\boldsymbol{\theta}) = 0\).

\textbf{DPO Loss Gradient.} Similarly to the \(\boldsymbol{\theta}\) case, we have
\begin{equation} \label{eq:dpo_grad_phi}
\nabla_{\boldsymbol{\phi}} \mathcal{L}_{\mathrm{dpo}}^{(x, y_w, y_l)} = -\beta (1 - \sigma(z)) \left( \nabla_{\boldsymbol{\phi}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x) - \nabla_{\boldsymbol{\phi}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_l|x) \right).
\end{equation}

\textbf{SFT Loss Gradient.} The SFT loss gradient is
\begin{equation} \label{eq:sft_grad_phi}
\nabla_{\boldsymbol{\phi}} \mathcal{L}_{\mathrm{sft}}^{(x, y_w)} = -\nabla_{\boldsymbol{\phi}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x).
\end{equation}

\textbf{Regularization Loss Gradient.} Similarly to the \(\boldsymbol{\phi}\) case, we have

\begin{equation}
\resizebox{0.99\textwidth}{!}{$
\begin{aligned} \label{eq:reg_grad_phi}
\nabla_{\boldsymbol{\phi}} \mathcal{L}_{\text{reg}}^{(x, y_w, y_l)} \approx
\begin{cases}
\frac{\nabla_{\boldsymbol{\phi}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_l|x) \cdot \nabla_{\boldsymbol{\phi}}^2 \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_l|x)}{\|\nabla_{\boldsymbol{\phi}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_l|x)\|} - \frac{\nabla_{\boldsymbol{\phi}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x) \cdot \nabla_{\boldsymbol{\phi}}^2 \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x)}{\|\nabla_{\boldsymbol{\phi}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x)\|} & \text{if } \delta > 0, \\
0 & \text{if } \delta \leq 0.
\end{cases}
\end{aligned}
$}
\end{equation}

Combining these with Eq.~\eqref{eq:grad_phi}, we can obtain
\begin{equation}
\begin{aligned}
\nabla_{\boldsymbol{\phi}} \mathcal{L} &= -\beta (1 - \sigma(z)) \left( \nabla_{\boldsymbol{\phi}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x) - \nabla_{\boldsymbol{\phi}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_l|x) \right)\\ 
&- \lambda \nabla_{\boldsymbol{\phi}} \log \pi_{\boldsymbol{\theta},\boldsymbol{\phi}}(y_w|x) + \gamma \nabla_{\boldsymbol{\theta}}\mathcal{L}_{\text{reg}}(\boldsymbol{\theta}, \boldsymbol{\phi}).
\end{aligned}
\end{equation}

This completes the derivation of the closed-form gradients.

