\section{Introduction}\label{sec:intro}
The Ore-DeMillo-Lipton-Schwartz-Zippel (ODLSZ) \cite{ore1922hohere, DL78,Zippel79,Schwartz80} lemma captures the basic algebraic fact that a low-degree polynomial does not have many roots on a ``nice set'' of points. The standard nice set for this lemma is a grid $S^n$ (where $S$ is a finite subset of a field) and a version of this lemma states that no non-zero degree-$d$ polynomial can vanish on more that $d |S|^{n-1}$ points. This is easily seen to be tight: Take, for example, a univariate polynomial that has $d$ roots in $S$.

There also exist useful variants of this lemma for the case where $|S| < d.$ The example above shows that in general a degree-$d$ polynomial can vanish over all of $S^n$ and so some further condition is necessary. The most obvious condition is to simply force the polynomial to be non-zero on the grid $S^n.$ In the setting of the Boolean cube, i.e. $S = \{0,1\}$, which is the setting we study, this is equivalent to considering non-zero \emph{multilinear} polynomials of degree $d.$ In this setting (a variant of) the ODLSZ lemma states that a non-zero multilinear polynomial of degree $d$ is non-zero on at least $2^{n-d}$ points of $\{0,1\}^n.$ Again, this is tight: Take, e.g., a multilinear monomial of degree $
d.$

Though both these forms of the ODLSZ lemma are simple statements with easy inductive proofs, they have many different applications in the design of randomized algorithms \cite{Rabin-Vazirani-Matching}, probabilistically checkable proofs~\cite{BFLS, ALMSS}, pseudorandom constructions~\cite{DKSS, GRS-codingbook}, Boolean function analysis \cite{Nisan-Szegedy}, data communication~\cite{ABCO}, small-depth circuit lower bounds ~\cite{PaturiSaks, HRRY-threshold} and extremal combinatorics \cite{Saraf-Sudan}.

In this paper, we extend the ODLSZ lemma to a different nice set namely the \emph{Boolean slice}, which is an important subset of the Boolean cube $\{0,1\}^n$. For a parameter $k$, we use $\{0,1\}^n_k$ to denote the $k$th Boolean slice, i.e., the set of points in the cube of Hamming weight exactly $k$. The behavior of low-degree polynomials on Boolean slices has received quite a bit of attention recently with motivations from learning theory \cite{OW}, Boolean function analysis \cite{Wimmer, Filmus2014AnOB, FilmusKMW, Filmus-Ihringer19}, property testing~\cite{DDGKS17, KLMZ}, circuit lower bounds \cite{HRRY-threshold}, and local decoding algorithms \cite{ABPSS25-ECCC}. However, as far as we know, the natural question of finding a tight version of the ODLSZ lemma over Boolean slices has not been considered before. This is the question we address in this paper. 

More precisely, we consider the following question: 
\begin{center}
    \textcolor{red}{\textit{Given a polynomial $P$ of degree at most $d$ that does not vanish on $\{0,1\}^n_k$, how many zeroes can have $P$ have in this set?}}
\end{center}
This question makes sense when $d\leq t:= \min\{k,n-k\}$, since any function on $\{0,1\}^n_k$ can be expressed as a polynomial of degree $t.$

We give a near-optimal answer to this question for low-degree polynomials. More precisely, our main theorem is stated below. It holds for polynomials over any field and even in the case where the coefficients come from an \emph{Abelian group}\footnote{A multilinear polynomial over an Abelian group $G$ is of the form $\sum_{S\subseteq [n]} a_S \prod_{i\in S}x_i $ where $a_S\in G$ for each $S.$ Polynomials over such domains appear naturally in applications to circuit complexity~\cite{ACC-Torus-Learning} and additive combinatorics~\cite{TZ}.} (as is also true of the standard version of ODLSZ lemma over the Boolean cube).

\begin{thmbox}
\begin{restatable}[Main Theorem]{theorem}{mainthm}\label{thm:main}
There exists an absolute constant $\varepsilon>0$ so that the following holds. Fix an arbitrary Abelian group $G$ and a degree parameter $d \in \mathbb{N}$. For all natural numbers $n$ and $k$ such that $d\le k \leq n-d$, the following holds whenever $d \leq t^{\varepsilon}$ where $t = \min\{k,n-k\}$:\newline
For any degree-$d$ polynomial $P: \Boo^{n}_{k} \to G$ that does not vanish on $\{0,1\}^n_k$, we have
\begin{align*}
    \Pr_{\mathbf{x} \sim \Boo^{n}_{k}}[P(\mathbf{x}) \neq 0] \; \geq \; \bigg(\dfrac{t}{n}\bigg)^{d} \cdot \paren{1-\dfrac{1}{t^{\varepsilon}}}.
\end{align*}
\end{restatable}
\end{thmbox}
We prove \Cref{thm:main} in \Cref{ssec:general-proof}.\newline
At a high level, the uniform distribution on $\Boo^{n}_{k}$ is similar to the $(k/n)$-biased distribution, i.e. the distribution where each coordinate is independently $1$ with probability $k/n$. With slight modifications to the proof of ODLSZ lemma, one can show (see for example  \cite[Claim 6.8]{Dinur2017Agreement}) that the probability  of sampling a non-zero point from $(k/n)$-biased distribution is $(t/n)^{d}$, where $t = \min\set{k, n-k}$. The bound given by \Cref{thm:main} is equal to this bound up to small error terms.



\paragraph{Tightness.} The bound given is easily seen to be nearly tight using essentially the same example as in the case of the Boolean cube. For $k\leq n/2$, the monomial $x_1\cdots x_d$ is non-zero with probability approximately $(k/n)^d$, and there is a similar example for $k > n/2.$ Moreover, it is also possible to see that for certain $k$, an error term is required. For example, assume that $G$ is the finite field $\F_2$, $k=n/2$ and $d=1.$ Then the linear polynomial $x_1+x_2+1$ is non-zero with probability $1/2 - \Theta(1/n)$, implying that the monomial does not yield exactly the optimal bound. In the case that the degree $d=1$, we can improve the error parameter and show a bound of $t/n - 1/n$ (\Cref{thm:deg1} in \Cref{sec:deg1}).



\paragraph{Proof Techniques.} The standard proofs of the ODLSZ lemma follow a simple inductive strategy, using the obvious univariate case for both the base case and each inductive step of the argument. The recent work of Amireddy, Behera, Paraashar, Srinivasan and Sudan~\cite{ABPSS25-ECCC} used a similar idea to show the following sub-optimal bound. Unfortunately, it is not clear how to make the inductive strategy work for the slice to get a tight answer.\\


\begin{lemma}[Suboptimal distance lemma for slices]\label{lemma:suboptimal-DLSZ-slice}
\cite[Lemma 5.1.6]{ABPSS25-ECCC}. For every Abelian group $G$ and non-negative integers $d,k,n$ with $n \geq 1$ and $d\le k \leq n-d$ the following holds: 
%and a degree parameter $d \in \mathbb{N}$. For all natural numbers $n,k$ such that $d\le k \leq (n-d)$, the following holds.\newline
For every degree-$d$ polynomial $P: \Boo^{n}_{k} \to G$ that does not vanish on $\{0,1\}^n_k$, we have
\begin{align*}
\Pr_{{\bf x}\sim \{0,1\}^n_k}[P(\mathbf{x}) \neq 0] \geq \binom{n-2d}{k-d}\bigg /{n\choose k}.
\end{align*}
In particular, for $k=n/2$ (for an even $n$), the above probability is at least $4^{-d}$.
\end{lemma}

A computation shows that for small $d$, the above implies that the fraction of points in $\{0,1\}^n_k$ where $P$ does not vanish is at least $((k/n)\cdot (1-(k/n)))^d$ (up to small error terms). When $k = n/2$, for example, this bound is $4^{-d}$ which is quadratically worse than \Cref{thm:main}.


To get the tight bound, we use a very different approach. We start with the above suboptimal bound, but combine it with spectral techniques, which we elaborate on next. Note that if the slice $k = n/2$, i.e. the balanced slice, then we get a bound of nearly $1/2^{d}$ which is essentially the same as the ODLSZ lemma over the Boolean cube $\Boo^{n}$ (\Cref{thm:DLSZ}). %The key lemma in our proof is to show a lower bound of nearly $1/2^{d}$ for balanced slices (see \Cref{lemma:balanced-slice}). 
To prove this, the high-level idea is to consider the process of choosing a random subcube in the balanced Boolean slice $\Boo^{n}_{n/2}$ as follows: pair the $n$ coordinates into $n/2$ pairs uniformly at random, and in each such pair $\{x_i,x_j\}$, identify $x_i$ with the Boolean negation of $x_j$, i.e. $1-x_j.$ This gives us a random embedding of an $n/2$-dimensional cube in the slice $\Boo^{n}_{n/2}$ and the polynomial $P$ restricts to a degree-$d$ polynomial $Q$ on this subcube. If we could guarantee that $Q$ was always non-zero, then the standard ODLSZ lemma on the cube would give us the desired statement. Unfortunately, there are subcubes on which $P$ could be identically zero. The main technical lemma is to show that $Q$ is non-zero with high probability: intuitively, this is because the random process above is a good \emph{\underline{sampler}} of the balanced slice, i.e. the points in the randomly chosen subcube behave essentially like independent samples of the balanced slice.

Formally, the technical lemma is a statement about the approximate pairwise independence of two random points of the chosen subcube. We show (see \Cref{lemma:main-informal}) that the probability that two random points of this subcube lie in a set of density $\rho$ is roughly $\rho^2.$ This is done by analyzing a natural weighted graph $\Gamma$ on the balanced slice defined by the above sampling process. We show this via two arguments, depending on the regime of the degree parameter $d$.

%first describe a random process $\Gamma$ that randomly maps a balanced point to another balanced point. Loosely speaking, $\Gamma$ randomly pairs up the $0$ and $1$ coordinates of a balanced point and flips both the coordinates in a random number of pairs. A similar idea was used in \cite{ABPSS25-ECCC} to understand the behavior of low-degree polynomials on the slice under random restrictions. The main technical argument in our work is to show that the random process $\Gamma$ is good \emph{\underline{sampler}} for the balanced slice $\Boo^{n}_{n/2}$ (see \Cref{lemma:main-informal}). We show this via two arguments, depending on the regime of the degree $d$.

For $d \leq C \log n$ for a constant $C > 0$, the main technical lemma follows from the use of the Expander mixing lemma \cite{Alon-Chung-EML}, which implies such a statement using bounds on the second-largest eigenvalue of the graph. To analyze the second-largest eigenvalue of $\Gamma$, we show that it can be embedded (as an induced subgraph) in a Cayley graph defined on the subgroup of $\F_2^n$ defined by points of even Hamming weight. The latter is easier to analyze using Boolean Fourier analysis, and an application of the eigenvalue interlacing theorem allows us to bound the eigenvalues of $\Gamma$. See \Cref{subsec:simple-proof-cayley} for more details. This easier case of the lemma is already interesting: for instance, it yields a different (arguably easier) proof of a junta theorem on the Boolean slice \cite{Filmus-Ihringer19}, analogous to a well-known theorem of Nisan and Szegedy \cite{Nisan-Szegedy}.

For $d = n^{\gamma}$ for a small constant $\gamma > 0$, we need to strengthen the guarantee of the sampler. To do so, we use the fact that the adjacency matrix for $\Gamma$ can be spectrally upper-bounded by another matrix\footnote{The technically accurate descriptor for this matrix is the `Noise operator in the Bose-Mesner algebra of the Johnson scheme.' See \Cref{sec:bal-slice} for details.} that satisfies a \emph{Hypercontractive inequality} (see \Cref{lemma:hypercontractive-log-Sobolev}). Intuitively, this is stronger than an eigenvalue bound, as the latter measures only the worst-case expansion of the underlying graph, while the former gives us stronger bounds on the expansion of smaller sets. Using this inequality alongside the Expander mixing lemma yields the desired pairwise independence. See \Cref{subsec:proof-johnson-scheme} for more details.

%and this shows that $\Gamma$ is a good sampler. 


% . We find a new natural application of this idea, namely to prove the main theorem for the balanced slice i.e. the case $k = n/2$ (see \Cref{lemma:balanced-slice}). Note that the lower bound from \Cref{thm:main} in this case is approximately $2^{-d}$ i.e. essentially the same as the ODLSZ lemma over the Boolean cube. To prove this, we start by embedding a random copy of the $n/2$-dimensional cube inside $\{0,1\}^n_{n/2}.$ The main technical argument uses spectral techniques to show that this is a good \emph{sampler} (see \Cref{sec:sampler-balanced}), implying (using the sub-optimal lemma above) that the polynomial remains non-zero on this random cube with high probability. The standard version of the ODLSZ lemma over the Boolean cube now implies the required bound.

For imbalanced slices, i.e. $k \neq n/2$, we reduce to the balanced case via a random restriction idea (see \Cref{sec:all-slices}). The main conceptual idea is to obtain a basis for the space of polynomial functions on a slice. We note, essentially using an argument of Wilson \cite{WILSON90}, that for many distinct slices, the space of homogeneous multilinear monomials of degree $d$ forms a basis for the space of polynomials of degree $d$ on the slice (see \Cref{claim:homogeneous-spanning-positive-char}). Unlike other known bases for this space~\cite{Filmus2014AnOB}, this idea also works over fields of positive characteristic and even over cyclic groups of prime power order. For such `good' slices $k\leq n/2$, we reduce to a $2k$-dimensional cube via a random restriction (see \Cref{lemma:good-slice-positive-char}), which can easily be seen to leave the polynomial non-zero with probability $(2k/n)^d.$ Invoking the balanced case now concludes the lemma for the good slices.

Finally, to extend the main theorem to all slices, we note that for any slice $k$, there is a good slice not too `far away' (in the range $[k-\bigO(d),k]$) (see \Cref{lem:all-slices}). By setting a few variables at random to $1,$ we are able to reduce to a good slice.


\paragraph{Related Work.} As mentioned above, the study of low-degree polynomials over Boolean slices has received much attention in recent years. Closely related to this work is the work of Filmus~\cite{Filmus2014AnOB} that constructs a basis for the space of real-valued degree-$d$ polynomial functions over general Boolean slices. A recent result of Kalai, Lifshitz, Minzer and Ziegler \cite{KLMZ} constructs a \emph{dense model} for the balanced slice $\{0,1\}^n_{n/2}$ under the Gowers norm $U_d$; in particular, this implies that there is a subset $S$ of $\{0,1\}^n$ of constant density such that any polynomial of degree-$d$ has the same density over $S$ as it does over the balanced slice. In principle, both these works should be useful in order to prove a version of the ODLSZ lemma over Boolean slices. However, we note that each of these results is applicable over different domains ($\mathbb{R}$ or $\F_2$) while we prove a unified statement that holds over any Abelian group (and in particular over all fields).


\subsection{Applications of Optimal Distance Lemma}

To give some idea of the applicability of the ODLSZ lemma over the slice, we prove some variants of well-known theorems in combinatorics and Boolean function analysis.

\paragraph{Hyperplane covering.} Given a subset $S$ of the cube $\{0,1\}^n,$ we define the \emph{exact cover number of $S$}, denoted $\mathrm{ec}_n(S)$ to be the minimum number of hyperplanes (over some field $\F$) such that their union intersects $\{0,1\}^n$ exactly in the set $S$. A classical result of Alon and F\"{u}redi shows that for $S$ being the cube with a single point removed, $\mathrm{ec}_n(S) = n.$ This combinatorial result, which easily follows from with ODLSZ lemma over the cube, has seen many subsequent generalizations (e.g. \cite{Clifton-Huang,Sauermann-Wigderson-hyperplance-multiplicities, Bishnoi-hyperplance-subspace}).

% Consider the following combinatorial problem:\newline
% \textit{For a $n$-dimension Boolean hypercube $\Boo^{n}$, how many hyperplanes are required such that every point in $\Boo^{n}$ except $\mathbf{0}$ lies on at least one of the hyperplanes?}

% \paragraph{}The above problem is known as the \textit{hyperplane covering problem} and variants of it have been studied for more than two decades. It is easy to convince oneself that $n$ hyperplanes suffice, namely the collection of hyperplanes $\set{\set{x_{1} = 1}, \ldots, \set{x_{n} = 1}}$. In an elegant use of the polynomial method, Alon and F{\"u}redi \cite{Alon-Furedi} showed that at least $n$ hyperplanes are required to cover every non-zero point in the hypercube, which is an optimal lower bound as there is an upper bound of $n$ hyperplanes. In finite geometry, generalization of hyperplance covering is studied in relation to blocking number \cite{Jamison, Brouwer-Schrijver}. Recently, \cite{Sauermann-Wigderson-hyperplance-multiplicities, Bishnoi-hyperplance-subspace} have also studied the multiplicity version of the hyperplane covering, where there is additional constraint on vanishing with multiplicities on all but one point in the hypercube $\Boo^{n}$.

Using just the sub-optimal version of the ODLSZ lemma (\Cref{lemma:suboptimal-DLSZ-slice}), we immediately get an optimal version of the hyperplane covering over a Boolean slice $\Boo^{n}_{k}$ with a missing point, instead of the whole Boolean cube $\Boo^{n}$. More precisely, for $S\subseteq \{0,1\}^n_k$, let $\mathrm{ec}_{n,k}(S)$ be the minimum number of hyperplanes (over some fixed field $\F$) such that their union intersects $\{0,1\}^n_k$ exactly in the set $S$. Following the idea of~\cite{Alon-Furedi}, we have the following.


\begin{thmbox}
\begin{restatable}{theorem}{hyperplaneslices}\label{thm:hyperplanes-slices}
Let $n,k$ be natural numbers with $k \in [n]$. Fix an arbitrary point $\mathbf{a} \in \Boo^{n}_{k}$. Then $\mathrm{ec}_{n,k}(\{0,1\}^n_k \setminus \{\mathbf{a}\}) = \min\{k,n-k\}.$
\end{restatable}
\end{thmbox}



\begin{proof}[Proof of \Cref{thm:hyperplanes-slices}]
Without loss of generality, we assume that $k \leq n/2$ and $\mathbf{a} = 1^{k} 0^{n-k}.$ Let $S$ denote $\{0,1\}^n_k \setminus \{\mathbf{a}\}.$

It is easy to see that $\mathrm{ec}_{n,k}(S) \leq k.$ The hyperplanes $H_{i} = \set{x_{i} = 0}$ for $i \in [k]$ cover exactly the points in $S.$

For the lower bound, assume for the sake of contradiction that there exists $m < k$ hyperplanes $H_{i} = \set{\ell_{i}(\mathbf{x}) = 0}$ (here $\ell_{i}(\mathbf{x})$ denotes a degree-$1$ polynomial and $i\in [m]$) 
covering exactly the points in $S.$
Then the polynomial $P(\mathbf{x}) := \prod_{i=1}^m \ell_i(\mathbf{x})$ is non-zero at exactly one point of $\{0,1\}^n_k$.

However, by \Cref{lemma:suboptimal-DLSZ-slice}, $P$ must be non-zero at at least $\binom{n-2m}{k-m}  > 1$ points (since $m < k \leq n/2$) of $\{0,1\}^n_k.$ Hence we arrive at a contradiction.
\end{proof}

\paragraph{A junta theorem for the slice.}
Nisan and Szegedy \cite{Nisan-Szegedy} showed that any Boolean function on $\Boo^{n}$ that has degree $d$ over $\mathbb{R}$ depends on $\bigO(d 2^{d})$ variables, i.e. it is a $\bigO(d 2^{d})$-junta. Chiarelli, Hatami, and Saks \cite{CHS-20} improved the bound to $\bigO(2^{d})$.  Filmus and Ihringer~\cite{Filmus-Ihringer19} extended this result to slices and showed that for a suitable range of $k$, any degree-$d$ (over $\mathbb{R}$) Boolean function on the slice $k$ is a restriction of a degree-$d$ function on $\{0,1\}^n$. Along with the result of~\cite{CHS-20}, this implies that such a function is an $\bigO(2^d)$-junta. While the results of~\cite{Nisan-Szegedy,CHS-20} are fairly elementary, the theorem of~\cite{Filmus-Ihringer19} is more involved, relying on the Log-Sobolev inequality and Hypercontractivity for the Boolean slice~\cite{LeeYau, DiaconisSaloffCoste}. 

Using \Cref{thm:main}, we show that we can avoid the use of advanced analytic techniques\footnote{We have two proofs of our main theorem. In the general case where $d$ can be as large as $n^{\Omega(1)}$, our proof also relies on hypercontractivity. However, in the case that $d \leq C \log n,$ which is also the main case of interest for junta theorems, our proof needs only basic Fourier analysis over the Boolean cube and the eigenvalue interlacing theorem.} in the proof of~\cite{Filmus-Ihringer19}, and give a direct proof (following the proof of~\cite{Nisan-Szegedy}) of the fact that any degree-$d$ Boolean function on the balanced slice $\{0,1\}^n_{n/2}$ depends on $\bigO(d2^d)$ variables (see \Cref{lem:improved-FI}). %(Note, however, that our proof of~\Cref{thm:main} uses known facts about the spectrum of Johnson graphs and is hence not as elementary as the proofs of~\cite{Nisan-Szegedy} or~\cite{CHS-20}.) 
Plugging this into the proof of~\cite{Filmus-Ihringer19}, we can again recover the optimal bound of $\bigO(2^d).$ More details can be found in \Cref{sec:junta}.

 \paragraph{Organization of the paper.} We provide basic definitions and other preliminaries in~\Cref{sec:preliminaries}. We give the proof details of the distance lemma over the balanced slice (i.e., $k=n/2$) in~\Cref{sec:bal-slice} and then use this to get the same over {\em all} slices in~\Cref{sec:all-slices}, thus finishing the proof of our main theorem~\Cref{thm:main}. In~\Cref{sec:junta}, we present our alternate proof of the junta theorem over slices. Finally, we obtain an improvement of our main theorem for the case of linear functions (i.e., $d=1$) as~\Cref{thm:deg1} in~\Cref{sec:deg1}.





\section{Preliminaries}\label{sec:preliminaries}
\paragraph{Notations.}Let $(G, +)$ denote an Abelian group $G$ with addition as the binary operation. For any $g \in G$, let $-g$ denote the inverse of $g \in G$. For any $g \in G$ and integer $a \geq 0$, $a \cdot g$ (or simply $ag$) is the shorthand notation of $g + \ldots + g$ (taken $a$ times), and $-ag$ denotes $a\cdot (-g).$

For any $\mathbf{x} \in \Boo^{n}$, $|\mathbf{x}|$ denotes the Hamming weight of $\mathbf{x}$. For any $\mathbf{x}, \mathbf{y} \in \Boo^{n}$, let $\Delta(\mathbf{x},\mathbf{y})$ denote the Hamming distance between $\mathbf{x}$ and $\mathbf{y}$, i.e. $\Delta(\mathbf{x}, \mathbf{y}) = |\setcond{i \in [n]}{x_{i} \neq y_{i}}|$. For natural numbers $n$ and $k \leq n$, let $\Boo^{n}_{k}$ denote the subset of strings in $\Boo^{n}$ of Hamming weight exactly $k$.\newline
We denote the set of functions $f :\Boo^{n} \to G$ that can be expressed as a multilinear polynomial of degree $d$, with the coefficients being in $G$ by $\mathcal{P}_{d}(n,G)$. We also consider functions $f: \Boo^{n}_{k} \to G$. We denote the set of functions on $\Boo^{n}_{k}$ that can be expressed as a multilinear polynomial of degree $d$ with the coefficients in $G$ by $\mathcal{P}_{d}(n,k,G)$. We will simply write $\mathcal{P}_{d}(n,k)$ when $G$ is clear from the context.


% For a polynomial $P(\mathbf{x})$, let $\mathrm{vars}(P)$ denote the variables on which $P$ depends, i.e., the variables that appear in a monomial with non-zero coefficient in $P$.

For any natural numbers $n$ and $k \leq n$, $U_{n}$ denotes the uniform distribution on $\Boo^{n}$ and $U_{n,k}$ denotes the uniform distribution on $\Boo^{n}_{k}$. For a growing parameter $n$, $o_{n}(1)$ denotes a function that goes to $0$ as $n$ grows large.




\paragraph{Basic Tools.}We start with the standard ODLSZ lemma over the Boolean cube.\\

\begin{theorem}[ODLSZ lemma over $\{0,1\}^n$]
\label{thm:DLSZ}
Let $G$ be any Abelian group and let $P\in \mathcal{P}_d(n,G)$ be any non-zero polynomial. Then 
\[
\Pr_{\mathbf{x}\sim U_n} \left[P(\mathbf{x})\neq 0\right]\geq \frac{1}{2^d}.
\]
\end{theorem}


% \paragraph{Probabilistic notions.} For any distribution $X$ on $\Boo^{n}$, let $\mathrm{supp}(X)$ denote the subset of $\Boo^{n}$ on which $X$ takes non-zero probability. For two distributions $X$ and $Y$ on $\Boo^{n}$, the statistical distance between $X$ and $Y$, denoted by $\mathrm{SD}(X,Y)$ is defined as 
% \begin{align*}
%     \mathrm{SD}(X,Y) = \max_{T\subseteq \{0,1\}^n} |\Pr[X \in T] - \Pr[Y \in T]|
% \end{align*}
% We say $X$ and $Y$ are $\varepsilon$-close if the statistical distance between $X$ and $Y$ is at most $\varepsilon$.

Another important tool we require is Lucas's theorem which allows us to compute binomial coefficients modulo a prime $p$.\\

\begin{lemma}[Lucas's Theorem~\cite{Lucas}]\label{lemma:lucas}
 Let $p$ be a prime number and $a$ and $b$ be any two natural numbers. Denote $a$ and $b$ in their unique $p$-ary representations as:
\begin{align*}
    a = \sum_{i = 0}^{\ell - 1} a_{i} p^{i}, \quad \quad b = \sum_{i = 0}^{\ell - 1} b_{i} p^{i}, \quad \quad  a_{i}, b_{i} \in \{0,1,\ldots, p-1\}
\end{align*}
Then,
\begin{align*}
    \displaystyle\binom{a}{b} \; \equiv \; \prod_{i = 0}^{\ell - 1} \displaystyle\binom{a_{i}}{b_{i}} \; \mod{p},
\end{align*}
where we define $\binom{x}{y}$ to be $0$ if $x < y$.
\end{lemma}


