We will need the following standard facts about expanders and Cayley graphs. We refer the reader to the survey~\cite{HLW} for more details.\\

\begin{definition}[Weighted Cayley Graph]
    Let $(G,+)$ be a finite Abelian group and $w:G \to \R^{\ge 0}$ be a {\em weight} function (we refer to the elements of non-zero weight as {\em generators}). We say that a weighted graph $\Gamma = \Gamma(G,w)$ defined as follows is a {\em weighted Cayley graph} over $G$.
    \begin{itemize}
        \item The vertices of $\Gamma$ are the elements of $G$.
        \item For every $g,g'\in G$, we add an edge $(g,g+g')$ with weight $w(g')$ to $\Gamma$.
    \end{itemize}
\end{definition}

The following lemma gives us a way of computing the eigenvalues of the adjacency matrix of weighted Cayley graphs over Abelian groups. \\

\begin{lemma}[Eigenvalues of Cayley graphs, see e.g.~\cite{HLW}]\label{lem:cayley-evals}
    Let $\Gamma = \Gamma(G,w)$ be a weighted Cayley graph over a finite Abelian group $G$, where $w:G \to \mathbb{R}^{\ge 0}$ is the corresponding weight function. Let $\chi:G \to \mathbb{C}^\times$ be an arbitrary group homomorphism (which we will refer to as a {\em character}). Then, $\chi$ is an eigenvector of the adjacency matrix of $\Gamma$ with eigenvalue equal to $\sum_{g\in G}w(g) \chi(G)$. 
\end{lemma}

\noindent
Following is a consequence of the \emph{expander mixing lemma}.\\

\begin{lemma}[Expander mixing lemma, see e.g.~\cite{HLW}~Lemma 2.5]\label{fact:eml}
    For a symmetric random walk matrix $W$ over vertices $V$ and every subset $S\subseteq V$, it holds that
    $$ \Pr_{u\sim V, v\sim N(u)}[u\in S\text{~and~}v\in S]\le \bigg(\frac{|S|}{|V|}\bigg)^2 + \mu(W)\cdot \frac{|S|}{|V|},$$ where $N(u)$ denotes the distribution over $V$ corresponding to taking a step from $u$ according to $W$ (i.e., the $u$-th row of $W$).
\end{lemma}



\section{Distance Lemma for the Balanced Slice}\label{sec:bal-slice}
In this section, we state the main technical lemma of our proof for \Cref{thm:main}. It is a statement on the ``expansion'' property of a graph $\Boo^{n}_{n/2}$, where the edge weights are given by a random process. We start by describing a random process that maps a string in $\Boo^{n}_{n/2}$ to a string in $\Boo^{n}_{n/2}$. In this section, we will always assume that $n$ is an even number.\\

\begin{definition}[The map $\Gamma$]
Let $\mathbf{a} \in \Boo^{n/2}$ and $\mathbf{u} \in \Boo^{n}_{n/2}$. Let $\mathbf{u}^{-1}\set{0}$ denote the set of coordinates where $\mathbf{u}$ is $0$, i.e. $\mathbf{u}^{-1}\set{0} \, = \, \setcond{i \in [n]}{u_{i} = 0}$. Similarly we have $\mathbf{u}^{-1}\set{1}$. let $\mathbf{u}^{-1}\set{1} = \set{i_{1},\ldots,i_{n/2}}$.\newline
For any perfect matching $\mathcal{M}$ between $\mathbf{u}^{-1}\set{0}$ and $\mathbf{u}^{-1}\set{1}$ ($\mathcal{M}$ is a bijection between these two sets), the function $\Gamma(\mathbf{u}, (\mathcal{M}, \mathbf{a}))$ is a balanced string $\mathbf{v} \in \Boo^{n}_{n/2}$ defined as follows:\newline
For every $k \in [n/2]$, $v_{i_{k}} = u_{i_{k}} \oplus a_{k}$ and $v_{\mathcal{M}(i_{k})} = u_{\mathcal{M}(i_{k})} \oplus a_{k}$.
\end{definition}

\noindent
In simple words, for every matching between the $0$-coordinates and $1$-coordinates of $\mathbf{u}$ and a string $\mathbf{a} \in \Boo^{n/2}$, we get a new balanced string $\mathbf{v}$ by flipping the endpoints of a subset of matching edges. Here the subset of matching edges whose endpoints are flipped is given by the string $\mathbf{a}$. Following is an example for $n = 8$.

\paragraph{Example.}Let $\mathbf{u} = 10101010$. Here $\mathbf{u}^{-1}\set{0} = \set{2,4,6,8}$ and $\mathbf{u}^{-1}\set{1} = \set{1,3,5,7}$. Let $\mathcal{M} = ((2,3),(6,1),(4,5),(8,7))$ and $\mathbf{a} = 0110$. Then $\Gamma(\mathbf{u}, (\mathcal{M}, \mathbf{a})) = \mathbf{v} = 00110110$ (endpoints of the $2^{nd}$ matching edge $(6,1)$ and the $3^{rd}$ matching edge $(4,5)$ are flipped).


\paragraph{}Next, we define a weighted graph on all the balanced strings with weights representing the probability of going from one balanced string to another for a random matching $\mathcal{M}$ and a random string $\mathbf{a}$ (using the map $\Gamma$).\newline
Let $n' = |\binom{n}{n/2}|$ denote the cardinality of the set of balanced strings $\Boo^{n}_{n/2}$. Let $G$ denote a weighted complete graph on $n'$ vertices, where the vertices denote strings in $\Boo^{n}_{n/2}$. For any two distinct balanced strings $\mathbf{u}, \mathbf{v} \in \Boo^{n}_{n/2}$, the weight of the edge $(\mathbf{u}, \mathbf{v})$, denoted by $w(\mathbf{u}, \mathbf{v})$ is:
\begin{align*}
    w(\mathbf{u}, \mathbf{v}) \; := \; \Pr_{\mathcal{M}, \mathbf{a}}[\Gamma(\mathbf{u}, (\mathcal{M}, \mathbf{a})) = \mathbf{v}],
\end{align*}
where the probability is over the choice of a random perfect labeled matching $\mathcal{M}$ between $\mathbf{u}^{-1}\set{0}$ and $\mathbf{u}^{-1}\set{1}$, and a uniformly random string $\mathbf{a} \in \Boo^{n/2}$. For every balanced string $\mathbf{u} \in \Boo^{n}_{n/2}$, we will denote by $W(\mathbf{u})$ the distribution on $\Boo^{n}_{n/2}$ where the probability of sampling $\mathbf{v}$ is equal to $w(\mathbf{u}, \mathbf{v})$. Let $W \in \mathbb{R}^{n' \times n'}$ denote the weighted adjacency matrix of $G$, i.e. 
\begin{align*}
    W[\mathbf{u}, \mathbf{v}] \, = \, w(\mathbf{u}, \mathbf{v}), \quad \quad \text{ for all } \mathbf{u}, \mathbf{v} \in \Boo^{n}_{n/2}
\end{align*}

\noindent
We are now ready to state the main technical lemma of our proof. It roughly says that if we sample a random vertex (which is a random balanced string) and its neighbour in the above-mentioned graph, then the two balanced strings behave ``almost like pairwise-independent'' points. In other words, the above-mentioned graph is a good sampler for the balanced slice $\Boo^{n}_{n/2}$.\\

\begin{thmbox}
\begin{restatable}[Main Lemma]{lemma}{mainlemma}\label{lemma:main-informal}
There exists a constant $\varepsilon > 0$ for which the following holds. Let $G$ and $W$ be as mentioned above and let $S \subseteq \Boo^{n}_{n/2}$ be an arbitrary subset of vertices with $|S| \geq 4^{-d} \cdot \binom{n}{n/2}$. Let $\rho$ denote the density of the set $S$. Then,
\begin{align*}
    \Pr_{\substack{\mathbf{x} \sim U_{n,n/2} \\ \mathbf{y} \sim W(\mathbf{x})}}[\mathbf{x} \in S \; \text{ and } \; \mathbf{y} \in S] \; \leq \; \rho^{2} \cdot \paren{1 + \dfrac{1}{n^{\varepsilon}}}.
\end{align*}
\end{restatable}
\end{thmbox}

\noindent
We will give two proofs for \Cref{lemma:main-informal}, for two regimes of the degree $d$:
\begin{enumerate}
    \item For degree $d \leq C\log n$ for some absolute constant $C > 0$, we give a simple argument using the spectral expansion properties of Cayley graphs and the expander mixing lemma. We prove this in \Cref{subsec:simple-proof-cayley}.
    \item For degree $d \leq n^{\gamma}$ for some absolute constant $\gamma > 0$, we rely on the spectrum of Johnson association schemes and use hypercontractivity for slice functions. We prove this in \Cref{subsec:proof-johnson-scheme}.
\end{enumerate}

\noindent
We will also need a lower bound on the probability in \Cref{lemma:main-informal}. This will hold for all degree $d$. Combining the upper and lower bounds (i.e.,~\Cref{lemma:main-informal} and~\Cref{lem:lower-bd} gives the final bound: see~\Cref{sec:everything}.)\\

\begin{lemma}[The lower bound]\label{lem:lower-bd}
Let $G$ be the graph as mentioned above and fix a degree parameter $d \in \mathbb{N}$. Let $P(\mathbf{x}):\Boo^{n}_{n/2} \to \mathbb{R}$ be a non-zero polynomial on the balanced slice $\Boo^{n}_{n/2}$ with $\deg(P) \leq d$. If $S \subseteq \Boo^{n}_{n/2}$ denote the set of non-zeroes of $P(\mathbf{x})$, then,
\begin{align*}
     \Pr_{\substack{\mathbf{x} \sim U_{n,n/2} \\ \mathbf{y} \sim W(\mathbf{x})}}[\mathbf{x} \in S \; \text{ and } \; \mathbf{y} \in S] \; \geq \; \dfrac{|S|}{\binom{n}{n/2}} \cdot \dfrac{1}{2^{d}}.
\end{align*}
\end{lemma}
 \begin{proof}[Proof of \Cref{lem:lower-bd}]
Note that it is sufficient to show that
\begin{align*}
    \Pr_{\mathbf{y} \sim W(\mathbf{x})}[\mathbf{y} \in S \, | \, \mathbf{x} \in S] \; \geq \; \dfrac{1}{2^{d}}, \quad \quad \text{ for all } \; \mathbf{x} \in S.
\end{align*}
Fix an arbitrary point $\mathbf{u} \in S$ and fix an arbitrary matching $\mathcal{M}$ between $\mathbf{u}^{-1}\set{0}$ and $\mathbf{u}^{-1}\set{1}$. We will show that for $1/2^{d}$-fraction of $\mathbf{a} \in \Boo^{n/2}$, the string $\Gamma(\mathbf{u}, (\mathcal{M}, \mathbf{a})) \in S$.\newline

\noindent
Define the polynomial $Q(z_{1},\ldots,z_{n/2}) := P(\Gamma(\mathbf{u}, (\mathcal{M}, \mathbf{z})))$. Note that $\deg(Q) \leq \deg(P) \leq d$ and $Q(\mathbf{0}) = P(\mathbf{u}) \neq 0$. Now using the standard ODLSZ lemma (\Cref{thm:DLSZ}) on $Q(\mathbf{z})$, we get,
\begin{align*}
    \Pr_{{\bf z} \sim \Boo^{n/2}}[Q({\bf z}) \ne 0] \; \ge \; \dfrac{1}{2^{d}} \quad \Rightarrow \quad \Pr_{\mathbf{a} \sim \Boo^{n/2}}[\Gamma(\mathbf{u}, (\mathcal{M}, \mathbf{a})) \in S] \; \geq \; \dfrac{1}{2^{d}}
\end{align*}
Since the above lower bound holds for every matching $\mathcal{M}$ between $\mathbf{u}^{-1}\set{1}$ and $\mathbf{u}^{-1}\set{0}$, we have,
\begin{align*}
    \Pr_{\mathcal{M},\mathbf{a}}[\Gamma(\mathbf{u}, (\mathcal{M}, \mathbf{a})) \in S] \; \geq \; \dfrac{1}{2^{d}}
\end{align*}
Since the above lower bound holds for arbitrary choice of $\mathbf{u} \in S$, this completes the proof of \Cref{lem:lower-bd}.
% as follows: For any $\mathbf{z} \in \Boo^{n/2}$,  over the variables ${\bf z}=(z_i)_{i\in \mathbf{x}^{-1}\set{0}}$ defined by setting $z_{i} = x_{i}$ for $i\in \mathbf{x}^{-1}\set{0}$ and $z_{i} = 1 \oplus y_{\mathcal{M}(i)}$ for $i\in \mathbf{x}^{-1}\set{1}$ in the polynomial $P({\bf x})$.


    % \noindent
    % Since $P({\bf x}) \ne 0$, we have that $Q(0^{n/2}) \ne 0$. Hence, by the standard polynomial distance lemma over the Boolean cube (\Cref{thm:DLSZ}), we have
    % By the way we have defined ${\bf y}$ in terms of $\mathcal{M}$ and since we set the values of $y_i$ for $i\in T$ are uniformly at random, even conditioned on $\mathcal{M}$, we get that $$\Pr [P({\bf y})\ne 0] = \Pr_{{\bf z}}[Q({\bf z})\ne 0] \ge 1/2^d.$$ Hence, $$\Pr_{{\bf y} \sim N({\bf x})}[P({\bf y}) \ne 0]\ge 1/2^d.$$
    % This finishes the proof of \Cref{lem:lower-bd}.
\end{proof}

\paragraph{}Next, we observe that the random process mentioned above is ``$S_{n}$-invariant''\footnote{$S_{n}$ is the group of permutations on $n$ elements.}, i.e. the probabilities do not change even if we simultaneously permute the coordinates of $\mathbf{u}$ and $\mathbf{v}$ (using the same permutation for both of them).\\


\begin{observation}\label{obs:undirected-matrix}
For any $\mathbf{u}, \mathbf{v} \in \Boo^{n}_{n/2}$, the weight $w(\mathbf{u}, \mathbf{v})$ depends only on\footnote{Recall that $\Delta(\cdot, \cdot)$ represents the Hamming distance.} $\Delta(\mathbf{u}, \mathbf{v})$. We have,
\begin{align*}
    w({\bf u},{\bf v}) \; = \; \dfrac{\Delta!(n/2-\Delta)!}{2^{n/2} \cdot (n/2)!} \; = \; \dfrac{1}{2^{n/2} \cdot {n/2\choose \Delta}}, \quad \quad \text{ where } \, 2\Delta=\Delta({\bf u},{\bf v}) \in [0,n]
\end{align*}
To see the above probability, observe that the $\frac{1}{2^{n/2}}$ factor corresponds to sampling the right $\mathbf{a}$ and the $\frac{\Delta!(n/2-\Delta)!}{(n/2)!}$ factor corresponds to picking a matching $\mathcal{M}$ that results in the output ${\bf v}$).
\end{observation}

\noindent
Note that the above observation in particular implies that the weighted adjacency matrix $W$ is a real \underline{symmetric} matrix, and thus has real eigenvalues. Both of our proofs for \Cref{lemma:main-informal} will be based on upper bounding the eigenvalues of $W$.

\subsection{Simple Proof Using Cayley Graphs}\label{subsec:simple-proof-cayley}
In this section, we prove a version of \Cref{lemma:main-informal} using a simple and (mostly) self-contained argument. This version holds for degrees $d \leq C \log n$ for some absolute constant $C$.\\


Let $1=\mu_1 \ge \mu_2 \ge \dots \ge \mu_{n'}$ be the eigenvalues of $W$ and let $\mu(W)$ denote the second largest eigenvalue in absolute value, i.e. $\mu(W):=\max(|\mu_2|,|\mu_{n'}|)$. A small value of $\mu(W)$ suggests that the random walk represented by $W$ is ``expanding'' (see \Cref{fact:eml}). The main lemma of this subsection is the following, which shows that $\mu(W)$ is small, i.e. $W$ is a good expander. In the rest of the subsection, let $m = n/2$.\\

\begin{lemma}[$W$ is a good expander]\label{lem:w-exp}
Let $W$ denote the $n' \times n'$ matrix as described before. Then,
\begin{align*}
    \mu(W) \le {\bigO}\bigg(\frac{\log n}{\sqrt{n}}\bigg).
\end{align*}
\end{lemma}

We now prove \Cref{lem:w-exp}, i.e., we show that $W$ is a good expander. The idea of the proof is to show that one can turn $W$ into a (weighted) Cayley graph by adding additional edges and vertices and deduce that the original graph is an expander by using the expansion of the Cayley graph. In particular, we will show that $W$ is an induced subgraph of a Cayley graph and use the interlacing of eigenvalues to prove the expansion.

\begin{proof}[Proof of \Cref{lem:w-exp}]
    For the proof, we will assume that $m$ is even; the odd case is handled similarly. Let $\{0,1\}^n_{odd}$ and $\{0,1\}^n_{even}$ denote the sets of points in $\{0,1\}^n$ that are of odd Hamming weight and even Hamming weight respectively. We will now define the weighted Cayley graph.

     Let $V'=\{0,1\}^{n}_{even}$ (note that $\Boo^{n}_{n/2} \subseteq V'$ as $n$ is assumed to be even). Note that $V'$ is an Abelian group with addition defined by performing coordinate sums modulo 2 (in particular, we may identify \{0,1\} with $\F_2$). We shall define a weighted Cayley graph $W'$ over vertices $V'$ by specifying its generators (and their weights) as follows. The set of generators is $\mathcal{S} =\{0,1\}^n_{even}$ and a generator ${\bf x} \in \mathcal{S}$ has weight
     \begin{align*}
         w(\mathbf{x}) \; = \; \dfrac{1}{2^{m} \cdot \binom{m}{\Delta}}, \quad \text{ where } \; |\mathbf{x}| = 2 \Delta \quad \text{ and } \quad 0 \leq \Delta \leq m
     \end{align*}

     With the above definition for $V'$ and $W'$, we note that the induced subgraph of $W'$ when restricted to the balanced slice $\Boo^{n}_{n/2} \subseteq V'$, is identical to $W$. Hence, by applying the eigenvalue interlacing theorem, we have the following.
     \begin{claim}[Eigenvalue interlacing, see e.g.~\cite{horn1991topics}]
        Let $\mu'_1 \ge \mu'_2 \ge \dots \ge \mu'_{|V'|}$ be the eigenvalues of $W'$. Then $\mu_2 \le \mu_2'$ and $\mu'_{|V'|} \le \mu_{n'}$. Hence, $\mu(W) \le \max(|\mu'_2|,|\mu'_{|V'|}|)$.
     \end{claim}
     The above claim allows us to bound $\mu(W)$ by bounding the absolute values of the eigenvalues of $W'$ (except the largest). To do this, we will first fix an eigenbasis for $W'$. The characteristic vectors of the first $(n-1)$ variables forms such an eigenbasis (because if $\mathbf{x} \in V'$, then $x_{n}$ can be expressed as a $\F_2$-linear combination of $x_{1},\ldots,x_{n-1}$). That is, for $A \subseteq [n-1]$, the characteristic vector ${\chi}_A \in \R^{2^{n-1}}$ is defined as ${\chi}_A({\bf x}) := (-1)^{\sum_{i\in A}{x_i}}$ for ${\bf x}\in V'$. The corresponding eigenvalue of $\chi_A$ is denoted by $\mu'_A$ (with a slight abuse of notation), and by~\Cref{lem:cayley-evals}, is equal to
     $$\mu'_A = \sum_{{\bf y}\in \mathcal{S}}w({\bf y})\chi_A({\bf y}).$$

     It will be convenient to normalize the weights of the generators in $\mathcal{S}$ to make it a probability distribution. More formally, let $\mathcal{D}$ be the probability distribution over $\mathcal{S}$ where the probability of sampling a point ${\bf x} \in \mathcal{S}$ is equal to $w({\bf x})/\sum_{{\bf y}\in \mathcal{S}}w({\bf y})$. Thus, $\mu'_{\emptyset} = \sum_{{\bf y}\in \mathcal{S}}w({\bf y})$ and $\mu'_A/\mu'_{\emptyset} =\E_{{\bf x}\sim \mathcal{D}}[\chi_A({\bf x})]$.\\

     \noindent 
     We will now show that $0 < \mu'_\emptyset \le \bigO(\sqrt{m})$ and $|\E_{{\bf x}\sim \mathcal{D}}[\chi_A({\bf x})]|=|\mu'_A/\mu'_{\emptyset}| \le O\big(\frac{\log m}{m}\big)$ for all {\em non-empty} $A \subseteq [2m-1]$. This would in turn give that $\mu(W) \le \max_{A \ne \emptyset}(|\mu'_A|) \le {\bigO}\bigg(\frac{\sqrt{m}\log m}{m}\bigg) = {\bigO}(\log m/\sqrt{m})$, finishing the proof of~\Cref{lem:w-exp}.

    The proof of \Cref{clm:eig-1} follows from a simple counting argument and can be found in \Cref{app:claims-simple-proof}.

    \begin{claim}\label{clm:eig-1}
        $0<\mu'_\emptyset \le \bigO(\sqrt{m}).$
    \end{claim}

    It remains to show that $|\E_{{\bf x}\sim \mathcal{D}}[\chi_A({\bf x})]| \le \bigO\big(\frac{\log m}{m}\big)$ for all {\em non-empty} $A \subseteq [2m-1]$. Note that the distribution $\mathcal{D}$ has some symmetry in the sense that all the points of a given Hamming weight have the same probability. Furthermore, two given points, one of weight $2 \Delta$ and the other of weight $(2m-2 \Delta)$ also have the same probability mass (for arbitrary $0 \leq \Delta \leq m$). This leads to $\E_{{\bf x}\sim \mathcal{D}}[\chi_A({\bf x})]$ being equal to $0$ if $|A|=1$ or $2m-1$, and hence it suffices to focus on the regime $2\le |A| \le 2m-2$.

    We show the following concentration inequality for the distribution $\mathcal{D}$. The proof of \Cref{clm:D-conc} can be found in \Cref{app:claims-simple-proof}.

    \begin{claim}\label{clm:D-conc}
        $\Pr_{{\bf x} \sim \mathcal{D}}[||{\bf x}|-m| > \sqrt{50 m \log m}] \le \bigO(1/m^2)$.
    \end{claim}

     Assuming \Cref{clm:D-conc}, it suffices to show that $\E_{{\bf x}\sim \mathcal{D}}[\chi_A({\bf x}) ~\mid~|{\bf x}| \in m\pm \sqrt{50 m \log m}] \le \bigO\big(\frac{\log m}{m}\big)$ to conclude that $\E_{{\bf x}\sim \mathcal{D}}[\chi_A({\bf x})] \le \bigO\big(\frac{\log m}{m}\big)$. We will show that this holds even conditioned on  $|{\bf x}|=2 \Delta$ for every $\Delta \in (m\pm \sqrt{50m\log m})/2$. However, recall that $\mathcal{D}$ is uniform when restricted to $\{0,1\}^{2m}_{2 \Delta}$. Therefore, we can equivalently upper bound the quantity $|\E_{{\bf x}\in \{0,1\}^{2m}_{2\Delta}}[\chi_A({\bf x})]|$ to conclude the proof. Now, we note that $\E_{{\bf x}\in \{0,1\}^{2m}_{2\Delta}}[\chi_A({\bf x})] = \E_{B \sim {[2m]\choose |A|}}[\chi_B({\bf c})]$, where ${\bf c}$ is an arbitrary point in $\{0,1\}^{2m}_{2\Delta}$ (we will fix it to be $0^{2m-2\Delta}1^{2\Delta}$). Hence, it suffices to show that 
     \begin{align}\label{eqn:exp-B}
        \bigg|\E_{B \sim {[2m] \choose k}}[\chi_B({\bf c})]\bigg| \; \le \; \bigO\bigg(\frac{\log m}{m}\bigg),
     \end{align}
     for every $2 \leq k \leq (2m-2)$ (since we assumed that $2\le |A| \le 2m-2$). We may further assume that $k\le m$ without loss of generality, as $\chi_B({\bf c}) = \chi_{\overline{B}}({\bf c})$.\\

     \noindent    
    To help with the analysis, we will choose $B\sim {[2m] \choose k}$ by first choosing a subset $C$ of $[2m]$ of size $(k-2)$ (which is non-negative) uniformly at random and then choosing two elements $b_1\ne b_2$ from $\overline{C}=[2m]\setminus C$ uniformly at random.

    For a subset $C \subseteq [2m]$, we will use the notation $\text{wt}(C)$ to denote the number of 1's in ${\bf c}$ when restricted to the coordinates indexed by $C$. Let $p:=\text{wt}([2m])/(2m)$ denote the fractional Hamming weight of ${\bf c}$. We say that a subset $C\subseteq [2m]$ is {\em good}, if $\big| |\overline{C}| - 2\text{wt}(\overline{C}) \big| \le \sqrt{{2000 \log m}}$. We claim that $\Pr_{C \sim {[2m] \choose k-2}}[C\text{~is not good}] \le \bigO(1/m^2)$. This essentially follows from standard tail bounds for the hypergeometric distribution but needs some care to handle small $k$. We divide this analysis into two cases.

    \begin{itemize}
        \item {\bf Case 1: $k \le \sqrt{50 m \log m}$.} We note that $|\overline{C}|=2m-k+2 \in 2m \pm \sqrt{50 m \log m}$, and similarly $\text{wt}(\overline{C}) \in \text{wt}([2m]) \pm \sqrt{50m\log m} \subseteq m \pm 2\sqrt{50m\log m}$. Using these bounds, it follows that $\big| |\overline{C}|-2\text{wt}(\overline{C}) \big| \le \sqrt{{2000\log m}}$ for sufficiently large $m$ (for every choice of $C\in {[2m] \choose k-2}$). Hence all choices of $C$ are good in this case.

        \item {\bf Case 2: $k > \sqrt{50 m \log m}$.} We note that $\text{wt}({C})$ is distributed according to a hypergeometric distribution --- it corresponds to the number of successes in $k-2$ draws with replacement from a population of $2m$ total states and $\text{wt}([2m])=2d$ success states. Using a standard tail bound~\cite{hoeffding1994probability}, we obtain that $\Pr_{C\sim {[2m]\choose k-2}}\big[|\frac{\text{wt}(C)}{k-2} - p|>\sqrt{\frac{4\log k}{k}}\big]= \bigO(1/k^4)= \bigO(1/m^2)$. Using $\big|p-\frac{1}{2}\big| \le \sqrt{\frac{50\log m}{m}}$, we thus get that $||C|-2\text{wt}(C)| \le 4\sqrt{50m\log m}$ with probability at least $1-\bigO(1/m^2)$. Because $2m=|C|+\overline{C}$ and $2d=\text{wt}(C)+\text{wt}(\overline{C})$, with probability at least $1-\bigO(1/m^2)$, we have $||\overline{C}|-2\text{wt}(\overline{C})| \le 6\sqrt{50m\log m}$, i.e., $C$ is good.
    \end{itemize}

    We now show that conditioned on $C$ being good, the expectation of $\chi_B({\bf c})$ is upper bounded by $\bigO\big(\frac{\log m}{m}\big)$ in absolute value. This would then prove~\eqref{eqn:exp-B}.  For ease of notation, let $n_0=|\overline{C}|=2m-k+2 \ge m$ and $d_0=\text{wt}(\overline{C}) \in \frac{n_0}{2} \pm \Theta(\sqrt{n_0\log n_0})$ (since $C$ is good).  We now note that $\chi_B({\bf c}) = \chi_{C}({\bf c})\cdot \chi_{\{b_1,b_2\}}({\bf c})$, so it suffices to bound $|\E_{b_1,b_2}[(-1)^{c_{b_1}+c_{b_2}}]|$. The idea now is that $c_{b_1}$ and $c_{b_2}$ almost behave like two independent draws, so the expectation is {\em roughly} the square of $|\E_b[(-1)^{c_b}]|$ for a uniformly random coordinate $b\in \overline{C}$, which is equal to $\big|\frac{n_0-2d_0}{n_0}\big| \le O(\sqrt{\frac{\log n_0}{n_0}}) \le O(\sqrt{\frac{\log m}{m}})$ as $n_0 \ge m$. More precisely, we have the following:
    \begin{align*}
        |\E_{b_1,b_2}[(-1)^{c_{b_1}+c_{b_2}}]| & = \frac{|{d_0\choose 2}+{n_0-d_0 \choose 2}-d_0(n_0-d_0)|}{{n_0\choose 2}}\\
        & = \frac{|(n_0-2d_0)^2-n_0|}{n_0(n_0-1)}\\
        & \le \bigO\bigg(\frac{\log n_0}{n_0}\bigg)\tag{as $d_0 \in n_0/2 \pm \Theta(\sqrt{n_0\log n_0})$} \le \bigO\bigg(\frac{\log n}{n}\bigg).
    \end{align*}

    This finishes the proof of~\Cref{lem:w-exp}.
\end{proof}


% \paragraph{}\Cref{lem:simple-upper-bound-balanced} now follows from the expander mixing lemma.
% \begin{proof}[Proof of \Cref{lem:simple-upper-bound-balanced}]
% The matrix $W$ is a symmetric matrix as mentioned in \Cref{obs:undirected-matrix}. Using \Cref{fact:eml} with \Cref{lem:w-exp} gives us the desired bound.    
% \end{proof}

\begin{proof}[Proof of \Cref{lemma:main-informal} for $d \leq C \log n$] 
We use \Cref{lem:w-exp} to prove an upper bound for \Cref{lemma:main-informal} that holds for all $d \leq C \log n$ for an absolute constant $C > 0$. Using the expander mixing lemma (\Cref{fact:eml}), we obtain
$$\Pr_{{\bf x}\sim U_{n,n/2}, \\ {\bf y}\sim N({\bf x})}[{\bf x}\in S\text{~and~}{\bf y}\in S] \le \rho^2 + \rho \cdot \bigO\paren{\frac{\log n}{\sqrt{n}}},$$ where $S$ denotes the non-zeroes of $P$ in $\{0,1\}^n_{n/2}$ and $\rho=|S|/{n \choose n/2}$. Thus assuming $d\le C\log n$ for small enough constant $C$ and using $\rho \ge 4^{-d}$ (\Cref{lemma:suboptimal-DLSZ-slice}), we get that the above probability is at most $\rho^2(1+1/n^\varepsilon)$ for sufficiently small constant $\varepsilon$. Hence, this finishes the proof of~\Cref{lemma:main-informal} in the regime $d \le C\log n$.

\end{proof}









\subsection{Proof via Johnson Association Schemes}\label{subsec:proof-johnson-scheme}
In this section, we prove a stronger version of \Cref{lemma:main-informal}, i.e. we will give a tighter upper bound. This will hold for all $d \leq n^{\gamma}$ for some absolute constant $\gamma > 0$. In this subsection, we will always assume that $n$ is divisible by $2$. We will first give some preliminaries on \emph{Johnson association schemes} and functions on the balanced slice.\\


\subsubsection{Preliminaries for Johnson Association Schemes}
We now discuss that the matrix $W$ has some useful properties. Recall $n' = \binom{n}{n/2}$. Consider the set of $n' \times n'$ dimensional matrices satisfying the following property: For every entry $(\mathbf{u}, \mathbf{v})$, the entry only depends on the Hamming distance $\Delta(\mathbf{u}, \mathbf{v})$ as mentioned in \Cref{obs:undirected-matrix}. The set of all such matrices forms an algebra known as \emph{Bose-Mesner algebra of the $(n,n/2)$ Johnson association scheme}. Note that the matrices in this algebra are invariant under the action of the symmetric group $S_{n}$ on the coordinates, i.e., if we apply a permutation $\pi \in S_{n}$ on the coordinates of the rows and columns simultaneously, the matrix remains invariant. Filmus \cite{Filmus2014AnOB} showed that there exist vector spaces that form orthogonal eigenspaces for matrices in Bose-Mesner algebra of the $(n,n/2)$ Johnson association scheme with certain useful properties.\\

We equip the space of functions on the balanced slice $\Boo^{n}_{n/2}$ with an inner product. We consider the following inner product on functions on the balanced slice: For any two functions $f,g:\Boo^{n}_{n/2} \to \mathbb{R}$
\begin{align*}
    \langle f,g \rangle \; = \; \mathbb{E}_{\mathbf{x} \sim U_{n,n/2}}[f(\mathbf{x}) \cdot g(\mathbf{x})]
\end{align*}
The $p^{th}$ norm of a function $f: \Boo^{n}_{n/2} \to \mathbb{R}$ is defined as follows:
\begin{align*}
    \lVert f \rVert_{p} \; = \; \mathbb{E}_{\mathbf{x} \sim U_{n,n/2}}[|f(\mathbf{x})|^{p}]^{1/p} \; = \; \dfrac{1}{n'} \paren{\sum_{\mathbf{x} \in \Boo^{n}_{n/2}} |f(\mathbf{x})|^{p} }^{1/p}
\end{align*}

\paragraph{}Let us define a particular function on the balanced slice $\Boo^{n}_{n/2}$. For every $t \in \set{0,1,\ldots,n/2}$, let $f_{t}(\mathbf{x}): \Boo^{n}_{n/2} \to \mathbb{R}$ be the following function: For $t = 0$, $f_{t} = 1$ and for $t\geq 1$,
\begin{equation}\label{eqn:nice-eigenvector}
    f_{t}(x_{1},\ldots,x_{n}) \; = \; (x_{1} - x_{2}) \cdot (x_{3} - x_{4}) \cdots (x_{2t-1} - x_{2t})
\end{equation}
We are going to interpret $f_{t}(\mathbf{x})$ as a vector, i.e. for every $\bm{\alpha} \in \Boo^{n}_{n/2}$, the $\bm{\alpha}^{th}$ entry of the vector is $f_{t}(\bm{\alpha})$. We will use the following result from \cite{Filmus2014AnOB}.\\

\begin{lemma}\label{lemma:bose-mesner-eigenspaces}
\cite[Lemma 18]{Filmus2014AnOB}. There exists orthogonal\footnote{The orthogonality is with respect to the inner product defined in the previous paragraph.} vector spaces $\mathcal{V}_{n,0}, \ldots, \mathcal{V}_{n,n/2}$ for which the following holds. Let $W$ be any matrix in the Bose-Mesner algebra for the $(n,n/2)$ Johnson association scheme. Then,
\begin{enumerate}
    \item The spaces $\mathcal{V}_{n,0}, \ldots, \mathcal{V}_{n,n/2}$ are orthogonal eigenspaces for the matrix $W$ with corresponding eigenvalues (not necessarily distinct) $\lambda_{0}, \lambda_{1}, \ldots, \lambda_{n/2}$.
    \item For every integer $t \in \set{0,1,\ldots,n/2}$, the function $f_{t}(\mathbf{x})$, as described in \Cref{eqn:nice-eigenvector} lies in $\mathcal{V}_{n,t}$. In other words, $f_{t}$ is an eigenvector of $W$ in the $t^{th}$ eigenspace with eigenvalue $\lambda_{t}$.
\end{enumerate}
\end{lemma}

\paragraph{}For a function $f: \Boo^{n}_{n/2} \to \mathbb{R}$ and $0 \leq t \leq n/2$, let $f^{=t}$ denote the component of $f$ in the $t^{th}$ eigenspace $\mathcal{V}_{n,t}$ (see \Cref{lemma:bose-mesner-eigenspaces}).
We now define the following noise operator for functions on the slice.\\ 

\begin{definition}[Noise operator for functions on slice]
(See \cite[Section 2]{Filmus-Ihringer19}). For a parameter $\rho \in (0,1]$, the \emph{noise operator} $T_{\rho}$ maps functions on the slice $\Boo^{n}_{n/2}$ to functions on the slice $\Boo^{n}_{n/2}$, defined as:
\begin{align*}
    T_{\rho}f \; = \; \sum_{t=0}^{n/2} \; \rho^{t \paren{1 - \frac{t-1}{n}}} \, f^{=t}.
\end{align*}
\end{definition}


\paragraph{}Now we state a hypercontractive inequality for the noise operator $T_{\rho}$. Lee and Yau \cite{LeeYau} proved a log-Sobolev inequality which combined with a result of Diaconnis and Saloff-Coste \cite{DiaconisSaloffCoste} implies the following hypercontractive inequality. The following lemma is a simplified form of the more general inequality. For more details, refer to \cite[Section 2]{Filmus-Ihringer19} and \cite[Section 2]{Filmus2014AnOB}.\\

\noindent
\begin{lemma}[Hypercontractive inequality using log-Sobolev inequality]\label{lemma:hypercontractive-log-Sobolev}
Fix any multilinear polynomial $f$ on the balanced slice $\Boo^{n}_{n/2}$. Then there exists a constant $c$ such that for every $1 \leq p \leq q \leq \infty$ with $\frac{q-1}{p-1} \leq \exp{(c \log 1/\rho)}$,
\begin{align*}
    \lVert T_{\rho} f \rVert_{q} \; \leq \; \lVert f \rVert_{p}.
\end{align*}
\end{lemma}

\noindent
\begin{remark}
In \cite{Filmus2014AnOB} and  \cite{Filmus-Ihringer19}, the above lemma is stated in a slightly different way, so we take a moment to clarify that here. As mentioned in \cite[Page 2]{Filmus-Ihringer19} (see the line after Equation (2)), the noise operator $T_{\rho}$ is equivalent to the expected value after applying random $\mathrm{Po}(\frac{n-1}{2} \log (1/\rho))$ transpositions. Using the comment in \cite{Filmus2014AnOB} (after Definition 26), $T_{\rho}$ is equivalent to $H_{g(\rho)}$, where $H_{\cdot}$ is the Heat operator and $g(\rho) = \frac{n-1}{2} \log (1/\rho)$. We get \Cref{lemma:hypercontractive-log-Sobolev} by using \cite[Lemma 27]{Filmus2014AnOB} (the reader should be careful that the $\rho$ in that lemma is the \emph{log Sobolev constant} and is different from the $\rho$ in \Cref{lemma:hypercontractive-log-Sobolev}).
\end{remark}


\subsubsection{Proof of the Sampling Guarantee}
One of the key steps in our proof of \Cref{lemma:main-informal} will be \Cref{lemma:eigenvalue-bound} which gives an upper bound on the eigenvalues of the matrix $W$. It says that for small $t$, the eigenvalue $\lambda_{t}$ is quite small (roughly $1/n^{t}$) and for larger $t$, the eigenvalue is still exponentially small (roughly $1/2^{t}$). To upper bound the eigenvalues, the idea is to choose a suitable eigenvector and argue about its non-zero coordinates. In particular, we will work with the eigenvector $f_{t}(\mathbf{x})$ as stated in \Cref{eqn:nice-eigenvector} and \Cref{lemma:bose-mesner-eigenspaces}.

\noindent
\begin{lemma}\label{lemma:eigenvalue-bound}
Let $\lambda_{0},\lambda_{1},\ldots,\lambda_{n/2}$ denote the eigenvalues of $W$ and let $\tau := n^{\delta}$ for a sufficiently small constant $\delta > 0$. Then,
\begin{itemize}
    \item For $1 \leq t \leq \tau$, $\lambda_{t} \leq 1/n^{\Omega(t)}$
    \item For $t > \tau$, $\lambda_{t} \leq 1/2^{n^{\Omega(1)}}$.
\end{itemize}
\end{lemma}

\noindent
Before going into the proof of \Cref{lemma:eigenvalue-bound}, we will define a property on bipartite matching. For a matching $\mathcal{M}$, if $(i,j) \in \mathcal{M}$, then we will use the notation $\mathcal{M}(i) = j$ and $\mathcal{M}(j) = i$.\\

\noindent
\begin{definition}[Good and self-good matching]
Consider a complete bipartite graph $K_{n/2,n/2}$ on vertex set $(L \bigcup R)$, where $L = \set{1,3,\ldots,n-1}$ and $R = \set{2,4,\ldots,n}$. We will refer to a matching $\mathcal{M}$ between $L$ and $R$ as \emph{\underline{$t$-good}} if the following holds:
\begin{align*}
    \mathcal{M}(2i-1) \in \set{2,4,\ldots,2t} \quad \text{ or } \quad \mathcal{M}(2i) \in \set{1,3,\ldots,2t-1}, \quad \quad \text{ for all } \, i \in [t]
\end{align*}
We will call a good matching $\mathcal{M}$ a \emph{\underline{$t$-self good}} matching if for every subset $T \subseteq [t]$ of size $t/2$, there exists $i \in T$ such that
\begin{align*}
    \mathcal{M}(2i-1) = 2i
\end{align*}
\end{definition}

\noindent
We will simply refer to matchings that are not $t$-good as \emph{$t$-bad} matchings. We will refer to matchings that are $t$-good but not $t$-self good as \emph{$t$ non-self good} matchings. In our proof of \Cref{lemma:eigenvalue-bound}, it will be useful to have an upper bound on the probability that a random matching $\mathcal{M}$ is a $t$-good matching or a $t$-self good matching. We upper bound these probabilities in the following claim. The proof is a straightforward counting argument with standard binomial estimations. We omit the proof here and it can be found in \Cref{app:good-matching}.\\

\noindent
\begin{restatable}[Upper bound on probability of (self) good matchings]{claim}{upperboundgoodmatching}\label{claim:upper-bound-good-matching}
Consider the complete bipartite graph $K_{n/2,n/2}$ on $L \bigcup R$ where $L = \set{1,3,\ldots,n-1}$ and $R = \set{2,4,\ldots,n}$. Let $\tau = n^{\delta}$ for a sufficiently small $\delta > 0$. Then,
\begin{align*}
    \Pr_{\mathcal{M}}[\mathcal{M} \; \text{ is a $t$-good matching}] \; \leq \; \dfrac{1}{n^{\Omega(t)}}, \quad \quad \text{ for all } \; t \leq \tau, 
\end{align*}
where the above probability is over the choice of a uniformly random matching $\mathcal{M}$. Also,
\begin{align*}
    \Pr_{\mathcal{M}}[\mathcal{M} \; \text{ is a $t$-self good matching}] \; \leq \; \dfrac{1}{n^{\Omega(t)}}, \quad \quad \text{ for all } \; t > \tau,
\end{align*}
where the above probability is over the choice of a uniformly random matching $\mathcal{M}$.
\end{restatable}


\paragraph{}Now we have all the essentials with us to prove the \Cref{lemma:eigenvalue-bound}. As mentioned earlier, the idea would be to fix a non-zero coordinate of the eigenvector $f_{t}(\mathbf{x})$ and consider that coordinate in $Wf_{t}$. 
\begin{proof}[Proof of \Cref{lemma:eigenvalue-bound}]
Recall that the rows and columns of the matrix $W$ are indexed by points of $\Boo^{n}_{n/2}$. Fix any particular $t \in \set{1,\ldots,n/2}$.  We know that $f_{t}$ is an eigenvector of the matrix $M$ with eigenvalue $\lambda_{t}$, i.e. for every $\mathbf{u} \in \Boo^{n}_{n/2}$, we have,
\begin{align*}
    (Wf_{t})[\mathbf{u}] \; = \; \lambda_{t} \cdot f_{t}(\mathbf{u}) \quad
    \Rightarrow \quad \mathbb{E}_{\mathbf{v} \sim W(\mathbf{u})}[f_{t}(\mathbf{v})] \; = \; \lambda_{t} \cdot f_{t}(\mathbf{u})
\end{align*}
Fix any $\mathbf{u}$ for which $f_{t}(\mathbf{u}) =1$. For convenience, let $\mathbf{u} = 1010\ldots10$. Then we have,
\begin{align*}
    \lambda_{t} \; = \; \mathbb{E}_{\mathbf{v} \sim W(\mathbf{u})}[f_{t}(\mathbf{v})]
\end{align*}



\paragraph{}We make the following observation about bad matchings.\\

\begin{observation}\label{obs:bad-matching}
Fix $\mathcal{M}$ to be any $t$-bad matching. For simplicity in notation, assume that $\mathcal{M}(1) \notin \set{2,4,\ldots,2t}$ and $\mathcal{M}(2) \notin \set{1,3,\ldots,2t-1}$. Let $\mathcal{M}(2) = (2j-1)$ for some $j > t$. Then we have $v_{1} = u_{1} \oplus a_{1}$ and $v_{2} = u_{2} \oplus a_{j}$. Since $a_{1}$ and $a_{j}$ are mutually independent, this implies that $v_{1}$ and $v_{2}$ are mutually independent too. This implies that the expected value of $(v_{1} - v_{2})$ over the random choice of $\mathbf{a}$ is $0$ (conditioned on a bad matching $\mathcal{M}$). Using the independence of bits in $\mathbf{a}$, we have,
\begin{gather*}
    \mathbb{E}_{\mathbf{v} \sim W(\mathbf{u})}[f_{t}(\mathbf{v}) \, | \, \mathcal{M} \text{ is $t$-bad}] \; =  \; \mathbb{E}_{(a_{1},a_{j})} \; [(v_{1} - v_{2})] \cdot \mathbb{E}_{a_{2},\ldots,a_{n/2} \setminus a_{j}}  \; \brac{\prod_{k>1}^{t} (v_{2k-1} - v_{2k})} \\
    \Rightarrow \mathbb{E}_{\mathbf{v} \sim W(\mathbf{u})}[f_{t}(\mathbf{v}) \, | \, \mathcal{M} \text{ is $t$-bad}] \; = \; 0
\end{gather*}
\end{observation}


\paragraph{}This gives us the following:
\begin{align*}
    \lambda_{t} \; = \; \mathbb{E}_{\mathbf{v} \sim W(\mathbf{u})}[f_{t}(\mathbf{v}) \, | \, \mathcal{M} \, \text{ is $t$-good}] \cdot \Pr_{\mathcal{M}}[\mathcal{M} \, \text{ is $t$-good}] \, + \, \mathbb{E}_{\mathbf{v} \sim W(\mathbf{u})}[f_{t}(\mathbf{v}) \, | \, \mathcal{M} \, \text{ is $t$-bad}] \cdot \Pr_{\mathcal{M}}[\mathcal{M} \, \text{ is $t$-bad}]
\end{align*}
From \Cref{obs:bad-matching}, we know that the expected value of $f_{t}(\mathbf{v})$ for $\mathbf{v} \in N(\mathbf{u})$ conditioned on a bad matching $\mathcal{M}$ is $0$.
This gives us
\begin{align*}
    \lambda_{t} \;  = \; \mathbb{E}_{\mathbf{v} \sim W(\mathbf{u})}[f_{d}(\mathbf{v}) \, | \, \mathcal{M} \, \text{ is $t$-good}] \cdot \Pr_{\mathcal{M}}[\mathcal{M} \, \text{ is $t$-good}]
\end{align*}

\paragraph{Case 1 - $t \leq \tau$:}Note that the expectation is over a random choice of $\mathbf{a} \sim \Boo^{n/2}$. For any $\mathbf{v} \in \Boo^{n}_{n/2}$, $f_{t}(\mathbf{v}) \in \set{-1,0,1}$. In other words, the absolute value of the expectation is at most $1$. Using this, we now have,
\begin{align*}
    \lambda_{t} \; \leq \; |\mathbb{E}_{\mathbf{v} \sim W(\mathbf{u})}[f_{t}(\mathbf{v}) \, | \, \mathcal{M} \, \text{ is $t$-good}]| \cdot \Pr_{\mathcal{M}}[\mathcal{M} \, \text{ is $t$-good}] \; \leq \; \Pr_{\mathcal{M}}[\mathcal{M} \, \text{ is $t$-good}]
\end{align*}
For $t \leq \tau$, \Cref{claim:upper-bound-good-matching} implies that $\lambda_{t} \leq 1/n^{\Omega(t)}$. This shows the first item of \Cref{lemma:eigenvalue-bound}.


\paragraph{Case 2 - $t > \tau$:}We make the following observation about non-self good matchings.\\

\begin{observation}\label{obs:self-good-matching}
Fix a $t$ non-self good matching $\mathcal{M}$. By definition of $t$-self good matchings, we know that there exists a set $T \subseteq [t]$ of size $t/2$ such that for every $i \in T$, $\mathcal{M}(2i-1) \neq 2i$. Assume without loss of generality that $T = [t/2]$ and $\mathcal{M}(2i) = (2j_{i}-1)$ for $i \in T$. Note that for every $i \in T$, if $a_{i} \neq a_{j_{i}}$, then $f_{t}(\mathbf{x}) = 0$. In other words, for $f_{t}$ to be non-zero, it is necessary that for every $i \in [t/2]$, $a_{i} = a_{j_{i}}$. This implies that $f_{t}$ is non-zero for at most $\frac{1}{2^{t/4}}$ choices of $\mathbf{a}$.
\end{observation}

\noindent
Using \Cref{obs:self-good-matching}, we get the following upper bound on the expected value conditioned on a $t$ non-self good matching $\mathcal{M}$:
\begin{align*}
     \mathbb{E}_{\mathbf{v} \sim W(\mathbf{u})}[f_{t}(\mathbf{v}) \, | \, \mathcal{M} \; \text{is $t$ non-self good}] \; \leq \; |\mathbb{E}_{\mathbf{v} \sim W(\mathbf{u})}[f_{t}(\mathbf{v}) \, | \, \mathcal{M} \; \text{is $t$ non-self good}]| \; \leq \; \dfrac{1}{2^{t/4}}
\end{align*}
Thus finally we have,
\begin{align*}
    \lambda_{t} \; = \;  \mathbb{E}_{\mathbf{v} \sim W(\mathbf{u})}[f_{t}(\mathbf{v}) \, | \, \mathcal{M} \, \text{ is $t$-good}] \cdot \Pr_{\mathcal{M}}[\mathcal{M} \, \text{ is $t$-good}] \\ \\
    = \; \mathbb{E}_{\mathbf{v} \sim W(\mathbf{u})}[f_{t}(\mathbf{v}) \, | \, \mathcal{M} \, \text{ is $t$-self good}] \cdot \Pr_{\mathcal{M}}[\mathcal{M} \, \text{ is $t$-self good}] \\ + \,  \mathbb{E}_{\mathbf{v} \sim W(\mathbf{u})}[f_{t}(\mathbf{v}) \, | \, \mathcal{M} \, \text{ is $t$ non-self good}] \cdot \Pr_{\mathcal{M}}[\mathcal{M} \, \text{ is $t$ non-self good}] \\ \\
    \leq \; \Pr_{\mathcal{M}}[\mathcal{M} \, \text{ is $t$-self good}] \, + \,  \mathbb{E}_{\mathbf{v} \sim W(\mathbf{u})}[f_{t}(\mathbf{v}) \, | \, \mathcal{M} \, \text{ is $t$ non-self good}] \\
    \Rightarrow \; \lambda_{t} \; \leq \;  \dfrac{1}{2^{t/4}} \, + \, \dfrac{1}{n^{\Omega(t)}} \; \leq \; \dfrac{1}{2^{n^{\Omega(1)}}}
\end{align*}
This shows the second item of \Cref{lemma:eigenvalue-bound} and completes the proof of \Cref{lemma:eigenvalue-bound}.

\end{proof}

We are now ready to prove our main lemma (\Cref{lemma:main-informal}) in the setting when $d \leq n^{\kappa}$. We recall the statement below.\\

\mainlemma*

\begin{proof}[Proof of \Cref{lemma:main-informal} for $d \leq n^{\gamma}$]
Let $\mathds{1}_{S}$ denote the $n'$-dimensional characteristic vector for the subset $S$. Then,
\begin{align*}
    \Pr_{\substack{\mathbf{x} \sim U_{n,n/2} \\ \mathbf{y} \sim W(\mathbf{x}) }}[\mathbf{x} \in S \; \text{ and } \; \mathbf{y} \in S] \; = \; \langle \mathds{1}_{S}, \; W \mathds{1}_{S} \rangle,
\end{align*}
where $\langle f,g \rangle = \mathbb{E}_{\mathbf{x} \sim U_{n,n/2}}[f(\mathbf{x}) g(\mathbf{x})]$. Let $\mathcal{V}_{n,0},\ldots,\mathcal{V}_{n,n/2}$ be the orthogonal basis for the space of functions on $\Boo^{n}_{n/2}$ as stated in \Cref{lemma:bose-mesner-eigenspaces}. Let $\mathds{1}_{S}^{=t}$ denote the component of $\mathds{1}_{S}$ in the $t^{th}$ eigenspace $\mathcal{V}_{n,t}$. We have,
\begin{align*}
    W \mathds{1}_{S} \; = \; \sum_{t=0}^{n/2+1} W \mathds{1}_{S}^{=t} \; = \; \sum_{t=0}^{n/2+1}\lambda_{t} \mathbf{1}_{S}^{=t},
\end{align*}
where for the final equality we used the fact that $\mathds{1}_{S}^{=t}$ is an eigenvector for $W$ (first item of \Cref{lemma:bose-mesner-eigenspaces}). Using this, we have,
\begin{align*}
    \langle \mathds{1}_{S}, \; W \mathds{1}_{S} \rangle \; = \; \left\langle \sum_{t=0}^{n/2+1} \mathds{1}_{S}^{=t}, \; \sum_{t=0}^{n/2+1} \lambda_{t} \mathds{1}_{S}^{=t} \right\rangle \; = \; \sum_{t=0}^{n/2+1} \lambda_{t} \lVert \mathds{1}_{S}^{=t} \rVert_{2}^{2},
\end{align*}
where for the final equality we used the orthogonality of $\mathcal{V}_{n,t}$'s.

\paragraph{}Using the orthogonality $\mathcal{V}_{n,t}$'s, we have,
\begin{align*}
    \lVert T_{\rho} \mathds{1}_{S} \rVert_{2}^{2} \; = \; \sum_{t=0}^{n/2+1} \; \rho^{2t \paren{1 - \frac{t-1}{n}}} \, \lVert \mathds{1}_{S}^{=t} \rVert_{2}^{2}
\end{align*}
Let $\tau := n^{\delta}$ for small enough $\delta > 0$ such that \Cref{lemma:eigenvalue-bound} holds. If we have $\rho = 1/n^{\delta'}$ for a small enough $\delta'$ depending on $\delta$, then for $t \leq \tau$, we have,
\begin{align*}
    \lambda_{t} \, \leq \, \rho^{2t} \, \leq \, \rho^{2t \paren{1 - \frac{t-1}{n}}}
\end{align*}
This implies that for $t \leq \tau$, we have,
\begin{equation}
    \sum_{t=0}^{\tau} \lambda_{t} \lVert \mathds{1}_{S}^{=t} \rVert_{2}^{2} \; \leq \; \sum_{t=0}^{\tau} \; \rho^{2t \paren{1 - \frac{t-1}{n}}} \, \lVert \mathds{1}_{S}^{=t} \rVert_{2}^{2} \; \leq \; \lVert T_{\rho} \mathds{1}_{S} \rVert_{2}^{2}
\end{equation}
For $t > \tau$, we have,
\begin{equation}
    \sum_{t=\tau+1}^{n/2+1} \lambda_{t} \lVert \mathds{1}_{S}^{=t} \rVert_{2}^{2} \; \leq \; \sum_{t=\tau}^{n/2+1} \dfrac{1}{2^{n^{\Omega(1)}}} \lVert \mathds{1}_{S}^{=t} \rVert_{2}^{2} \; \leq \; n \cdot \dfrac{1}{2^{n^{\Omega(1)}}},
\end{equation}
where we upper bounded $\lVert \mathds{1}_{S}^{=t} \rVert_{2}^{2}$ by $1$. Combining these two together, we get,
\begin{align*}
    \sum_{t=0}^{n/2+1} \lambda_{t} \lVert \mathds{1}_{S}^{=t} \rVert_{2}^{2} \; \leq \; \lVert T_{\rho} \mathds{1}_{S} \rVert_{2}^{2} \, + \, \dfrac{n}{2^{n^{\Omega(1)}}}
\end{align*}
Now applying the hypercontractivity theorem for the noise operator $T_{\rho}$, we get,
\begin{align*}
    \lVert T_{\rho} \mathds{1}_{S} \rVert_{2} \; \leq \; \lVert \mathds{1}_{S} \rVert_{p},
\end{align*}
where $1/(p-1) \leq \exp{(c \log 1/\rho)} = \exp{(c \delta' \log n)}$.
We also have that for any $p$, the norm $\lVert \mathds{1}_{S} \rVert_{p}$ is equal to $(|S|/n')^{1/p}$. Using this, we get,
\begin{align*}
     \lVert T_{\rho} \mathds{1}_{S} \rVert_{2}^{2} \; \leq \; \paren{\dfrac{|S|}{n'}}^{2/p} \; = \; \paren{\dfrac{|S|}{n'}}^{2 (1-1/n^{\kappa})},
\end{align*}
for some constant $\kappa$ depending on the constant $c$ from the hypercontractive inequality \Cref{lemma:hypercontractive-log-Sobolev} and $\rho$. Plugging this back in, we have,
\begin{gather*}
    \Pr_{\substack{\mathbf{x} \sim U_{n,n/2} \\ \mathbf{y} \sim W(\mathbf{x}) }}[\mathbf{x} \in S \; \text{ and } \; \mathbf{y} \in S] \; = \; \langle \mathds{1}_{S}, \; W \mathds{1}_{S} \rangle 
    = \; \sum_{t=0}^{n/2+1} \lambda_{t} \lVert \mathds{1}_{S}^{=t} \rVert_{2}^{2}\\ 
    \leq \; \paren{\dfrac{|S|}{n'}}^{2 (1-1/n^{\kappa})} \, + \, \dfrac{1}{2^{n^{\Omega(1)}}} = \paren{\dfrac{|S|}{n'}}^{2}\cdot \left(\paren{\dfrac{|S|}{n'}}^{-2/n^{\kappa}} + \frac{(n'/|S|)^2}{2^{n^{\Omega(1)}}}\right).
\end{gather*}
From the hypothesis of \Cref{lemma:main-informal}, we know that $|S|/n' \geq 4^{-d}$. Using this in the parenthetical term above, we get
\begin{align*}
    \Pr_{\substack{\mathbf{x} \sim U_{n,n/2} \\ \mathbf{y} \sim W(\mathbf{x}) }}[\mathbf{x} \in S \; \text{ and } \; \mathbf{y} \in S] \; \leq \; \paren{\dfrac{|S|}{n'}}^{2}\cdot 
    \left(4^{\bigO(d/n^\kappa)} + \frac{4^{\bigO(d)}}{2^{n^{\Omega(1)}}}
    \right) \;
    \leq \; \paren{\dfrac{|S|}{n'}}^{2} \cdot \paren{1 + \dfrac{1}{n^{\varepsilon}}}.
\end{align*}
for a small enough absolute constant $\varepsilon > 0$ as long as $d\leq n^\gamma$ for a small enough absolute constant $\gamma > 0.$ This concludes the proof of \Cref{lemma:main-informal}.
%Since $d \leq n^{\gamma}$, this means $|S|/n' \geq 4^{-n^{\gamma}(1+o(1))}$. Thus there exists a sufficiently small constant $\varepsilon > 0$ such that $4^{d(1+o(1))} \cdot (1-1/n^{\varepsilon}) \leq 2^{n^{\Omega(1)}}$. Using this, we get
%\begin{align*}
 %   \Pr_{\substack{\mathbf{x} \sim U_{n,n/2} \\ \mathbf{y} \sim W(\mathbf{x}) }}[\mathbf{x} \in S \; \text{ and } \; \mathbf{y} \in S] \; \leq \; \paren{\dfrac{|S|}{n'}}^{2} \cdot \paren{1 + \dfrac{1}{n^{\varepsilon}}}.
%\end{align*}
%This finishes the proof of \Cref{lemma:main-informal} in the regime of $d \leq n^{\gamma}$ for an absolute constant $\gamma > 0$.
\end{proof}


