\begin{thmbox}
\begin{theorem}[Distance lemma over the balanced slice]\label{lemma:balanced-slice}
There exists an absolute constant $\varepsilon > 0$ so that the following holds. Fix an arbitrary Abelian group $G$ and fix a degree parameter $d \in \mathbb{N}$ where $d \leq n^{\varepsilon}$. For every even natural number $n$, and for every non-zero degree-$d$ polynomial $P(\mathbf{x}) \in \mathcal{P}_{d}(n,n/2, G)$,
\begin{align*}
    \Pr_{\mathbf{x} \sim U_{n,n/2}  }[P(\mathbf{x}) \neq 0] \; \geq \; \dfrac{1}{2^{d}} \cdot \paren{1 - \dfrac{1}{n^{\Omega(1)}} }
\end{align*}
\end{theorem}
\end{thmbox}

\begin{proof}[Proof of \Cref{lemma:balanced-slice}]
Letting $S \subseteq \{0,1\}^n_{n/2}$ denote the set of points on the balanced slice on which $P$ evaluates to a non-zero value. From \Cref{lemma:suboptimal-DLSZ-slice}, the set $S$ satisfies the density lower required in \Cref{lemma:main-informal}. Combining~\Cref{lemma:main-informal} and~\Cref{lem:lower-bd}, we obtain
\begin{align*}
    \dfrac{|S|}{\binom{n}{n/2}} \cdot \dfrac{1}{2^d} \le \Pr_{\substack{\mathbf{x} \sim U_{n,n/2} \\ \mathbf{y} \sim W(\mathbf{x})}}[\mathbf{x} \in S \; \text{ and } \; \mathbf{y} \in S] \le \paren{\dfrac{|S|}{\binom{n}{n/2}}}^2 \cdot \paren{1+\frac{1}{n^\varepsilon}},
\end{align*}
 where $\varepsilon$ is a sufficiently small constant. Hence, $|S|/\binom{n}{n/2} \; \ge \; \frac{1}{2^d}\cdot \paren{1-\frac{1}{n^{\Omega(1)}}}$.
\end{proof}


\section{Arbitrary Slices} \label{sec:all-slices}
In this section we prove a distance lemma for slices over arbitrary Abelian groups $G$. As discussed in the proof overview, the proof has three key steps:
\begin{enumerate}
    \item First, we prove a distance lemma over cyclic groups of prime power order for some fixed set of slices, which we refer to as ``good'' slices. We prove this in \Cref{lemma:good-slice-positive-char}.
    \item Secondly, we prove a distance lemma over cyclic groups of prime power order for any slice by reducing it to one of the good slices. We prove this in \Cref{lem:all-slices}.
    \item In the end, we show that any Abelian group can be assumed to be a finitely generated Abelian group. To prove the distance lemma for a finitely generated Abelian group, it suffices to have the distance lemma over cyclic groups of prime power order, which we prove in \Cref{lemma:DLSZ-slice-finite-fields}.
\end{enumerate}

We will start by proving a distance lemma for slices over cyclic groups of prime power order.

\subsection{Cyclic Groups of Prime Power Order}
In this subsection we will prove the distance lemma for slices over $\mathbb{Z}_{p^{\ell}}$ for some prime $p$ and natural number $\ell$. The main result of this subsection is the following lemma.

\begin{thmbox}
\begin{restatable}[Distance lemma for cyclic groups]{lemma}{cyclicgroups}\label{lemma:DLSZ-slice-finite-fields}
There exists an absolute constant $\varepsilon > 0$ so that the following holds. Fix a cyclic group $\mathbb{Z}_{q}$ where $q = p^{\ell}$ for some prime $p$ and a degree parameter $d \in \mathbb{N}$. For all natural numbers $n$ and $k$ such that $1+d\le k^\varepsilon$ and $k\leq n/2$, the following is true.\newline
For a non-zero degree-$d$ polynomial $P: \Boo^{n}_{k} \to \mathbb{Z}_{q}$, 
\begin{align*}
    \Pr_{\mathbf{x} \sim U_{n,k}}[P(\mathbf{x}) \neq 0] \; \geq \; \alpha^{d} \paren{1- \dfrac{1}{k^{\Omega(1)}}}, \quad \quad \text{ where } \alpha := \frac{k}{n}.
\end{align*}
\end{restatable}
\end{thmbox}


We will start with the definition of good slices. The idea is that these slices admit a nice basis which can be used to reduce the problem from a good slice to the balanced slice over a smaller dimensional cube, which we have proved in \Cref{lemma:balanced-slice}.\\

\begin{definition}[Good slices]\label{defn:good-slices}
Fix a prime $p$ and a degree parameter $d \in \mathbb{N}$.
An integer $k\geq d$ is said to be $(d,p)$-\textit{good} if the $p$-ary expansion of $k$ agrees with that of $d$ in all the digits up to the leading digit of $d$, and is greater than equal to $d$ in the leading digit. More formally, if $k = \sum_{j = 0}^m a_j p^j$ and $d = \sum_{j=0}^\ell b_j p^j$ with $a_j, b_j \in \{0,\ldots, p-1\},$ with $b_\ell > 0$, then $a_j = b_j$ for all $j < \ell$ and $a_\ell \geq b_\ell.$
\end{definition}

For a degree parameter $d$, let $\mathcal{H}_{d}$ denote the set of homogeneous monomials in $\set{x_{1},\ldots,x_{n}}$, i.e.
\begin{align*}
    \mathcal{H}_{d} \; = \; \setcond{\prod_{i \in T} x_{i}}{T \subseteq [n], |T| = d}
\end{align*}
Since every $x_{i} \in \Boo$, we only work with multilinear monomials. So for convenience, we will identify monomials with sets and vice-versa and for a set $T \subseteq [n]$, let $x^{T} := \prod_{i \in T} x_{i}$.\newline

\noindent
We will now show that if $k$ is $(d,p)$-good, then the set of degree-$d$ homogeneous multilinear monomials $\mathcal{H}_{d}$ form a `basis' for degree-$d$ polynomials on the $k^{th}$ slice in the following sense.\\

\begin{lemma}
    \label{lem:basis}
    Let $q$ be a power of prime $p$ as above. Fix $n,k,d$ such that $d\le k\leq n-d$ and assume that $k$ is $(d,p)$-good. Then, any function in $\mathcal{P}_d(n,k,\mathbb{Z}_q)$ can be written uniquely as a linear combination of the monomials in $\mathcal{H}_d.$
\end{lemma}

To prove the above lemma, we will first show that there are at least $q^{\binom{n}{d}}$ distinct degree-$d$ polynomial functions on the slice, and then that the monomials in $\mathcal{H}_d$ span all these functions. Since $|\mathcal{H}_{d}|$ is exactly $\binom{n}{d}$, these two statements immediately implies \Cref{lem:basis}. 

We start with the lower bound on $|\mathcal{P}_d(n,k,\mathbb{Z}_q)|.$ The proof is implicit in the work of Wilson \cite{WILSON90}. For the sake of completeness, we give a proof in \Cref{app:wilson-proof}.\\

\begin{restatable}[Number of degree-$d$ polynomials on the slice]{lemma}{degdslicedimension}\label{lem:dim-wilson}
\cite{WILSON90}. For every degree parameter $d \in \mathbb{N}$ and for every slice parameter $k$ such that $d\leq \min\{k,n-k\}$, the number of distinct degree-$d$ polynomial functions on $\Boo^{n}_{k}$ is at least $q^{\binom{n}{d}}$. 
\end{restatable}

We now show that $\mathcal{H}_{d}$ is a spanning set for $\mathcal{P}_d(n,k,\mathbb{Z}_q)$, which is our next claim. This proof is also inspired by~\cite{WILSON90} who proves this in the case when the polynomials have coefficients that are real numbers.

\noindent
\begin{claim}\label{claim:homogeneous-spanning-positive-char}
Fix a cyclic group $\mathbb{Z}_{q}$ where $q$ is a power of prime $p$. Fix a degree parameter $d \in \mathbb{N}$. For all natural numbers $n,k$ such that $d\le k \leq (n-d)$ and $k$ is $(d,p)$-good, the following holds.\newline
The set $\mathcal{H}_{d}$ of homogeneous degree-$d$ monomials is a spanning set for $\mathcal{P}_{d}(n,k,\mathbb{Z}_{q})$.
\end{claim}

\paragraph{Proof Idea:}Every monomial of degree strictly less than $d$ can be expressed as a linear combination of monomials of degree exactly equal to $d$ using the fact that we are working over the slice $\Boo^{n}_{k}$. As we are working over a group of prime power order, we have to be careful about the coefficients arising while expressing lower degree monomials using homogeneous monomials. We will use that $k$ is $(d,p)$-good and Lucas's theorem (\Cref{lemma:lucas}) in a crucial way to argue about the coefficients.\\

\begin{proof}[Proof of \Cref{claim:homogeneous-spanning-positive-char}]
Consider any monomial $\mathfrak{m}$ of degree $0\leq i < d$. For simplicity in notations, assume without loss of generality that $\mathfrak{m} = x_{1} x_{2} \cdots x_{i}$. Let $\mathcal{H}_{d}|_{\mathfrak{m}}$ denote the subset of $\mathcal{H}_{d}$ which is divisible by $\mathfrak{m}$, i.e.
\begin{align*}
    \mathcal{H}_{d}|_{\mathfrak{m}} \; := \; \setcond{x^{T} \in \mathcal{H}_{d}}{\set{1,\ldots,i} \subset T}
\end{align*}
Since every monomial in $\mathcal{H}_{d}|_{\mathfrak{m}}$ is divisible by $\mathfrak{m}$, it is easy to verify that over the slice $\Boo^{n}_{k}$, the following identity holds:
\begin{align*}
    \sum_{x^{T} \in \mathcal{H}_{d}|_{\mathfrak{m}}} x^{T} 
    \; =  \; \mathfrak{m} \sum_{\substack{T' \subseteq [n] \setminus [i] \\ |T'| = d - i}} x^{T'} \; = \; \; \mathfrak{m} \cdot \binom{k - i}{d - i} 
\end{align*} 
To write the monomial $\mathfrak{m}$ as a linear combination of monomials in $\mathcal{H}_{d}$, we need the integer $\binom{k-i}{d-i}$ to be invertible in the ring $\mathbb{Z}_q$. This happens, exactly when $\binom{k-i}{d-i}$ is non-zero modulo the prime $p$.\\

\noindent
Using Lucas's theorem \Cref{lemma:lucas}, we now argue that if the slice $k$ is $(d,p)$-good, then for all $0 \leq i < d$,
\begin{align*}
    \binom{k-i}{d-i} \nequiv 0 \mod{p}
\end{align*}

Let $r = p^{\ell}$ be the smallest power of $p$ strictly greater than $d$. From \Cref{defn:good-slices}, we know that $k \equiv d \mod{p^{\ell}}$. Fix any $0 \leq i \leq (d-1)$. If we represent $(k-i)$ and $(d-i)$ in $p$-ary representation, then, we get,
\begin{align*}
    (d-i) \; = \; \sum_{j = 0}^{\ell-1} b_{j} p^{j} + \sum_{j = \ell}^{m} 0 p^{j}, \quad \quad \quad
    (k-i) \; = \; \sum_{j = 0}^{\ell-1} a_{j} p^{j} + \sum_{j = \ell}^{m} a_{j} p^{j}
\end{align*}
One can verify that $a_{j} = b_{j}$ for all $0\leq j \leq (\ell-2)$ and $a_{\ell - 1}  \geq b_{\ell - 1}$.\footnote{This is true by assumption for $i=0.$ The fact that it is also true when $i > 0$ follows from elementary properties of subtraction.} Thus by Lucas's theorem \Cref{lemma:lucas}, $\binom{k-i}{d-i} \nequiv 0 \mod{p}$. This concludes our proof that a degree strictly less than $d$ monomial can be expressed as a linear combination of monomials in $\mathcal{H}_{d}$.
% \paragraph{If $p$ is atleast $d$}From \Cref{defn:good-slices}, we know that $k \mod{p} \geq d$. Fix any $0 \leq i < d$. If we represent $(k-i)$ and $(d-i)$ in $p$-ary representation, then, we get,
% \begin{align*}
%     (d-i) \; = \; b_{0} p^{0} + b_{1} p^{1} + \sum_{j = 2}^{m} 0 p^{j}, \quad \quad \quad
%     (k-i) \; = \; a_{0} p^{0} + a_{1} p^{1} + \sum_{j = 2}^{m} a_{j} p^{j}
% \end{align*}
% One can verify that $a_{0} = b_{0}$ and $a_{1} \geq b_{1}$. Thus by Lucas's theorem \Cref{lemma:lucas}, $\binom{k-i}{d-i} \nequiv 0 \mod{p}$, and this handles the first case.
\end{proof}

Note that \Cref{lem:dim-wilson} and \Cref{claim:homogeneous-spanning-positive-char} together imply \Cref{lem:basis}.

Now we are ready to prove the following distance lemma for degree-$d$ polynomials for good slices.\newline
The proof will be by a random restriction, which allows us to reduce to the case of \Cref{lemma:balanced-slice}. It random restriction sets a uniformly random set of $(n-2k)$ variables to $0$ (i.e. we are reducing from $\Boo^{n}_{k}$ to $\Boo^{2k}_{k}$). The main step is to argue that a non-zero polynomial on the $k^{th}$ slice continues to be a non-zero polynomial on the balanced slice (in a smaller dimension) with good enough probability. For this, we use $\mathcal{H}_{d}$ as a basis $\mathcal{P}_{d}(n,k,\mathbb{Z}_{q})$ for good slices.\\

\noindent
\begin{thmbox}
\begin{lemma}[Distance Lemma over good slices]\label{lemma:good-slice-positive-char}
There exists an absolute constant $\gamma > 0$ so that the following holds.
Fix a cyclic group $\mathbb{Z}_{q}$ where $q$ is a power of a prime number $p$. Fix a degree parameter $d \in \mathbb{N}$. For all natural numbers $n,k$ such that $1+d\le k^\gamma$ and $k\leq n/2$ and $k$ is $(d,p)$-good, the following holds.\newline
For every non-zero degree-$d$ polynomial $P(\mathbf{x}) \in \mathcal{P}_{d}(n,k,\mathbb{Z}_{q})$, 
\begin{align*}
    \Pr_{\mathbf{x} \sim U_{n,k}}[P(\mathbf{x}) \neq 0] \; \geq \; \alpha^{d}\paren{1  - \dfrac{1}{k^{\Omega(1)}}}, \text{ where } \alpha := \dfrac{k}{n}
\end{align*}
\end{lemma}
\end{thmbox}
\begin{proof}[Proof of \Cref{lemma:good-slice-positive-char}]
We start by describing the random process to reduce the problem from $k^{th}$ slice to the balanced slice in a smaller dimension cube.

\paragraph{\underline{Random process and the new polynomial}}Sample a random subset $T \subseteq [n]$ of size exactly $2k$ and set all the variables NOT in $T$ to $0$. Let $\Tilde{P}(y_{1},\ldots,y_{2k})$ be the resulting polynomial in $2k$ variables.\footnote{We identify the elements in $T$ with $[2k]$ in a canonical way.} Note that $\deg(\Tilde{P}) \leq \deg(P) = d$.\\
We will now argue that if $P(x_{1},\ldots,x_{n})$ is a non-zero degree-$d$ polynomial in $\mathcal{P}_{d}(n,k,\mathbb{Z}_{q})$, then $\Tilde{P}(y_{1},\ldots,y_{2k})$ is a non-zero degree-$d$ polynomial in $\mathcal{P}_{d}(2k,k,\mathbb{Z}_{q})$ with some good enough probability.\\
\begin{claim}\label{claim:non-zero-most-vars-killed}
Let $P(\mathbf{x}) \in \mathcal{P}_{d}(n,k,\mathbb{Z}_{q})$ be a non-zero polynomial. Then $\Tilde{P}$, as defined above, is a non-zero polynomial over $\Boo^{2k}_{k}$ with probability at least $(2k/n)^{d} \cdot (1 - (d^{2}/2k))$ over the randomness of set $T$.
\end{claim}

\begin{proof}[Proof of \Cref{claim:non-zero-most-vars-killed}]
Firstly, represent the polynomial $P(x_{1},\ldots,x_{n})$ as a unique linear combination of monomials in $\mathcal{H}_{d}$ using \Cref{claim:homogeneous-spanning-positive-char}. Let $\mathfrak{m}$ be a monomial in $\mathcal{H}_{d}$ which has a non-zero coefficient in the polynomial $P(\mathbf{x})$. Assume without loss of generality that $\mathfrak{m} = x_{1} x_{2} \cdots x_{d}$. The probability over the choice of $T$ that $\set{1,\ldots,d} \subset T$ is:
\begin{align*}
\displaystyle\binom{n-d}{2k-d}/\displaystyle\binom{n}{2k}
\end{align*}
Since $d \leq 2k \leq n$, we have the following inequality:
\begin{align*}
    \displaystyle\binom{n-d}{2k-d} \; \geq \; \displaystyle\binom{n}{2k} \cdot \paren{\dfrac{2k-d}{n-d}}^{d}
\end{align*}
Using the inequality $(1-x)^{m} \geq (1 - mx)$ and upper bounding $(n-d)^{d}$ by $n^{d}$, we get the following inequality:
\begin{align*}
    \displaystyle\binom{n-d}{2k-d} \; \geq \; \paren{\dfrac{2k}{n}}^{d} \cdot \paren{1 - \dfrac{d^{2}}{2k}}
\end{align*}
By \Cref{lem:basis}, the probability of $\Tilde{P}$ is a non-zero polynomial function over $\Boo^{2k}_{k}$ is at least the probability that the monomial $\mathfrak{m}$ has non-zero coefficient in $\Tilde{P}$, and this is at least $(2k/n)^{d} \cdot (1-(d^{2}/2k))$. This finishes the proof of \Cref{claim:non-zero-most-vars-killed}.
\end{proof}

Note that if $\Tilde{P}(\Tilde{\mathbf{a}}) \neq 0$ for some $\Tilde{\mathbf{a}} \in \Boo^{2k}_{k}$, then $P(\mathbf{a}) \neq 0$ where $\mathbf{a}$ is obtained from $\Tilde{\mathbf{a}}$ and fixing the coordinates not in $T$ to $0$. It is also easy to see that for a random choice of $T$, if $\Tilde{\mathbf{a}} \sim U_{2k,k}$, then the corresponding $\mathbf{a} \sim U_{n,k}$. Thus we get,
\begin{align*}
    \Pr_{\mathbf{x} \sim U_{n,k}}[P(\mathbf{x}) \neq 0] \; \geq & \; \Pr_{T}[\Tilde{P} \; \text{ doesn't vanish on } \; \Boo^{2k}_{k}]\\ &~~~~~\cdot ~\Pr_{\mathbf{y} \sim U_{2k,k}}[\Tilde{P}(\mathbf{y}) \neq 0~|~\Tilde{P} \; \text{ doesn't vanish on } \; \Boo^{2k}_{k}] .
\end{align*}
By using $d\le k^{\varepsilon'}$ for sufficiently small $\varepsilon'$ and applying the distance lemma for the balanced slices \Cref{lemma:balanced-slice} on $\Tilde{P} \in \mathcal{P}_{d}(2k,k,d)$ and \Cref{claim:non-zero-most-vars-killed}, we get,
\begin{align*}
    \Pr_{\mathbf{x} \sim U_{n,k}}[P(\mathbf{x}) \neq 0] \; \geq \; \frac{1}{2^d}\paren{1 - \dfrac{1}{k^{\Omega(1)}}} \cdot  \paren{\dfrac{2k}{n}}^{d} \cdot \paren{1 - \dfrac{d^{2}}{2k}} \;
    \geq \; \paren{\dfrac{k}{n}}^{d}\paren{1 - \dfrac{1}{k^{\Omega(1)}}}.
\end{align*}
 This finishes the proof of \Cref{lemma:good-slice-positive-char}.
\end{proof}



Now we will show how to reduce a non-good slice to a good slice by randomly fixing some $\bigO(d)$ many variables to $1$. We will prove the following lemma.\newline

\begin{lemma}[Reducing any slice to a good slice]
    \label{lem:all-slices} Fix a cyclic group $\mathbb{Z}_{q}$ where $q$ is a power of a prime number $p$, a degree parameter $d \in \mathbb{N}$. Let $n$ and $k\in [n^{1/3},n/2]$ be positive integers, and let $0\le c \le 2d \le k^{\varepsilon}$ for a sufficiently small constant $\varepsilon>0$. Let $\beta \in (0,(k/n)^d)$ be such that for every non-zero polynomial $Q({\bf x}) \in \cP_d(n-c,k-c,\Z_q)$, it holds that
         \begin{align*}
            \Pr_{{\bf x} \sim U_{(n-c),(k-c)}}[Q({\bf x}) \ne 0] \ge \beta.
    \end{align*}
     Then for every non-zero polynomial $P({\bf x}) \in \cP_d(n,k,\Z_q)$, it holds that
    \begin{align*}
        \Pr_{{\bf x} \sim U_{n,k}}[P({\bf x}) \ne 0] \ge \beta \paren{1 -  {\dfrac{c}{{n^{0.1}}}}}.
    \end{align*}
\end{lemma}

Together with~\Cref{lemma:good-slice-positive-char}, this completes the proof of \Cref{lemma:DLSZ-slice-finite-fields} as shown below. We recall the statement first.\\

\begin{thmbox}
\cyclicgroups*
\end{thmbox}

\begin{proof}[Proof of~\Cref{lemma:DLSZ-slice-finite-fields}]  
We first argue that we can assume that $k\ge n^{1/3}$. Otherwise,~\Cref{lemma:suboptimal-DLSZ-slice} suffices to give us the desired bound. Indeed, if $k \le n^{1/3}$, we have
$$\frac{{{n-2d}\choose k-d}}{{n\choose k}} \ge \paren{\frac{k-d}{n}}^d\paren{\frac{n-2k}{n}}^d \ge \paren{\frac{k}{n}}^d\paren{1-\frac{d^2}{k}}\paren{1-\frac{2kd}{n}}\ge \paren{\frac{k}{n}}^d \paren{1-\frac{1}{k^{\Omega(1)}}}.$$

Hence, for the rest of the proof, we will assume that $k\le n^{1/3}$. We show below that it suffices to show that for every slice $k > d$, there exists $c\in [0,2d]$ such that the slice $(k-c)$ is $(d,p)$-good (see \Cref{defn:good-slices}). Assuming this, the premise of \Cref{lem:all-slices} is true with 
\begin{align*}
    \beta = \paren{\frac{k-c}{n-c}}^d \, \paren{1-  \, \dfrac{1}{(k-c)^\gamma}},
\end{align*}
for some constant $\gamma \in (0,1)$, by the distance lemma for good slices (\Cref{lemma:good-slice-positive-char}). 

The conclusion of~\Cref{lem:all-slices} then implies that
    \begin{align*}
        \Pr_{{\bf x}\sim U_{n,k}}[P({\bf x}) \ne 0] \; \geq \; \bigg(\frac{k-c}{n-c}\bigg)^d\paren{1-\frac{1}{(k-c)^\gamma}}\paren{1-\frac{c}{n^{0.1}}} \ge\paren{\frac{k}{n}}^d \paren{1- \frac{1}{k^{\Omega(1)}}},
    \end{align*} using $d\le k^{\varepsilon}$ and $c\le 2d$.
    Hence, it only remains to show that there exists a $c\in [0,2d]$ such that the slice $(k-c)$ is $(d,p)$-good.

     \noindent
    Let $d=\sum_{j=0}^\ell b_j p^j$ and $k=\sum_{j=0}^m a_j p^j$ be the $p$-ary representations of $d$ and $k$ respectively, with $b_\ell, a_m >0$ and $m \ge \ell$ (since $k \ge d$). We first note that for $c_1 \in [0,p^\ell-1]$ such that $c_1 \equiv k-d \mod{p^\ell}$, we have $k_1 := k-c_1 \equiv d \mod{p^\ell}.$ Or equivalently for $k_1 = \sum_{j=0}^m u_j p^j$ in $p$-ary representation, we have
     \begin{align}
        \label{eqn:cond-1}
        u_j = b_j,\text{~for all~}j<\ell.
     \end{align}
     We now show that there exists a $c_2 \in [0,d]$ such that when $k_2 := k_1-c_2$ is expressed in its $p$-ary representation as $k_2 = \sum_{j=0}^{m} v_j p^j$, it holds that $v_\ell \ge b_\ell$ and $v_j = u_j$, for all $j<\ell$. We have two cases:
     \begin{itemize}
        \item {\bf Case 1: $u_\ell \ge b_\ell$.} In this case, we can take $c_2=0$ and $k_2=k_1$.
        \item {\bf Case 2: $u_\ell < b_\ell$.} We take $c_2=(u_\ell+1)p^\ell \le b_\ell\cdot p^\ell \le d$. In this case, the $p$-ary representation of $k_2$ as described above satisfies $v_j = u_j$ for all $j < \ell$ and $v_\ell = p-1.$
     \end{itemize}
     Taking $c=c_1+c_2$, we see that $k_2=k-c$ is indeed $(d,p)$-good, with $c \le 2d$.

     This finishes the proof of \Cref{lemma:DLSZ-slice-finite-fields}.
\end{proof}

We now prove \Cref{lem:all-slices}.

\begin{proof}[Proof of~\Cref{lem:all-slices}]
    Note that the proof is trivial for $c=0$. We will now show the lemma for $c\ge 1$. Consider the following way of sampling a point ${\bf x}$ from $U_{n,k}$. 

    \begin{enumerate}
        \item Initialize $S=\emptyset$.
        \item Choose $s \in [n]\setminus S$ uniformly at random, set $x_{s} = 1$, and add $s$ to $S$.
        \item Repeat Step 2 until $|S|=c$. 
        \item Set the co-ordinates of $\mathbf{x}$ not in $S$ according to the distribution $U_{n-c,k-c}$.
        \item Output ${\bf x}$.
    \end{enumerate}

    Let $P_1\in \cP_d(n-1,k-1,\Z_q),P_2\in \cP_d(n-2,k-2,\Z_q),\dots,P_c\in \cP_d(n-c,k-c,\Z_q)$ be the restrictions of the polynomial $P$ on the respective domains obtained by setting $x_{s_1}=1$, $x_{s_2}=1,\dots,x_{s_c}=1$ successively by the above random procedure, so that $S=\{s_1,s_2,\dots,s_c\} \in {[n] \choose c}$. 

    We claim that $P_1$ is non-zero on $\{0,1\}^{n-1}_{k-1}$, with high probability over the choice of $s_1$. To prove this, let us call an index $s\in [n]$ ``bad'' if for all ${\bf a}\in \{0,1\}^n_k$ such that $a_s=1$, we have that $P({\bf a})=0$. We observe that the probability of $P_1$ being entirely zero over $\{0,1\}^{n-1}_{k-1}$ is equal to the probability of a uniformly random $s \in [n]$ being bad. We show below that the number of such bad indices $s \in [n]$ is at most $\ell:=\lfloor{n/\sqrt{k}}\rfloor $. Towards a contradiction, suppose there are some $\ell$ bad indices $i_1,i_2,\dots,i_\ell \in [n]$. This means that if at least one of these co-ordinates takes value 1, $P({\bf x})$ evaluates to $0$. Thus the number of non-zeroes of $P$ in $\{0,1\}^n_k$ is upper bounded by the number of points that take the value $0$ on all these bad indices, i.e., ${n-\ell \choose k}$. However, by the weak distance lemma (\Cref{lemma:suboptimal-DLSZ-slice}), we know that the number of non-zeroes has to be at least ${n-2d \choose k-d}$. This yields a contradiction as we have ${n-\ell \choose k} < {n-2d \choose k-d}$ by the following claim. 

    \begin{claim}
        \label{clm:non-roots} 
        For every sufficiently large integer $n$ and arbitrary integers $k\in [n^{1/4},n/2]$, $d\in [1, k^{0.1}]$, and $\ell = \lfloor{n/\sqrt{k}}\rfloor$, we have
         $${n-\ell \choose k} < {n-2d \choose k-d}.$$
    \end{claim}
    \begin{proof}
        We have $${n-\ell \choose k} \le {n-2d \choose k}\cdot \bigg(1-\frac{k}{n}\bigg)^{\ell -2d} < {n-2d\choose k-d}\cdot n^d \cdot \bigg(1-\frac{k}{n}\bigg)^{\ell -2d}.$$ Hence, it suffices to show that $(1-\frac{k}{n})^{\ell-2d}\le \frac{1}{n^d}$. Using $\ell - 2d \ge n/(4\sqrt{k})$, indeed we have that $(1-\frac{k}{n})^{\ell-2d} \le (1-\frac{k}{n})^{n/(4\sqrt{k})} \le e^{-{\sqrt{k}/4}} \le \frac{1}{n^d}$, using $d\le k^{0.1}$ and $k \ge n^{1/4}$.
    \end{proof}
    By using the notation $P' \notequiv 0$ to denote that a polynomial $P'\in \cP_d(n',k',\Z_q)$ has at least one non-zero evaluation over the underlying slice,
    we have $$\Pr_{s_1 \sim [n]}[P_1 \notequiv 0] \ge 1-\frac{\ell}{n} \ge 1-\frac{1}{\sqrt{k}} \ge 1-\frac{1}{n^{1/6}}.$$

    By the same argument for $P_2,\dots,P_c$, we get with probability at least $1-\frac{1}{(n-1)^{1/6}}$ (over the choice of $S$), that $P_c$ has at least one non-zero evaluation over $\{0,1\}^{n-c}_{k-c}$. Here, we note that we will need to show that~\Cref{clm:non-roots} is also applicable if we replace $n$ and $k$ with $n-i$ and $k-i$ for every $i\in [c]$; this follows as $c \le 2d\le k^{\varepsilon}$, so $d\le (k-i)^{0.1}$ and $k-i \in [(n-i)^{1/4},(n-i)/2]$. Hence, at each step $i\in [1,c-1]$, conditioned on $P_i$ being non-zero over $\{0,1\}^{n-i}_{k-i}$, we get that $P_{i+1}$ is non-zero over $\{0,1\}^{n-i-1}_{k-i-1}$ with probability at least $1-\frac{1}{(n-i)^{1/6}} \ge 1-\frac{1}{n^{0.1}}$.


    Finally, applying the premise of the lemma statement (\Cref{lem:all-slices}) for $Q=P_c$, we get the desired bound. More formally, we obtain \\
    \begin{align*}   
        \Pr_{{\bf x}\sim U_{n,k}}[P({\bf x}) \ne 0] & \ge \Pr_{s_1 \sim [n]}[P_1 \notequiv 0] \cdot \Pr_{s_2 \sim [n]\setminus \{s_1\}}[P_2 \notequiv 0~\mid~P_1 \notequiv 0] \cdot \dots \\ &~~~~~~~\dots \cdot \Pr_{s_c \sim [n]\setminus \{s_1,\dots,s_{c-1}\}}[P_c \notequiv 0~|~P_{c-1} \notequiv 0] \cdot \Pr_{{\bf y}\sim U_{n-c,k-c}}[P_c({\bf y})\ne 0~\mid~P_c \notequiv 0]\\
        & \ge \bigg(1-\frac{1}{n^{0.1}}\bigg)^{c} \cdot \beta\\
        & \ge \beta \paren{1- \frac{c}{n^{0.1}}}.
    \end{align*}
    This concludes the proof of~\Cref{lem:all-slices}.
\end{proof}


\subsection{General Abelian Groups}\label{ssec:general-proof}
In this subsection, we use the distance lemma for slices over cyclic groups of prime power order \Cref{lemma:DLSZ-slice-finite-fields} to get a distance lemma for slices over arbitrary Abelian groups. We prove \Cref{thm:main} now.

\begin{proof}[Proof of \Cref{thm:main}]
By negating all the variables if necessary, we can assume that $k\leq n/2$. Let $P(\mathbf{x}) \in \mathcal{P}_{d}(n,k,G)$ be the following polynomial:
\begin{align*}
    P({\bf x}) = \sum_{\substack{I \subseteq [n] \\ |I| \leq d}} a_I \cdot x^I,
\end{align*}
where $x^{I} := \prod_{j \in I} x_{j}$. We first argue that it suffices to prove \Cref{thm:main} for \textbf{finite} Abelian groups. Then we will use the fundamental theorem of finite Abelian groups and our distance lemma for cyclic groups (\Cref{lemma:DLSZ-slice-finite-fields}) to finish the proof.

\paragraph{\underline{Reducing to finitely generated Abelian groups}}
Define $G'$ to be the subgroup of $G$ generated by the coefficients of $P$, i.e.
\begin{align*}
    G' =  \left\langle \setcond{a_I}{I \subseteq [n], |I| \leq d} \right\rangle
\end{align*}
Observe that we can treat the polynomial $P(\mathbf{x})$ as a degree-$d$ polynomial over the group $G'$ with a non-zero evaluation on the slice $\{0,1\}^n_k$, i.e. $P(\mathbf{x}) \in \mathcal{P}_{d}(n,k,G')$. Thus we have reduced to the case of finitely generated Abelian groups. Using the structure theorem of finitely generated Abelian groups, we know that $G'$ is isomorphic to 
\begin{align*}
    G' \; \cong \; \Z_{p_1^{\ell_1}} \times \dots \times \Z_{p_s^{\ell_s}}\times \Z^r
\end{align*}
for some prime numbers $p_1,\dots,p_s$, positive integers $\ell_1,\dots,\ell_s$ and $r\in \Z_{\ge 0}$.

\paragraph{\underline{Reducing to finite Abelian groups}}We now show that there exists a \emph{finite} Abelian group $G''$ and a polynomial $P'' \in \cP_d(n,k,G'')$ such that the following holds:
\begin{align*}
    \Pr_{{\bf x} \sim U_{n,k}}[P({\bf x}) \ne 0] = \Pr_{{\bf x} \sim U_{n,k}}[P''({\bf x}) \ne 0]
\end{align*}
If $r=0$, we can take $G'' = G'$ and we are done.\newline
Otherwise, let $M$ be a prime number greater than the absolute values of the last $r$ co-ordinates (using the isomorphism between $G$ and $\Z_{p_1^{\ell_1}} \times \dots \times \Z_{p_s^{\ell_s}}\times \Z^r $) of the evaluations $P({\bf x})$ for all ${\bf x} \in \{0,1\}^n_k$. Then, we take $G'' := \Z_{p_1^{\ell_1}} \times \dots \times \Z_{p_s^{\ell_s}}\times \Z_M^r $. Let $a_{I} = (a_{I}(1),\ldots,a_{I}(s+r)) \in G'$ be a coefficient of $P(\mathbf{x})$. Define the coefficient $a''_{I} \in G''$ as follows:
\begin{align*}
    a''_{I} \, := \, (a_I(1),a_I(2),\dots,a_I(s), a_I(s+1) \mod M, \dots, a_I(s+r) \mod M)
\end{align*}
Now define the polynomial $P''(\mathbf{x})$ as follows:
\begin{align*}
    P''({\bf x}) = \sum_{\substack{I \subseteq [n] \\ |I| \leq d}} a''_I \cdot x^I,
\end{align*}
where $x^{I} := \prod_{j \in I} x_{j}$. For every ${\bf x} \in \{0,1\}^n_k$.
we have that $P({\bf x}) = 0 \iff P''({\bf x}) = 0$, since by the definition of $M$, the last $r$ co-ordinates of $P({\bf x})$ can only take values strictly in between $-M$ and $M$. Thus we have reduced to finite Abelian group $G''$.

\paragraph{\underline{Cyclic groups of prime power order}}We will now argue that we can further reduce it to the case of cyclic groups of prime power order. For simplicity of notation, let the primes $p_{s+1} = \dots = p_{s+r} = M$, exponents $\ell_{s+1} = \dots = \ell_{s+r} = 1$. We thus have $G'' \cong \mathbb{Z}_{p_{1}^{\ell_{1}}} \times \cdots \times \mathbb{Z} _{p_{s+r}^{\ell_{s+r}}}$ and $P''({\bf x}) \in \cP_{d}(n,k,G'')$ is non-zero on $\{0,1\}^n_k$.
This means that there exists $j \in [s+r]$ such that the polynomial $P''(\mathbf{x})$ is a non-zero degree-$d$ polynomial on $\Boo^{n}_{k}$ over the cyclic group $\mathbb{Z}_{p_{j}^{\ell_{j}} }$.\\

Using \Cref{lemma:DLSZ-slice-finite-fields}, we know there exists a constant $\varepsilon$ such that $P''(\mathbf{x})$ is non-zero on at least $\alpha^{d}(1 - \bigO(1/k^{\varepsilon})) \cdot \binom{n}{k}$ points  over the cyclic group $\mathbb{Z}_{p_{j}^{\ell_{j}} }$ where $\alpha = k/n$. This implies that the polynomial $P''(\mathbf{x})$ is non-zero on at least $\alpha^{d}(1 - \bigO(1/k^{\varepsilon})) \cdot \binom{n}{k}$ points over the group $G''$. As we argued above, this in particular implies that the polynomial polynomial $P(\mathbf{x})$ is non-zero on at least $\alpha^{d}(1 - \bigO(1/k^{\varepsilon}))$ fraction of points on the slice $\Boo^{n}_{k}$ over the Abelian group $G$. This finishes the proof of \Cref{thm:main}.
\end{proof}




\section{Low-degree Functions Over Slices}\label{sec:junta}
In this section we will give a simple proof of a lemma of Filmus and Ihringer~\cite{Filmus-Ihringer19} following the proof idea of Nisan and Szegedy~\cite{Nisan-Szegedy}. We will first give a couple of definitions and set the notations for this section.\\

\noindent
For a function $f(x_{1},\ldots,x_{n})$ on the slice $\Boo^{n}_{k}$ with coefficients in $\mathbb{R}$, and for any two coordinates $i,j \in [n] \times [n]$, define $f^{(ij)}$ to be the function where we swap the $i^{th}$ variable with the $j^{th}$ variable in the function $f$.\newline
\begin{definition}[Influence]\label{defn:influence}
Let $f:\Boo^{n} \to \mathbb{R}$ be a function on the slice $\Boo^{n}_{k}$. For $(i,j) \in [n] \times [n]$, the $(i,j)^{th}$-influence of $f$, denoted by $\mathrm{Inf}_{ij}(f)$, is defined as,
\begin{align*}
    \mathrm{Inf}_{ij}(f) \; := \; \dfrac{1}{4} \; \Pr_{\mathbf{x} \sim U_{n,k}}[f(\mathbf{x}) \neq f^{(ij)}(\mathbf{x})]
\end{align*}
The total influence of $f$, denoted by $\mathrm{Inf}(f)$, is defined as,
\begin{align*}
    \mathrm{Inf}(f) \; := \; \dfrac{1}{n} \sum_{1 \leq i < j \leq n} \mathrm{Inf}_{ij}(f)
\end{align*}
\end{definition}
Note that if $i = j$ in the above definition, then $\mathrm{Inf}_{ii}(f) = 0$ and it does not contribute anything towards the total influence.\\

A key lemma in the proof of \cite{Filmus-Ihringer19} is a lower bound on every non-zero influence (see \cite[Lemma 3.1]{Filmus-Ihringer19}). They showed that there exists a constant $\alpha$ such that every non-zero influence of a degree-$d$ polynomial on the balanced slice is at least $\alpha^{d}$. The proof of this lemma in~\cite{Filmus-Ihringer19} uses analytic techniques such as the Log-Sobolev inequality on the Boolean slice~\cite{LeeYau} and the Hypercontractive inequality~\cite{DiaconisSaloffCoste}. Using our distance lemma for the balanced slices (\Cref{lemma:balanced-slice}), we can improve the lower bound to almost $1/2^{d}$ (which is easily seen to be tight up to constant factors). Note that the main result of this section only holds for degree $d \leq C \log n$ for some absolute constant $C > 0$, it suffices to use the simpler proof of \Cref{lemma:balanced-slice}. We state the lemma below.\\

\begin{thmbox}
\begin{lemma}[Lower bound on influences]\label{lemma:influence-lower-bound}
Let $f(x_{1},\ldots,x_{n})$ be a non-zero degree-$d$ function on the balanced slice $\Boo^{n}_{n/2}$. Then for every $(i,j) \in [n] \times [n]$ for which $\mathrm{Inf}_{ij}(f) > 0$, the following holds:
\begin{align*}
    \mathrm{Inf}_{ij}(f) \; \geq \;  \dfrac{1}{4} \cdot \dfrac{1}{2^{d}} \cdot \paren{1 - \dfrac{1}{n^{\varepsilon}}}
\end{align*}
for some absolute constant $\varepsilon > 0.$
\end{lemma}
\end{thmbox}

\begin{proof}
Fix some pair $(i,j) \in [n] \times [n]$ with $\mathrm{Inf}^{(ij)}(f) > 0$ and consider the polynomial $g_{ij}$ on the balanced slice, defined as follows: $g_{ij}(\mathbf{x}) := f(\mathbf{x}) - f^{(ij)}(\mathbf{x})$.\newline
Observe that since $f$ is a degree-$d$ polynomial, $f^{(ij)}$ is also a degree-$d$ polynomial, which means $g_{ij}$ is also a degree-$d$ polynomial on the balanced slice. Since the influence $\mathrm{Inf}_{ij}(f) > 0$, this means that $g_{ij}$ is non-zero on the slice $\Boo^{n}_{n/2}$. Now using our distance lemma on the balanced slice \Cref{lemma:balanced-slice},
\begin{gather*}
    \Pr_{\mathbf{x} \sim U_{n,n/2}}[f(\mathbf{x}) \neq f^{(ij)}(\mathbf{x})] \; = \; \Pr_{\mathbf{x} \sim U_{n,n/2}}[g_{ij}(\mathbf{x}) \neq 0] \; \geq \; \dfrac{1}{2^{d}} \cdot \paren{1 - \dfrac{1}{n^{\varepsilon}}} \\
    \Rightarrow \mathrm{Inf}_{ij}(f) \; \geq \;  \dfrac{1}{4} \cdot \dfrac{1}{2^{d}} \cdot \paren{1 - \dfrac{1}{n^{\varepsilon}}}
\end{gather*}
for some absolute constant $\varepsilon > 0.$
\end{proof}

Filmus and Ihringer \cite[Lemma 3.3]{Filmus-Ihringer19} use this lower bound on non-zero influences to get a bound on junta of degree-$d$ polynomials on the balanced slice. Using the above-mentioned improved lower bound on non-zero influence, we can also improve the bounds in \cite[Lemma 3.3]{Filmus-Ihringer19}.\\

\begin{lemma}\label{lem:improved-FI}
There exists an absolute constant $C > 0$ such that for all degree parameters $d \in \mathbb{N}$ such that $d \leq C \log n$, the following holds. Every degree-$d$ polynomial on the slice $\Boo^{n}_{n/2}$ is a $\eta(d)$-junta, where
\begin{align*}
    \eta(d) = \bigO(d \cdot 2^{d}).
\end{align*}
\end{lemma}
\begin{proof}
The proof is essentially the same proof as in \cite{Filmus-Ihringer19}, except for one inequality which can be improved using \Cref{lemma:influence-lower-bound}. Let $f(\mathbf{x}) \in \mathcal{P}_{d}(n,n/2,\mathbb{R})$ and let $G$ be a graph on the vertex set $[n]$ where $(i,j)$ is an edge if $\mathrm{Inf}_{ij}(f) \geq 1/2^{d} \cdot (1 - 1/n^{\varepsilon})$, where $\varepsilon$ is the absolute constant from \Cref{lemma:influence-lower-bound}. Let $M$ be a maximal matching in $G$. We now proceed similar to the proof in \cite[Lemma 3.3]{Filmus-Ihringer19} and we request the reader to refer \cite{Filmus-Ihringer19} as we just highlight the changes in the proof here.

Using \Cref{lemma:influence-lower-bound}, we get the following two inequalities upper and lower bounding the influence:
\begin{gather*}
    \paren{\dfrac{1}{4} \cdot \dfrac{1}{2^{d}} \cdot \paren{1 - \dfrac{1}{n^{\varepsilon}}} } \cdot \paren{1 - \dfrac{1}{n}} \cdot M \; \leq \; \mathrm{Inf}(f) \; \leq \; d \\
    \Rightarrow M \leq \bigO(d \cdot 2^{d}),
\end{gather*}
where we used the assumption $d \leq C \log n$ in upper bounding $1/n^{\varepsilon}$ by $\frac{1}{10} \cdot \frac{1}{2^{d}}$. Following the argument of~\cite{Filmus-Ihringer19}, this gives us that $f$ is a $2M$-junta, i.e., a $\bigO(d\cdot 2^d)$-junta.
\end{proof}

As already noted in the introduction, a stronger upper bound of $\eta(d) = \bigO(2^d)$ follows from the work of~\cite{Filmus-Ihringer19, CHS-20} (and can also be obtained by plugging \Cref{lemma:influence-lower-bound} in place of \cite[Lemma 3.3]{Filmus-Ihringer19} in the proof of~\cite{Filmus-Ihringer19}). The advantage here is the relatively simple proof following exactly the template of~\cite{Nisan-Szegedy}.

\section{Improved Bound for Linear Functions}
\label{sec:deg1}

In this section, we show how to obtain an improvement over our distance lemma (\Cref{thm:main}) for the case of linear polynomials, i.e., $d=1$. In particular, we will show the following.\\

\begin{thmbox}
\begin{theorem}
    \label{thm:deg1} Let $G$ be an arbitrary Abelian group, and $n\ge 8$ and $k \in [n-1]$ be positive integers. Then, for every polynomial $P({\bf x}) \in \cP_1(n,k,G)$ that is non-zero on $\{0,1\}^n_k$, we have
    $$\Pr_{{\bf x}\sim \{0,1\}^n_k}[P({\bf x}) \ne 0] \ge \frac{t-1}{n},$$ where $t = \min\{k,n-k\}$.
\end{theorem}
\end{thmbox}

This is an improvement over~\Cref{thm:main} as we have an additive term of $1/n$ as opposed to $1/n^\varepsilon$ for some constant $\varepsilon \in (0,1)$. In particular, in the regime $k\leq n^\delta$ for small enough $\delta \in (0,1)$, the above theorem gives a lower bound of $1/n^{1-\delta}$, while~\Cref{thm:main} fails to give anything non-trivial.

We note that this is also an improvement over the weak distance lemma shown by~\cite{ABPSS25-ECCC} (i.e.,~\Cref{lemma:suboptimal-DLSZ-slice}) as it gives a lower bound of $\frac{k(n-k)}{n(n-1)}$ which is less than $\frac{k-1}{n}$ for $k \ge \sqrt{n}+1$. In particular, taking $P({\bf x}) = x_1$, we see that our bound is almost tight. Furthermore, the additive term of $1/n$ in the above theorem cannot be avoided (at least for $k=n/2$ and up to a constant factor) as the polynomial $P({\bf x}) = x_1+x_2+1$ in $\cP_1(n,k=n/2,\Z_2)$ which is non-zero with probability $\frac{1}{2}-\frac{1}{2(n-1)}$.  



We will now prove~\Cref{thm:deg1}.

\begin{proof}[Proof of~\Cref{thm:deg1}]
   Let $P({\bf x}) = a_1 x_1 + a_2 x_2 + \dots + a_n x_n + c$, where $a_1,\dots,a_n, c \in G$. We may (and we will) assume that $a_1,a_2,\dots,a_n$ are not all equal (abbreviated as NAE from now), as otherwise the polynomial always evaluates to a constant over $\{0,1\}^k$ since $\sum_{i\in [n]} x_i = k$ for all ${\bf x} \in  \{0,1\}^n_k$. Hence the desired probability is equal to 1 since we are guaranteed that $P({\bf x}) \ne 0$ for at least one point ${\bf x} \in \{0,1\}^n_k$.  We may further assume that $k\le n/2$, as otherwise, we can consider the evaluations of the polynomial $P(1-x_1,\dots,1-x_n)$ over ${\bf x} \in \{0,1\}^n_{n-k}$.  

    We divide the proof into two cases depending on whether $k$ divides $n$:

    {\bf Case 1: $k$ divides $n$.} That is, $n=mk$ for some integer $m \ge 2$. Let $M \in [n]^{k \times m}$ be the matrix formed by arranging $[n]$ according to a uniformly random permutation.  Denoting the $j$-th column of $M$ by $M_j$, let $\su(M_j) = \sum_{i\in M_j} a_i$. We note that
    \begin{align}\label{eqn:prob:nonzero}\Pr_{x \sim \{0,1\}^n_k}[P({\bf x}) \ne 0] = \Pr_M[\su(M_1) \ne -c],\end{align} as both LHS and RHS are essentially picking $k$ elements (without replacement) from $a_1,\dots,a_n$ uniformly at random and checking whether their sum is not equal to $-c$. We construct $M$ by the following random process:
    \begin{itemize}
        \item Partition $[n]$ into $k$ buckets, $B_1,B_2,\dots,B_k \subseteq [n]$, each of size $m$, uniformly at random. 
        \item Set the $i$-th row of $M$ to be a uniformly random permutation of $B_i$, for each $i\in [k]$ independently.   
    \end{itemize}
    We say that an index $i\in [k]$ is ``good'' if the elements $(a_{j})_{j\in B_i}$ are NAE and ``bad'' otherwise. Since $a_1,\dots,a_n$ are NAE, one might expect that there is at least one good index with high probability (over the randomness of the first step i.e., choosing the buckets $B_1,\dots,B_k$). That is, we give an upper bound on 
    $$\Pr_{B_1,\dots,B_k}[\text{all the indices in }[k] \text{ are bad}].$$

    Note that for the above probability to be positive, the number of times each $a_i$ appears in $(a_i)_{i\in [n]}$ must be a multiple of $m$. Thus we may assume that the multiset $(a_i)_{i\in [n]}$ is of the form: $b_1$ (taken $f_1m$ times), $b_2$ (taken $f_2m$ times), $\dots b_\ell$ (taken $f_\ell m$ times), where $\ell \ge 2$ and $b_1,\dots,b_\ell$ are mutually distinct elements of $G$ and $f_1,f_2,\dots,f_\ell \ge 1$. 


    We handle the case of $\ell = m =2$ and either $f_1=1$ or $f_2=1$ separately by the following claim.

    \begin{claim}
        \label{clm:small-case}
        If $\ell=m=2$ and at least one of $f_1$ or $f_2$ is equal to 1, then $$\Pr_{{\bf x}\sim \{0,1\}^n_k}[P({\bf x})\ne 0]\ge \frac{1}{2}-\frac{1}{2(n-1)} \ge \frac{k-1}{n}.$$
    \end{claim}

    Hence, for the rest of the argument, we will assume that $m,\ell$ and $f_i$'s are such that the premise of~\Cref{clm:small-case} are not met. We then bound the bad probability as follows:
    \begin{claim}\label{clm:bad-prob}
        $$\Pr_{B_1,\dots,B_k}[\text{all the indices in }[k] \text{ are bad}] = \frac{{k \choose f_1,~f_2 ,~\dots,~f_\ell}}{{n \choose f_1m,~f_2 m,~\dots,~f_\ell m}} \le \frac{1}{n}.$$
    \end{claim}

    Given~\Cref{clm:bad-prob}, we conclude that with probability at least $1-1/n$, there exists at least one index $i\in [k]$ such that $(a_j)_{j\in B_i}$ are NAE; suppose $h_1 \ne h_2 \in (a_j)_{j\in B_i} \subseteq  G$ be such elements. Recall that we permute the elements corresponding to $B_i$ randomly to form the $i$-th row of the matrix $M$. As this is performed independently across the rows, we may fix an arbitrary permutation of all the rows except the $i$-th one and argue a lower bound on the probability of $P({\bf x})$ being non-zero by~\eqref{eqn:prob:nonzero}. Let $g_1,\dots,g_i,\dots,g_k \in G$ be the corresponding group elements in the first column, where $(g_j)_{j\ne i}$'s are some constants and $g_i$ is picked uniformly at random from the multiset $(a_j)_{j\in B_i}$. We have $\su(M_1) = g_1 + \dots + g_k$. Notice that the sum corresponding to $g_i = h_1$ and $g_i = h_2$ are not equal as $h_1 \ne h_2$. Hence,
    $$\Pr_{g_i}[g_1 + \dots + g_k \ne -c] \ge 1/m.$$ Therefore, we get $$\Pr_M[\su(M_1)\ne -c~|~\text{there exists a good index }i\in [k]]\ge 1/m = k/n.$$ Combining with~\Cref{clm:bad-prob}, this gives us that $\Pr_M[\su(M_1) \ne -c] \ge (k-1)/n$, thus finishing the proof of the theorem (when $k$ divides $n$).

    We now move to the case when $k$ does not divide $n$. 

    {\bf Case 2: $k$ does not divide $n$.} Suppose $n = mk +k'$ for some positive integers $m$ and $k' < k$. Since $k \le n/2$, this implies $m\ge 2$. Similar to the previous argument, we will analyze the probability of $P({\bf x})$ being non-zero using the group elements. In particular, we would like to lower bound the probability of $\sum_{i\in A} a_i \ne -c$, where $A \subseteq [n]$ is subset of size $k$ chosen uniformly at random. We will first sample $A$ by the following process. 
    \begin{itemize}
        \item[--] Choose a uniformly random subset $B$ of $[n]$ of size $mk$.
        \item[--] Choose a uniformly random subset $A$ of $B$ of size $k$. 
    \end{itemize} We claim that with probability at least $mk/n$, the elements $(a_i)_{i\in B}$ are NAE. More formally, we claim that $\Pr_{B \sim {[n]\choose mk}}[(a_i)_{i\in B}\text{~are NAE}] \ge mk/n$. To show this, suppose $g_1 \ne g_2 \in G$ be two distinct elements in $(a_i)_{i\in [n]}$. We have two cases.
    \begin{itemize}
        \item {\bf Case (i): There exists a $g\in G$ that occurs at least $mk$ times in $(a_i)_{i\in [n]}$.} Since $g_1 \ne g_2$, at least one of these two elements is not equal to $g$; say $g \ne g_1$ without loss of generality. We claim that $g_1 \in (a_i)_{i\in B}$ implies $(a_i)_{i\in B}$ are NAE. To see this, we note that $n-mk = k' < mk$, so $g$ must always appear in $(a_i)_{i\in B}$. Hence, $(a_i)_{i\in B}$ are NAE whenever $g_1 \in (a_i)_{i\in B}$. As $B$ is a uniformly random subset of size $mk$, this event (i.e., $g_1 \in (a_i)_{i\in B}$) happens with probability at least $mk/n$. 
        \item {\bf Case (ii): No such element exists.} In this case, $(a_i)_{i\in B}$ are NAE for all choices of $B \in {[n]\choose mk}$. 
    \end{itemize}
    Therefore, $\Pr_{B \sim {[n]\choose mk}}[(a_i)_{i\in B}\text{~are NAE}] \ge mk/n$. Conditioned on $B$ satisfying the condition that $(a_i)_{i\in B}\text{~are NAE}$, we note that $\sum_{i\in A} a_i \ne -c$ with probability at least $(k-1)/(mk)$ by using the fact that we have already established in \Cref{thm:deg1} for the case when $k$ divides $n$. Hence, the final probability is
    \begin{align*}
        \Pr_{A\sim {[n]\choose k}}\bigg[\sum_{i\in A}a_i \ne -c\bigg] & \ge \Pr_{B\sim {[n] \choose mk}}\bigg[(a_i)_{i\in B}\text{ are NAE}\bigg]\cdot \Pr_{A \sim {B \choose k}}\bigg[\sum_{i\in A} a_i \ne -c~\mid~(a_i)_{i\in B}\text{ are NAE}\bigg]\\
        & \ge \frac{mk}{n}\cdot \frac{k-1}{mk} = \frac{k-1}{n}.
    \end{align*}
\end{proof} 

We end with the proofs of~\Cref{clm:small-case} and~\Cref{clm:bad-prob}.


\begin{proof}[Proof of~\Cref{clm:small-case}]
    We have $k=n/2$. Without loss of generality, suppose $f_1=1$. Recall that the multiset $(a_i)_{i\in [n]}$ is equal to $b_1$ repeated $2f_1 = 2$ times and $b_2$ repeated $2f_2 = n-2$ times, for some $b_1\ne b_2 \in G$. We may further assume that $P({\bf x}) = a_1x_1 + a_2 x_2 + \dots + a_n x_n +c$ where $a_1=a_2=b_1$ and $a_3=a_4=\dots=a_n = b_2$. As $\sum_{i=1}^n x_i = k$ for all points ${\bf x} \in \{0,1\}^n_k$, we have  
    \begin{align*}P({\bf x}) & = b_1(x_1 + x_2) + b_2 (x_3 + x_4 + \dots + x_n) +c \\
    & = b_1(x_1 + x_2) + b_2 (k-x_1-x_2) + c \\
    & = {(b_1 - b_2)} (x_1 + x_2) + {kb_2 + c}.
    \end{align*}
    Let $b:=b_1-b_2$ and $b':=kb_2+c$. Then we have, $P({\bf x}) = \begin{cases}  b',\text{~if~}x_1=x_2=0,\\
    b + b',\text{~if~}x_1+x_2 =1,\\
    2b + b',\text{~otherwise.}
     \end{cases}$ 

     Since $b\ne 0$, we have the implication $$b+b' =0 \implies (b' \ne 0 \text{~and~} 2b+b' \ne 0).$$ 
     Hence, $$\Pr_{{\bf x}\sim \{0,1\}^n_{n/2}}[P({\bf x})\ne 0] \ge \min\bigg\{\Pr_{{\bf x}\sim \{0,1\}^n_{n/2}}[x_1 + x_2 =1], ~\Pr_{{\bf x}\sim \{0,1\}^n_{n/2}}[x_1 + x_2 \ne 1]\bigg \} = \frac{1}{2}-\frac{1}{2(n-1)}.$$
\end{proof}

Now, we prove~\Cref{clm:bad-prob}.


\begin{proof} [Proof of~\Cref{clm:bad-prob}]
    We consider two cases depending on the value of $m$.
    \begin{itemize}
        \item {\bf Case 1: $m=2$.} We have $n=2k$. We note that at least one of the two conditions below must be met:
        \begin{itemize}
            \item $\ell \ge 3$, or 
            \item $\ell = 2$ and $f_1,f_2 \ge 2$.
        \end{itemize}
        Regardless of which of the above two conditions is satisfied, we can always partition the multiset $(a_i)_{i\in [n]}$ into two sub(multi)sets $S_1 \subseteq G$ and $S_2 \subseteq G$, %with one of them being of size $|S_1|\ge 4$ (while $|S_1| \le n/2$ also holds) 
        such that $4\leq |S_1|\leq n/2$ 
        and for every $g_1 \in S_1$ and $g_2 \in S_2$, we have that $g_1 \ne g_2$. We now note that a necessary condition for an index $i\in [k]$ to be bad is $\{a_j|j\in B_i\}$ being a subset (as a multiset) of $S_1$ or $S_2$. Hence, the probability that all $i\in [k]$ are bad is at most ${{k\choose f}}/{{n \choose 2f}}$, where $f:=|S_1|/2 \in [2,k/2]$.  As ${{k\choose f}}/{{n \choose 2f}}$ is an increasing function of $f$ when $f \le k/2$, we can lower bound it by the value corresponding to $f=2$, i.e., $\frac{{k \choose 2}}{{n \choose 4}} = \frac{3}{(n-1)(n-3)} \le \frac{1}{n}$.
        \item {\bf Case 2: $m \ge 3$.} We note that the numerator of the fraction in~\Cref{clm:bad-prob} is $A:={k \choose f_1,~f_2,~\dots,~f_\ell} \ge k$ (as each $f_i \ge 1$) and the denominator is ${km \choose f_1 m,~f_2 m,~\dots,~f_\ell m} \ge {k \choose f_1,~f_2,~\dots,~f_\ell}^m = A^m$ by a simple counting argument. Hence, we have
        \begin{align*}
            \frac{{k \choose f_1,~f_2,~\dots,~f_\ell}}{{km \choose f_1 m,~f_2 m,~\dots,~f_\ell m}} \le \frac{A}{A^m}
            \le \frac{1}{k^{m-1}}
             \le \frac{1}{mk} = \frac{1}{n}.
        \end{align*}
        The last inequality follows using $k^{m-2} \ge m$ for $k,m \ge 3$ and for $k=2,m=4$.
    \end{itemize}
\end{proof}




