\section{Appendix}
\subsection{Proofs of \Cref{clm:eig-1} and \Cref{clm:D-conc}}\label{app:claims-simple-proof}
\begin{proof}[Proof of~\Cref{clm:eig-1}]
    By the definition of the weight function $w$ of the generators, we have
    \begin{align*}
        \mu'_\emptyset = \sum_{{\bf y}\in \{0,1\}^{2m}_e} w({\bf y})
         = \sum_{d=0}^m {2m \choose 2d} \cdot \frac{1}{2^m \cdot {m\choose d}}
         = \sum_{d=0}^m \frac{{2m \choose 2d}}{{m\choose d}^2} \cdot \frac{{m\choose d}}{2^m}
         & \le \max_{d \in [0..m]}\bigg(\frac{{2m \choose 2d}}{{m\choose d}^2}\bigg) \cdot \sum_{d=0}^m \frac{{m\choose d}}{2^m}\\
        & = \max_{d \in [0..m]}\bigg(\frac{{2m \choose 2d}}{{m\choose d}^2}\bigg).
    \end{align*}
    Now, for every $d\in [0..m]$, 
    $$\frac{{2m \choose 2d}}{{m\choose d}^2} = \frac{(2m)!d!^2(m-d)!^2}{(2d)!(2m-2d)!m!^2} = \frac{{2m \choose m}}{{2d \choose d}{2m-2d \choose m-d}}=O\bigg(\frac{2^{2m} }{\sqrt{m}}\cdot \frac{\sqrt{d}}{ 2^{2d}} \cdot \frac{\sqrt{m-d}}{2^{2m-2d}}\bigg)=O\bigg(\sqrt{\frac{d(m-d)}{m}}\bigg) \le O(\sqrt{m}),$$ where the last inequality uses the AM-GM inequality. Therefore, $0<\mu'_\emptyset \le O(\sqrt{m})$. 
\end{proof}

Finally, we prove~\Cref{clm:D-conc}.

\begin{proof}[Proof of~\Cref{clm:D-conc}]
    Letting $B:=\{d\in [0..m]~|~|2d-m|>\sqrt{50m\log m}\}$, we can explicitly express the probability as $$\Pr_{{\bf x}\sim \mathcal{D}}[||{\bf x}| - m| > \sqrt{50 m \log m}] = \sum_{d\in B}{2m \choose 2d}\cdot \frac{1}{2^m {m\choose d}} = \sum_{d\in B}\frac{{2m \choose 2d}}{{m\choose d}^2}\cdot \frac{{m\choose d}}{2^m} \le O(\sqrt{m})\cdot \sum_{d\in B}\frac{{m\choose d}}{2^m},$$ by using the bound $\frac{{2m \choose 2d}}{{m\choose d}^2} \le O(\sqrt{m})$ from the proof of~\Cref{clm:eig-1}. To bound the second factor $\sum_{d\in B} \frac{{m\choose d}}{2^m}$, we use a Chernoff bound for the sum of $m$ i.i.d.~copies of a uniformly random Boolean variable. In particular, we get $\sum_{d\in B} \frac{{m\choose d}}{2^m} \le O(1/m^3)$. Hence $\Pr_{{\bf x}\sim \mathcal{D}}[||x|-m|>\sqrt{50m \log m}] \le O(1/m^{2})$.
\end{proof}

\subsection{Proof of \Cref{claim:upper-bound-good-matching}}\label{app:good-matching}

\upperboundgoodmatching*

\begin{proof}[Proof of \Cref{claim:upper-bound-good-matching}]
Let us first how to describe a good matching, or in other words, how to generate a good matching. We first choose a subset $T \subseteq \mathbf{u}^{-1}\set{1}$ of size $0 \leq k \leq t$ which will be matched outside the set $\set{2,4,\ldots,2t}$. To satisfy the good matching condition, it enforces that for every $i \in T$, $\mathcal{M}(2i) \in \set{1,3,\ldots,2t-1} \setminus T$. We choose remaining $k$ vertices from $\mathbf{u}^{-1}\set{0}$ which will be matched outside $\set{1,3,\ldots,2t-1}$. This also enforces that $(t-k) \geq k \Rightarrow k \leq t/2$. Finally, we also account for the possible matching. This gives us:
\begin{equation}
    \Pr_{\mathcal{M}}[\mathcal{M} \; \text{ is a good matching}] \, = \, \sum_{k=0}^{t/2} \dfrac{\binom{t}{k} \binom{t-k}{k} (t-k)! (n/2-t+k)!}{(n/2)!}
\end{equation}
We upper bound $\binom{t}{k}, \binom{t-k}{k}$, and $(t-k)!$ by $t^{t}$ for all $0 \leq k \leq t/2$. Since $t \leq n^{\delta}$, we can upper bound $(n/2-t+k)$ by $(n/2-t/2)!$ for all $0 \leq k \leq t/2$. Using these we get,
\begin{align*}
   \Pr_{\mathcal{M}}[\mathcal{M} \; \text{ is a good matching}] \; \leq \; \dfrac{t^{3t}}{\binom{n/2}{t/2} (t/2)!}
\end{align*}
Employing the standard binomial estimate that $\binom{N}{K} \geq (N/K)^{K}$ and Stirling's approximation, we get,
\begin{align*}
    \Pr_{\mathcal{M}}[\mathcal{M} \; \text{ is a good matching}] \; \leq \; \dfrac{t^{3t}}{n^{t/2}} \; = \; \dfrac{1}{n^{\Omega(t)}}
\end{align*}

\noindent
Now we upper bound the probability that a random matching is a $t$-self good matching. Observe that if a matching $\mathcal{M}$ is a $t$-self good matching, then it implies there exists a subset $\widetilde{T} \subset [t]$ of size $t/2$ such that $\mathcal{M}(2i-1) = 2i$ for $i \in \widetilde{T}$. We can have an arbitrary matching in the remaining $(n/2-t/2)$ vertices in both $L$ and $R$. This gives us:
\begin{align*}
     \Pr_{\mathcal{M}}[\mathcal{M} \; \text{ is a $t$-self good matching}] \; \leq \; \dfrac{\binom{t}{t/2}(n/2-t/2)!}{(n/2)!} \; \leq \; \dfrac{1}{n^{\Omega(t)}}
\end{align*}
This finishes the proof of \Cref{claim:upper-bound-good-matching}.
\end{proof}



\subsection{Proof of \Cref{lem:dim-wilson}}\label{app:wilson-proof}

\degdslicedimension*

The proof is by induction on the parameter $t = (k-d)\cdot(n-k-d).$

The base case of the induction corresponds to the case when $t = 0$, i.e. $d = \min\{k,n-k\}.$ In this case, we want to show that any function $f:\{0,1\}^n_k \rightarrow \mathbb{Z}_q$ is a degree-$d$ polynomial. To show this, it suffices to show that any $\delta$-function on $\{0,1\}^n_k$ can be written as a polynomial of degree at most $d.$ 

Consider without loss of generality the $\delta$-function at the point $\mathbf{a} = 1^k 0^{n-k}.$ If $d = k,$ then the monomial $x_1\cdots x_d$ computes exactly this $\delta$-function. On the other hand, if $d = n-k,$ we can instead use the polyomial $(1-x_1)\cdots (1-x_d).$ In either case, we are done. This proves the base case, i.e. that $|\mathcal{P}_d(n,k,\mathbb{Z}_q)| \geq q^{\binom{n}{d}}$ in this case.

For the induction, assume that $d < \min\{k, n-k\}.$ We claim that 
\begin{equation}\label{eq:Wilson-indn}
|\mathcal{P}_d(n,k,\mathbb{Z}_q)| \geq |\mathcal{P}_d(n-1,k,\mathbb{Z}_q)\times \mathcal{P}_{d-1}(n-1,k-1,\mathbb{Z}_q)| 
\end{equation}
which immediately implies the inductive case using the induction hypothesis\footnote{Note that the induction hypothesis is applicable as either $k-d$ or $n-k-d$ drops by $1$ while the other remains the same.}, as we have
\begin{align*}
    |\mathcal{P}_d(n-1,k,\mathbb{Z}_q)\times \mathcal{P}_{d-1}(n-1,k-1,\mathbb{Z}_q)|  &\geq  |\mathcal{P}_d(n-1,k,\mathbb{Z}_q)|\cdot |\mathcal{P}_{d-1}(n-1,k-1,\mathbb{Z}_q)|\\ 
    &\geq  q^{\binom{n-1}{d}}\cdot q^{\binom{n-1}{d-1}} = q^{\binom{n}{d}}.
\end{align*}

To prove \Cref{eq:Wilson-indn}, we give an injection $\iota$ from the set $\mathcal{P}_d(n-1,k,\mathbb{Z}_q)\times \mathcal{P}_{d-1}(n-1,k-1,\mathbb{Z}_q)$ to the set $\mathcal{P}_d(n,k,\mathbb{Z}_q)$. For each function in $\mathcal{P}_d(n-1,k,\mathbb{Z}_q),$ we fix arbitrarily a polynomial of degree at most $d$ representing this function, and do the same for functions in $\mathcal{P}_{d-1}(n-1,k-1,\mathbb{Z}_q)$ with the degree parameter being $d-1.$

Let $(P,Q)\in \mathcal{P}_d(n-1,k,\mathbb{Z}_q)\times \mathcal{P}_{d-1}(n-1,k-1,\mathbb{Z}_q)$ be the chosen polynomial representations of a pair of functions in the corresponding sets. Define $\iota(P,Q)$ to be 
\[
R(x_1,\ldots, x_n) = P(x_1,\ldots, x_{n-1}) + x_n \cdot Q(x_1,\ldots, x_{n-1}).
\]
The map is injective because the function computed by $P$ (and hence the underlying polynomial which is fixed by the function) can be obtained by restricting $R$ to the points where $x_n = 0$. Further, the function $Q$ can be obtained by evaluating $R$ at the points where $x_n = 1$ and subtracting the value of the polynomial $P$ evaluated at the same point. 

This proves \Cref{eq:Wilson-indn} and concludes the inductive case.
